window.HB_TR["jeremiah"]["ks"]=["1.\\tہلکیاہ سٕندِس نیچوِس یرمیاہ سٕندِ کلام، یُس بنیامین سٕندِس سرزمینس مَنٛز انتھوتھس مَنٛز {ٲس} پادٕرین ہُند کلام:\n2. یٔمِس خداوند سُند کلام یہوداہ کِس بادشاہ آمون سٕندِس نیچوِس یوسیاہ سٕندِس زمانس مَنٛز تٔمۍ سٕندِس بادشاہ کِس تروٲہِمِس ؤریس مَنٛز آو ۔\n3.\\tیہِ آو یہوداہ کِس بادشاہ یوسیاہ سٕندِس نیچوِس یہوویاقیم سٕندِس دۅہس مَنٛز، یہوداہ کِس بادشاہ یوسیاہ سٕندِس نیچوِس کٔہمہِ ؤریس تام یُس یُوداہ کِس بادشاہ سٕندِس نیچوِس سٍتـ̡ یُس پوٗنٛژمِس ریتس مَنٛز یورشلیم نِنہٕ آمُت اوس۔\n4. اَمہِ پَتہٕ آو خداوند سُند کلام یَتھ مَنٛز وَننہٕ آمُت،\n5.\\tامہ برونہہ زِ میہ ٲس ژیہ ژیہ زانان۔ تہٕ یێمہِ برونہہ زِ ژے کٔر رحمہٕ منزٕ نیرُن، مے کٔر ژے قومن خٲطرٕ اکھ پیغمبر مقرر کرنہٕ۔ {مقرر: ہیب۔ دِنہٕ آمُت}\n6. اَمہِ پتہٕ ووٚن مے، آہ، خدا! وچھ، بہٕ ہیکہٕ نہٕ کتھ کٔرتھ: کیازِ بہٕ چُھس اکھ شُر۔\n7. مگر خداوند ووٚن میہ زِ یہ نہ ونُن، بہٕ چُھس شُر، تہٕ یُس بہٕ ژے سوزان چُھس تہٕ یُس تہِ بہٕ ژے حکم دِوان چُھ، تہٕ یُس تہِ بہٕ ژے حکم دِوان چُھس تہٕ ژٕ کتھ کرٕنۍ۔\n8. تِہٕندِس بُتھِس سٍتـ̡ گژھہِ نہٕ خوفزدہ گژھُن: تِکیازِ بہٕ چُھس ژے سٍتـ̡ نجات دِنہٕ خٲطرٕ، خداوند چُھ فرماوان۔\n9. تێمہِ پَتہٕ کٔر خداوند پَنُن اَتھٕ تہٕ کوٚرُن میٲنِس ٲسس تھپھ۔ تہٕ خداوند ووٚن مےٚ، وُچھ، بہٕ چُھس پنٕنۍ کتھ ژےٚ ٲسِس مَنٛز ترٛٲومٕژ۔\n10. وُچھو، مے چُھس از دۅہہ قومن تہٕ سلطنتن پیٹھ مقرر کورمُت، مُلہٕ مُلاونہٕ خٲطرٕ، تہٕ تباہ کرنہٕ خٲطرٕ، تہٕ تباہ کرنہٕ خٲطرٕ، تعمیر کرنہٕ خٲطرٕ، تہٕ ووپداونہٕ خٲطرٕ۔\n11.\\tامہِ علاوہ آو خداوند سُند کلام میانہِ نِش، یرمیاہ کیا چُھہ وُچھان؟ تہٕ میہ ووٚن، میہ وچھ بادام کُلِچ اکھ لور۔\n12. اَمہِ پَتہٕ ووٚن خداوند مےٚ زِ ژے چُھہ اصل پٲٹھۍ وُچھمُت، تِکیازِ بہٕ کَرٕ پنُن کلام جلدٕ۔\n13. تہٕ خداوند سُند کلام آو میہ نِش دوٚیمہِ لٹہِ وونُن، ژیہ کیا چُھہ وچھان؟ تہٕ میہ ووٚن، میہ وچھ اکھ دپان بانہ۔ تہٕ امیک بُتھ {چُھ} شمالس کُن۔ {کُن...: ہیب۔ شمالہٕ کس بُتھ پیٹھ}\n14. تێمہِ پَتہٕ ووٚن خداوند مے زِ شمالہٕ کِس سارنٕے بسکیٖنن پى۪ٹھ گژھہِ بُرٕ۔ {شال...: ہیب۔ کھولنہٕ یِن}\n15. کیازِ، بہٕ کرٕ شمالہٕ کین سلطنتن ہٕندِس سارنٕے خاندانن بلاوُن، خداوند چُھ فرماوان۔ تہٕ تِم یِن یِن، تہٕ یِم پرٮ۪تھ أکِس تختس پیٹھ یروشلم کِس دروازس منز اژنہٕ وِزِ تہٕ اَتھ اندۍ پٔکۍ سارِنٕے دیوارن خٕلاف، تہٕ یہوداہ کین سارنٕے شہرن خٕلاف۔\n16. تہٕ بہٕ کَرٕ تِمن خلاف پنُن فٲصلہٕ یِمن ہٕندِس سارِنٕے بدکارس سٍتـ̡ ، یِمو مے ترٲومُت چُھ، تہٕ باقین دیوتاہن خٲطرٕ بخور زٲلمُت تہٕ پننین اتھن ہٕنزِ کامہِ ہٕنز پوجا کٔرمٕژ۔\n17. تێمہِ کِنۍ کٔرِو پَنٕنۍ کمر بٔنِتھ، تہٕ ووٚتھ، تہٕ تِمن سٍتـ̡ کتھ کٔرِو یُس بہٕ ژے حُکُم دِوان چُھس، تِمن ہٕندِس بُتھِس سٍتـ̡ گژھ نہٕ مایوس گژھُن، یێلہِ بہٕ ژٕ تِمن برونہہ کنہِ پریشان گٔژھِ۔ {کنفیونڈ: یا، پھٹُن ٹُکر}\n18.\\tیِکیازِ وُچھِو مے ژے از دۅہہ اکھ دفاع شَہر، تہٕ ششتٕرُک تھَم تہٕ سارِنٕے زمینس خٕلاف تہٕ یہوداہ کِس بادشاہن خٕلاف، اَمہ کِس شہزادن خٕلاف، اَمہ کِس پادٕرین خٕلاف تہٕ زمینہٕ کین لوکن خٕلاف۔\n19. تہٕ تِم گژھن توے خٕلاف لڑان۔ مگر تِم گژھن نہٕ تۅہہِ خٕلاف غلبہٕ حٲصِل کٔرِتھ۔ کیازِ بہٕ چُھس ژے سٍتـ̡ چُھہ ژے سٍتـ̡ نجات دِنہٕ خٲطرٕ۔","1. اَمہِ علاوٕ آو خداوند سُند کلام میانہِ نِش وَنُن،\n2.\\tگژھ تہٕ یروشلم کین کنن منز روُن، یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ میہ چھہ ژے یاد، چانہِ جوانی ہنز مہربانی، چانہِ مددگارن ہُند محبت، ییلہ ژے میانۍ پَتہٕ بیابانن منز، تتھ زمینس منز یُس نہٕ وونہٕ آمُت اوس۔ {ژے: یا، پننہِ خاطرہ}\n3. اسرٲیل اوس خداوند سٕندِ خٲطرٕ پاکیزگی تہٕ تٔمۍ سٕندِ اضافہٕ ہُند گۄڈنیُک پھل: یُس أمِس کھٮ۪وان چُھ، سُہ گژھہِ ناراض۔ خداوند چُھ فرماوان زِ تِمن پیٹھ گژھہِ بُرٕ واتہٕ۔\n4. اے یعقوب سٕندِ گرٕ تہٕ اسرٲیلِکۍ سارِنٕے خاندانن ہُند کلام بوزو:\n5.\\tیِتھٕ پٲٹھۍ چُھ خداوند فرماوان، تہندٮ۪ن آباؤ اجدادو کُس بدکار لٔبِتھ زِ تِم چھِ میہ نِش دور گٔمٕتۍ، تہٕ بےکار گٔمٕتۍ۔\n6.\\tتِمو ووٚن نہٕ کتہِ چُھہ خداوند یُس اسہِ مصرٕچ سرزمینہٕ منزٕ نیبر کٔرِتھ، یُس اسہِ بیابانن منز، صحرا تہٕ گۅڈن ہٕنزِ سرزمینہٕ کِنۍ، خشک سالی ہٕنزِ زمینہٕ کِنۍ، تہٕ موتٕچ ژھایہ کِس سرزمینس مٔنٛز، یُس نہٕ کانہہ انسان روزان اوس، تہٕ یتہِ نہٕ کانہہ انسان روزان اوس۔\n7. تہٕ بہٕ اَنُن ژےٚ أکِس کُنہِ مُلکس مَنٛز، اَمہ ہُند پھل تہٕ اَمہ سٕنزِ نیکی کھٮ۪نہٕ خٲطرٕ۔ مگر ییلہ ژیہ اژِو، میانہِ زمینہِ ناپاک کٔرِتھ تہٕ بنووُکھ میون وراثت اکھ مکروہ ۔ {اکھ کثرت...: یا، کارملُک سرزمین}\n8.\\tپادٕرۍ ووٚن نہٕ، خداوند کتہِ چُھہ؟ تہٕ یِم شریعت سٍتـ̡ چِھہ میہ پٲٹھـ̡ زانان: پادریو تہِ کٔر میانہِ خلاف زیادٕ، تہٕ پیغمبرن کٔر بعل سٕنزِ پیشن گوئی، تہٕ پکان {تِمن چیزن پى۪ٹھ﴾ یِمن نہٕ فٲیدٕ چُھہ دِنہٕ۔\n9. اَمہِ مۄکھٕ چُھس بہٕ توتہِ ژے سٍتـ̡ التجا کٔرِتھ، خداوند چُھہ فرماوان، تہٕ چُھس تہندٮ۪ن شُرین ہٕندِس شُرین سٍتـ̡ بہٕ گُزٲرِش کَران۔\n10.\\tچِٹِم کِس جزیرس منزٕ گزرُن، تہٕ وُچھِو؛ تہٕ سوزُن کیدارس نِش، تہٕ غور کرُن تہٕ وُچھِن زِ یِژھ ما آسہٕ یِژھ کُنہِ چیز۔ {اوور: یا، اوور ٹو}\n11.\\tکُنہِ قومس بدلٲوۍ {تِہند} دیوتا، یُس نہٕ وُنیُک تام کانہہ دیوتا چھُ؟ مگر میانیو لوکو بدلٲوۍ پنٕنۍ شان {یُس نہٕ فٲیدٕ چُھ}۔\n12. اے آسمانو، اتھ پیٹھ گژھ حیران، تہٕ خوفزدہ گژھو، تم گژھ واریاہ ویران گژھن، خداوند چُھ فرماوان۔\n13.\\tمیانہِ لوکو کٔر زٕ بُرۍ؛ تِمو چھُ مے زندٕ آبُک چشمہٕ ترٲومُت، {تہٕ} کٔرِکھ تِم حوض تہٕ پھُٹمٕتۍ حوض، یِمن نہٕ آب رٔٹِتھ ہیکان۔\n14.\\tکیا اسرائیل چھہ نوکر؟ {کیا} سُہ چھُ گَرِ زامُت {غلام}؟ سُہ کیازِ چُھ خراب گومُت؟ {خراب: ہیب۔ بٔنِو غنیمت؟}\n15.\\tجوان شیرن کٔر أمِس پیٹھ گرٛٮ۪کھ، تہٕ تِمو کٔر تٔمۍ سٕنز زمین برباد: تٔمۍ سٕندِ شہر چھِ بسکیٖن بغٲر زالنہٕ آمٕتۍ۔ {کرٛٮ۪کہٕ: ہیب۔ دِژ پننہ آواز}\n16.\\tنوف تہٕ طحاپان سٕندٮ۪و شُرٮ۪و تہِ پھُٹروو تُہٕندِس کَلُک تاج۔ {ہاو...: یا، پنُن تاج کھیوٚو}\n17. کیا ژے چُھہ نہٕ یہ پانس حٲصل کورمُت، یێلہِ تێلہِ چُھہ خداوند پنُن خدا ترٲومُت، یێلہِ سُہ تۅہہِ وتہِ پۯاوُن؟\n18.\\tتہٕ وُنہِ کیا چُھکھ ژے مصرٕچ وتہِ سِہورُک آب چیٚنہٕ خٲطرٕ کرُن؟ نتہٕ ژیہ کیا کرُن اسریاہس منز، دریاوُک آب چنہٕ خٲطرٕ؟\n19.\\tتُہٕنزِ بدکٲری کٔرِہ تۅہہِ ٹھیٖک، تہٕ تُہٕنزِ پتھ کُن دِیہِ تہٕ وُچھِو تہٕ وُچھِو زِ یہِ چُھ اَکھ بد تہٕ تلخ تہٕ یُس ژے خداوند پنُن خدا ترٲومُت چُھ، تہٕ یێلہِ چُھہ میٲنۍ خوف ژے مَنٛز چُھنہٕ، یێلہِ چُھہ خداوند لشکرن ہُند خدا۔\n20. پرٲنِس زمانس منز چُھس مے تُہند جوُر پھُٹرٲومُت، {تہٕ} پھُٹرٲومُت تُہند بند۔ تہٕ ژے ووٚن، بہٕ کٔرٕ نہٕ زیادٕ۔ ییلہ پرٮ۪تھ تھدِ بالس پیٹھ تہٕ پرٮ۪تھ سبز کُلِس تلہ کُنہِ {خلاف ورزی کرُن: یا، سرو}\n21.\\tتوتہِ اوس میہ ژے اکھ عظیم بیل ووتمُت، یُس مکمل طور صحیح بیول اوس، تیلہِ کِتھہ پاٹھۍ چھکھ ژے میانہِ خاطرہ أکِس عجیب بیل ہٕندِس زوال پذیر کُلِس منز بنیومُت؟\n22. یێلہِ تہِ ژے ژے نائٹرہٕ سٍتـ̡ واش کٔرِتھ، تہٕ واریاہ صابن نِوان چُھ، {توتہِ} چُھہ تُہند بدکار میانہِ برونہہ کُن نشان زد کرنہٕ آمُت، خداوند خدا چُھ فرماوان۔\n23.\\tژیہ کتھہ پاٹھۍ ہیکو ؤنتھ زِ بہٕ چھُس نہٕ آلودہ گومُت، بہٕ چُھس نہٕ بعلیم پتہٕ گومُت۔ وادی منز وچھ پنٕنۍ وتھ، زان ژیہ کیا کورمُت: {ژے} چھکھ اکھ تیز رفتار ڈرومیڈری یُس پننہ وتہِ پیٹھ پکناوان چھُ۔ {تُہۍ چھِ...: یا، اے تیز رفتار ڈرومیڈری}\n24.\\tبیابانس منز عادت اکھ جنگلی گَر، {یُس} چُھ پننہِ مرضی سٍتۍ واو نِش نِوان۔ پننس موقعس پیٹھ کُس ہیکہِ تس پھیُرِتھ؟ یِم سٲری أمِس ژھاران چھِ، تِم گژھن نہٕ پانس تھکان ۔ أمۍ سٕنٛدِس رٮ۪تس منٛز لٔبِن تِم أمِس ۔ {اکھ جنگلی...: یا، اے جنگلی گٔر، بیترِ} {استعمال: ہیب۔ تٔمۍ سٕنز خوشی: ہیب۔ تٔمۍ سٕندِ دِلٕچ خواہش} {پھیر...: یا، یہ الٹ؟}\n25.\\tپَنُن کھوٚر رُکُن تہٕ پَنُن حلق رُکٲوِو ترشہٕ نِش، مگر ژے ووٚن، وۅمید چھُنہٕ نہٕ۔ تکیازِ میہ چھہ اجنبین سیتۍ محبت کورمُت، تہٕ تمن پتہ گژھہِ بہ۔ {تتہِ...: یا، کیا معاملہ چھا مایوس؟}\n26. یِتھٕ پٲٹھۍ چُھ چور لبنہٕ وِزِ شرم گژھان تِتھے پٲٹھۍ چُھ اسرٲیلِک گرٕ شرمندہ سپدان۔ تِم، تِہٕندِ بادشاہ، تِہٕندِ شہزادٕ، تہٕ تِہٕندِ پادٕرۍ تہٕ تِہٕندِ پیغمبر،\n27.\\tأکِس ذخیرس وَنُن، ژے چھُکھ میون مول۔ تہٕ أکِس کٔنِس کُن، تہٕ تِمو چُھ میہ کُن پھیُرۍمٕتۍ، تہٕ نہٕ تِمن ہٕندِس بُتھِس کُن، مگر تِمن ہٕندِس مصیبت وِزِ وَنُن تِم وَنُن، وۅتھٕ وُتھ، تہٕ اسہِ بچاو۔ {اَننہٕ آمُت...: یا، پیدٕ مے} {تہند پٹھ: ہیب۔ گردنُک پٔتمہِ حصہٕ}\n28.\\tمگر کتہِ چھہِ تہند خدا یُس ژے بنوومت چھُ؟ تِم گژھن وۅتھنہٕ، اگر تِم تُہٕندِس مصیبت وِزِ تُہٕندِس مُشکِلَس مَنٛز بچٲوِتھ ہیکن: کیازِکہِ {مُطٲبق} چُھہ تُہند دیوتا، اے یہوداہ۔ {پریشانی: ہیب۔ برائی}\n29.\\tژیہ کیازِ کٔرِو میہ سٍتـ̡ التجا کرنہٕ؟ خداوند چُھ ونان زِ تم سارِوٕے چُھ میانہِ خلاف زیادتی کٔرمٕژ۔\n30.\\tمیہ چھہ تہندین شُرین بیکار مارۍ متۍ۔ تِمن میلہِ نہٕ کانٛہہ تہِ درستگی: تُہنزِ تلوار چھِ تُہندِ پیغمبرن ہٕندۍ پٲٹھۍ، تباہ کٔرِتھ شیرٕکۍ پٲٹھۍ۔\n31. اے نسل، وُچھو خداوند سُند کلام۔ کیا بہٕ اوسُس اسرٲیلُک بیابان اوسمُت؟ انہِ گٹہِ ہند سرزمین؟ تَمہِ مۄکھٕ چھُ میانہِ لوٗکھ ونان زِ أسۍ چھِ مالک۔ أسۍ یِو نہٕ ژےٚ نِش یِنہٕ؟ {أسۍ چھِ...: ہیب۔ اسہِ چھہ غلبہ}\n32.\\tاکھ نونہِ ہیکہِ پنُن زیور مٔشِد کٔرِتھ، {یا} مہرِنہِ پَنُن پَلَو؟ توتہِ چھِ میانین لوٗکن مٔشِد گٔمٕتۍ دۅہ بے شمار۔\n33. ژے کیازِ چُھکھ محبت ژھارنہٕ خٲطرٕ پنٕنۍ وتھ ژٹان۔ تَمہِ مۄکھٕ چھُکھ ژے بدکارن تہِ پنٕنۍ وتھ ہیچھناوٕنۍ۔\n34.\\tتہِ چُھہ تۅہہِ سٍتـ̡ غریبن ہٕندِس روحن ہُند خوُن لبنہٕ آمُت: مے چُھنہٕ یہِ ژوٗرِ پٲٹھـ̡ تلاشہٕ سٍتـ̡ لبنہٕ آمُت، بلکہِ یِمن سارِنٕے سٍتـ̡ لٔبـ̡ ۔ {راز...: ہیب۔ کھَننہٕ کَرنہٕ آمُت}\n35.\\tتوتہِ چُھہ ژیہ ونان، کیازِ بہٕ چُھس بے گناہ چُھس، یقینا گژھہِ تٔمۍ سُند غصہٕ میانہِ نِش پھیرِ۔ وچھ، بہٕ کٔرٕ ژے نِش التجا کرنہٕ، کیازِ ژے چُھہ ونان زِ مےٚ چُھ نہٕ گناہ کورمُت۔\n36.\\tژیہ کیازِ چُھکھ پنُن وتھ بدلاونہٕ خٲطرٕ یوتاہ گٔژھان؟ تۅہہِ گژھہِ مصرس سٍتـ̡ تہِ شرمندہ گژھُن، یێلہِ ژے اسریاہس سٍتـ̡ شرم ٲس۔\n37. آ، تہٕ ژے گژھ أمس نِش نیرُن، تہٕ پنٕنۍ اتھہٕ پننِس کلس پیٹھ، کیازِ خداوند چُھ تُہند اعتماد رد کورمُت، تہٕ تُہۍ گژھہٕ نہٕ تمن منٛز کامیاب۔","1.\\tتِم چھِ ونان زِ اگر کانہہ مرد پننہِ زنانہِ نِش نیرِ، تہٕ سُہ نیرِتھ بییِس مردس سٍتـ̡ بٔنِتھ، کیا سُہ دُبارٕ أمِس نِش واپس؟ کیا یہ زمین گژھہِ نہٕ واریاہ آلودہ؟ مگر ژے چھکھ واریاہن عاشقن سٍتۍ بدکار گِندمُت۔ توتہِ گژھہِ میہ نش واپس، رب چھہ فرماوان۔ {تِم چھِ ونان: ہیب۔ وَنُن}\n2. پَنٕنۍ أچھ تُلِو تھدٮ۪ن جاین کُن، تہٕ وُچھِو نہٕ کتہِ تہِ چھُکھ نہٕ۔ تِمن ہٕندِ خٲطرٕ بِہتھ تہٕ یِمن ہٕندِ خٲطرٕ بِہِتھ یِتھٕ پٲٹھۍ، بیابانن منز عرب۔ تہٕ ژے کٔر پننہ بدکاری تہٕ بدکاری سٍتۍ زمینہٕ آلودہ کرنہٕ۔\n3.\\tامہ کنۍ چھہ روٗد بند کرنہ آمت تہ پوٚت رود نہ کانہہ تہِ۔ تہٕ ژے ٲس کُنہِ کُ\n4. کیا ژٕ کٔرٕ نہٕ یمہٕ وقتہٕ پیٹھٕ میانہِ خٲطرٕ فریاد دِنہٕ، میون بابا، ژٕ چُھکھ میانہِ جوانی ہُند رہنما؟\n5. کیا سُہ روزِ ہمیشہٕ خٲطرٕ رژھراونہٕ؟ کیا سُہ تھاوِ ٲخرس تام؟ وچھ ژے کٔر غلط کتھ تہٕ کٔرٕکھ بد کامہٕ۔\n6.\\tخداوند وۆن میہ تہِ یوسیاہ بادشاہ سٕندِس زمانس مَنٛز، کیا ژے وُچھمُت {یہ} یُس اسرٲیلَن کُس پتھ کھسُن چُھ؟ سۅ چھیہ پریتھ تھدِ بالس پیٹھ تہ پریتھ سبز کُلِس تلہ کنہِ کھسنہ آمژ تہ اتہِ چھیہ بدکاری گِندان۔\n7.\\tتہٕ میہ ووٚن تٔمۍ سٕندِ یِم سارِنٕے {کامہِ} کرنہٕ پتہٕ، ژٕ کٔرِو میہ کُن۔ مگر سۅ آیہ نہ واپس۔ تہٕ تسٕنزِ غدار بینہِ یہوداہ وُچھ {یہ}۔\n8.\\tتہٕ میہ وُچھ ییلہ سارِنٕے وجوہاتو کِنۍ یِمو سٍتـ̡ اسرٲیلِس زنا کٔرِتھ دِژمُت اوس، تہٕ دِژمُت طلاقُک نوٹ۔ توتہِ ٲس نہٕ تسٕنزِ غدار بینہِ یہوداہ کھوژان، مگر گٔیہِ تہٕ گٔیہِ بدکار تہِ گِندُن۔\n9.\\tتہٕ یہِ سپُد تٔمۍ سٕنزِ بدکٲری ہٕندِس ہلکہٕ سٍتـ̡ زِ تٔمۍ کٔر زمینہٕ ناپاک تہٕ کٔرٕن کٔنہِ سٍتـ̡ زنا کٔرِتھ۔ {ہلکہٕ: یا، شہرت}\n10. تہٕ توتہِ چُھہ یێمہِ سارِوٕے سٍتـ̡ تسٕنزِ غدار بینہِ یہوداہ سٍتـ̡ پورٕ دِلہٕ سٍتـ̡ میانہِ کُن پھیرمُت، بٔلکہِ چُھہ خداوند فرماوان ۔ {فرضی طور پٲٹھۍ: ہیب۔ اپزس منز}\n11. تہٕ خداوند ووٚن مے زِ پتھ کھسنہٕ وٲلِس اسرٲیلِس چُھ غدار یہوداہ سٕندِ کھۅتہٕ زیادٕ پانس جواز دِژمُت۔\n12.\\tگژھ تہٕ یِمن کلامَن ہُند اعلان کٔرِو شمالس کُن، تہٕ ونُن زِ واپس، اے پتھ کھسِتھ اسرٲیل، خداوند چُھ فرماوان۔ {تہٕ} بہٕ کرٕ نہٕ پنُن غصہٕ ژے پیٹھ تراوُن: کیازِ بہٕ چُھس رحم کرُن، خداوند چُھس فرماوان، {تہٕ} بہٕ روزٕ نہٕ ہمیشہٕ خٲطرٕ [غصہٕ}۔\n13. صرف کرو پنٕنـ̡ بدکاری تسلیم زِ ژے چُھہ خداوند پننِس خداہس خلاف زیادتی کٔرمٕژ، تہٕ چُھکھ پرٮ۪تھ سبز کُلِس تَل کُلِس تَل پرٲنِس تام پنٕنـ̡ وتہٕ پھٔہلٲومٕژ، تہٕ تێہہ چُھہ نہٕ میانہِ آوازِ ہٕنز فرمانبرداری کٔرمٕژ، خداوند چُھ فرماوان۔\n14. اے پتھ کُن بچہٕ، خداوند چُھ فرماوان۔ تکیازِ بہٕ چُھس ژے سٍتـ̡ خاندر کٔرِتھ: تہٕ بہٕ نِیہٕ ژے أکِس شہرس منزٕ اکھ تہٕ أکِس خاندانس منزٕ زٕ تہٕ بہٕ نِہ ژے صییونس کُن:\n15. تہٕ بہٕ دِیہ ژے پننہِ دِلہٕ مطٲبق پادری، یُس ژے علم تہٕ فہم سٍتـ̡ کھٲلِتھ دِیہِ۔\n16. تہٕ یێلہِ تُہۍ زمینس مَنٛز بٔرِتھ تہٕ بٔرِتھ بٔرِتھ، خداوند چُھ ونان زِ تِم گژھن نہٕ مزید وَنُن، خداوند سٕندِ عہدُک صندوق: نَہ گژھہِ یہِ ذہنس منز یِنہٕ، تہٕ نہ گژھن تِم یہِ یاد۔ نہ گژھن تم {it}؛ نہ گژھِ مزید کرنہٕ یُن۔ {ذہنس منز آو : ہیب۔ دلس پیٹھ آو {یہ...: یا، یہ گژھہِ بڑاونہٕ}\n17. تمہِ وِزِ گژھن تِم یروشلمس خداوند سُند تخت وَنُن۔ تہٕ سارِنٕے قومہٕ یِن اَتھ مَنٛز جمع کرنہٕ، خداوند سٕندِس ناوس پیٹھ، یروشلمس مَنٛز: نۂ تِم گژھن پنہٕ نِس بد دِل سٕندِ خیالہٕ سٍتـ̡ پَکُن۔ {تخیل: یا، ضد}\n18.\\tتِمن دۅہن گژھہِ یہوداہ سُند گرٕ اسرٲیلِس سٍتـ̡ پکان تہٕ تِم گژھن شُمالہٕ کِس سرزمینہٕ پى۪ٹھہٕ یُس میہ چُھہ تُہندین مٲلن ہٕندِس وراثتس مۅکھہٕ دِژمُت۔ {with: or, to} {دِنہٕ آمُت...: یا، چُھس پننین مٲلن ہُند سبب بٔنِتھ}\n19.\\tمگر میہ ووٚن، بہٕ کِتھ کٔنۍ تھاوٕ ژے شُرین مَنٛز، تہٕ ژے دِیہٕ اکھ خۄشگوار زمین، قومن ہٕندِس لشکرس ہُند اکھ اصل میراث۔ تہٕ میہ ووٚن، ژے وَنُن میہ مول۔ تہٕ گژھ نہٕ میہ نِش پھیرٕنۍ۔ {میانہِ طرفہٕ: ہیب۔ میہ پتہٕ} {a goodly...: Heb. اکھ ورثہ عظمت، یا، خوبصورتی} {خوشگوار...: ہیب۔ خواہش ہٕنٛز سرزمین}\n20. یێلہِ زن خانٛدارِنہِ غداری سٍتـ̡ پننِس خاوندس سٍتـ̡ دِوان چُھ، تِتھے پٲٹھـ̡ چُھہ میہ سٍتـ̡ غداری کٔرمٕژ، اے اِسرٲیلِیُک گھر، خداوند چُھ فرماوان۔ {خانٛدر: ہیب۔ دوس}\n21. تھدٮ۪ن جاین پیٹھ آو اکھ آواز بوزنہٕ، یێلہِ وَننہٕ آمٕژ {تہٕ} بنی اِسرٲیلِچ دُعا کٔرٕن، کیازِ تِمو چُھ پنٕنـ̡ وَتھ گٔمٕژ، {تہٕ} تِمو چُھ خداوند پنُن خدا مٔشِد گٔمٕتـ̡۔\n22.\\tواپس، اے پتھ کھسنہ والیو شُرۍ، {تہٕ} بہٕ کٔرٕ چانہِ پتھ کُن شفا دِنہٕ۔ وچھو أسۍ چھِ ژے نِش آمٕتۍ۔ تِکیازِ چُھہ تُہُند خداوند سُہ خدا۔\n23. پٔزۍ پٲٹھـ̡ چُھہ بێکار {نجات ہٕنز وۅمید کرنہٕ آمٕژ} بالہٕ پیٹھ، {تہٕ پہاڑن ہٕنزِ بٔڑِس سٍتـ̡ پٔزۍ پٲٹھـ̡ خداوند سٕندِس خداہس مَنٛز {چُھ} اسرٲیلٕچ نجات ۔\n24.\\tکیازِ شرم کٔر سانین مٲلن ہٕنز محنت سانہِ جوانی پیٹھے کھٮ۪مٕژ۔ تہند ریچھ تہٕ تہند ریوڑ، تہندٕ نیچوۍ تہٕ تہنزٕ کور۔\n25. أسۍ چھِ پننِس شرم سٍتـ̡ بٔرِتھ، تہٕ أسـ̡ چُھہ پننِس خداہس سٍتـ̡ گۅناہ کورمُت، أسـ̡ تہٕ پننین بابن سٍتـ̡ چُھہ جوانی پیٹھٕ از تام گۅناہ کورمُت، تہٕ چُھہ نہٕ خداوند سٕنزِ آوازِ ہٕنز فرمانبرداری کٔرمٕژ۔","1. اے اسرٲیل، یێلہِ تہٕ یێلہِ ژے واپس گژھِو، اے اِسرٲیل، یێلہِ تہٕ یێلہِ پَنٕنـ̡ پَنٕنـ̡ کُنہِ سٍتـ̡ ہُند دُبارٕ دِیُن، تێلہِ گژھِ نہٕ ژے ہٹٲوِتھ۔\n2. تہٕ تُہہِ کٔرِو قَسم زِ خداوند چُھہ حقیقتس منز، فیصلس منز تہٕ نیکی سٍتـ̡ زندٕ۔ تہٕ قومن کرن أمس منز پانس برکت تہٕ تس منز کرن تِم جلال حٲصل۔\n3. یِتھٕ پٲٹھۍ چُھ خداوند یہوداہ تہٕ یروشلم کین لوکن ونان زِ پَنُن بنجر مٲدان پھُٹرٲوِو تہٕ کٔرِو نہٕ کانٹَن مَنٛز۔\n4. یێلہِ یہوداہ ہٕندِس مردو تہٕ یروشلم کِس بسکیٖن دِلٕچ کھال ژٔٹِو، یێلہِ میٲنۍ قہر نارٕکۍ پٲٹھۍ، تہٕ دزِتھ تہٕ یێلہِ تہٕ تُہٕندِ بُراونہٕ کِس سٍتـ̡ ہێکہِ نہٕ ژٔٹِتھ۔\n5. یہوداہَس مَنٛز اعلان کٔرِو تہٕ یروشلمس مَنٛز شایع کٔرِو۔ تہٕ وَنُن، زمینس مَنٛز وُپھ دِیُو: کٔرِو کٔرِو، جمع گٔژھِو، تہٕ ؤنِو، پان جمع کٔرِو، تہٕ أسۍ گٔژھِو دفٲعی شہرن مَنٛز۔\n6.\\tصیہنس کُن معیار قٲیم کرُن: سبکدوش گژھُن، روزُن نہٕ: کیازِ بہٕ اَنہٕ شمالہٕ پیٹھٕ بُردی تہٕ اکھ بٔڈ تباہی۔ {ریٹائر: یا، مضبوط} {تباہی: ہیب۔ بریکنگ}\n7.\\tشیر آو پننہِ کۅکرِ منزہ نیران، تہٕ غیر قومن ہُند تباہ کرن وول چُھ وتہِ پٲٹھۍ۔ سُہ چُھ پننہِ جایہِ پٮ۪ٹھٕ تُہٕنٛز سرزمین ویران کرنہٕ خٲطرٕ درٛامُت۔ تہٕ تُہند شہر گژھن تباہ کرنہٕ، بغٲر کُنہِ بسکین۔\n8. اَمہِ مۅکھہٕ چُھہ ژے بۄرٕ کُلِتھ، ماتم تہٕ کرٛٮ۪کہٕ دِنہٕ خٲطرٕ، یێلہِ چُھہ نہٕ اَسہ نِش پتھ کُن۔\n9. تہٕ اَمہِ دۅہہ سپدِ، خداوند چُھ ونان زِ بادشاہ سُند دِل گژھہِ ختم تہٕ شہزادن ہُند دِل گژھہِ۔ تہٕ پادٕرۍ گژھن حیران، تہٕ پیغمبرن گژھن حیران۔\n10. اَمہِ پتہٕ ووٚن مے، آہ، خدا! یێلہِ چُھہ ژے یێمہِ لُکہٕ تہٕ یروشلمس سٍتـ̡ سٮ۪ٹھاہ دھوکہٕ دِژمُت تہٕ یہِ ؤنِتھ زِ ژے گژھہِ امن۔ ییلہ زن تلوار روحس تام واتان۔\n11.\\tاَمہِ وِزِ یێمہِ لُکہٕ تہٕ یروشلمس وَننہٕ یُن، بیابانن مَنٛز تھدٮ۪ن مقامن ہُند خشک واو یُس میانین لُکن ہٕنزِ کورِ ہٕندِس کُن چُھہ نہٕ پھپھ دِنہٕ خٲطرٕ تہٕ نہ صاف کرنہٕ خٲطرٕ،\n12.\\t{حتیٰ کہ} یِمو {مقامات} سٍتـ̡ ییہ میہ نِش پورٕ واو واتہِ: وۅنۍ تہِ دِیہ بہٕ تمن خلاف سزا۔ {اکھ پور...: یا، تمن کھوتہٕ اکھ مکمل واو} {دِو...: ہیب۔ سراسر فیصلہٕ}\n13.\\tوُچھِو سُہ اوٚبرٕ ہٕندِس پٲٹھۍ، تہٕ تٔمۍ سٕندِ رتھٕ گُرِ ہٕندِ کھۅتہٕ تیز گُرۍ۔ اسہِ ہُند افسوس! تکیازِ أسۍ چھِ خراب گٔمٕتۍ۔\n14. اے یروشلم، پَنُن دِل چھلُکھ بدکٲری نِش یُتھ ژٕ نجات حٲصِل گٔژھِو۔ چانۍ فضول خیال کوتاہ کالس روزِ ژیہ اندر۔\n15.\\tدانس سٍتـ̡ چُھہ اکھ آواز اعلان کٔرِتھ، تہٕ کوہ افرائیم سٍتـ̡ مصیبت شایع کٔرِتھ۔\n16. قومن ہُند ذکر کرُن۔ وُچھِو، یروشلمس خلاف شایع کرُن، {یہ} وُچھن وٲلہِ چھِ دور دراز مُلکہٕ پیٹھٕ یِوان، تہٕ یہوداہ کین شہرن خلاف پنٕنۍ آواز دِوان۔\n17.\\tکھہِ ہٕندِس رٲچھ کٔرِتھ چھِہ تِم أمِس خلاف ۔ کیازِ سۅ چھے میہ خلاف بغاوت کٔرمٕژ، خداوند چُھ فرماوان۔\n18.\\tچانہِ وتہِ تہٕ تۅہہِ سٍتـ̡ چُھہ یِم {چیز} حٲصل کٔرۍمٕتۍ۔ یہ چھہ تۅہہِ ہنز بدکاری، تکیازِ یہ چھیہ تلخ تہ تۅہہِ ہندس دلس تام واتان۔\n19. میٲنۍ أندر، میٲنۍ أندرم! میہ چھہ دِلس منز دگ گژھان۔ میون دِل چُھ میہ اندر شور کران؛ بہٕ ہیوٚک نہٕ پنُن خاموش رٔٹِتھ، تکیازِ ژے بوزمُت، اے میانہِ روح، بُزرگ ہٕنز آواز، جنگُک الارم۔ {میٲنۍ وٲر...: ہیب۔ میانہِ دِلٕچ دیوار}\n20. تباہی پیٹھ چُھ وُچھان۔ تکیازِ سورے زمین چھہ خراب گومت: اچانک چھہ میٲنۍ خیمہ خراب سپدان، {تہٕ} میٲنۍ پردٕ چھِ أکِس لمحس منز۔\n21.\\tمیہ کوتاہ کال وُچھِتھ معیار وُچھِتھ، {تہٕ} بوزنُک آواز۔\n22.\\tمیانین لوکن چھہ بیوقوف، تم چھہِ نہ میہ زانان۔ تِم چھِ سوٹِش شُرۍ، تہٕ تِمن چُھنہٕ کانہہ فِکر: تِم چھِ بُرٕ کَرنہٕ خٲطرٕ دانشمند، مگر نیکی کرنہٕ خٲطرٕ چُھنہٕ تِمن کانہہ علم۔\n23.\\tمیہ وچھ زمینہ، تہٕ لو، یہ ٲس بے شکلہ، تہٕ خالی۔ تہٕ آسمانس سٍتۍ، تہٕ تمن اوس نہٕ کانہہ گاش۔\n24.\\tمیہ وُچھ پہاڑ تہٕ وُچھ تِم تھرِ تھرِ تہٕ سارِنٕے بالہٕ ہلکہٕ ہلکہٕ پٲٹھۍ۔\n25.\\tمیہ وُچھ تہٕ اتہِ اوس نہٕ کانہہ انسان، تہٕ آسمانٕکۍ سٲری جاناوار ژٔلۍ۔\n26.\\tمیہ وُچھ تہٕ وُچھ پھلہٕ دار جاے {ٲس} بیابان، تہٕ اَمہ ہٕندۍ سٲری شہر گٔیہِ خداوند سٕندِ حضوری سٍتـ̡ تباہ تہٕ تٔمۍ سٕندِس شدید غصہٕ سٍتـ̡ پھُٹمٕتۍ۔\n27. یِتھٕ پٲٹھۍ چُھ خداوند ووٚنمُت زِ سٲرٕے زمین گژھہِ ویران۔ توتہِ کرِ نہ میہ پورہ پاٹھۍ ختم۔\n28.\\tامہِ مۅکھہ گژھہِ زمینہِ ماتم تہٕ ہیرِ کُن آسمان کرہُن، کیازِ میہ چھہ کتھ کرمژ، میہ چھہ ارادہ کورمُت، تہٕ نہ کرٕ توبہ تہٕ نہ کرٕ بہٕ امہِ نشہِ پتھ کُن۔\n29. سورُے شہر ژلہِ گُرۍ سوارَن تہٕ کمانَن ہٕندِس شورس خٲطرٕ۔ تِم گژھن جھاڑن منز، تہٕ کنن پیٹھ کھسنہٕ: پرتھ کانہہ شہر گژھہِ تراونہٕ یُن، تہٕ اَتھ منز گژھِ نہٕ کانہہ انسان روزُن۔\n30. تہٕ {یێلہِ} ژے {بگاڑ} گٔیہِ، ژیہ کیا کرِو؟ یودوے ژے پانس سرخ پوش لٲگِتھ، یوٚدوے ژے سۅنہٕ سٍتۍ سجٲوِتھ، یوٚدوے تہٕ ژے پنُن بُتھ پینٹنگہٕ سٍتۍ سجاوِتھ، بیکار کٔرِو پنُن پان خوبصورت۔ تۅہہِ ہٕندِس عاشقس کٔرِن تۅہہِ حقارت، تِم ژھارن تۅہہِ ہٕنزِ زُوٕ۔ {بُتھ: ہیب۔ اچھ}\n31.\\tکیازِ میہ بوز زنانہِ ہٕنز آواز، {تہٕ} تٔمِس سٍتـ̡ یُس پنُن گۄڈنیُک شُر پیدہ کران چُھ، صییون سٕنزِ کورِ ہٕنز آواز، {یُس} چُھہ پننِس پانس ماتم کران، {یُس} چُھہ پنُن اتھہٕ پھٔہلٲوِتھ، {ونان}، ہا ہا میہ وُن! تکیازِ میون روح چھہ قاتلن ہندِ وجہ سٍتۍ تھکان گومت۔","1.\\tیروشلم کین سڑکن منز ژٔلِو تہٕ وُچھِو، تہٕ زانِو تہٕ ژھانڈِو، یێلہِ کانہہ انسان لٔبِتھ، یێلہِ کانہہ تہِ آسہِ یُس فیصلہٕ کران آسہِ، یُس حقیقتس ژھاران آسہِ۔ تہٕ بہٕ کٔرٕ معاف۔\n2. تہٕ یودوَے تِم ونان چھِ، خداوند چُھہ زندٕ۔ یقینا چھِ تِم اپُز قسم۔\n3. اے خداوند، کیا چُھہ نہٕ حقیقتس کُن نظر تھاوان؟ ژے چھکھ تِمن مارمُت، مگر تِمو چُھنہٕ غم۔ ژے چُھ تِم کھٮ۪ومُت، {مگر} تِمو چُھ اصلاح حٲصل کرنہٕ نِش انکار کوٚرمُت: تِمو چُھ پنُن بُتھ کنہِ کنہِ کھۅتہٕ سخٕت بنٲومُت۔ تِمو چھُ واپس یِنہٕ نِش انکار کوٚرمُت۔\n4.\\tلہذا وون میہ پزۍ پاٹھۍ یم غریب۔ تِم چھِ بیوقوف: تِکیازِ تِم چھِنہٕ خداوند سٕنز وتھ زانان، تہٕ نہ چُھہ پننِس خدایہ سُند فیصلہٕ۔\n5. بہٕ واتناوٕ بہٕ بٔڈٮ۪ن نفرن نِش، تہٕ تِمن سٍتـ̡ کتھ کرٕنـ̡ تکیازِ تِمو چُھ خداوند سٕنز وتھ زانمٕژ، {تہٕ} پننِس خدایہِ سُند فیصلہٕ، مگر یِمو چُھ یِمو پوٗرٕ پٲٹھـ̡ ژُٹِھمُت، {تہٕ} بندھن پھُٹرٲومُت۔\n6. اَمہِ مۄکھٕ چُھ جنگلہٕ منزٕ اکھ شیر تِمن مارِتھ، {تہٕ}شامُک رامہٕ ہُند اکھ رامہٕ کرِ تِمن ہٕندِس شہرس رٲچھ کَرُن: یُس تہٕ یُس تہٕ یُس نیران چُھ، سُہ گژھہِ ٹُکرٕ ٹُکرٕ کرنہٕ: کیازِ تِہٕندِ خطا چِھ واریاہ زیادٕ، {تہٕ} تہٕ تِمن ہٕندِس پتھ کُن ہُرراوُن۔ {شام: یا، صحرا} { ہُریر: ہیب۔ مضبوٗط چھِ}\n7. بہٕ کِتھ کٔنۍ کٔرٕ ژےٚ معافی؟ چانہِ شُرٮ۪و چھُ مےٚ ترٛٲومُت، تہٕ تِمن ہُند قسم کھیوٚومُت یِم نہٕ کانٛہہ دیوتا چھِ: ییٚلہِ مےٚ تِمن پوٗرٕ کھٮ۪ن دِیُت، تِمو کٔر زنا تہٕ کٔرٕکھ طوائفَن ہٕندِس گَرَن مَنٛز فوجہٕ جمع ۔\n8.\\tتِمن اوس صبحس گُرِ کھٮ۪وان تہ پرٮ۪تھ کانہہ اوس ہمساے سٕنزِ زنانہِ ہٕندِس پَتہٕ کھٮ۪وان ۔\n9. کیا بہٕ گژھ نہٕ یِمن {چیزن} خٲطرٕ گژھُن؟ خداوند چُھ فرماوان: تہٕ یِتھِس قومس سٍتـ̡ گژھہِ نہٕ میانہِ روحُک انتقام؟\n10. تٔمۍ سٕندِس دیوارس پیٹھ گژھ تہٕ تباہ کٔرِو۔ مگر مکمل خاتمہٕ کرُن نہٕ: تٔمۍ سٕندِ جنگہٕ نِش نِن؛ تِکیازِ تِم چِھ نہٕ خداوند سٕندِس سٍتـ̡ ۔\n11. کیازِ اسرائیلُک گرٕ تہٕ یہوداہ کِس گرن چُھ میانہِ خلاف واریاہ غداری کٔرمٕژ، خداوند چُھ فرماوان۔\n12.\\tتِمو چُھ خداوند سُند اِنکار کٔرِتھ وونُن، {یہِ} چُھہ نہٕ سُہ چُھہ نہٕ۔ نہ گژھہِ اسہِ پیٹھ بُردی واتہِ۔ نہ وُچھِو اسہِ تلوار تہٕ نہ قحط:\n13.\\tتہٕ پیغمبرن گژھن واو بنہِ، تہٕ تِمن مَنٛز چُھنہٕ لفظ {چُھ} آسان، یِتھٕ پٲٹھۍ ییہ تِمن سٍتـ̡ کرنہٕ۔\n14. اَمہِ کِنۍ چُھ خداوند لشکرن ہُند خدا، یێلہِ چُھہ یہِ کتھ کٔرِتھ، یێلہِ چُھہ بہٕ پنٕنـ̡ کَتھٕ تێنہِ ہٕندِس ٲسِس مَنٛز نار بناوُن، تہٕ یێمہِ لُکہٕ سٍتـ̡ لٔکرِ تہٕ سُہ چُھہ تِمن کھٮ۪وان۔\n15.\\tاے اِسرٲیلِیُک گرٕ چُھس دوٗرِ پیٹھٕ اَکھ قوم اَننہٕ یِوان، خداوند چُھ فرماوان زِ یہِ چُھہ اَکھ طاقتور قوم، یہِ چُھ اکھ قدیم قوم، یێمِچ زبان ژے نہٕ زانان چھِ، تہٕ تێہہ چُھہ نہٕ تِمن ہٕندِس کتھہِ سٍتـ̡ سمجِتھ ۔\n16.\\tتِہُند کُلہٕ قبر چھُ، تِم چھِ سارِنٕے طاقتور انسان۔\n17. تہٕ تِم کھٮ۪ن تُہٕندِس فصلس تہٕ تُہٕندِس نیچوِس تہٕ کورِ کھٮ۪ن، تِم کھٮ۪ن تُہٕندِس گۅلہٕ تہٕ تُہٕندِس کُلِس تہٕ تُہٕندِس کُلِس کھٮ۪ن، تِم کٔرِن تُہٕندِس تارس سٍتـ̡ غریب۔\n18. بہر حال خداوند چُھ ونان زِ بہٕ کٔرٕ نہٕ ژے سٍتـ̡ پورٕ پٲٹھـ̡ ختم کرنہٕ۔\n19. تہٕ یێلہِ تہِ گژھہِ یێلہِ تہِ وَنُن، یێلہِ تہٕ یێلہِ یِم سارِنٕے {چیز} چُھہ اسہِ سٍتـ̡ دِنہٕ آمُت؟ تیلہ کٔرِو تِمن جواب یِتھٕ پٲٹھۍ ژے مے ترٲومُت تہٕ پننہِ سرزمینس منز عجیب دیوتاہن ہٕنز خدمت کٔرِو، تِتھے پٲٹھۍ کٔرِو تُہۍ أکِس زمینس مَنٛز اجنبین ہٕنز خدمت کٔرِتھ یُس نہٕ تُہند آسہِ۔\n20.\\tیعقوب سٕندِس گرس مَنٛز کٔرِو یہِ اعلان تہٕ یہوداہَس مَنٛز شایع کٔرِتھ وَنُن،\n21.\\tیہ بوزو اے بیوقوف لوکو تہٕ بےٚ فہم ۔ یِمن أچھ چھِ، تہٕ یِمن نہٕ وُچھان چھِ؛ یِمن کَن چِھ، تہٕ بوزان چُھ: {سمجھ: Heb. دِل}\n22.\\tژیہ چھکھ نہ میہ کھوژان؟ خداوند چُھ فرماوان: کیا ژٕ چُھہ نہٕ میانہِ حضوری سٍتـ̡ تھرتھر کٔرِتھ، یٔمۍ سمندرُک پابند چُھہ أکِس دائمی حکمس سٍتـ̡ تھوومُت، زِ یہِ ہیکہِ نہٕ اَتھ کُن نیرِتھ: تہٕ یێلہِ تہٕ یێلہِ ہٕنزِ لہرٕ پانَے ٹاس دِوان چھِ، توتہِ ہیکن نہٕ تِم غالب سپدِتھ۔ یوٚدوے تِم گرٛٮ۪وان چھِ، توتہِ ہیکَن نہٕ تِم اَتھ پٮ۪ٹھٕ نیرِتھ؟\n23.\\tمگر یِمن لوکن ہُند دِل چھُ بغاوت تہٕ باغی دِل۔ تِم گٔیہِ بغاوت تہٕ گٔیہِ۔\n24. نہ چُھ تِم پننِس دِلس منز ونان زِ أسـ̡ وۅنۍ چُھہ پننِس خداہس سٍتـ̡ کھوژان، یُس پننِس موسمس مَنٛز گۅڈنِچ تہٕ دویمِس دۅشوے روٗد دِوان چُھ، سُہ چُھ فصلہٕ ہٕندِ مقرر ہفتہٕ اسہِ خٲطرٕ رژھراوان ۔\n25.\\tتُہٕندِس گناہ سٍتـ̡ چُھہ یِم {چیز} پتھ کٔرۍمٕتۍ، تہٕ تُہٕندِس گۅناہو چُھہ ژے نِش رُکٲوِمُت۔\n26. تکیازِ میانین لوکن منز چِھ بدکار لبنہٕ آمٕتۍ: تِم چِھ انتظار کران، یِتھٕ پٲٹھـ̡ یُس پھانس چُھ دِوان۔ تِم چھِ اکھ جال ترٛاوان، تِم چھِ نفر رَٹان۔ {تِم چھِ...: یا، تِم چھِ ژٔٹِتھ یِتھٕ پٲٹھۍ کُلۍ کٔرِتھ انتظار کران چھِ}\n27.\\tیِتھے پٲٹھـ̡ پنجرٕ جاناوارو سٍتـ̡ بٔرِتھ چُھہ، تِتھے پٲٹھـ̡ چُھہ تِہُند گرٕ دھوکہٕ سٍتـ̡ بٔرِتھ بٔرِتھ: اَمہِ مۄکھٕ چُھ تِم بٔڈۍ بٔنِتھ تہٕ موم گٔژھان۔ {پنجرے: یا، کوپ}\n28.\\tتِم چھِ موم موٚٹۍ، تِم چمکان: آ، تِم چھِ بدکارن ہٕندِس اعمال سٍتـ̡ پتھ کٔرِتھ: تِم چِھہ نہٕ وجہ، یێلہِ تہِ چھِ تِم ترقی کَران۔ تہٕ ضرورتمندن ہُند حق چُھ نہٕ تِم فیصلہ کران۔\n29.\\tبہٕ گژھ نہٕ یِمن {چیزن ہٕندِ} خٲطرٕ گژھُن؟ خداوند چُھ فرماوان: یِتھِس قومس سٍتـ̡ گژھہِ نہٕ میانہِ روحُک انتقام؟\n30.\\tزمینس منز چھہ اکھ حیرت انگیز تہٕ خوفناک چیز سپدان۔ {اکھ حیرت انگیز...: یا، حیرت تہٕ گندگی}\n31.\\tپیغمبرن چھِ اپُز پیشن گویی کران، تہٕ پادٕرۍ چھِ پننہِ وسیلہٕ سٍتـ̡ حکمرٲنی کران۔ تہٕ میانہِ لوٗکھ چھِ یہِ پسند کران: تہٕ ٲخرس پیٹھ کیا کرِو تُہۍ کٔرِو؟ {بیئر...: یا، تِمن ہٕندِس اتھس منز}","1. اے بنیامین سٕندِ بچو، یروشلم منزٕ ژلنہٕ خٲطرٕ جمع گژھِو، تہٕ تیکوا ہس مَنٛز بُرٕچ علامت بَنٲوِو، تہٕ بیت ہاکریمس مَنٛز کٔرِو نارُک نِشانہٕ، کیازِکہِ شُمالہٕ کِنۍ چُھ بُرٕ ظٲہر سپدان تہٕ بٔڈ تباہی سپدان۔\n2.\\tمیہ چھہ صیون سنزِ کورِ اکھ خوبصورت تہ نازک زنانہِ سیتۍ تشبیہ دژمژ۔ {خوبصورت: یا، گرس منز روزُن}\n3.\\tپَنٕنـ̡ پَنٕنـ̡ پۯاوٕنـ̡ یِن أمِس نِش۔ تِم لگٲوِن أمِس اندۍ خیمہٕ۔ تِم دِن پرٮ۪تھ أکِس پننہِ جایہِ کھٮ۪نہٕ۔\n4. أمِس خٕلاف کٔرِو جنگ تیار۔ وۅتھُن تہ اسہِ گژھہِ دوپہرس پیٹھ۔ اسہِ ہُند افسوس! تکیازِ دۅہ چھہ ژلان، تکیازِ شامکۍ ژھایہ چھہِ پھہلان۔\n5. وۅتھٕ وُتھ، تہٕ أسۍ گژھو رٲژ تہٕ أسۍ کرو تٔمۍ سٕندِ محل تباہ کرنہٕ۔\n6.\\tیِتھٕ پٲٹھـ̡ چُھہ لشکرن ہُند وَنُن زِ یێلہِ کُلۍ ژٔٹِو، تہٕ یروشلمس پیٹھ اکھ پہاڑ تراوُن: یێہے چُھہ یُس شہر گژھُن۔ سۅ چھیہ پانس منز سراسر ظلم۔ {کاسٹ ...: یا، شاٹُک انجن تراوُن}\n7.\\tیِتھے پٲٹھـ̡ چُھہ چشمہٕ پَنُن آب کڈان تہٕ تِتھے پٲٹھـ̡ چُھ سُہ پَنُن بد کار کڈان: تِمن منز چُھ تشدد تہٕ غنیمت بوزنہٕ یوان۔ میانہِ برونہہ کنہِ چھہ مسلسل غم تہ زخم۔\n8. اے یروشلم، ژے گژھ ہدایت دِنہٕ، نتہٕ گژھ میون روح ژے نِش نیرُن۔ میہ کٔرِتھ ژیہ ویران کرُن، یُس نہ آباد آسہِ۔ {روانہ: ہیب۔ یلہٕ گژھُن، یا بے جوڑ}\n9. یِتھٕ پٲٹھـ̡ چُھ لشکرن ہُند رب فرماوان زِ تِم کرِ اِسرٲیلِچ باقیات سٍتـ̡ پَنُن اَتھٕ پھیُرِتھ پٲٹھـ̡ سٍتـ̡ سٍتـ̡ پَنُن اَتھٕ پٲٹھـ̡ پٲٹھـ̡\n10. بہٕ کٔمِس سٍتـ̡ کتھ کرٕنـ̡ تہٕ تنبیہٕ کرٕنـ̡ یُتھ تِم بوزنہٕ یِن؟ وُچھِو، تِہُند کَن چُھہ نہٕ ختنہٕ آمُت، تہٕ تِم ہیکن نہٕ بوزِتھ: وُچھِو، خداوند سُند کلام چُھ تِمن خٲطرٕ ملامت ۔ تمن چھہ نہ اتھ منز کانہہ خوشی۔\n11. تێمہِ کِنۍ چُھس بہٕ خداوند سٕندِ قہر سٍتـ̡ بٔرِتھ۔ بہٕ چُھس تھکان زِ بہٕ تراوٕ یہ نیبرمین شُرین پیٹھ، تہٕ جوانن ہٕندِس مجلسس پیٹھ، تکیازِ خانٛدار تہِ گژھِ زنانہِ سٍتۍ نِنہٕ، بُزرگ تہِ یُس دۅہن بٔرِتھ آسہِ۔\n12. تہٕ تِہٕندِ گرٕ یِن باقین ہٕندِس خٲطرٕ دِنہٕ، تہٕ تِہٕندِس کھیت تہٕ زنانہٕ سٍتـ̡ یکوٹہٕ، کیازِ بہٕ کَرٕ زمینہٕ کین بسکینن پیٹھ پنُن اتھہٕ، خداوند چُھ فرماوان۔\n13.\\tتکیازِ یِمو منزٕ سارِوٕے کھۄتہٕ بٔڈِس تام چھُ پرٮ۪تھ کانہہ لالچ دِنہٕ آمُت۔ تہٕ نبی سٕندِ طرفہٕ پادٕرِس تام تہِ چھُ پرٮ۪تھ کانہہ غلط سلوک کران۔\n14.\\tیِمو کٔر میانین لوکن ہٕنزِ کورِ ہُند زخم تہِ رژھ کھنڈ شفا دِتھ ونان، امن، امن۔ ییلہ {اتہِ} چھہ نہ کانہہ سکون۔ {زخم: ہیب۔ زخم، یا، خلاف ورزی}\n15.\\tییلہ تمو مکروہ کٲم کٔرمٕژ ٲس، کیا تِمن ٲس شرم گٔمٕژ؟ بلکہ اوس نہٕ تِم کُنہِ تہِ شرمندٕ گٔژھمٕتۍ، تہٕ نہ ہیوٚک تِم شرم کٔرِتھ، لہذا گژھن تِمن مَنٛز یِم پیوٚو یِم یِمن مَنٛز یِنہٕ وِزِ یِم یِن دِنہٕ، خداوند چُھ فرماوان۔\n16. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، وتہٕ وتہٕ وُچھِو، تہٕ پرٲنۍ وتہٕ منگو، یتہِ چُھ اصل وتہٕ، تہٕ اَتھ مَنٛز پٔکِو، تہٕ پَکُن پَنٕنـ̡ پَنٕنـ̡ روحن ہٕندِ خٲطرٕ آرام حٲصِل کٔرِو۔ مگر تِمو ووٚن زِ أسۍ پَکَو نہٕ اَتھ مَنٛز۔\n17.\\tتہِ چُھس میہ چوکیدار تھوومُت، {ونن}، بُنجہِ ہٕنز آواز۔ مگر تِمو ووٚن زِ أسۍ بوزو نہٕ۔\n18.\\tتێلہِ بوزو اے قومو، تہٕ زانِو زٲنِو، اے جماعت، یِمن مَنٛز کیا چُھہ {چُھ}۔\n19.\\tبوزو، اے زمین: وچھ بہٕ یِمن لوکن پیٹھ بد کار انان، تہندِ خیالُک پھل تہِ، کیازِ تِمو چُھ نہٕ میانہِ کلامٕچ کتھ بوزمٕژ، تہٕ نہ میانہِ شریعتٕچ کتھ کٔرٕکھ رَد۔\n20.\\tکتھ مقصدس خٲطرٕ چُھ میانہِ خٲطرٕ شیبا سٕنز بخور تہٕ دور دراز ملکہٕ پیٹھٕ مٔدٕر لورِ دِنہٕ آمٕژ؟ چانۍ دزنہٕ آمٕژ نذرانہ چھِنہٕ قبول، تہٕ نہ چھِ چانۍ قربانی میانہِ خٲطرٕ میٹھۍ۔\n21. تێمہِ کِنۍ چُھ خداوند فرماوان، وُچھ، بہٕ تراوٕ یِمن لوکَن برونہہ کُن ٹھوکر، تہٕ مٲلۍ تہٕ نیچوۍ یِکہٕ وَٹہٕ یِمن پیٹھ پیٚیہِ۔ ہمسایہ تہٕ تٔمۍ سُنٛد دوس گژھِ مارٕ۔\n22.\\tیِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ وُچھِو شُمٲلی مُلکہٕ پیٹھٕ یِیہِ اکھ لُکھ یِوان تہٕ اَکھ بٔڈ قوم یِیہِ زمینہِ ہٕندِس اندس سٍتـ̡ پٲدٕ کرنہٕ۔\n23.\\tتِم گژھن کمان تہٕ نیزٕ تھپھ کٔرِتھ۔ تِم چھِ ظالم، تہٕ چھِنہٕ کانہہ رحم۔ تہنز آواز چھیہ سمندرکۍ پاٹھۍ گڑبڑ کران۔ تہٕ تِم چھِ گُرٮ۪ن پیٹھ سوار گٔژھِتھ، اے صیہون سٕنزِ کورِ، ژےٚ خٕلاف جنگہٕ خٲطرٕ نفرن ہٕندِس طورس پیٹھ ترتیب دِنہٕ آمٕتۍ۔\n24.\\tاسہِ چھیہ امہ چہ شہرت بوزمژ: سانۍ اتھہ چھہِ کمزور سپدان: دکھ چھہ اسہِ رٔٹتھ رٔٹتھ تہ دگ تہِ چھہ زنانہِ ہندۍ پاٹھۍ مصیبت کران۔\n25.\\tکھاہس منز گژھ نہٕ نیرُن، تہٕ وتہِ پٔکِو نہٕ۔ دُشمن سٕنز تلوار {تہٕ} خوف {چُھ} پریتھ طرفہٕ۔\n26. اے میانہِ لُکہٕ سٕنزِ کورِ، ژے لٲگِتھ رٔٹِتھ تہٕ پان رٔٹِتھ ژے ماتم کٔرِتھ، یُس کُنی نیچوِس سٍتـ̡\n27. مے چُھس ژے پننین لوکن منز اکھ مینار تہٕ اکھ قلعہ بنوومُت، یُتھ ژٕ ہێکہٕ تِہٕنزِ وتھ زانِتھ تہٕ کوشش کٔرِتھ۔\n28.\\tتِم چھِ سارِنٕے بغاوت کٔرِتھ، یِم چھِ بدنام کٔرِتھ: {تِم چھِ} پیتل تہٕ ششتٕر۔ تِم چھِ سٲری بدعنوان ۔\n29.\\tبیلہٕ چھِ زالنہٕ یوان، سیسہ چُھ نارس منز کھٮ۪نہٕ یوان۔ بانی چھہ بیکار پژان: بدکار چھہ نہ ژٹنہ یوان۔\n30.\\tرۅپہٕ رۅپہٕ وُچھِن تِمن بُلاونہٕ، کیازِکہِ خداوند چُھ تِم رد کٔرِمٕتۍ۔ {بدکار...: یا، رۄپہٕ نِش انکار کٔرِو}","1. سُہ کلام یُس خداوند سٕندِ طرفہٕ یرمیاہ ہس تام آمُت چُھ، یُس ونان چُھ،\n2. خداوند سٕندِس گرٕ کِس دروازس مَنٛز کھڑا گژھِو، تہٕ اَتہِ کٔرِو یہِ کلامُک اعلان تہٕ ونُن، خداوند سُند کلام بوزو، یُس یِمن دروازن پیٹھ اژان چُھ، یُس خداوند سٕنز عبادت کرنہٕ خٲطرٕ اژان چھُ۔\n3. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھہ ونان زِ پَنٕنـ̡ وَتھ تہٕ پَنٕنـ̡ کَرٕنـ̡ تہٕ بہٕ کٔرٕ ژے یَتھ جایہِ روزُن۔\n4.\\tپُزِ کُنہِ کلامَس مَنٛز پژھ نہٕ پٲٹھۍ، یێلہِ چُھہ خداوند سُند مندر، خداوند سُند مندر، خداوند سُند مندر، یِم چھِ۔\n5. یێلہِ پَنٕنـ̡ پَنٕنـ̡ طٔریٖقہٕ تہٕ پَنٕنـ̡ پَنٕنـ̡ پَنٕنـ اگر تُہۍ أکِس نفرس تہٕ تٔمۍ سٕنٛدِس ہمساین درمیان فٲصلہٕ پوٗرٕ پٲٹھۍ انجام دِیِو۔\n6. یێلہِ نہٕ تُہۍ اَتھ جایہِ بے گناہ سٍتـ̡ ظُلم کٔرِو، تہٕ یێلہِ نہٕ یێلہِ بێیِس دیوتاہن سٍتـ̡ پَکُن:\n7. تیلہٕ کٔرٕ بہٕ ژے اتھ جایہِ روزُن، تتھ زمینس مَنٛز یُس مے چُھس پننین مٲلن دِژمُت، ہمیشہٕ خٲطرٕ۔\n8.\\tوچھو، توے چھِو اپُز لفظس پیٹھ بھروسہ کران، یُس نہٕ فٲیدٕ حٲصل کٔرِتھ۔\n9. کیا ژیہ ژوٗرِ کٔرِتھ، قتل کٔرِتھ زنا کٔرِتھ، تہٕ اپُز قسم کٔرِتھ، تہٕ بعلس تام بخور زٲلِتھ، تہٕ باقین دیوتاہن پَتہٕ پکان یِمن نہٕ تۅہہ زانان چھِو۔\n10.\\tتہٕ یێمہِ مَنٛز یێلہِ میانہِ ناوٕ سٍتـ̡ وَننہٕ آمُت چھُ، تہٕ وَنُن زِ أسـ̡ چُھہ یِم سارِنٕے مُکمل کٔرِتھ دِنہٕ آمٕتـ̡ ۔ {کُس...: ہیب۔ ییمہ پتہٕ میون ناو وننہٕ چُھ یوان}\n11.\\tیہِ مکانہٕ، یُس میانہِ ناوٕ سٍتۍ وَنان چھُ، چھا تۅہہِ نظرِ منز ڈاکوَن ہُند گۅپھ بَنُن؟ وچھو، میہ تہِ چھہ وچھمُت، خداوند چھہ فرماوان۔\n12.\\tمگر وۅنۍ گژھ میانہِ جایہ یُس شیلوہس منز اوس، ییتہ میہ گۅڈنچہ لٹہِ پنُن ناو تھوومُت، تہٕ وُچھو میہ کیا کورمُت پننین لوکن ہندِ بدکاری خٲطرٕ۔\n13. تہٕ وُن، کیازِ یِم سٲری کٲم کٔرۍمٕتۍ، خداوند چُھ فرماوان، تہٕ بہٕ چُھس ژے سُلہٕ وُتھان تہٕ کتھ کٔرِتھ، مگر تۅہہ بوز نہٕ۔ تہٕ میہ بُلوو ژےٚ، مگر ژے دیت نہٕ جواب۔\n14.\\tتێلہِ کٔرٕ بہٕ اتھ مکانس سٍتـ̡ یُس میانہِ ناوٕ سٍتـ̡ وننہٕ یوان چُھ، یێتھ تێلہِ تێلہِ تہٕ تێہٕندِس مٲلِس دِژمُت چُھ، یێلہٕ مے شِلوہس سٍتـ̡ دِژمُت چُھ۔\n15. تہٕ بہٕ کٔرٕ ژے پننہِ نظرِ نِش کٔرِتھ، یِتھ کٔنۍ مے چُھہ چانہِ سارِنٕے بٲے تہٕ افرائیم سُند سورُے بیول تہِ کڈِمُت۔\n16. تێمہِ کِنۍ کٔرِو نہٕ یِمن لُکن ہٕندِ خٲطرٕ دُعا تہٕ تِمن ہٕندِ خٲطرٕ کٔرِو نہٕ دُعا تہٕ دُعا تہٕ نہ کٔرِو میانہِ خٲطرٕ شفاعت، کیازِ بہٕ کٔرٕ نہٕ تُہٕندِ بوزنہٕ یِنہٕ۔\n17.\\tژیہ چُھہ نہٕ وُچھان زِ تِم یہوداہ کین شہرن تہٕ یروشلم کین سڑکن مَنٛز کیا کران چھِ؟\n18.\\tشُرۍ چھِ لٔکر جمع کران، تہٕ مٲلۍ چھِ نار زالان تہٕ زنانہٕ چھِ جنتٕچ ملکہِ خٲطرٕ کیک بناونہٕ خٲطرٕ تہٕ باقین دیوتاہن خٲطرٕ شراب نذرانہ تراوٕن، یُتھ تِم مےٚ شرارت ہُند شکار کٔرِتھ۔ {ملکہ...: یا، فریم، یا، جنتچ کاریگری}\n19. کیا تِم چھِ مےٚ شرارت دِوان؟ خداوند چُھ ونان: {کیا تِم چِھہ نہٕ پننین بُتھِن ہٕندِس پریشٲنی سٍتـ̡ اِشارٕ دِوان؟\n20. تَمہِ کِنۍ چُھ خداوند خدا یِتھ پٲٹھۍ وَنان۔ وچھ میٲنۍ غصہٕ تہٕ میٲنۍ قہر یَتھ جایہِ پیٹھ، انسانس پیٹھ، تہٕ درندس پیٹھ، تہٕ کھاہن ہٕندٮ۪ن کُلٮ۪ن پیٹھ، تہٕ زمینہٕ کِس پھلس پیٹھ۔ تہٕ یہ گژھہِ دزان، تہٕ یہ گژھہِ نہٕ ژھینہٕ۔\n21. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھ فرماوان۔ پَنٕنۍ زٲلِتھ نذرانہ ترٲوِو پننہِ قربانیَس مَنٛز، تہٕ کھیٛو ماز۔\n22.\\tکیازِ میہ کٔر نہٕ تۅہہِ آبن سٍتـ̡ کتھ تہٕ نہ دِژ تِمن دۅہٕ یُس بہٕ تِم مصر کہِ سرزمینہٕ منزٕ نیبر کٔرِتھ، زالنہٕ نذرانہٕ تہٕ قربانین مُتعلِق حُکُم۔ معاملس متعلق}\n23. مگر امۍ چیزن دیت میہ تمن حکم زِ میانہِ آوازِ ہنز فرمانبرداری، تہٕ بہٕ بنہٕ پنُن خدا، تہٕ تہٕ تم گژھن میٲنۍ لوک، تہٕ تم گژھن تمن تمام طریقن پیٹھ پکُن یُس میہ چُھہ حکم دِژمُت، یُتھ تہٕ یہ گژھہِ تۅہہِ خٲطرٕ ٹھیٖک روزُن۔\n24.\\tمگر تِمو بوز نہٕ تہٕ کٔرٕکھ کَن کُن، بلکہ گٔیہِ مشورن مَنٛز پَکُن تہٕ پَتہٕ کُن تہٕ پَتہٕ کُن گٔیہِ، تہٕ گٔیہِ نہٕ برونہہ کُن۔ {تخیل: یا، ضد} {گٔیہ: ہیب۔ ٲس}\n25.\\tییمہِ دۅہہٕ تُہند باپ مصر کہِ سرزمینہٕ منزٕ نیرِتھ دِنہٕ آمٕتۍ، مے چھُ از تام پَنٕنـ̡ سارِنٕے خادمَن نِش سُلہٕ سُلہٕ وُتھان تہٕ سوزان {تِم}۔\n26.\\tتوتہِ کٔر نہ تِمو میانہِ کُن بوزُن، نہ کٔرٕکھ کَن، بلکہ کٔرٕکھ گردن سخٕت: تِمو کٔر پننین مٲلن کھۅتہٕ بدتر کٲم۔\n27. تێمہِ کِنۍ کٔرِو تِمن سٍتـ̡ یِم سارِنٕے کَتھٕ وَنُن۔ مگر تِم کرِ نہٕ تۅہہِ بوزُن: تُہۍ تہِ کرِ تِمن پکار۔ مگر تِم دِن نہٕ تۅہہِ جواب۔\n28.\\tمگر تۅہہ گژھہِ تِمن ونُن، یہِ چُھہ اکھ تِژھ قوم یُس نہٕ خداوند پننِس خدایہ سٕنزِ آوازِ ہٕنز اطاعت کران چُھ، تہٕ نہ چُھہ تِمن ہٕندِس ٲسس سٍتـ̡ ژٹنہٕ آمُت۔ {تصحیح : یا، ہدایت}\n29.\\tاے یروشلم، پَنُن مَس ژٹِتھ ژٔٹِتھ تہٕ تھدٮ۪ن جاین پیٹھ کٔرِو ماتم کٔرِتھ۔ تکیازِ خداوند چُھ پننہِ قہر ہُند نسل رد تہٕ ترک کورمُت۔\n30. خداوند چُھ ونان زِ یہوداہ کٮ۪و بچیو چُھ میانہِ نظرِ منز بُرٕ کٔرمٕژ، یُس میانہِ ناوٕ سٍتـ̡ ونان چُھ، تِمو چُھ پنٕنۍ مکروہ کُن گٔژھمٕژ۔\n31.\\tتہٕ تِمو چھِ توپھتٕچ تھدِ جایہ بنٲومٕژ، یُس حِنوم سٕندِس نیچوِس وادی مَنٛز چھُ، یُس پننین نیچوٮ۪ن تہٕ کورِ نارس مَنٛز زالنہٕ مۅکھہٕ چھُ۔ یُس نہ میہ حکم دِژمُت اوس، نہ آو میٲنس دلس منز۔ {آو...: ہیب۔ یہ آو میٲنس دلس پیٹھ}\n32.\\tتێلہِ وُچھِو یِم دۅہ یِن، خداوند چُھ ونان زِ اتھ ییہ نہٕ وُنہٕ ٹوفیت وننہٕ، تہٕ نہ ہینوم سٕندِس نیچوِس سٕنز وادی، بٔلکہِ ذبح کرنٕچ وادی، تکیازِ تِم گژھن ٹوفیتس مَنٛز دفن کرنہٕ، یوتام نہٕ کانہہ جاے آسہِ۔\n33.\\tتہٕ یِمن لُکن ہٕندِ لاشہٕ گژھن اسمانٕکۍ جاناوارن تہٕ زمینہٕ کین جانورن ہُند ماز ۔ تہٕ کانٛہہ تہِ گژھِ نہٕ ژٔلِتھ۔\n34. تیلہٕ کَرٕ بہٕ یہوداہ کِس شہرو منز، تہٕ یروشلم کین سڑکو پیٹھ، خوشی ہٕنز آواز، مہرازٕ سٕنز آواز تہٕ مہرنہِ ہٕنز آواز، تکیازِ زمین گژھہِ ویران۔","1. اَمہِ وِزِ خداوند چُھ فرماوان زِ تِم کٔڈِن یہوداہ کِس بادشاہن ہٕنزِ أڈجہِ، تہٕ تٔمۍ سٕندٮ۪ن شہزادن ہٕنزِ أڈجہِ، تہٕ پادٕرین ہٕنزِ أڈجہِ، تہٕ یروشلم کین بسکینن ہٕنزِ أڈجہِ تہٕ یِمن ہٕنزِ قبرو منزٕ کٔڈِن:\n2. تہٕ تِم پھٔہلٲوِن آفتابس تہٕ زونہِ تہٕ آسمانٕچ سارِنٕے لشکرس برونہہ کُن، یِمن سٍتـ̡ تِمو محبت کٔرمٕژ چھِ، تہٕ یٔمِس پَتہٕ پٔکۍمٕتۍ، تہٕ یٔمِس سٍتـ̡ تِمو پٔکۍمٕتۍ، تہٕ یٔمِس سٍتـ̡ تِمو پٔزۍ پٲٹھۍ، تہٕ یٔمِس سٍتـ̡ یِمو پٔزۍ پٲٹھۍ، تہٕ یٔمِس سٍتـ̡ یِمو پٔزۍ کٔرِتھ، تہٕ یٔمِس سٍتـ̡ یِم پٔزۍ پٲٹھۍ، تہٕ یِمن تِم آسن زمینہٕ کِس بُتھِس پیٹھ گُرِ خٲطرٕ۔\n3. تہٕ موت گژھہِ زندگی بجایہ ژارنہٕ یُن تِمن سارِنٕے باقیاتن سٍتـ̡ یُس اتھ بدکار خاندانس منز باقی، یِم تِمن سارِنٕے جاین یِمن میہ ژٔلِمٕژ آسہِ، یێلہِ میہ تِمن ہٕندِس سٍتـ̡ روزان چُھ، خداوند سُند فرماں چُھ ۔\n4.\\tیِہ تہِ چُھہ تِمن وَنُن، یِتھٕ پٲٹھـ̡ خداوند چُھ فرماوان۔ کیا تِم پیٚنہٕ پیٚیہِ، تہٕ وۅتھنہٕ نہٕ؟ کیا سُہ پھیُرِتھ، تہٕ واپس؟\n5.\\tیروشلمکۍ یہ لوک کیازِ چھہِ دٲیمی پتھ کھسنہ سیتۍ واپس؟ تِم چھِ دھوکہٕ دِوان تہٕ واپس یِنہٕ نِش چھِ انکار کران۔\n6.\\tمیہ بوز تہٕ بوزمُت، {مگر} تِمو کٔر نہٕ صحیح: کٲنسہ تہِ اوس نہٕ أمِس پننہِ بدکٲری پیٹھ توبہ کٔرِتھ، وَنُن زِ مے کیا کوٚر ؟ پرٮ۪تھ کانٛہہ گوٚو پننہِ وتہِ کُن، ییٚلہِ گُرۍ جنگس منٛز دٔسۍ دِوان چھُ۔\n7. آ، اسمانس منز چُھ سارِوٕے سٕندِس مُقرر وقتس زانان۔ تہٕ کچھوٕ تہٕ کرین تہٕ نگلہٕ چِھ پننہٕ یِنُک وقت وچھان۔ مگر میانین لوکن چِھ نہٕ خداوند سُند فیصلہٕ زانان۔\n8. تُہۍ کِتھ کٔنۍ چُھہ ونان زِ أسۍ چھِ عقلمند تہٕ خداوند سُند شریعت چُھ اسہِ سٍتـ̡ ؟ لو، یقینا اوس سہ {it} بنیومُت۔ کاتب سُند قلم {چُھ} بیکار۔ {بیکار بنیومُت...: یا، کاتب سند اپز قلم چھہ اپزس پیٹھ کٲم کران}\n9.\\tعقلمند چھِ شرمندہ سپدان، تِم چھِ مایوس تہٕ رٔٹِتھ گٔمٕتۍ: یِمو چُھ خداوند سٕندِس کلامَس رَد کٔرمٕتۍ۔ تہٕ تمن منز کیا حکمت چِھ؟ {دانشمند...: یا، کیا تِم چھا شرمندہ گٔمٕتۍ، وغیرہ} {کیا...: ہیب۔ کتھ چیزچ حکمت}\n10. تێمہِ کِنۍ دِم بہٕ تِہٕنزِ زنانہٕ باقیَن تہٕ تِمن ہٕندِس کھیت دِنہٕ یُس تِمن ہُند وَرث بَناوُن، یێمہِ سٍتـ̡ سارِوٕے کھۄتہٕ بٔڈِس تام چُھہ پرٮ۪تھ أکِس سٍتـ̡ لالچ دِنہٕ آمٕژ، پیغمبر سٕندِ پٲٹھـ̡ پادٕرِس تام تہِ چُھہ پرٮ۪تھ کانہہ اپُز سٍتـ̡ دِنہٕ آمُت۔\n11. تِکیازِ تِمو چُھ میانین لوکن ہٕنزِ کورِ ہُند دکھ رژھ کھنڈ ٹھیک کٔرِتھ ونان زِ امن، امن۔ ییلہ {اتہِ} چھہ نہ کانہہ سکون۔\n12.\\tییلہ تِمو مکروہ کٲم کٔرمٕژ ٲس، کیا تِمن ٲس شرم گٔمٕژ؟ بلکہ تِم ٲسۍ نہٕ کُنہِ تہِ شرمندہ گٔمٕتۍ، تہٕ نہ ہیوٚک تِم شرم کٔرِتھ، تێمہِ مۄکھٕ گژھن تِمن مَنٛز یِم یِمن ہٕندِس یِنہٕ وِزِ یِم یِن دِنہٕ، خداوند چُھ فرماوان۔ {بہٕ کرِ...: یا، اجتماعس منز کرٕ بہٕ کھٮ۪وان}\n13. خداوند چُھ فرماوان: {انگور آسہِ نہٕ انگور تہٕ انجیر کُلِس پیٹھ آسہِ نہٕ انجیر تہٕ پنہٕ وُن گژھہِ ژھٹان۔ تہٕ {یُس چیز میہ تمن دِژمُت} گژھن تمن نِش ختم گژھن۔\n14. أسۍ کیازِ چھہِ خاموش بِہتھ؟ پَنُن پان جمع کٔرِو، تہٕ أسۍ دِژِو دِفٲعی شہرن مَنٛز، تہٕ أسۍ روزو اَتہِ ژھۄپہٕ: کیازِ خداوند سانہِ خداہَن چُھ اسہِ ژھۄپہٕ کٔرِمُت، تہٕ چنہٕ خٲطرٕ چُھکھ آب دِژمُت، کیازِ أسۍ چُھ خداوند سٕندِس خلاف گۅناہ کورمُت۔ {گال: یا، زہر}\n15.\\tأسۍ ژھانڈان سُکُن، مگر کانہہ خیر آو نہٕ تہٕ صحت مند وقتس خٲطرٕ، تہٕ وُچھو مصیبت!\n16.\\tتٔمۍ سٕندِس گُرِ ہٕندِس آوازس سٍتـ̡ بوزنہٕ آمُت: سٲرۍسٕے زمینس لٔج تٔمۍ سٕندِس مضبوٗط گُرِ ہٕنزِ آوازٕ سٍتـ̡ لرزان۔ تِکیازِ تِم آیہ تہٕ زمینہٕ تہٕ اَتھ منز موجود سارِنٕے چیزس کھٮ۪نہٕ آمٕتۍ۔ شہر، تہٕ یِم اتھ منز روزان چھِ۔ {سٲری ...: ہیب۔ امچ مکمل آسن}\n17.\\tیِکیازِ بہٕ سوزٕ توے منزٕ ناگ، کۅکر، یُس نہٕ ژٔلِتھ تہٕ تِم ژٔٹِتھ ژٔٹِھتھ دِنہٕ۔\n18.\\t{ییلہ} بہٕ غمس منز پانس تسلی دِوان اوسس، میون دِل {چھُ} پانس منز بے ہوش۔ {منز: ہیب۔ اَپَن}\n19.\\tوُچھِو میانین لوکن ہٕنزِ کورِ ہٕنزِ فریاد ہٕنز آواز، یُس دور دراز مُلکس منز روزان چُھہ: {کیا چُھ} صییونس مَنٛز خداوند چُھنہٕ؟ {کیا} چھُنہٕ أمِس منز تٔمۍ سُند بادشاہ ؟ تِمو کیازِ چھُ میہ پننہ کھٔرِتھ تصویرن سٍتۍ شرارت دِژمُت، {تہٕ} عجیب بےکار سٍتۍ؟ {تِم...: ہیب۔ تمن ہند ملک یُس دور چُھ}\n20.\\tفصلہٕ چُھہ مُکمل گومُت، تہٕ أسـ̡ چُھہ نہٕ بچاونہٕ آمُت۔\n21. میانین لوکن ہٕنزِ کورِ ہٕندِس زخمس سٍتـ̡ چُھس بہٕ تکلیف دِنہٕ آمُت۔ بہٕ چھُس سیاہ فام۔ حیرانگی چھیہ میہ سیتۍ واٹھ دوان۔\n22.\\t{کیا چھا} گلعادس منز کانہہ بام۔ {کیا تتہِ} چھَا نہٕ کانٛہہ طبیب؟ تیلہِ کیازِ چھُنہٕ میانین لوکن ہٕنزِ کورِ ہُند صحت ٹھیٖک گومُت؟ {بازیافت شدہ: ہیب۔ ہیوٚر گٔیہِ؟}","1. کاش میون کلہٕ آب آسہِ، تہٕ میانہِ أچھ آسہٕ اوٚش ہُند چشمہٕ، یُتھ بہٕ دۅہ راتس پننین لوکن ہٕنزِ کورِ ہٕندِس مارنہٕ خٲطرٕ روُن! {اوہ...: ہیب۔ کُس دِیہِ میون کلہ، وغیرہ}\n2.\\tکاش میہ آسہ بیابانن منز وتہِ روزن والٮ۪ن ہٕنز روزنٕچ جاے ۔ زِ بہٕ گژھہٕ پنٕنۍ لوٗکھ ترٛٲوِتھ، تہٕ تِمن نِش نیرُن! تکیازِ تِم چھِ سٲری زناکار، غدار نفرن ہٕنز مجلس۔\n3.\\tتہٕ تِم چھِ پنٕنۍ زبان نژان یِتھٕ پٲٹھۍ، مگر تِم چھِنہٕ زمینس پیٹھ حقیقتہٕ خٲطرٕ بہادر آسان۔ تِکیازِ تِم چھِ بدی پٮ۪ٹھٕ بدی کُن پکان، تہٕ تِم چھِ نہٕ مےٚ زانان، خداوند چُھ فرماوان۔\n4. تٔمۍ سٕندِس ہمساین ہُند خیال تھاوُن تہٕ کُنہِ تہِ بٲے سٍتـ̡ پٲٹھـ̡ پى۪ٹھ۔ {ہمسایہ: یا، دوس}\n5.\\tتہٕ تِم کرِ پرٮ۪تھ أکِس ہمساین دھوکہٕ دِنہٕ، تہٕ پٔزۍ کتھ کٔرِن نہٕ: تِمو چھِ پنٕنۍ زبان اپُز بولُن ہیٚچھناومٕژ، {تہٕ} گُننہٕ خٲطرٕ تھکھ دِوان۔ {دھوکہٕ: یا، مذاق}\n6.\\tتُہند بستی {چھُ} دھوکہ دہی منز؛ خداوند چُھ ونان زِ دھوکہ دِنہٕ سٍتـ̡ چِھ تِم مےٚ زاننہٕ نِش انکار کران۔\n7. تێمہِ کِنۍ چُھہ لشکرن ہُند رب یِتھٕ پٲٹھۍ ونان، وُچھ، بہٕ کٔرٕ تِم پِلہٕ تہٕ تِمن آزمٲیش۔ تکیازِ بہٕ کِتھ کٔرٕ پننین لوکن ہٕنزِ کورِ ہٕندِ خٲطرٕ؟\n8.\\tتہنز زبان چھیہ تیر نیبر نیران۔ یہ چھہ دھوکہ دِتھ کتھ کران: {اکھ} چھہ پننس ہمساین سیتۍ پننہ ٲسس سیتۍ امن سان کتھ کران، مگر دلس منز چھہ سہ انتظار کران۔ {دلس منز: ہیب۔ امس منز} {تسند انتظار: یا، انتظار کرُن}\n9.\\tکیا بہٕ گژھہٕ نہٕ یمن {چیزن} خٲطرٕ تمن نِش گژھُن؟ خداوند چُھ فرماوان: یِتھِس قومس سٍتـ̡ گژھہِ نہٕ میانہِ روحُک انتقام؟\n10.\\tپہاڑن ہٕندِ خٲطرٕ چُھس بہٕ روُن تہٕ وُپھ کٔرِتھ، تہٕ بیابان ہٕندٮ۪ن بستی ہٕندِس خٲطرٕ چھُس اکھ ماتم کٔرِتھ، تِکیازِ تِم چھِ زالنہٕ آمٕتۍ، یُتھ کانہہ تہِ ہیکہِ نہٕ تِمن منزٕ نیرِتھ۔ نہ ہیکہِ {انسان} چارواین ہٕنز آواز بوزِتھ۔ اسمانٕکۍ جاناوار تہٕ درندٕ دۄشوے ژٔلِتھ ژٔلِتھ۔ تِم گٔیہِ گٔیہِ۔ {بستی: یا، مرگہٕ} {دزمُت: یا، ویران} {دۄشوے...: ہیب۔ کۅکرِ پیٹھہ تہِ وغیرہ}\n11. تہٕ بہٕ بناوٕ یروشلم انبار، {تہٕ} ڈریگن ہُند گۅپھ۔ تہٕ بہٕ بناوٕ یہوداہ ہٕکۍ شہر ویران ، بغٲر کُنہِ بسکین۔ {ویران : ہیب۔ ویرانی}\n12.\\tعقلمند کُس چھہ یُس یہ سمجھ آسہِ؟ تہٕ {سُہ کُس چُھ} یٔمِس رب سٕندِ ٲسِس کتھ کٔرمٕژ، یُس سُہ اعلان کٔرِتھ، یُس زمینہٕ ختم سپدِتھ {تہٕ} بیابان ہٕندۍ پٲٹھۍ، یُس نہٕ کانہہ تہِ نیرِ؟\n13. تہٕ خداوند چُھ ونان، کیازِ تِمو چُھ میٲنۍ شریعت ترٲومٕژ یُس میہ تِمن برونہہ کُن تھوومُت چُھ، تہٕ چُھکھ نہٕ میانہِ آوازِ ہٕنز اطاعت کٔرمٕژ، تہٕ نہ چُھکھ اَتھ مَنٛز پٔکِتھ۔\n14.\\tمگر تم چھہِ پننین دلن ہندِ تخیلس پٔکۍ، تہ بعلیم پٔتۍ، یُس تہند مٲلۍ حضرات تمن ہیچھناوان اوس: {تخیل: یا، ضد داری}\n15. تێمہِ کِنۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھ، یێلہِ چُھ یہِ فرماوان۔ وچھ، بہٕ دِیہ یمن یمن لُکن تہِ، ورم ووڈ سٍتۍ، تہٕ دِوان تِمن چنہٕ خٲطرٕ گالُک آب۔\n16. بہٕ کٔرٕ تِم کافرن مَنٛز تہِ پھٔہلِتھ، یِمن نہٕ تِمن تہٕ تِمن ہٕندِس مٲلِس پتاہ آسہِ، تہٕ بہٕ سوزٕ تِمن پتہٕ تلوار، یوٚت تام بہٕ تِم کھٮ۪نہٕ یِن۔\n17. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب فرماوان، غور کرُن، تہٕ ماتم کرن واجنہِ زنانن بلاوُن، یُتھ زن تِم یِن۔ تہٕ سوز چالاک {زنانہٕ}، تاکہ تم یِن:\n18.\\tتہٕ تِم گژھن جلدی کٔرِتھ، تہٕ اسہِ خٲطرٕ وُپھ کٔرِتھ، یُتھ سانہِ أچھ اوٚش وسان تہٕ سانہِ ٹٲرۍ گژھن آبہٕ سٍتـ̡ وسان ۔\n19.\\tزیون منزٕ چُھہ واے ہٕنز آواز بوزنہٕ یوان، اسہِ کِتھہ پٲٹھـ̡ گٔیہِ خراب! أسۍ چھِ واریاہ پریشان گٔمٕتۍ، تِکیازِ أسۍ چھِ زمینہٕ ترٲومٕژ، تِکیازِ سانٮ۪و مکانو چھِ {اسہِ} کٔرِتھ ژٔٹِتھ دِژمٕژ۔\n20. توتہِ بوزو خداوند سُند کلام، اے زنانہٕ، تہٕ پَنٕنـ̡ کٔرِو تٔمۍ سٕندِس کُنـ̡ ہُند کلام رٔٹِتھ، تہٕ پَنٕنـ̡ کورِ ہٕندِس کُنہِ سٍتـ̡ وُپھ کٔرِتھ ہیچھناوٕنـ̡ تہٕ پرٮ۪تھ أکِس ہمساین ہٕندِس ماتم سٍتـ̡ ہیچھناوٕنـ̡ ۔\n21.\\tتکیازِ موت چُھ سانہِ دارِ منز آمُت، {تہٕ} چُھ سانین محلن منز اژنہٕ یوان، یُس شُرۍ نیبر کُن ژٹنہٕ خٲطرٕ، {تہٕ} نوجوانن سڑکہٕ نِش ژٹنہٕ خٲطرٕ۔\n22.\\tیِتھٕ پٲٹھۍ چھُ خداوند فرماوان زِ انسانن ہٕندِ لاشہٕ تہِ گژھن کھُلہٕ کھہَس پٲٹھۍ، تہٕ فصلہٕ وٲلِس پَتہٕ مُٹھہٕ پٲٹھۍ، تہٕ کانہہ تہِ گژھِ نہٕ جمع کرنہٕ۔\n23. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ دانا {انسان} گژھہِ نہٕ پننہِ حکمتس مَنٛز جلال حٲصل کٔرِتھ، تہٕ نہ گژھہِ طاقتور {انسان} پننِس طاقتس مَنٛز جلال حٲصِل کٔرِتھ، امیر {انسان} گژھہِ نہٕ پنہٕ نِس دولتس سٍتـ̡ جلال حٲصِل کٔرِتھ:\n24. مگر یُس اتھ مَنٛز جلال حٲصل کرُن، یُس سُہ سُہ سمجُن تہٕ زانان چُھ، زِ بہٕ چُھس خداوند یُس زمینس مَنٛز محبت، فیصلہ تہٕ نیکی ہُند استعمال کران چُھ، کیازِ یِمن {چیزن منز} چُھس بہٕ خوش گژھان، خداوند چُھ فرماوان۔\n25. خداوند چُھ ونان زِ بہٕ دِیہٕ سارِنٕے ختنہ کرنہٕ آمٕتۍ سارِنٕے سٍتـ̡ سزا دِنہٕ۔ {سزا: ہیب۔ وزِٹ کٔرِو}\n26. مصر، یہوداہ، تہٕ ادوم، تہٕ عمون تہٕ موآب سٕندِ بچہٕ تہٕ سارِنٕے {یِم} یِم بیابانن مَنٛز روزان چھِ، تِکیازِ سارِنٕے {یِم} قومن {چھِ} ختنہ کرنہٕ آمٕتۍ، تہٕ سارِنٕے اِسرٲیلِیُک گرٕ {چُھ} دِلس مَنٛز ختنہ کرنہٕ آمُت۔ {انتہٲیی منٛز...: ہیب۔ کونن منز ژٹنہٕ، یا تہندِس مَس کُن کٔرِتھ کٔرِتھ}","1. سُہ کلام بوزو یُس خداوند چُھہ تۅہہِ سٍتـ̡ کتھ کران چُھ، اے اِسرٲیلِیُک گَرٕ:\n2. یِتھٕ پٲٹھـ̡ چُھ خداوند فرماوان زِ کُلِس ہٕنز وتھ ہیچھِو نہٕ تہٕ اسمانٕچ نشانہٕ سٍتـ̡ گژھ نہٕ مایوس گژھُن۔ تکیازِ کافر چھہِ تمن نش مایوس۔\n3.\\tلُکن ہٕندِس رسمَس مۅکھہٕ چھُ بےکار: کیازِ {اَکہ} کُلِس ژٹِتھ چھُ، کۅلہٕ سٍتۍ کامہِ سٍتۍ۔ {رسم و رواج...: ہیب۔ قوانین، یا، آرڈیننس چِھ باطل }\n4. تِم چھِ اتھ رۄپہٕ تہٕ سۄنہٕ سٍتۍ سجاوان ۔ تِم چھِ اتھ کیلو تہٕ ہتھوڑیو سۭتۍ گنڈان تاکہ یہِ نہٕ حرکت کٔرِتھ۔\n5.\\tتِم چھِ کھجور کُلِس ہٕندۍ پٲٹھۍسیدٕ مگر کتھ چھِنہٕ کران: تِمن گژھہِ برداشت کرنٕچ ضرورت، تکیازِ تِم ہیکن نہٕ گژھِتھ۔ تِمَن نِش گژھِ نہٕ کھوژُن۔ تِکیازِ تِم ہیکن نہٕ بُرٕ کٔرِتھ، تہٕ نہ چُھ تِمن منز نیکی کرٕنۍ۔\n6.\\tیوت تام نہ کانہہ تہِ چُھہ نہٕ توے ہیو کانہہ تہِ، اے خداوند۔ تُہۍ چھُکھ عظیم، تہٕ تُہند ناو چھُ طاقتس منز عظیم۔\n7. اے قومن ہٕندِس بادشاہس کُس چُھ نہٕ ژےٚ کھوژان؟ تکیازِ یہ چُھہ تۅہہِ سٍتـ̡ تہٕ تِمن ہٕندِس سارِنٕے دٲنِس مَنٛز تہٕ تِمن ہٕندِس سارِنٕے سلطنتن مَنٛز چُھہ نہٕ تۅہہِ ہیوٗ کانہہ تہِ۔ {to...: یا، یہ چُھ ژے پسند}\n8.\\tمگر تِم چھِ سراسر وحشی تہٕ بیوقوف: ذخیرٕ {چُھ} باطل ہُند نظریہ۔ {مجموعی طور پٲٹھۍ: ہیب۔ اکس منز، یا اکی وقتس منز}\n9.\\tرۅپہٕ رۅپھ چھُ ترشِش پٮ۪ٹھٕ تہٕ اُفاز سٕندِ سٍتۍ سۄنہٕ یُس کامہِ سٕنز کٲم چھُ، تہٕ بانی سٕندِس اَتھٕ سٕندِس کامہِ سٍتـ̡ نیوٗل تہٕ جامنی رَنٛگ چھُ تِہُند پَلَو: تِم چھِ سارِنٕے چالاک {مرد} ہٕنز کٲم۔\n10. مگر خداوند چُھ حقیقی خدا، سُہ چُھ زندٕ خدا، تہٕ اکھ ابدی بادشاہ: تٔمۍ سٕندِس قہر سٍتـ̡ گژھہِ زمینہٕ تھرتھراونہٕ، تہٕ قومن ہێکہِ نہٕ تٔمۍ سٕندِس غصہٕ سٍتـ̡ ہێکہِ ہێکان۔ {صحیح...: ہیب۔ خدا حقیقت} {زندٕ خدا: ہیب۔ زندٕ خدا} {ابدی...: ہیب۔ کِنٛگ آف ایٹرنیٹی}\n11. یِتھٕ پٲٹھۍ کٔرِو تُہۍ تِمن وَنُن، یِمو دیوتا یِمو نہٕ آسمانن تہٕ زمینہٕ بنٲومٕتۍ چھِ، تِم گژھن زمینہٕ پیٹھٕ تہٕ یِمن آسمانن تلہ کنہِ ختم گٔژھن۔\n12.\\tتٔمۍ کٔر پننہِ طاقتہٕ سٍتـ̡ زمینہٕ بنوومُت، تٔمۍ کٔر پننہِ عقلہٕ سٍتـ̡ دُنیا قایم تہٕ پننہِ مرضی سٍتـ̡ آسمانس پھٔہلٲومُت۔\n13.\\tییلہ سُہ پنٕنۍ آواز کٔرِتھ چُھہ آسمانس مَنٛز واریاہ آب آسان، تہٕ سُہ چُھ زمینہٕ کِس اندس پیٹھٕ بخارات کھسان۔ سُہ چُھ روٗد سٍتـ̡ بجلی بناوان، تہٕ پنہٕ نِس خزانہٕ منزٕ واو کڈان۔ {کثیر: یا، شور} {سۭتۍ: یا، for}\n14.\\tپریتھ انسان چھہ پننہِ علمس منز وحشی: پریتھ بانی چھہ کھٔنتھ شبیہہ سٍتۍ پریشان گژھان: تکیازِ تمۍ سنز پگھلمت تصویر {چھہ} اپز، تہ {چھہ} چھہ نہ تمن منز کانہہ شاہ۔ {پننس علمس منز وحشی: یا، زاننہٕ کھوتہٕ زیادٕ وحشی}\n15.\\tتِم چھِ بےکار تہٕ غلطین ہٕنز کٲم: تِمن ہٕندِس زیارت وِزِ گژھن تِم فنا گٔژھان۔\n16.\\tیعقوب سُند حصہ {چُھ} تِمن ہیوٗ نہٕ: کیازِ سُہ {چُھ} سارِنٕے {چیزن} ہُند گۄڈنِک۔ تہٕ اسرٲیل چُھ تٔمۍ سٕندِس وراثتٕچ لاٹھ: لشکرن ہُند رب {چُھ} تٔمۍ سُند ناو۔\n17. اے قعلہٕ کِس روزن وٲلۍ، پَنُن مال کٔرِو زمینہٕ منزٕ جمع ۔ {بسکین: ہیب۔ بسکین}\n18. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، وُچھ، بہٕ کٔرٕ یِتھٕ وقتہٕ زمینہٕ کین بسکینن ہٕندِس بسکیٖن سٍتـ̡ ژٔٹِتھ تہٕ تِمن دِلہٕ دِنہٕ یُن، یُتھ تِمن لٔبِتھ تہٕ تِمن ہُند دکھ دِنہٕ۔\n19.\\tافسوس چھہ میہ پننہِ تکلیف دوان۔ میون زخم چھہ خوفناک: مگر میہ ووٚن، پزۍ پاٹھۍ چھہ یہ غم تہ میہ پزِ یہ برداش کرُن۔\n20.\\tمیون خیمہ چُھہ خراب گومُت، تہٕ میٲنۍ سارِنٕے رزٕ گٔیہِ پھُٹۍمٕتۍ: میٲنۍ شُرۍ گٔیہِ میہ نِش نیران، تہٕ تِم چِھنہٕ نہٕ: {اَتہِ} چُھنہٕ کانہہ تہِ یُس میانہِ خیمہ پھٔہلاونہٕ خٲطرٕ، تہٕ میٲنۍ پردٕ لاگنہٕ خٲطرٕ۔\n21.\\tیِکیازِ پادری چھِ وحشی بٔنِتھ تہٕ یِمو نہٕ خداوند سٕنز تلاش کٔرمٕژ، تێمہِ مۄکھٕ گژھن نہٕ تِم ترقی کٔرِتھ، تہٕ تِہٕندِ سارِنٕے ریوٕڈ گژھن پھٔہلِتھ ۔\n22.\\tوُچھِو، بروٹُک شور آو تہٕ شُمٲلی مُلکہٕ منزٕ آو اکھ بٔڈ ہنگامہٕ، یہوداہ ہٕندِس شہرس ویران کرنہٕ خٲطرٕ، {تہٕ} ڈریگن ہُند گۅپھ۔\n23.\\tاے خداوند، میہ چھیہ پتاہ زِ انسان سنز وتھ چھیہ نہ پانس منز: {یہ} چھہ نہ انسانس منز یُس پننین قدمن پیٹھ پکناوان چھہ۔\n24. اے خداوند، میہ کٔر صحیح، مگر فیصلہٕ سٍتـ̡ نہ پننہِ شرارتس منز، نہ ژیہ میہ کُنہِ کُ {انن...: ہیب۔ کم کٔرِو مے}\n25. پَنُن غصہٕ تراوُن یِمن نہٕ تۅہہِ زانان چھِ، تہٕ تِمن خاندانن پیٹھ یِم نہٕ تُہُند ناو ونان چھِ، تِکیازِ یِمو چُھ یعقوب کھٮ۪مُت، تہٕ کھٮ۪وُکھ تہٕ تٔمۍ سُند بَسٲیِل چھُکھ ویران کٔرِمُت۔","1. سُہ کلام یُس خداوند سٕندِ طرفہٕ یرمیاہ ہس تام آمُت چُھ، یُس ونان چُھ،\n2. یێمہِ عہدٕچ کتھ بوزو، تہٕ یہوداہ کین لوکن تہٕ یروشلم کین بسکینن سٍتـ̡ کتھ کرٕنـ̡ ۔\n3. تہٕ تِمن وَنُن زِ یِتھٕ پٲٹھۍ چُھ اسرٲیلُک خداوند خدا۔ یُس نہ امہِ عہد کین کلامَن ہٕنز اطاعت کرِ، سُہ گژھہِ لعنت،\n4.\\tیُس میہ تُہند آباؤ اجداد دۅہہ حکم دِیُتمُت {یُس} بہٕ تِم مصرٕکہِ سرزمینہٕ منزٕ ششتٕرِ بھٹہٕ منزٕ نیبر کٔرِتھ، وونُن، میانہِ آوازِ ہٕنز فرمانبرداری، تہٕ تِمن کٔرِو تِمن ہُند یُس بہٕ چُھس حُکُم کٔرِتھ، یِتھٕ پٲٹھۍ بٔنِتھ تہٕ بہٕ بنہٕ تُہند خدا۔\n5. یُس بہٕ چُھس پننین مٲلن سٍتـ̡ حلف کورمُت چُھ، یُس تِمن دۄدٕ تہٕ ماچھ سٍتـ̡ وسان زمینہٕ دِنہٕ، یِتھ کٔنۍ از چُھ۔ اَمہِ پتہٕ دیت میہ جواب، تہٕ وونُن، اے خداوند۔ {تو...: ہیب۔ آمین}\n6. اَمہِ پَتہٕ ووٚن خداوند مےٚ زِ یہوداہ کِس شہرَن تہٕ یروشلم کِس سڑکَن مَنٛز یِم سارِنٕے کلامَن ہُند اعلان کٔرِو، تہٕ وَنُن زِ یَتھ عہدٕکِس کلامَس بوزو، تہٕ یِم کٔرِو یِم کٔرِو۔\n7.\\tکیازِ میہ کٔر تِمن سٍتـ̡\n8. توتہِ کٔر نہٕ تِمو اطاعت کٔرِتھ، تہٕ کٔرٕکھ کَن کُن، بٔلکہِ کٔرٕکھ پرٮ۪تھ أکِس پَنٕنِس بد دِل کِس خیالس مَنٛز، اَمہِ مۄکھٕ بہٕ اَتھ عہدٕکۍ سٲری کلام، یُس مےٚ حُکُم دِیُتمُت چھُ۔ مگر تِمو کٔر نہٕ۔{تخیل: یا، ضد ]\n9. تہٕ خداوند ووٚن مے زِ یہوداہ کین لوکن تہٕ یروشلم کین بسکینن مَنٛز چُھ اکھ سٲزش لبنہٕ آمٕژ۔\n10.\\tتِم چھِ پننین آباؤ اجدادن ہٕندِس بدکارس کُن واپس پھیرنہٕ آمٕتۍ، یِمو میانہِ کتھ بوزنہٕ نِش انکار کٔر۔ تہٕ تِم گٔیہِ باقین دیوتاہن پَتہٕ تِہنز خدمت کرنہٕ خٲطرٕ: اسرائیلُک گرٕ تہٕ یہوداہ کِس گرن پھُٹروو میون عہد یُس میہ تِہندین مٲلن سٍتـ̡ کورمُت۔\n11. تێمہِ کِنۍ چُھ خداوند فرماوان، وُچھِو بہٕ تِمن پیٹھ بُردی انان، یُس نہٕ تِم بچِتھ ہیکن۔ تہٕ یودوَے تِم میہ کُن فریاد کٔرِتھ، بہٕ بوزٕ نہٕ تِمن ہٕنز۔ {فرار گژھنہٕ خٲطرٕ: ہیب۔ نیبر نیرُن}\n12. اَمہِ پَتہٕ گژھن یہوداہٕکۍ شہر تہٕ یروشلمٕکۍ بسکیٖن دِنہٕ یِن، تہٕ تِمن دیوتاہن نِش کٔرِن یِمن اگربتی دِنہٕ یِوان، مگر تِم ہیکن نہٕ تِمن مصیبت وِزِ بچاوٕنۍ۔ {پریشانی: ہیب۔ برائی}\n13. تکیازِ {مطٲبق} چُھہ تُہند دیوتا، اے یہوداہ۔ تہٕ {مطٲبق} یروشلم کین سڑکن ہند تعداد چُھ تم قربان گاہ لگٲومٕژ {یہ} شرمناک چیز، {حتیٰ کہ} قربان گاہ تہٕ بعلس تام بخور زالنہٕ خٲطرٕ۔ {شرم آور...: ہیب۔ شرم}\n14. تێمہِ کِنۍ کٔرِو نہٕ یِمن لُکن ہٕندِ خٲطرٕ دُعا تہٕ دُعا تُلِتھ تہٕ تِمن ہٕندِ خٲطرٕ کُنہِ دُعا تہٕ دُعا تُلِتھ تہٕ بہٕ بوزٕ نہٕ تِمن ہٕندِس مُشکِلَس مۅکھہٕ دُعا ۔ {پریشانی: ہیب۔ برائی}\n15.\\tمیانہِ معشوقہ کیا چُھ میٲنِس گرس مَنٛز کٔرِتھ، {وُچھِتھ} تٔمۍ کٔر واریاہن سٍتـ̡ بے حیائی کٔرمٕژ، تہٕ پاک ماز چُھہ ژے نِش نیران۔ ییلہ تہۍ بد کار کران چھِو، تیلہِ چھِو توہۍ خوش گژھان۔ {کیا...: ہیب۔ میٲنس گرس منز کیا چُھہ میٲنس معشوقس {ییلہ...: یا، ییلہ چانۍ بد کار آسہِ}\n16.\\tخداوند چُھہ تُہند ناو وَنُن، اَکھ سبٕز زیتون کُل، گورٕ تہٕ رٔژ پھُلُک کُل، اَمہ سٍتـ̡ چُھہ اَتھ سٍتـ̡ نار دِژمُت، تہٕ اَمہ سٕنزِ لنجہِ پھُٹمٕژ۔\n17.\\tلشکرن ہٕندِس خداوند سٍتـ̡ یُس تۅہہِ کٔرِتھ چُھہ تۅہہِ سٍتـ̡ بد کار کورمُت، یُس تِمو پانس سٍتـ̡ بعلس بخور دِنہٕ سٍتـ̡ شرارت دِنہٕ خٲطرٕ کورمُت چُھ۔\n18. تہٕ خداوند چُھ مے اَتھ مُتلق علم دِژمُت، تہٕ بہٕ چُھس پتاہ تہٕ تێلہِ ہٲو مے تِہٕندِ اعمال ہاونہٕ۔\n19.\\tمگر بہٕ اوسُس کۅکرِ ہٕندۍ پٲٹھۍ{یا} اکھ داند {یُس} ذبح کرنہٕ خٲطرٕ اننہٕ آمُت۔ تہٕ مےٚ ٲس نہٕ خبر زِ تِمو چھِ میٲنِس خٕلاف سازش کٔرمٕژ، {ونان}، أسۍ کرو کُلِس امہِ کِس پھلہٕ سٍتۍ تباہ تہٕ أسۍ ژٔٹِو أمِس زندٕ سٕندِ سرزمینہٕ نِش ژٹِتھ، یُتھ نہٕ تٔمۍ سُند ناو یاد روزُن۔ {کُل...: ہیب۔ تٔمۍ سٕنزِ روٹی سٍتۍ ڈنٹھ}\n20. مگر، اے لشکرن ہٕندِس خداوند، یُس نیکی سٍتـ̡ انصاف کٔرِتھ، یُس لگام تہٕ دِلٕچ کوشش کران چُھ، بہٕ وُچھـ̡ تِمن سٍتـ̡ پنُن انتقام: کیازِ مے چُھس ژے سٍتـ̡ پنُن مقصد ظٲہر کورمُت۔\n21. تێمہِ کِنۍ چُھ یِتھٕ پٲٹھـ̡ انتھوتھ کِس انسانس ہُند خداوند یُس تُہٕندِ زُو ژھاران چُھ، یێلہِ چُھہ تُہٕندِس زُو سٍتـ̡ نِش نِش پیشن گویی کٔرِتھ، یێلہِ نہٕ ژٕ مٔرِو نہٕ سانہِ اتھہٕ سٍتـ̡ مَرُن:\n22.\\tتێلہِ چُھہ یِتھٕ پٲٹھـ̡ لشکرن ہُند رب وَنُن، وُچھِو بہٕ تِمن سزا: جوان گژھن تلوار سٍتـ̡ مرنہٕ۔ تہند نیچو تہٕ کورِ گژھن قحط سٍتـ̡ مرن: {سزا: Heb. وزِٹ کٔرِو}\n23.\\tتہٕ یِمن ہُند کانہہ تہِ بُرٕ روزُن، تکیازِ بہٕ کرٕ انتھوتھ کین لوکن سٍتـ̡ یِمن ہٕندِس یِنہٕ وٲلِس ؤریس سٍتـ̡ بُرٕ ۔","1. اے خداوند، ییلہ بہٕ ژے سٍتـ̡ درخواست کران چُھس، توتہِ چُھس بہٕ ژے سٍتـ̡ پننین فٲصلن مُتلق کتھ کرٕنـ̡ ۔ {کیازِ} تِم سٲری چھِ خۄش یِم واریاہ غداری سان کٲم کران چھِ؟ {کَتھ...: یا، کَتھ کٔرِو تُہٕندِس معاملَس مَنٛز}\n2. ژے چُھہ تِم ووتمُت، آ، تِمو چُھ موٗل رٔٹمٕتۍ: تِم چِھ پھل دِوان، آ، تِم چِھہ پھل دِوان: تہٕ چُھہ تِہٕندِس لگام نِش دور۔ {تم چِھ بڑان: ہیب۔ تِم چِھ گَژھان}\n3. مگر اے خداوند، ژے چھے مے زانان: ژے چھے مے وُچھمٕژ، تہٕ کٔرٕن میون دِل پانس کُن آزماونہٕ: تِم کٔڑِکھ ذبح کرنہٕ خٲطرٕ کٔڑِتھ تہٕ ذبح کرنہٕ خٲطرٕ تیار کٔرِتھ۔ {کُن...: ہیب۔ توے سٍتۍ}\n4. زمینس منز روزن والین ہٕنزِ بدکاری خٲطرٕ کٲتِس کالس روزِ زمینہٕ ماتم تہٕ پرٮ۪تھ کھہٕچ جڑی بوٹی مرزاونہٕ۔ جانور چھِ کھٮ۪نہٕ یوان، تہٕ جاناوار؛ تِکیازِ تِمو ووٚن زِ سُہ وُچھِ نہٕ سون ٲخری انجام وُچھان۔\n5.\\tاگر ژیہ پیدل سٍتـ̡ ژٔلِتھ تہٕ تِمو تُہٕندِس سٍتـ̡ تُہٕندِس سٍتـ̡ کِتھہ کٔرِتھ ہُند مقابلہ کٔرِتھ؟ تہٕ {اگر} امن کِس سرزمینس منز، {یَتھ مَنٛز} تۅہہ بھروسہٕ کٔرِتھ، {تِمو چُھہ تُہہِ تھکھ دِژمُت}، تیلہِ کِتھہٕ کٔرِو ژے اردن کِس ورمَس مَنٛز؟\n6.\\tتہٕ تُہٕندِس بٲے تہٕ تُہٕندِس مٲلہِ سٕندِس گرس سٍتـ̡ تہِ چُھہ تۅہہِ سٍتـ̡ غدٲری کٔرمٕژ۔ آ، تِمو چُھ تۅہہِ پتہٕ واریاہ بُلاونہٕ آمُت: تِمن ہُند پژھ نہٕ پٲٹھۍ، حالانکہ تِم چھِ تۅہہِ سٍتۍ نیک کتھ کران۔ {تِمو چُھ بلاومُت...: یا، تِمو روو پورٕ پٲٹھۍ} {منصفانہ...: ہیب۔ اصل چیز}\n7. میہ چھہ پنُن مکانہ ترٲومُت، میہ تروو پنُن وراثت۔ مے دِژ پننہ روحُک عزیز تٔمۍ سٕندِس دُشمنن ہٕندِس اتھس منٛز۔ {پیاری ...: ہیب۔ دی لول}\n8.\\tمیٲنۍ وراثت چھُ میانہِ خٲطرٕ جنگلَس منز شیر سٕندِ پٲٹھۍ۔ یہ چھہ میہ خلاف فریاد کران: لہذا چھہ میہ اتھ سیتۍ نفرت۔ {کرُن...: یا، چُھس کرٛٮ۪کھ: ہیب۔ تٔمۍ سٕنٛز آواز دِیُن}\n9.\\tمیون ورثہ {چھُ} میانہِ خٲطرٕ {as} اکھ داغدار جاناوار، جاناوار اندۍ {چھِ} أمِس خلاف۔ یِمو کٔرِو میدانٕکۍ سارِنٕے درندٕ جمع کٔرِتھ، یِمو کھٮ۪نہٕ خٲطرٕ۔ {سپیکلڈ: یا، ٹیلونڈ} {آو کُن: یا، تمن کُن یِن}\n10. واریاہو پادریو چُھ میون انگور تباہ کورمُت، تِمو چُھ میون حصہٕ کھۄرن تل لٔگِمُت، تِمو چُھ میون خۄشگوار حصہٕ ویران بیابان بنوومُت۔ {خوشگوار...: ہیب۔ خواہشُک حصہٕ}\n11.\\tتِمو چھُ یہِ ویران کوٚرمُت، {تہٕ ویران آسنہٕ کِنۍ} چھُ میانہِ خٲطرٕ ماتم کران۔ سورے زمین چھیہ ویران کرنہ آمژ، تکیازِ کانہہ تہِ انسان چھہ نہ دلس پیٹھ تراوان۔\n12.\\tبدکار چھِ بیابان مٔنزۍ سارنٕے تھدٮ۪ن جاین پیٹھ آمٕتۍ: کیازِ خداوند سٕنز تلوار گژھہِ زمینہٕ کِس {أکِس} اندس پیٹھٕ زمینہٕ کِس {بییِم} اندس تام کھٮ۪نہٕ: کُنہِ تہِ مازس گژھہِ امن حٲصِل۔\n13. تِمو چُھ کٕنُک ووومُت، مگر تِمو چُھ پانس دَگ دِژمُت، {مگر} چُھہ نہٕ فٲیدٕ حٲصِل کٔرِتھ، تہٕ تِم گژھن خداوند سٕندِ شدید غصہٕ سٍتـ̡ تُہٕندِس مٲلِس سٍتـ̡ شرمندٕ۔ {تِم کرِن: یا، تم کرٕن}\n14. یِتھٕ پٲٹھۍ چُھ خداوند میانین سارِنٕے بد کار ہمساین خلاف فرماوان، یُس میہ پننین لوکن اسرٲیلِس وراثتس منز دِژمُت چھُ۔ وچھ بہٕ تِمن ہٕنزِ زمینہٕ منزٕ کٔڈِتھ تہٕ یِمو منزٕ یہوداہ سُند گرٕ کٔڈِتھ کٔڈِتھ۔\n15. تہٕ یِہ سپدِ، اَمہِ پَتہٕ بہٕ یِم ژٔٹِتھ تہٕ بہٕ واپس، تہٕ تِمن پیٹھ رحم کرٕ تہٕ یِمن دُبارٕ اَننہٕ، پرٮ۪تھ کانہہ انسان پنہٕ نِس میراثس کُن، تہٕ پرٮ۪تھ کانہہ انسان پنہٕ نِس سرزمینس کُن۔\n16. تہٕ یێلہِ تِم میانہِ لُکن ہٕنزِ وتہٕ ہیٚچھناوٕن، میانہِ ناوٕ سٍتـ̡ قَسم کٔرِن، خداوند چُھہ زندٕ۔ یِتھ کٔنۍ تِمو میانین لوٗکن بعل سُند قسم کھُن ہیچھناوُن۔ تیلہ گژھن تم میانین لوکن منز تعمیر کرنہٕ۔\n17. مگر اگر تِم اطاعت کرن نہٕ، بہٕ کٔرٕ تتھ قومس مکمل طور تُلتھ تہٕ تباہ کرُن، خداوند چُھ فرماوان۔","1. یِتھٕ پٲٹھـ̡ چُھ خداوند میانہِ خٲطرٕ ونان، گژھ تہٕ اَنِن کُن تہٕ تھووُن نہٕ آبس مَنٛز۔\n2.\\tتێلہِ لوٚگ میہ خداوند سٕندِ کلامٕ مُطٲبق اکھ گرڈ، تہٕ تھووُن پننین کمرن پیٹھ۔\n3. تہٕ خداوند سُند کلام آو میہ نِش دوٚیمہِ لٹہِ وونُن،\n4.\\tسُہ کمر رٔٹِتھ یُس تۅہہِ ہٕندِس کمرس پیٹھ چُھ، تہٕ وۅتھِتھ گژھِو فرات کُن تہٕ تتہِ تھٲوِو کنہِ کُنہِ سوراخس منز۔\n5. تہٕ بہٕ گۆو تہٕ یہ فرات سٍتـ̡ ژوٗرِ تھووُن، یُتھ زن خداوند میہ حُکُم دِیُت۔\n6. تہٕ واریہو دۅہو پَتہٕ سپُد یہِ زِ خداوند ووٚن مےٚ، وُتھ، فرات کُن گژھ تہٕ تتہِ نِش کٔرِو سُہ بند، یُس میہ ژے اتہِ ژوٗرِ تھاونُک حُکُم دِتمُت اوس۔\n7.\\tامہ پتہ گۆو میہ فرات کُن تہ کھنُن تہ کٔرِتھ تہٕ وُچھِتھ گٔیہِ گٔرِتھ تہٕ کُنہِ تہِ کُنہِ فٲیدٕ مُطٲبِق۔\n8. پتہٕ آو خداوند سُند کلام میانہِ نِش وَنُن،\n9. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ یِتھٕ پٲٹھـ̡ بہٕ یہوداہ سُند غرور تہٕ یروشلمُک بۆڈ غرور۔\n10.\\tیِم بد کار لُکھ یِم میانہِ کتھ بوزنہٕ نِش انکار کران چھِ، یِم پنہٕ نِس دِل کِس تصورس منز پکان چھِ، تہٕ باقین دیوتاہن پَتہٕ پکان چھِ، تِہنز خدمت کرنہٕ خٲطرٕ، تہٕ تِمن ہٕنز عبادت کرنہٕ خٲطرٕ، گژھِ اَتھ گٔنڈِس ہٕندۍ پٲٹھۍ، یُس نہٕ کُنہِ کُنہِ خٲطرٕ اصل چھُ۔ {تخیل: یا، ضد}\n11. یِتھٕ پٲٹھـ̡ چُھہ اِنسان سٕندِس کمرس سٍتـ̡ ژٔٹِتھ چُھہ، تِتھے پٲٹھـ̡ چُھہ میہ سارِوٕے اِسرٲیلِیُک تہٕ یہوداہ سُند پورٕ گرٕ پانس سٍتـ̡ ژٔٹِتھ دِژمُت، خداوند چُھ فرماوان۔ تاکہ تِم گژھن میانہِ خٲطرٕ أکِس قومہٕ خٲطرٕ، تہٕ أکِس ناو، تہٕ تعریفٕ خٲطرٕ تہٕ عظمتٕکۍ خٲطرٕ، مگر تِم بوزان نہٕ۔\n12. تێمہِ کِنۍ کٔرِو تِمن سٍتـ̡ یہِ لفظ کتھ کرنہٕ۔ یِتھٕ پٲٹھـ̡ چُھ اسرٲیلُک خداوند خداوند ونان زِ پرتھ بوتلہٕ گژھہِ شرابہٕ سٍتـ̡ بٔرِتھ بٔرِتھ تہٕ تِم وَنُن تۅہہِ پٲٹھـ̡ پى۪ٹھـ̡\n13.\\tتێلہِ کٔرِو تِمن وَنُن، یِتھٕ پٲٹھـ̡ چُھہ خداوند فرماوان، یێلہِ بہٕ دٲیود سٕندِس تختس پیٹھ بِہِتھ بادشاہن تہٕ پادٕر، پیغمبرن تہٕ سارنٕے بسکیٖنن شرابہٕ سٍتـ̡ بٔرِتھ بٔرِتھ۔\n14. تہٕ بہٕ کرٕ تِمن اَکھ أکِس خٕلاف، مٲلِس تہٕ نیچوۍ تہِ یکوٹہٕ، خداوند چُھ ونان زِ بہٕ کَرٕ نہٕ رحم کَرُن، نہ بخشہٕ تہٕ رحم کَرٕن، مگر کٔرٕ تِمن تباہ کرنہٕ۔ {اکھ...: ہیب۔ اکھ انسان پننس بٲیس خلاف} {مگر...: ہیب۔ تمن تباہ کرنہٕ نِش}\n15.\\tبوزو تہٕ بوز تہٕ بوزُن؛ ناز گژھ نہٕ: کیازِ خداوند چُھ کتھ کٔرمٕژ۔\n16.\\tخداوند خدایہ سُند جلال دِیُو، امہ برونہہ زِ سُہ انہِ گوٚٹ پٲدٕ سپدِ، تہٕ یێلہِ تہٕ گاش ژھانڈنہٕ وِزِ سُہ کرِ سُہ موتُک ژھایہِ بَناوُن، {تہٕ} بناوُن سُہ موتُک ژھایہِ بناوُن، {تہٕ} بناوُن سٮ۪ٹھاہ انہِ گوٚٹ۔\n17.\\tمگر اگر نہ یہ بوزو، میون روح روو پننہِ غرور خٲطرٕ پوشیدہ مقامن منز۔ تہٕ میٲنۍ أچھ وَنُن دَگ تہٕ اوٚش وَسُن، کیازِ خداوند سُند ریوڑ چُھ قٲد کرنہٕ آمُت۔\n18.\\tبادشاہس تہٕ ملکہِ وَنُن، بِہِتھ کٔرِو عاجزی تہٕ تُہٕندِس جلال ہُند تاج تہِ یِنہٕ خٲطرٕ۔ {پرنسپلٹیز: یا، ہیڈ ٹایر}\n19.\\tجنوبٕکۍ شہر گژھن بند کرنہٕ یِن، تہٕ کانہہ تہِ گژھِ نہٕ یلہٕ یِنہٕ: یہوداہ یِیہِ سارِنٕے یِمن ہٕندِس قٲد نِنہٕ یُن، یہِ گژھہِ پوٗرٕ پٲٹھۍ قٲد کرنہٕ۔\n20. پَنٕنۍ أچھ تُلِتھ تہٕ وُچھِو تِم یِم شُمالہٕ کِنۍ یِوان چھِ: کَتہِ چھُ سُہ ریوڑ {یُس} ژےٚ دِنہٕ آمُت، چانہِ خوبصوٗرت ریوُن؟\n21.\\tییلہ سہ ژیہ سزا دِیہِ تہِ کیا ونُن؟ تکیازِ ژے چھکھ تمن کپتان بنُن ہیچھناومُت، تہٕ پانس پیٹھ سردار بنُن: کیا غم نِش نِنہٕ ژے زنانہٕ ہٕندۍ پٲٹھۍ؟ {سزا: Heb visit upon}\n22. تہٕ اگر ژے پننِس دِلس منز ونان چھِ، یِم چیز کیازِ آیہ میہ پیٹھ؟ تۅہہِ ہٕنزِ بدکاری ہٕنز عظمت، تۅہہِ ہٕندِس کھورِ ہٕندِس کھورِ ہٕندِس سٍتـ̡ گٔیہِ۔ {بَناونہٕ آمُت...: یا، یِیہِ تشددٕ سان نِنہٕ}\n23. کیا ایتھوپِین ہیکہٕ پنُن مٕسلہٕ بدلٲوِتھ، یا سٕہہ سٕہہ پنٕنۍ داغ؟ {تیلہِ} تہِ گژھ تم نیکی کٔرتھ، یُس بدی کرنک عادت آسہِ۔ {عادت: ہیب۔ ہیچھناونہٕ آمُت}\n24.\\tتێلہِ کٔرٕ بہٕ یِم بیابان کِس واو سٍتـ̡ ژٔلِتھ ۔\n25. یہِ چُھہ تُہُند حصہٕ، میانہِ نِش چُھہ تُہٕندِس پیمانس ہُند حصہٕ، خداوند چُھ فرماوان۔ تکیازِ ژے چھکھ میہ مٔشِد گومُت، تہٕ اپزس پیٹھ بھروسہ کورمُت۔\n26. تێمہِ کِنۍ کٔرٕ بہٕ چانہِ بُتھِس پیٹھ چانۍ لۅتہٕ لٔگِتھ تہٕ چانۍ شرم ظٲہر گژھہِ۔\n27.\\tمیہ وچھ چانۍ زنا تہ چانۍ بے حیائی تہ چانۍ بے حیائی تہ کھاہن منز بالن پیٹھ تہِ چھیہ چانۍ بدکاری وچھمژ۔ اے یروشلم! کیا ژٕ گژھ نہٕ پاک کرنہٕ؟ {یہِ کَر} اَکہِ لٹہِ {بَن}؟ {ییلہ...: ہیب۔ کَمہِ پتہٕ؟}","1. خداوند سُند کلام یُس یرمیاہ ہس نِش کمی مُتلق آو۔ {کمی: ہیب۔ کُنہِ کتھہِ ہٕندِس کلام، یا، پابندی}\n2. یہوداہ چُھ ماتم کران، تہٕ اَمہِ کِس دروازٕ چِھہ سُہ سُہ گٔژھان۔ تِم چھِ زٔمیٖنس تام کرٛیٚہنہِ؛ تہٕ یروشلمُک فریاد چُھ ہیوٚر گومُت۔\n3. تہٕ تِہندیو رئیسَو سوٗزۍ پنٕنۍ لۄکٕٹۍ آبَس کُن: تِم آیہِ کھۄدَن کُن، {تہٕ} لوٚبُکھ نہٕ آب ۔ تِم آیہ پنٕنۍ بانہٕ خٲلی ہٮ۪تھ واپس۔ تِم گٔیہِ شرم تہٕ پریشان تہٕ کوٚرُکھ پنُن کلہٕ تھوٚپ۔\n4.\\tکیازِ زمینہِ چُھہ چُھہ ژٔٹِتھ، تکیازِ زمینہِ منز اوس نہٕ روٗد پیوٚو، ہل والیو گٔیہِ شرم، تِمو کٔر کلہٕ تھوٚپ۔\n5.\\tآ، ہِندِ تہِ کٔر کھہَس منز، تہٕ ترووُن {یہ}، تکیازِ اَتہِ اوس نہٕ گاسہٕ۔\n6.\\tتہٕ جنگلی گَرٕ گٔیہِ تھدٮ۪ن جاین پیٹھ کھڑا، تِمو کٔر ڈریگن ہٕندۍ پٲٹھۍ واو نِش ۔ تہنز أچھ گٔیہٕ ناکام، تکیازِ {اتہِ} اوس نہٕ گاسہٕ۔\n7. اے خداوند، یێلہِ تہِ سانہِ گناہ اسہِ خلاف گوٲہی دِن، تێہہ کٔرِو پننہِ ناوٕ خٲطرٕ تہِ کٔرِتھ، تکیازِ سانہِ پتھ کُن چھِ واریاہ زیادٕ۔ أسۍ چھِ ژےٚ خٕلاف گۅناہ کٔرمٕژ۔\n8.\\tاے اسرٲیلٕچ وۅمید یُس مصیبت وِزِ نجات دِنہٕ وول چھُ، ژے کیازِ آسُکھ زمینس مَنٛز اجنبی تہٕ اکھ وَتھ بٔنِتھ یُس أکِس رٲژ روزنہٕ خٲطرٕ پھیُرِ؟\n9.\\tژیہ کیازِ گژھہِ اکھ طاقتور انسان یُس نہ بچٲوتھ ہیکو؟ توتہِ چُھ، اے خداوند، اسہِ منز، تہٕ اسہِ چُھہ چانہِ ناوٕ سٍتـ̡ وننہٕ یوان۔ اسہِ تراوو نہٕ۔ {أسۍ...: ہیب۔ تُہند ناو چُھ اسہِ پیٹھ پکارنہٕ آمُت}\n10. یِتھٕ پٲٹھـ̡ چُھ خداوند یِمن لُکن سٍتـ̡ ونان، یِتھٕ پٲٹھـ̡ چُھہ یِمن ہٕندِس قدمس رُکاونہٕ آمُت، تێمہِ مۄکھٕ چُھہ نہٕ خداوند تِمن قبوٗل کَران۔ سُہ کرِ وۅنۍ تِہٕنزِ بدکاری یاد، تہٕ تِمن ہٕندِس گۅنہن ہُند دور۔\n11. اَمہِ پتہٕ ووٚن خداوند مےٚ زِ یِمن لُکن ہٕندِ خٲطرٕ کٔرِو نہٕ یِمن ہٕنزِ بھلائی خٲطرٕ دُعا۔\n12. ییلہِ تِم روزٕ روزان چھِ، بہٕ بوزٕ نہٕ تِہُند فریاد ۔ تہٕ ییلہ تم زالنہٕ نذرانہ تہٕ نذر پیش کرن، بہٕ کرٕ نہٕ تم قبول: مگر بہٕ کٔرٕ تم تلوار سٔتۍ، قحط تہٕ وباہن سۭتۍ۔\n13. اَمہِ پتہٕ ووٚن مے، آہ، خدا! وچھو پیغمبرن تمن ونان زِ تم وچھو نہ تلوار تہ نہ گژھہِ قحط۔ مگر بہٕ دِیہ ژیہ یَتھ جایہِ یقینی سکون۔ {یقین دِنہٕ...: ہیب۔ پزر ہُند امن}\n14. تێمہِ پَتہٕ وۆن خداوند مےٚ، پیغمبرن ہٕنز پیشن گویی چھے میانہِ ناوٕ سٍتـ̡ ، مے چُھہ نہٕ تِمن سٍتـ̡ سوزمُت، تہٕ نہ چُھس تِمن سٍتـ̡ حُکُم کورمُت، تہٕ تِمن سٍتـ̡ چُھہ نہٕ تِمن سٍتـ̡ کتھ کٔرمٕژ۔\n15. تێمہِ کِنۍ چُھ خداوند تِمن پیغمبرن مُتلق یِم میانہِ ناوٕ سٍتـ̡ پیشن گویی کران چِھ، تہٕ مے سوزمُت نہٕ تِم تہٕ توتہِ چھِ تِم ونان زِ تلوار تہٕ قحط گژھِ نہٕ یتھ زمینس مَنٛز آسُن۔ تلوار تہٕ قحط سٍتـ̡ گژھن تِم پیغمبرن ختم کرنہٕ۔\n16. تہٕ یِمن لُکھ یِمن سٍتـ̡ تِم پیشن گویی کٔرِتھ یِن قحط تہٕ تلوار سٍتـ̡ یروشلم کین سڑکن مَنٛز کڑنہٕ۔ تہٕ تِمن آسہِ نہٕ تِمن دفن کرنہٕ خٲطرٕ، تِمن ہٕنزِ خانٛدارِن، تہٕ تِہٕنزِ نیچوِ، تہٕ تِہٕنزِ کورِ دفن کرنہٕ خٲطرٕ، تِکیازِ بہٕ تراوٕ تِمن پیٹھ تِہُند بدکار ۔\n17.\\tتێلہِ کٔرِو تِمن سٍتـ̡ یہِ کتھ ونُن۔ میانین اچھن گژھن رٲژ دۅہس اشہ سٍتۍ، تہٕ گژھن نہ بند گژھن: تکیازِ میانہِ لوکٕچ کنوارِ کورِ چھے سٮ۪ٹھاہ زبردست دھکہٕ سٍتـ̡ پھُٹمٕژ۔\n18.\\tاگر بہٕ میدانس منز نیرِ، تیلہِ وُچھِو تلوار ہیتھ مارنہٕ آمُت! تہٕ اگر بہٕ شہرس منز اژان چھُس، تیلہِ وُچھِو تِم یِم قحطس سٍتـ̡ بیمار چھِ! آ، رسول صلی اللہ علیہ وآلہ وسلم تہ پادری دۅشوے چھہِ تتھ زمینس منز گژھان یُس نہ تم زانان چھہِ۔{گژھو...: یا، کُنہِ زمینس خلاف تجارت کرُن، تہ انسان چھہ نہ اتھ تسلیم کران}\n19.\\tکیا ژے چھُکھ یہوداہ سراسر رد کورمُت؟ کیا تُہند روح چُھ صیونس سۭتۍ نفرت کٔرمٕژ؟ ژے کیازِ دیت اسہِ مار، تہٕ اسہِ خٲطرٕ چُھنہٕ کانہہ شفا؟ أسۍ ژھانڈ امن، تہٕ {اتہِ} چھُنہٕ کانہہ خیر ۔ تہٕ شفا کِس وقتس خٲطرٕ، تہٕ وُچھِو مصیبت!\n20. اے خداوند، أسـ̡ چُھہ پنُن بد کاری تہٕ پننین آباؤ اجدادن ہٕنزِ بدکاری ہُند اعتراف کران، کیازِ أسـ̡ چُھہ تۅہہِ سٍتـ̡ گۅناہ کورمُت۔\n21.\\tپننہِ ناوٕ خٲطرٕ مہٕ کرو نہٕ پننہِ عظمتُک تختس بے عزتی کرنہٕ۔ یاد تھاوُن، اسہِ سٍتـ̡ گژھ نہٕ پنُن عہد پھُٹراوُن۔\n22.\\tکیا غیر قومن ہٕندِس باطلس منز چھا کانہہ {کُنہ} یُس روٗد ہیکہِ بٔنِتھ؟ کِنہ آسمانن دِتھ دِتھ؟ کیا تۅہہ چھُنہٕ سُہ اے خداوند سانہِ خدا؟ تَمہِ کِنۍ چُھہ أسۍ چانہِ ہُند انتظار کٔرِتھ: تِکیازِ ژے چھِ یِم سارِنٕے {چیز} بنٲومٕتۍ۔","1. اَمہِ پَتہٕ ووٚن خداوند میانہِ برونہہ کُن، یودوَے موسیٰ تہٕ سموئیل میانہِ برونہہ کنہِ کھڑا ٲسۍ، {توتہِ} میون ذہن ہیوٚک نہٕ یِمن لُکن کُن {بٔنِتھ} تہٕ دِیُن تِم نیرُن۔\n2.\\tتہِ گژھہِ یہ سپدِ، اگر تۅہہِ ونن زِ أسۍ کوٚت نیرِو؟ تێلہِ چُھہ تِمن وَنُن، یِتھٕ پٲٹھـ̡ چُھ خداوند فرماوان۔ مثلاً {are} موت، موتس تام؛ تہٕ یِتھ کٔنۍ زَن تلوار خٲطرٕ، تلوار خٲطرٕ؛ تہٕ یِتھ کٔنۍ زَن قحطہٕ خٲطرٕ، قحطہٕ خٲطرٕ؛ تہٕ یتھ کٔنۍ زِ {are} قید خٲطرٕ، قید خٲطرٕ۔\n3. تہٕ بہٕ کَرٕ یِمن پیٹھ ژور قٕسمٕ، خداوند چُھ فرماوان: تلوار مارنہٕ خٲطرٕ، تہٕ ہونۍ ژٹنہٕ خٲطرٕ، تہٕ اسمانٕکۍ جاناوار، تہٕ زمینٕکۍ جانور کھٮ۪نہٕ تہٕ تباہ کرنہٕ خٲطرٕ۔ {قسم: ہیب۔ خاندان}\n4. تہٕ بہٕ کٔرٕ یِم یہوداہ کِس بادشاہ حزقیاہ سٕندِس نیچوِس منسیہہ سٕندِ سٍتـ̡ یُس یروشلمس مَنٛز کٔرِ۔ {وجہ...: ہیب۔ تِم دِیِو ہٹاونہٕ خٲطرٕ}\n5. اے یروشلم، کُس کرِ توے پیٹھ رحم کھسنہٕ؟ نتہٕ کُس کرِ ژےٚ ماتم ؟ نتہ کُس گژھہِ الگ پرژھنہِ زِ ژیہ کتھہ پاٹھۍ چھکھ کران؟ {کتھہ پاٹھۍ...: ہیب۔ چانہِ امن ہُند؟}\n6. خداوند چُھہ ونان زِ ژے چُھہ میہ ترٲومُت، تێہہ چُھہ پتھ کُن گومُت، تێلہِ کٔرٕ بہٕ ژے سٍتـ̡ پنُن اتھہٕ تہٕ ژے تباہ کٔرِتھ۔ بہٕ چُھس توبہ کٔرِتھ تھوٚکمت ۔\n7. تہٕ بہٕ کٔرٕ تِمن زمینہٕ کِس دروازس پیٹھ پنکھہٕ سٍتۍ۔ بہٕ کٔرٕ تِمن شُرین ہُند غم ، بہٕ کٔرٕ پنٕنۍ لوٗکھ تباہ ، {کیازِ} تِم چھِ نہٕ پنٕنۍ وتہٕ نِش واپس۔ {شُرۍ: یا، یُس تہِ پیاری چھُ}\n8.\\tتِہٕنزِ بیواہ ہٕندِس سمندرن ہٕندِس سیکہِ پیٹھٕ چھُ میہ ہٕندِس سٍتـ̡ بێیہِ سٍتـ̡ بێیہِ سٍتـ̡ دُپہرٕ سٍتـ̡ یِمن ہٕندِس ماجہ سٍتـ̡ دُپہرٕ سٍتـ̡ دُپہرٕ سٍتـ̡ دِژمُت: مے چُھس اَتھ پیٹھ اچانک پۯاونہٕ آمُت، تہٕ شہرس پۯاوُن دِژمُت۔ {موج...: یا، مادر شہر اکھ نوجوان خراب کران، بیترِ، یا، موج تہٕ نوجوان}\n9. سُہ یُس سَتھ زیٚنہٕ چُھ، سُہ چُھ بھوت تراومُت۔ تٔمۍ سُند آفتاب چُھ لوسُن: سُہ چُھ شرمندہ تہٕ پریشان گومُت: تہٕ یِمن ہُند باقیات بہٕ دِیہٕ تِہندِ دُشمنن برونہہ تلوارس تام، خداوند چُھ فرماوان۔\n10.\\tمیہ چھے ہا ہا میانہِ موج زِ ژے چھے میہ سارِنٕے زمینس سٍتۍ اکھ کشمکش تہٕ تنازعہ وول انسان پٲدٕ کورمُت۔ مے چُھ نہٕ سود دِژمُت، تہٕ نہ چُھ مردو مےٚ سود دِژمُت۔ {توتہِ} یمن منز چھہ پریتھ کانہہ میہ لعنت۔\n11. خداوند ووٚن زِ یێلہِ چُھہ تێہٕندِس باقیَس سٍتـ̡ ٹھیٖک روزُن۔ پٔزۍ پٲٹھۍ کرٕ بہٕ دُشمن بد وِزِ تہٕ مصیبت ہٕندِس وقتس مَنٛز تہٕ مُصیبت ہٕندِس وقتس مَنٛز دُشمن ہٕندِس دُشمن سٍتـ̡ التجا کرنہٕ۔ {وجہ...: یا، دُشمن کٔرِو پانس خٲطرٕ}\n12. کیا ششتٕر پھُٹراوٕ شُمٲلی ششتٕر تہٕ سٹیل؟\n13.\\tچانۍ مال تہٕ تُہند خزانہٕ دِیہ بہٕ غنیمتس بغٲر قٲمت، تہٕ سُہ چُھس تُہندِ سارِنٕے گۅنہٕ خٲطرٕ، چانہِ سارِنٕے سرحدن منز تہِ۔\n14. تہٕ بہٕ بناوٕ ژے پننین دشمنن سٍتـ̡ تتھ ملکس مَنٛز {یُس} یُس نہٕ ژے پتاہ چُھ، کیازِ میانہِ غصہٕ سٍتـ̡ چُھہ نار دِنہٕ آمُت، {یُس} چُھہ توے سٍتـ̡ دزان۔\n15.\\tاے خداوند، ژے چُھہ زانان: مے یاد تھاوُن، تہٕ میہ سٍتـ̡ کرُن، تہٕ میانین ظالمن ہُند بدلہٕ کرُن۔ میہ نِو نہٕ پننہِ زیچھرِ مصیبت منز: زان زِ چانہِ خٲطرٕ چُھس میہ ملامت کرنہٕ آمُت۔\n16.\\tچانۍ کلام لٔبِتھ تہٕ میہ کھیوٚو تِم کھیوٚن۔ تہٕ تُہند کلام اوس میانہِ خٲطرٕ میٲنِس دِلٕچ خوشی تہٕ خوشی: تکیازِ بہٕ چُھس چانہِ ناوٕ سٍتـ̡ بُلاونہٕ آمُت، اے خدایہِ لشکرن ہُند خدا۔ {بہٕ چھُس...: ہیب۔ چانہِ ناو چُھس میہ پٲٹھۍبَناونہٕ آمُت}\n17.\\tبہٕ بیوٹھ نہٕ طنز کرن والٮ۪ن ہٕندِس مجلسس مَنٛز، تہٕ نہ کٔر خۅش۔ بہٕ بِہتھ ژے اَتھٕ کِنۍ کُنی زَن، تِکیازِ ژے چُھس مےٚ شرارت سٍتۍ بٔرِتھ۔\n18.\\tمیون دگ کیازِ چھہ دایمی تہ میون زخم چھہ نہ لاعلاج، {یُس} چھہ ٹھیک گژھنہ نش انکار کران۔ کیا ژٕ کٔرِکھ میہ سٍتۍ سراسر اپُز، {تہٕ یِتھ} آبس {یُس} ناکام گٔیہِ؟ {ناکام: ہیب۔ پَکہٕ چھُنہٕ پَکُن؟}\n19. تێمہِ کِنۍ چُھ خداوند یِتھٕ پٲٹھۍ ونان زِ یێلہِ تہٕ ژٕ واپس، تێلہِ بہٕ اَننہٕ ژے دُبارٕ، تہٕ تہٕ تێہہ گژھہِ میانہِ برونہہ کُن کھڑا تہٕ یێلہِ ژے بدکارن نِش قیمتی چیز کڈِ، تہٕ تێہہ گژھہِ میانہِ ٲسِس پٲٹھۍ: تِم گژھن پانس نِش واپس۔ مگر تِمن کُن گژھ نہٕ واپس۔\n20. تہٕ بہٕ بناوٕ ژے یِمن لُکن ہٕندِس خٲطرٕ اکھ تار لٔگِتھ دیوار، تہٕ تِم کرَن توے خٕلاف لڑان، مگر تِم ہیکن نہٕ توے خٕلاف فتح حٲصل کٔرِتھ، کیازِ بہٕ چُھس ژے سٍتـ̡ بچاونہٕ خٲطرٕ تہٕ نجات دِنہٕ خٲطرٕ، خداوند چُھ فرماوان۔\n21. تہٕ بہٕ کَرٕ ژے بدکارن ہٕندِ اتھہٕ نِش نجات تہٕ بہٕ کٔرٕ ژے خوفناک سٕندِ اتھہٕ نِش نجات دِنہٕ۔","1. خداوند سُند کلام تہِ آو میہ نِش وَننہٕ،\n2. ژے گژھِ نہٕ خانٛدارِنۍ رٔٹِتھ تہٕ یَتھ جایہِ گژھِ نہٕ نیچو تہٕ کورِ۔\n3. یِتھٕ پٲٹھۍ چُھ خداوند یِمن نیٚچوٮ۪ن تہٕ یِمن کورٮ۪ن مُتعلق تہٕ یِمن ہٕنزِ ماجہِ مُتعلق تہٕ یِمن ہٕندِس مٲلِس مُتعلِق یِم یِمن اتھ زمینس مَنٛز زامٕژ چھِ۔\n4. تِم گژھن شدید موتَس سٍتـ̡ مرنہٕ۔ تِمن گژھِ نہٕ ماتم کرنہٕ؛ نہ گژھن تم دفن کرنہٕ۔ {مگر} تِم گژھن زمینہِ ہٕندِس بُتھِس پیٹھ گُبر ہٕندۍ پٲٹھۍ: تہٕ تِم گژھن تلوار تہٕ قحط سٍتۍ کھٮ۪نہٕ۔ تہٕ تِہٕندِ لاشہٕ آسن اسمانن ہٕندٮ۪ن جاناوارن تہٕ زمینہٕ کیٚن درندن ہُند ماز ۔\n5. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ ماتم کِس گرس مَنٛز اژُن نہٕ تہٕ گژھ نہٕ ماتم کرنہٕ خٲطرٕ، تہٕ نہ گژھ تِمن ہُند ماتم کرنہٕ، کیازِ خداوند چُھ ونان زِ مے چُھ یِمن لوکن نِش پنُن امن نِش نِمُت، محبتہٕ تہٕ رحمتہٕ تہٕ رحمت۔ {ماتم : یا، ماتم دعوت}\n6.\\tبٔڈۍ تہٕ لۄکٕٹ دۅشوے گژھن اتھ زمینس منز مرُن: تِم گژھن نہ دفن کرنہٕ، نہ یِمن ہٕندِ خٲطرٕ ماتم کرنہٕ، نہ گژھن پان ژٹنہٕ، تہٕ نہ گژھن تِمن خٲطرٕ گنج کرنہٕ۔\n7.\\tنہ کرِ {انسان} تِمن ہٕندِ خٲطرٕ ماتم کرنہٕ خٲطرٕ، تِمن ہٕندِ خٲطرٕ تسلی دِنہٕ خٲطرٕ۔ نہ دِن تِمن مٲلِس یا ماجہ ہٕندِ خٲطرٕ تسلی دِنہٕ خٲطرٕ۔ {اوٚش...: یا، تمن خٲطرٕ بریڈ بریک}\n8.\\tژیہ گژھ نہٕ دعوت کِس گرس منز تہِ یِمن سٍتـ̡ کھٮ۪نہٕ تہٕ چیٚنہٕ خٲطرٕ بِہنہٕ خٲطرٕ۔\n9. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب اسرٲیلُک خدا فرماوان۔ وُچھ، بہٕ کَرٕ یَتھ جایہِ نِش ژےٚ نظرن منٛز، تہٕ چانہِ دۄہَن منٛز، خوشی ہٕنٛز آواز، مہرازٕ سٕنٛز آواز، تہٕ مہرِنہِ ہٕنٛز آواز۔\n10.\\tتہٕ یێلہِ گژھہِ یێلہِ ژے یِمن لُکن یِم سارِنٕے لفظ ہٲوِو، تہٕ تِم وَنُن تۅہہِ زِ خداوند کیازِ دیت اسہِ سٍتـ̡ یێمہِ سارِنٕے بٔڈ بُرکاری ہُند اعلان دِژمُت؟ یا سون بدکار کیا چُھ؟ یا کیا چُھہ سون گۅناہ یُس اسہِ پننِس خداہس خلاف کورمُت چُھ؟\n11. تیلہٕ چُھہ تِمن وَنُن، کیازِکہِ تُہٕندِس آباؤ اجدادو چُھ مے ترٲومُت، تہٕ چُھکھ باقین دیوتاہن پٲٹھۍ، تہٕ چُھکھ تِمن ہٕنز عبادت کٔرمٕژ، تہٕ چُھکھ میہ ترٲومُت، تہٕ چُھکھ نہٕ میٲنۍ شریعت ہٕنز پابرٲہی کٔرمٕژ۔\n12. تہٕ تہٕ تۅہہ چھُ پننین مٲلن کھوتہٕ بدتر کٲم کٔرمٕژ۔ تکیازِ وچھو، تم چھہِ پریتھ کٲنسہِ تمۍ سندِ بد دلک تخیلس پیٹھ پکناوان، تاکہ تم گژھن نہ میانہِ کتھہِ بوزتھ: {تصور: یا، ضد داری}\n13.\\tتێلہِ کٔرٕ بہٕ ژے یتھ زمینہٕ منزٕ تتھ زمینس مَنٛز کٔڑِتھ یُس نہٕ تۅہہ تہٕ نہ تہٕ تُہٕندِس مٲلس پتاہ آسہِ۔ تہٕ تتہِ کٔرِو تُہۍ دۅہہٕ راتس باقین دیوتاہن ہٕنز عبادت کٔرِو۔ ییتہِ نہ بہٕ ژیہ احسان ہٲوِتھ۔\n14. تێمہِ وِزِ وُچھِو یِم دۅہ یِن، خداوند چُھ ونان زِ یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ اسرٲیلٕکۍ اولاد مصر کِس سرزمینہٕ پى۪ٹھٕ پرورش کٔرِ۔\n15.\\tمگر خداوند چُھ زندٕ، یٔمۍ اسرٲیلٕکۍ اولاد شمالہٕ کِس سرزمینہٕ پیٹھٕ پرورش کٔرۍ، تہٕ تِمن سارِنٕے زمینہٕ پیٹھٕ یِمن تِمن ہٕندِس مٲلِس دِژمٕژ ٲس۔\n16. خداوند چُھ ونان زِ بہٕ سوزٕ واریہن گاڈٕ رٹنہٕ والٮ۪ن ہٕندِس سٍتـ̡ تہٕ تِم کرِ تِمن گاڈٕ رٹنہٕ۔ تہٕ اَمہِ پتہٕ سوزٕ بہٕ واریاہ شِکار، تہٕ تِم کٔرِن تِمن پرٮ۪تھ بالہٕ پیٹھٕ تہٕ پرٮ۪تھ بالہٕ پیٹھٕ تہٕ کَنہِ ہٕندِس سوراخس منزٕ شِکار۔\n17.\\tمیانہِ اچھ چھیہ تِمن سارِنٕے وتہِ پیٹھ: تِم چھِنہٕ میانہِ بُتھِ نِش پوشیدٕ تہٕ نہ چھِ تِہُند بدکار میانہِ نظرِ نِش پوشید۔\n18.\\tتہٕ گۅڈٕ بہٕ تِہٕندِس بدکارس تہٕ تِہٕندِس گۅناہ سٍتـ̡ دوٚگنہٕ بدلہٕ۔ تِکیازِ تِمو چُھ میٲنۍ زمینہٕ ناپاک کٔرمٕژ، تِمو چھُ میٲنۍ وراثت پنٕنۍ نفرت انگیز تہٕ مکروہ چیزن ہٕنٛز لاشہٕ سۭتۍ بٔرِمٕژ۔\n19. اے خداوند، میٲنۍ طاقت، تہٕ میٲنۍ قعلہٕ، تہٕ مُصیبت ہٕندِس دۅہس مَنٛز میٲنۍ پناہ گاہ، غیر قومن ہٕندِس اندس پیٹھ یِن توے نِش، تہٕ ونن، یٔقیٖنی طور سانین آباؤ اجدادن چُھ اپُز، باطل تہٕ {چیز} وراثتس منز میلہِ نہٕ، یِمن مَنٛز چُھنہٕ کانہہ فٲیدٕ چُھ۔\n20.\\tکیا انسان بَناوُن پانس خٲطرٕ دیوتا، تہٕ تِم چھِنہٕ کانہہ دیوتا؟\n21.\\tتێلہِ، وُچھِو بہٕ یێمہِ لٹہِ تِمن زانناوُن، بہٕ دِیہٕ تِمن پنُن اتھہٕ تہٕ پنُن طاقت۔ تہٕ تِمن گژھہِ معلوم زِ میون ناو {چُھ} خداوند۔ {خداوند: یا، یہوواہ}","1.\\tیہوداہ سُند گۅناہ {چُھ} ششتٕرِ قلمہٕ سٍتـ̡ لیکھنہٕ آمُت، {تہٕ} ہیرہ سٕندِس نوکَس سٍتـ̡ {یہ} چُھہ تِہندِ دِل کِس میزس پیٹھ تہٕ تُہنزن قربان گاہن ہٕندِس سینگس پیٹھ کھٔنِتھ آمُت۔ {پوائنٹ: ہیب۔ کیل}\n2. ییلہ زن تِہندِ شُرۍ تھدٮ۪ن بالن پیٹھ سبز کُلٮ۪ن نِش پنٕنۍ قربان گاہ تہٕ پنٕنۍ باغ یاد تھاوان چھِ۔\n3.\\tاے میٲنۍ پہاڑ، بہٕ دِیہ تُہند مال تہٕ تُہند سارِنٕے خزانہٕ غنیمتس تہٕ تُہٕندِس سارِنٕے سرحدس سٍتـ̡ گۅنہٕ خٲطرٕ تُہند تھدِ مقام۔\n4. تہٕ ژے تہٕ پَنُن پان تہِ کٔرِو پننہِ وراثت نِش یُس مے ژے دِژمُت چھُ۔ تہٕ بہٕ کرٕ ژے تتھ زمینس منز پننین دشمنن ہنز خدمت کرُن یُس نہٕ ژے پتاہ چھُ، کیازِ ژے چھُکھ میانِس غصس منز نار زالمُت، یُس ہمیشہٕ خٲطرٕ دزِ۔ {پنُن: ہیب۔ پانس منز}\n5. خداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ سُہ شخص گژھہِ لعنت یُس انسانس پیٹھ بھروسہٕ کرِ، تہٕ پنُن نرِ ماز بناوان چُھ، تہٕ یٔمۍ سُند دِل خداوند نِش نیران چُھ۔\n6.\\tتکیازِ سُہ گژھہِ صحراہس مَنٛز ہیو، تہٕ یێلہِ نہٕ وُچھِتھ ییلہ خیر واتہِ۔ مگر بیابانن منز روزن خشک جاین منز روزُن، نوٗنہٕ زمینس منز تہٕ آباد نہٕ۔\n7. بابرکت چُھ سُہ انسان یُس خداوند سُند بھروسہٕ چُھ، تہٕ یٔمۍ سٕنز وۅمید خداوند چُھ۔\n8.\\tتکیازِ سُہ آسہِ آبہٕ سٍتـ̡ لگاونہٕ آمٕژ کُلِس ہٕندۍ پٲٹھۍ، تہٕ یُس دریاوس سٍتـ̡ پنٕنۍ موٗل پھٔہلٲوِتھ آسہِ، تہٕ سُہ گژھہِ نہٕ وُچھِتھ ییلہ گرمی یِیہ، مگر تٔمۍ سُند پنہٕ وُن آسہِ سبٕز۔ تہٕ خشک سالی ہٕندِس ؤریس منز گژھِ نہٕ محتاط روزُن، تہٕ نہ گژھِ پھل دِنہٕ نِش بند۔ {خشک سالی: یا، پابندی}\n9.\\tدِل چُھہ سارِوٕے کھۄتہٕ زیادٕ دھوکہ دِنہٕ آمُت، تہٕ بدکار چُھس: کُس ہیکہِ یہ پتاہ کٔرِتھ؟\n10. بہٕ چُھس خداوند دِل ژھانڈان، {بہ} چُھس لگام کوشش کران، یوتام زِ پرتھ انسان چُھ تٔمۍ سٕندِس طریقس مطٲبق دِنہٕ خٲطرٕ، {تہٕ} تٔمۍ سٕندِ اعمال کہ پھلہٕ مطٲبق۔\n11.\\tتیتر چھہ ٹھولس پیٹھ بِہتھ تہ ٹھولس پیٹھ بِہتھ {تمن پیٹھ} تہِ چھہ نہ۔ یُس دولت حٲصل کرِ، تہٕ حقہٕ سٍتۍ نہٕ، سُہ تراوِ پننین دۅہن منز، تہٕ ٲخرس پیٹھ گژھہِ بیوقوف۔ {بِہتھ...: یا، یُس نہٕ أمِس پٲدٕ کورمُت چھُ}\n12. شروع پیٹھے اکھ شاندار تھوٚد تخت {چُھ} سانہِ مقدس مقامچ جاے۔\n13. اے خداوند، اسرٲیلٕچ وۅمید، یُس تہٕ یُس تہٕ یُس میہ نِش نیران چُھ، سُہ گژھہِ زمینس مَنٛز لیکھنہٕ یُن، کیازِکہِ تِمو چُھ خداوند یُس زندٕ آبُک چشمہٕ چُھہ ترٲومُت۔\n14. اے خداوند، میہ کرو شفا تہٕ بہٕ گژھہٕ شفا۔ میہ بچاو، تہٕ بہٕ روزٕ بچاو: تکیازِ ژے چُھہ میٲنۍ تعریف۔\n15.\\tوُچھِو تِم چھِ میہ ونان زِ خداوند سُند کلام کتہِ چُھہ؟ یہ گژھہِ وۅنۍ یُن۔\n16.\\tیوٚتام میانہِ مۅکھہٕ چُھ، بہٕ چُھس نہٕ پادری آسنہٕ سٍتـ̡ تۅہہِ سٍتـ̡ جلدی کٔرمٕژ: نۂ چُھس بہٕ یُس افسوسناک دۅہہٕ یێلہِ ہُند خواہش۔ ژے چھے پتاہ زِ یُس میانہِ چپنہِ منزہ نیران اوس سہ اوس ژے برونہہ کنہِ {صحیح}۔ {to...: Heb. تمہِ پتہٕ}\n17.\\tمیانہِ خاطرہ گژھ نہ دہشت گردی تہ بد دۅہہِ چھکھ میٲنۍ وۅمید ۔\n18.\\tتِم گژھن پریشان گژھن یُس میہ ستاوان چُھ، مگر بہٕ گژھ نہٕ پریشان گژھُن: تِم گژھن مایوس گژھن، مگر بہٕ گژھ نہٕ مایوس گژھُن: تِمن پیٹھ اَنُن بدی ہُند دۅہہ، تہٕ تِمن کرُن دۄگنہٕ تباہی سٍتـ̡ تباہ کرنہٕ۔ {تباہ...: ہیب۔ تِم پھُٹرٲوِو دۄگنہٕ خلاف ورزی سٍتۍ}\n19. یِتھٕ پٲٹھۍ ووٚن خداوند میانہِ خٲطرٕ۔ گژھ تہٕ لوکن ہٕندِس بچن ہٕندِس دروازس مَنٛز کھڑا گژھُن، یێمہِ سٍتـ̡ یہوداہٕکۍ بادشاہ اژان چِھ، تہٕ یێمہِ سٍتـ̡ تِم نیران چِھ، تہٕ یروشلم کِس سارنٕے دروازن منز۔\n20. تہٕ تِمن وَنُن، یێلہِ یہوداہٕکۍ بادشاہو تہٕ سارِنٕے یہوداہٕکۍ بادشاہو تہٕ یروشلم کین سارِنٕے بسکین، یِمو دروازو سٍتـ̡ اژان چُھ، یێلہِ خداوند سُند کلام بوزو:\n21.\\tیِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ پَنُن پان رٔٹِو، تہٕ سبت دۅہہٕ گژھِو نہٕ بَٹہٕ دۅہہٕ تہٕ یِنہٕ یروشلم کِس دروازٕ پیٹھٕ اژُن۔\n22.\\tسبت دۅہہٕ کُنہِ تہِ کُنہِ تہِ کامہِ ہُند دۅہ تُلِتھ تہٕ کُنہِ تہِ کامہِ ہُند دۅہہ، یِتھہٕ کٔنۍ میہ پننین مٲلن ہُند حُکُم دِیُتمُت چھُ۔\n23.\\tمگر تِمو کٔر نہٕ فرمانبردار، نہ کٔرِکھ کَن کُن، بلکہ کٔرٕکھ گردن سخٕت، یُتھ زن نہ تِم بوزِتھ تہٕ نہ ہدایت۔\n24. تہٕ یہِ گژھہِ سپدُن، یێلہِ تہٕ یێلہِ تہٕ یێلہِ سبت دۅہہٕ یێمہِ شہرٕکِس دروازو منزٕ یێلہِ نہٕ کانہہ بوجھ انُن، مگر سبت دۅہہٕ گژھہِ نہٕ اتھ منز کانہہ کٲم کرنہٕ۔\n25. اَمہِ پَتہٕ یِم بادشاہ تہٕ شہزادٕ داؤد سٕندِس تختس پیٹھ بِہِتھ، رتھن تہٕ گُرٮ۪ن پیٹھ سوار گژھِتھ، تِم تہٕ تِہٕندِ شہزادٕ، یہوداہٕکۍ مرد تہٕ یروشلمٕکۍ روزن وٲلۍ، تہٕ یِہ شہر روزِ ہمیشہٕ خٲطرٕ۔\n26.\\tتہٕ یِم یِن یہوداہ کِس شہرو پیٹھ، یروشلمس اندۍ پکھۍ مقامو پیٹھ، تہٕ بنیامین سٕنزِ زمینہٕ پیٹھ، میدانی پیٹھ، تہٕ پہاڑو پیٹھٕ تہٕ جنوبہٕ پیٹھٕ یِن، زٲلِتھ نذرانہ تہٕ قربانی، ماز تہٕ بخور تہٕ تعریفٕچ قربانی أنِتھ خداوند سٕندِس گرس مَنٛز۔\n27. مگر یێلہِ نہٕ ژٕ سبت دۅہہٕ مقدس کرنہٕ خٲطرٕ تہٕ سبت دۅہہٕ یروشلم کِس دروازس پیٹھ اژنہٕ خٲطرٕ تہِ چُھہ نہٕ میانہِ کتھ بوزان۔ تیلہ کرٕ بہٕ اَمہ کِس دروازس منز نار زال، تہٕ سُہ کرِ یروشلم کین محلن کھٮ۪تھ، تہٕ یہ گژھہِ نہٕ ژھیتہٕ۔","1. سُہ لفظ یُس خداوند سٕندِ طرفہٕ یرمیاہ ہس تام آو ، یُس ونان چُھ،\n2.\\tوۅتھٕ ووٚتھ، تہٕ کمہار سٕندِس گرس منز، تہٕ تتہِ کرٕ بہٕ ژے پنٕنۍ کتھ بوزناوٕنۍ۔\n3.\\tامہ پتہ ووت بہٕ کمہار سٕندِس مکانس منز، تہٕ وُچھ تٔمۍ کٔر چکرس پیٹھ کٲم۔ {وہیلز: یا، فریم، یا، سیٹ}\n4.\\tتہٕ یُس بانہٕ تٔمۍ میژِ سٍتۍ بنوومُت اوس، سُہ اوس کمہار سٕندِس اتھس منز خراب گومُت، تہٕ تٔمۍ بنوو بییہ بیاکھ بانہٕ، یُس کمہارس بَناوُن جان باسان۔ {میژِ ہُند...: یا، اوس میژِ ہٕندۍ پٲٹھۍ کمہار سٕندِس اتھس منز میژِ ہٕندۍ پٲٹھۍ} {بنیوو یہ...: ہیب۔ واپس، تہٕ بنیومُت، وغیرہ}\n5. پتہٕ آو خداوند سُند کلام میانہِ نِش وونُن،\n6. اے اِسرٲیلٕکۍ گرٕ، بہٕ ہیٛکہٕ ژےٚ سٍتـ̡ یێمہِ کمہار سٍتـ̡ کٔرِتھ؟ خداوند چُھ فرماوان۔ وُچھو، یِتھٕ پٲٹھۍ میژِ چُھہ کمہار سٕندِس اتھس منز، تِتھے پٲٹھـ̡ چُھہ میژِ مٲنِس اتھس منز، اے اسرائیلُک گرٕ۔\n7. {کُنہِ ساتہٕ} بہٕ کُنہِ قومس متعلق، تہٕ أکِس سلطنتس متعلق، تُلنہٕ خٲطرٕ، تہٕ ژٹنہٕ خٲطرٕ، تہٕ تباہ کرنہٕ خٲطرٕ کتھ کرٕنۍ۔\n8. اگر سُہ قوم، یٔمِس خٕلاف میہ قرار دِژمُت چُھ، تِمن ہٕنزِ بُرٲیی نِش پھِرِ، بہٕ کَرٕ تِمن سٍتـ̡ بُرٲیی نِش توبہ یُس میہ تِمن سٍتـ̡ کرُن سونچُمُت۔\n9. تہٕ {کُنہِ ساعتہٕ} بہٕ کُنہِ قومس متعلق، تہٕ أکِس سلطنتس متعلق، تعمیر کرنہٕ خٲطرٕ تہٕ کاشت کرنہٕ خٲطرٕ کتھ کرٕنۍ۔\n10.\\tاگر یہ میانہِ نظرِ منز بد کار کرِ، زِ یہ میانہِ آوازِ ہنز اطاعت کرِ نہ، تیلہِ کرٕ بہٕ نیکی پیٹھ توبہ، ییمہ سٍتۍ میہ ووٚنمُت زِ بہٕ کرٕ تِمن فٲیدٕ۔\n11. تێمہِ کِنۍ گژھ یہوداہ کین لوکن تہٕ یروشلم کین بسکینن سٍتـ̡ کتھ کرٕن، یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ وچھ بہٕ چُھس ژے خلاف بد کار بناوان، تہٕ ژے خلاف اکھ چال بناوان: وۅنۍ کرو پریتھ کانہہ تٔمۍ سٕنزِ بد وتہِ نِش واپس، تہٕ پنٕنۍ وتہٕ تہٕ پنٕنۍ کٲم کٔرِو اصل۔\n12.\\tتہٕ تِمو ووٚن، کانہہ وۅمید چھُنہٕ، مگر أسۍ پٔکِو پننین چالن پٲٹھۍ، تہٕ أسۍ کرو پرٮ۪تھ کانہہ پننہِ بد دِلُک تخیل۔\n13. تێمہِ کِنۍ چُھ خداوند یِتھٕ پٲٹھۍ فرماوان۔ وۅنۍ پرژھو کافرن منز، یۅہے کتھ بوزمژ چھیہ: اسرائیلچ کنواری چھیہ سیٹھا خوفناک کٲم کٔرمژ۔\n14.\\tکیا {انسان} تراوِ لبنانُک شیٖن {یُس یوان چھُ} میدانہٕ کِس کنہِ پیٹھ؟ {یا} یُس سرد وسان آب یُس بییس جایہ پیٹھہ یِوان چھُ، سہ گژھہِ تراونہ یُن؟ {شیٖن...: یا، میانہِ کھیت کنہِ پتھرِ خٲطرٕ، یا لبنان کِس شینہٕ خٲطرٕ؟ وسوُن آب گژھا عجیب سرد آبس خٲطرٕ ترک؟}\n15.\\tکیازِ میانہِ لُکھ چھُ میہ مٔشِد گومُت، تِمو چُھ بخور زٲلمُت، تہٕ تِمو چھُ تِمن پنہٕ نِس وتہِ پٔکِتھ، یُس نہٕ وَتہٕ پٔکِتھ چھُ۔\n16.\\tتِہٕنزِ زمینہٕ ویران کرٕنۍ، {تہٕ} ہمیشہٕ ہِس پھِراونہٕ خٲطرٕ؛ یُس تہِ نیران چھُ، سہ گژھہِ حیران تہ کلہ ہلاوان۔\n17. بہٕ کٔرٕ تِم دُشمن برونہہ کُن مشرِقی واو ہٕندۍ پٲٹھۍ۔ بہٕ ہاوٕ تِمن ہٕنزِ آفت ہٕندِس دۅہس منز بُتھ نہٕ۔\n18.\\tتَمہِ پتہٕ ووٚن تِمو یِمو یِمن ہٕندِس خٕلافس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ ہى۪کان۔ تکیازِ شریعت گژھہِ نہ پادٕرِ سٕندِ طرفہٕ ختم، نہ دانشمندن ہٕندِ طرفہٕ مشورٕ، تہٕ پیغمبرن ہُند کلام گژھہِ نہٕ۔ آو، تہٕ اسہِ دِیُو أمِس زَبانہِ سٍتـ̡ تہٕ أسـ̡ نہٕ تسٕندِس کُنہِ تہِ کلامَس کُن توجہ دِنہٕ۔ {سۭتۍ...: یا، زبانہِ خٲطرٕ}\n19. اے خداوند، میانہِ کُن توجہ دِیُن تہٕ تِمن ہٕنز آواز بوز یُس میانہِ سٍتـ̡ مقابلہ کران چُھ۔\n20. کیا بدی ہُند بدلہٕ یِیہِ نیکی ہُند بدلہٕ؟ تِکیازِ تِمو چھُ میانہِ روحہٕ خٲطرٕ اکھ کھۄڈ کھننہٕ آمُت۔ یاد تھاوُن زِ بہٕ اوسُس ژےٚ برونہہ کنہِ تِمن ہٕندِ خٲطرٕ نیک کتھ کرنہٕ خٲطرٕ کھڑا تہٕ تِمن نِش پنُن غصہٕ دور کرنہٕ خٲطرٕ۔\n21. تێمہِ کِنۍ دِیُن پننین شُرٮ۪ن قحطس مَنٛز، تہٕ تلوار ہٕندِ زورٕ سٍتـ̡ تِہُند خوُن تراوُن۔ تہٕ تہنز زنانہٕ گژھن پننین بچن نِش سوگم، تہٕ بیواہ گژھن۔ تہٕ تِمن ہٕندِس نفرس گژھن مارنہٕ۔ {یِن}تِہٕندِ جوان گژھن جنگس منز تلوار سٍتۍ مارنہٕ۔ {پُر...: ہیب۔ تِم تراوُن}\n22.\\tیِمن ہٕندِس گَرَو منزٕ گژھہِ کرٛٮ۪کھ بوزنہٕ، یێلہِ تہٕ تِمن پیٹھ اچانک اکھ فوج أنِو، تکیازِ تِمو چُھکھ میہ نِنہٕ خٲطرٕ اکھ کھۄڈ کھٔنِمُت، تہٕ میانین کھۅرن ہٕندِ خٲطرٕ چھُکھ جال ژوٗرِ تھوومُت۔\n23. توتہِ، خداوند، توتہِ چُھہ تِہُند سارِنٕے مشورٕ زانان زِ تِہُند گناہ گژھہِ نہٕ پانس نِش مٔٹِتھ تہٕ تِہُند گۅناہ تہِ کٔرِو پانس برونہہ کُن ختم کرنہٕ۔ پننہِ شرارت وِزِ کرو تمن سٍتـ̡ معاملہٕ۔ {مارنہٕ خٲطرٕ...: ہیب۔ موت}","1. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، گژھ تہٕ اکھ کمہار سٕنز میژِ بوتلہٕ أنِن، تہٕ لوکن ہٕندِس پرانین تہٕ پادٕرین ہٕندِس پرانہِ سٍتـ̡ نِنـ̡ ۔\n2.\\tتہٕ نیرِو ہِنوم سٕندِس نیچوِس وادی کُن، یُس مشرِقی دروازٕ کِس اژنہٕ سٍتـ̡ {چُھ} تہٕ تتہِ کرُن تِم لفظ یُس بہٕ ژے وَنُن، {مشرق...: حب۔ سن گیٹ}\n3. تہٕ ونُن، اے یہوداہ کٮ۪و بادشاہو تہٕ یروشلم کین بسکین، خداوند سُند کلام بوزو۔ یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھ وَنان۔ وچھ، بہٕ اَتھ جایہِ بد کار انان، یُس بوزان آسہِ، تٔمۍ سٕندِس کَن گٔژھ گٔژھان۔\n4. کیازِ تِمو چُھکھ میہ ترٲومُت، تہٕ یێمہِ جایہ الگ کورمُت، تہٕ چُھکھ اَتھ مَنٛز باقین دیوتاہن خٲطرٕ بخور زٲلمُت، یِمن نہٕ تِمو تہٕ تِہٕندِس مٲلِس پتاہ چُھ، تہٕ یہوداہ کِس بادشاہن تہٕ یێمہِ جایہ چُھکھ معصومن ہٕندِ خونہٕ سٍتـ̡ بٔرِتھ۔\n5.\\tتِمو چُھ بعلٕچ تھدِ جاے تہِ بنٲومٕژ، پننین نیچوین نارٕ سٍتـ̡ زالنہٕ خٲطرٕ، یُس نہٕ میہ حکم دِتمُت اوس تہٕ نہ اوس میٲنس ذہنس منز آمُت:\n6.\\tتێلہِ وُچھِو یِم دۅہ یِن، خداوند چُھ ونان زِ اتھ جایہ گژھہِ نہٕ وُنہٕ توپھیت وننہٕ یُن، تہٕ نہ ہینوم سٕندِس نیچوِس سٕنز وادی وَننہٕ یِنہٕ، بلکہ ییہ ذبحٕچ وادی وننہٕ۔\n7. تہٕ بہٕ کَرٕ یَتھ جایہِ یہوداہ تہٕ یروشلمُک مشورٕ کالعدم ۔ تہٕ بہٕ دِیہ تِمن تلوار سٍتـ̡ تہندٮ۪ن دُشمنن برونہہ کُن، تہٕ تِمن ہٕندِس اتھہٕ سٍتـ̡ یِمن ہُند جان ژھاران چُھس، تہٕ بہٕ دِیہٕ تِمن ہٕندِ لاشہٕ اسمانس کِس جاناوارن تہٕ زمینہٕ کین درندن ہُند ماز ۔\n8. تہٕ بہٕ بناوٕ یہِ شہر ویران تہٕ اکھ ہِس۔ یُس پرٮ۪تھ کانہہ یُس اَتھ کُن نیران چُھ، سُہ گژھہِ حٲران تہٕ سارِنٕے آفتن ہٕندِ وجہ سٍتـ̡ ہُند شکار سپدُن۔\n9. تہٕ بہٕ کرٕ تِمن پننین نیچوین ہُند ماز تہٕ تہنزِ کورِ ہُند ماز کھٮ۪ن، تہٕ تِم کھٮ۪ن پرٮ۪تھ أکِس سٕندِس یارس سُند ماز تہٕ یُس تِمن ہُند دُشمن تہٕ یُس پنُن جان ژھاران چھُ، تِمن ہُند ماز کھٮ۪ن۔\n10. تیلہٕ پھُٹرٲوِو تِمن نفرن ہٕندِس نظرس منز یُس پانس سٍتـ̡ گژھان چُھ،\n11. تہٕ یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب وَنان۔ یتھے پاٹھۍ پھٹراوِ میہ یہ لوکھ تہ یہ شہر، یتھہ پاٹھۍ {اکھ} کُنہِ کمہار سُند بانہ، یُس نہ بییہ مکمل سپدِتھ، تہ تم کرِ ٹوفیتس منز دفن، یوت تام نہ دفنچ کانہہ جاے آسہِ۔ {بٔنِو...: ہیب۔ ٹھیک گژھُن}\n12. یِتھٕ پٲٹھۍ کٔرٕ بہٕ یَتھ جایہِ تہٕ اَمہ کِس بسکینس سٍتـ̡ تہٕ {حتیٰ کہ} بَناوٕ یہِ شہر ٹوفٹ:\n13. تہٕ یروشلمٕکۍ گرٕ تہٕ یہوداہ کِس بادشاہن ہٕندِ گرٕ یِن ٹوپھ سٕنزِ جایہ ناپاک کرنہٕ، تِکیازِ یِمن سارِنٕے گرن پیٹھ یِمو اسمانس ہٕندِس سارِنٕے لشکرس تام بخور زٲلِمٕژ چھِ، تہٕ باقین دیوتاہن خٲطرٕ چُھکھ شرابٕچ نذرانہ تراومٕژ۔\n14. پتہٕ آو یرمیاہ توفیت پیٹھ، ییتہِ خداوند سُہ پیشن گویی کرنہٕ خٲطرٕ سوزمُت اوس۔ تہٕ سُہ اوس خداوند سٕندِس گرٕ کِس دربارس منز کھڑا۔ تہٕ وونُن سارِنٕے لوٗکَن ،\n15. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب اسرٲیلُک خدا فرماوان۔ وچھ بہٕ اَتھ شہرس تہٕ اَمہِ سٕندِس سارنٕے قصبن پیٹھ سٲرِے بُرٲیی یُس مے اَتھ خلاف اعلان کورمُت چھُ، تِکیازِ تِمو چھِ پنٕنۍ گردن سخٕت کٔرمٕژ، یُس نہٕ تِم میٲنۍ کتھ بوزنہٕ یِن۔","1.\\tوُن پادٕرۍ سُند نیچو پاشور، یُس خداوند سٕندِس گرس مَنٛز تہِ سردار اوس، بوز زِ یرمیاہ ہن کٔر یمن چیزن ہنز پیشن گوئی۔\n2.\\tپَتہٕ دِژ پشورن یرمیاہ نبی سٕندِس تھدِس دروازس مَنٛز، یُس خداوند سٕندِس گرٕ سٍتـ̡ اوس۔\n3.\\tتہٕ پَگہہ سپُد یِرمیاہ ذخیرٕ منزٕ نیبر۔ اَمہِ پتہٕ ووٚن یرمیاہ تٔمِس زِ خداوند چُھ نہٕ تُہند ناو پاشور بٔلکہِ مگورمیسابیب۔ {Magormissabib: یعنی خوفہٕ اندۍ اند}\n4. یِتھٕ پٲٹھـ̡ چُھہ خداوند فرماوان، وُچھ، بہٕ بناوٕ ژے پانس تہٕ تُہٕندِس سارِنٕے یارن ہٕندِس خٲطرٕ دہشت تہٕ تِم پنہٕ نِس دُشمن ہٕنزِ تلوار سٍتـ̡ پۯاوٕن، تہٕ تُہٕنزِ أچھ وُچھن تہٕ بہٕ دِیہٕ سورُے یہوداہ بابل کِس بادشاہ سٕندِس اتھس مَنٛز، تہٕ سُہ نِیہِ تِم قٲد بابل کِس اتھس منز،  تہٕ مارِ تِم تلوار سٍتۍ۔\n5. امہِ علاوٕ بہٕ دِیہٕ امہِ شہرٕچ سورے طاقت، تہٕ اَمہِ ہٕنٛز تمام محنت، تہٕ اَمہِ ہٕندۍ تمام قیمتی چیز تہٕ یہوداہ کین بادشاہن ہٕندۍ سٲری خزانہٕ تہٕ یِمن ہٕندِس دُشمنن ہٕندِس اتھس مَنٛز دِنہٕ، یُس تِمن خراب کرِ، تہٕ نِن تہٕ نِنہٕ بابل نِن۔\n6. تہٕ تُہہ، پاشور، تہٕ تُہٕندِس گرس مَنٛز روزن وٲلِس سارِنٕے سٍتـ̡ گژھن قٲد کرنہٕ، تہٕ تُہۍ یِیہِ بابل یِن، تہٕ تتہِ گژھِو تہٕ تتہِ یِیہِ دفن کرنہٕ، تہٕ تُہۍ تہٕ تُہٕندِس سارِنٕے یارَن یِمن سٍتـ̡ ژے پیشن گویی کٔرمٕژ چھِ۔\n7. اے خداوند، ژے کٔر میہ دھوکہٕ، تہٕ بہٕ چُھس دھوکہٕ دِژمُت: ژٕ چُھس میانہِ کھوتہٕ زیادٕ مضبوط، تہٕ چُھس غالب: بہٕ چُھس دۅہہٕ چُھس طنز کران، پرٮ۪تھ کانٛہہ چُھ مےٚ ٹھٹھہٕ کران۔ {دھوکہٕ دِنہٕ آمُت: یا، آو لالچ دِنہٕ}\n8. یێلہِ بہٕ کَتھ کٔرِتھ، بہٕ کٔر دِژ تشددٕ تہٕ خراب۔ تکیازِ خداوند سُند کلام اوس میانہِ خٲطرٕ ملامت تہٕ طنز کرنہٕ آمُت۔\n9.\\tاَمہِ پتہٕ ووٚنمُت بہٕ کَرٕ نہٕ تٔمِس سُند ذِکر، تہٕ نہ کَرٕ تٔمۍ سٕندِس ناوَس پیٹھ کَتھ کَرٕنۍ۔ مگر {تہند لفظ} اوس میٲنس دلس منز یتھہ پاٹھۍ میانین اڈجن منز دزُن نار بند گومُت، تہٕ بہٕ اوسس برداش کٔرِتھ تھکان تہٕ بہٕ ہیوٚک نہٕ {روزِ}۔\n10.\\tکیازِ میہ بوز واریاہن ہنز بدنامی، پریتھ طرفہ خوف۔ رپورٹ کٔرِو، {تِم وَن}، تہٕ أسۍ کٔرِو اَمِچ رپورٹ۔ میانۍ سٲری واقف ٲسۍ میانہِ رُکُن وچھان، {ونن}، شاید گژھہِ سہ پھیُر، تہ أسۍ کرو تس خلاف غالب، تہٕ أسۍ نِو أمس نِش پنُن انتقام۔ {سٲری ...: ہیب۔ میانہِ امن ہند پرتھ کانہہ انسان}\n11. مگر خداوند چُھہ میہ سٍتـ̡ سٍتـ̡ بێیہِ سٍتـ̡ پى۪ٹھ تِکیازِ تِم گژھن نہٕ ترقی: {تِہُند} ابدی انتشار گژھِ نہٕ زانہہ مشراونہٕ۔\n12.\\tمگر، اے خداوندگار، یُس صالحن آزماوان چُھ، {تہٕ} لگام تہٕ دِل وُچھِو، بہٕ وُچھُن تِمن سٍتـ̡ پنُن انتقام: کیازِ مے چُھہ توے سٍتـ̡ پنُن مقصد کھولمُت۔\n13. خداوند سٕندِ خٲطرٕ گٮ۪وُن، خداوند سٕندِ حمد کٔرِو، تِکیازِ تٔمۍ کٔر غریبن ہُند روح بدکارن ہٕندِ اتھہٕ نِش بچاو۔\n14.\\tسُہ دۅہ گژھہِ لعنت ییمہِ دۅہہٕ میہ زامُت اوس، سُہ دۅہ گژھ نہٕ میانہِ ماجہ دِنہٕ آمُت۔\n15.\\tسُہ بد دعا یُس میٲنِس مٲلِس خبر دِتھ وَنُن زِ ژے چُھہ اکھ شُر زامُت۔ تس چھہ سیٹھا خۅش کران۔\n16. تہٕ سُہ انسان گژھہِ تِمن شہرن ہٕندۍ پٲٹھۍ، یُس خداوند الٹٲومُت چھُ، تہٕ گژھہِ نہٕ توبہ کرُن، تہٕ سُہ گژھہِ صبحٲے فریاد تہٕ دوپہرس کُن کرٛٮ۪کہٕ بوزُن۔\n17.\\tکیازِ تٔمۍ کوٚر نہٕ میہ رحمہ پیٹھٕ مٲرِتھ۔ یا یہ زِ میانہِ موج آسہ ہا میٲنۍ قبر، تہٕ تٔمۍ سٕنز کوکھ آسہ ہمیشہ عظیم {میانہِ سۭتۍ}۔\n18.\\tبہٕ کیازِ دراو میہ رحمہٕ منزٕ محنت تہٕ غم وُچھنہٕ خٲطرٕ، یُتھ میانہِ دۅہ گژھن شرم سٍتۍ ضایع کرنہٕ؟","1. سُہ کلام یُس خداوند سٕندِ طرفہٕ یرمیاہ ہس ووت ، یێلہِ بادشاہ صدقیاہ ہن أمِس نِش ملکیا سُند نیچو پاشور تہٕ پادٕرۍ ماسیاہ سُند نیچو زفانیاہ سُند نیچو سُہ وونُن ،\n2. بہٕ چُھس ژے پرژھہٕ سانہِ خٲطرٕ خداوند سٕندِس سٍتـ̡ پرژھان۔ تکیازِ بابلُک بادشاہ نبوکدرِزر چُھ اسہِ خلاف جنگ کران۔ یێلہِ تہِ آسہِ زِ خداوند کرِ اسہِ سٍتـ̡ پنہٕ نِس سارِنٕے عجیب کامہِ مطٲبق سٍتـ̡ س�\n3.\\tیێلہِ وۆن یرمیاہ تِمن سٍتـ̡ یِتھٕ پٲٹھـ̡ تُہۍ وَنُن صدقیاہ سٍتـ̡ ۔\n4. یِتھٕ پٲٹھـ̡ چُھ اسرٲیلُک خداوند خدا فرماوان۔ وچھ، بہٕ پھیُرٕ جنگٕکۍ ہتھیار واپس یِم تہندِس اتھس مَنٛز چھِ، یِمو سٍتـ̡ تۅہہ بابل کِس بادشاہس خٕلاف لڑان چُھ، تہٕ چالدینس خٕلاف، یِم دیوارو ورٲے ژےٚ محاصرٕ کران چھِ، تہٕ بہٕ کٔرٕ تِم اتھ شہرس مَنٛز جمع کرنہٕ۔\n5. تہٕ بہٕ کَرٕ پانہٕ ژےٚ خٕلاف اَتھٕ تہٕ مضبوٗط نٔرِ سٍتۍ، شَرارتہٕ تہٕ غصہٕ سٍتـ̡ تہٕ سٮ۪ٹھاہ غصہٕ سٍتـ̡ تہِ لڑان۔\n6. تہٕ بہٕ مارٕ یَتھ شہرٕکۍ روزن وٲلۍ، انسان تہٕ جانور دۄشوٕنی، تِم مرن أکِس بٔڈِس وباہٕ سٍتۍ۔\n7. تہٕ اَمہِ پتہٕ، خداوند چُھ فرماوان زِ بہٕ کرٕ یہوداہُک بادشاہ صدقیاہ تہٕ تٔمۍ سٕندِس خادمَن تہٕ لُکن تہٕ یُس اتھ شہرس مَنٛز باقٕے روزان چُھ، یُس اتھ شہرس مَنٛز وبا نِش، تلوار نِش تہٕ قحط نِش بچاونہٕ آمُت چُھ، بابل کِس بادشاہ نبوکدرِزر سٕندِس اتھس منز، تہٕ تِمن ہٕندِس دُشمن ہٕندِس اتھس منز، تہٕ یِمن ہٕنزِ جان ژھارن والٮ۪ن ہٕندِس اتھس مَنٛز۔  تہٕ سُہ دِیہِ تِمن تلوار ہٕندِ دھار سٍتـ̡ مارُن۔ سُہ گژھِ نہٕ تِمن بخش، نہ رحم تہٕ رحم۔\n8. تہٕ یِمن لُکن وَنُن چُھہ یِتھٕ پٲٹھۍ خداوند فرماوُن؛ وچھ میہ ژے برونہہ کنہِ زندگی ہنز وتھ تہ موتچ وتھ۔\n9. یُس اتھ شہرس منز روزان چُھ، سُہ گژھہِ تلوار سٍتـ̡ تہٕ قحط سٍتـ̡ تہٕ وبا سٍتـ̡ مرُن، مگر یُس نیبر نیرِ، تہٕ یُس چالدانن ہٕندِس نِش یُس تۅہہِ گھیرٕ کٔرِتھ، سُہ روزِ زندٕ، تہٕ تٔمۍ سٕنز زندگی آسہِ أمِس خٲطرٕ شکار۔\n10. کیازِ میہ چُھ اتھ شہرس خلاف بُتھ بُتھ تھوومُت، نہ کہ اصلہٕ خٲطرٕ، خداوند چُھ فرماوان: یہِ یِیہِ بابل کِس بادشاہ سٕندِس اتھس مَنٛز دِنہٕ، تہٕ سُہ دِیہِ نارٕ سٍتـ̡ زالنہٕ۔\n11.\\tتہٕ یہوداہ کِس بادشاہ سٕندِس گرس مُتلِق چُھہ، {ونن}، خداوند سُند کلام بوزو۔\n12. اے داؤد سٕندِس گھرس سٍتـ̡ چُھہ خداوند یِتھٕ پٲٹھـ̡ فرماوان ۔ صُبحَس کٔرِو فٲصلہٕ عملہٕ، تہٕ یُس ظالم سٕندِ اتھہٕ نِش بٔرِتھ چھُ، نتہٕ گژھہِ میون غصہٕ نارٕکۍ پٲٹھۍ، تہٕ دزِتھ زٲلِتھ زِ تۅہہِ ہٕندِ بُرٲیی ہٕندِ کامہِ سٍتۍ گژھہِ نہٕ کانہہ تہِ ژھیُرِتھ۔ {ایگزیکیوٹ: ہیب۔ جج}\n13. وُچھ، بہٕ چُھس ژے خلاف، اے وادی ہٕندِس بسکین، {تہٕ} میدانٕچ پتھر، خداوند چُھ فرماوان۔ یُس ونان چُھ، اسہِ خلاف کُس واتہِ؟ نتہٕ کُس کرِ سانہِ بستن منز اژُن؟ {بسکین: ہیب۔ بسکین}\n14. مگر بہٕ دِیہٕ ژےٚ چانہِ کامہِ ہٕندِس پھلہٕ مُطٲبق سزا، تہٕ بہٕ دِیہٕ اَتھ کِس جنگلس مَنٛز نار زالنہٕ، تہٕ سُہ کرِ اَتھ أندۍ پٔکۍ سارِنٕے چیٖز کھٮ۪وان۔ {سزا: ہیب۔ وزِٹ کٔرِو}","1. خداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ یہوداہ کِس بادشاہ سٕندِس گرس مَنٛز گژھ تہٕ تتہِ کٔرِو یہِ لفظ،\n2. تہٕ وَنُن، اے یہوداہُک بادشاہ، یُس داؤد سٕندِس تختس پیٹھ بِہِتھ چُھ، تہٕ تُہٕندِس خادمَن تہٕ تُہٕندِس لُکہٕ سُند کلام بوزُن یُس یِمو دروازو کِنۍ اژان چُھ:\n3. خداوند چُھ یِتھٕ پٲٹھۍ وَنان۔ فیصلہٕ تہٕ نیکی کٔرِو عملہٕ، تہٕ ظالم سٕندِ اتھہٕ نِش کٔرِو نہٕ بدکار تہٕ کٔرِو نہٕ اَتھ جایہِ بے گناہ خون۔\n4.\\tیێلہِ داؤد سٕندِس تختس پیٹھ بِہِتھ بِہِتھ، سُہ تہٕ تٔمۍ سٕندِس نوکر تہٕ تٔمۍ سٕندِس لُکہٕ سٍتـ̡ دٲخل سپدِ۔ {on...: Heb. داؤد سٕندِس تختس پیٹھ}\n5. مگر اگر نہٕ یِم لفظ بوزِو، بہٕ چُھس پانَے قسم، خداوند چُھس ونان زِ یہِ گرٕ گژھہِ ویران بنہٕ۔\n6. یِتھٕ پٲٹھۍ چُھ خداوند یہوداہ کِس بادشاہ سٕندِس گرس سٍتـ̡ وَنان۔ ژے {اَر} گِلاد مےٚ، {تہٕ} لبنانُک سربراہ: {توتہِ} بہٕ بناوٕ ژے اکھ بیابان، {تہٕ} شہر {یِم} یِم نہٕ آباد چھِ۔\n7. تہٕ بہٕ کَرٕ ژےٚ خٕلاف تباہ کَرن وٲلہِ تیار، پرٮ۪تھ کانٛہہ پَنٕنہِ ہتھیار سٍتـ̡ تہٕ تِم ژٔٹِتھ ژٔٹِتھ نارس مَنٛز ترٛاوٕنـ̡ ۔\n8.\\tتہٕ واریاہ قوم گژھن اتھ شہرس مٔنزۍ نیران، تہٕ تِم پرٮ۪تھ أکِس شخصس پننِس ہمساین ونن، خداوند کیازِ کوٚر اتھ عظیم شہرس سٍتـ̡ یِتھٕ پٲٹھۍ کورمُت؟\n9.\\tتێلہِ دِن تِم جواب، کیازِ تِمو چُھ خداوند پنُن خدا سُند عہد ترٲومُت، تہٕ باقین دیوتاہن ہٕنز عبادت کٔرِتھ تہٕ تِہنز خدمت کٔرمٕژ۔\n10.\\tتُہۍ روو نہٕ مُردن خٲطرٕ، نہ روو أمِس خٲطرٕ یُس نیران چُھ، تکیازِ سُہ گژھِ نہٕ بییہ واپس، تہٕ نہ گژھِ پنُن وطن وُچھان۔\n11.\\tیِتھٕ پٲٹھۍ چُھ خداوند یہوداہ کِس بادشاہ یوسیاہ سٕندِس نیچوِس شلمس متعلق ونان یُس یوسیاہ سٕندِس مٲلِس سٍتـ̡ حکومت کٔر، یُس امہِ جایہ نیبر نیرِ۔ سُہ گژھِ نہٕ مزید تتہِ واپس:\n12.\\tمگر سُہ گژھہِ تتھ جایہِ مرُن ییتہِ تمو أمس قٲد کرِمُت آسہِ، تہٕ وُچھِ نہٕ یہ زمین۔\n13. یُس پنُن گرٕ بد نیکی سٍتـ̡ بناوان چُھ، تہٕ پَنُن خانہٕ بدکار سٍتـ̡ بناوان چُھ، تٔمِس سٍتـ̡ افسوس {یُس} چُھ پننِس ہمساین سٕنز خدمت مزدوری ورٲے استعمال کران، تہٕ أمِس کامہِ بدلہٕ دِیہِ نہٕ۔\n14.\\tیہ ونان، بہٕ بناوٕ پانس اکھ وسیع مکانہ تہٕ بٔڈۍ کمرہٕ، تہٕ دٲرٕ ژٔٹِتھ ژٔٹِتھ ۔ تہٕ {یہٕ} چُھ} دیودارس سٕتۍ سٕتۍ رنٛگ کرنہٕ آمُت، تہٕ سِندرٕ سٕتۍ پینٹ کرنہٕ آمُت۔ {بٔڑ: ہیب۔ تھرو ایئرڈ} {ونڈوز: یا، میٲنۍ ونڈوز}\n15.\\tژے کٔرِو بادشاہت، کیازِ ژے چھُکھ دیودارس مَنٛز نزدیک؟ چانہِ مٲلۍ اوسُکھ نہٕ کھٮ۪وان تہٕ چیٚوان تہٕ فیصلہ تہٕ انصاف کٔرِتھ، {تہٕ} پتہٕ اوسُس أمِس سٍتۍ ٹھیٖک گومُت؟\n16. سُہ اوس غریبن تہٕ محتاجن ہُند فیصلہ کران۔ اَمہِ پَتہٕ {یہِ اوس} اَکھ اَکھ {أمِس سٍتۍ: اَمہِ سٍتۍ اوسُس نہٕ یہِ زانُن؟ خداوند چُھ فرماوان۔\n17.\\tمگر تۅہہِ أچھ تہٕ تُہُند دِل چُھنہٕ تُہٕندِس لالچس سٍتـ̡ تہٕ معصوم خوُن تراونہٕ خٲطرٕ، تہٕ ظلمہٕ خٲطرٕ، تہٕ تشددٕ خٲطرٕ، یہِ کرنہٕ خٲطرٕ۔ {تشدد: یا، حملہٕ}\n18. تێمہِ کِنۍ چُھ خداوند یہوداہ کِس بادشاہ یوسیاہ سُند نیچو یہویاکیمس مُتلق یِتھ پٲٹھۍ فرماوان۔ تِم گژھن نہٕ أمِس خٲطرٕ ماتم کٔرِتھ، {ونان}، آہ میانہِ بٲے! یا، آہ بینہِ! تِم گژھن نہٕ أمِس خٲطرٕ ماتم کٔرِتھ، {ونان}، اے خدا! یا، آہ تٔمۍ سٕنز عظمت!\n19. سُہ یِیہِ گَرٕ سٕندِ دفن کرنہٕ سٍتـ̡ دفن کرنہٕ، یُس یُس یروشلم کِس دروازس نیبر کڈنہٕ یُن۔\n20. لبنان تام گژھ تہٕ روُن۔ تہٕ پنٕنۍ آواز تُلِو بشنَس مَنٛز، تہٕ وَتہٕ کٔرِو وَنُن: تِکیازِ تُہٕندِس سارِنٕے عاشق گٔیہِ تباہ گٔمٕتۍ۔\n21.\\tمیہ کٔر ژے سٍتـ̡ چانہِ خوشحالی سٍتـ̡ کتھ کرنہٕ۔ {مگر} ژے ووٚن، بہٕ بوز نہٕ۔ یہ چھہ تۅہہ جوانی پیٹھے تۅہہِ ہُند طریقہ، زِ ژے کٔر نہ میانہِ آوازِ ہنز فرمانبرداری۔ {خوشحالی: ہیب۔ خوشحالی}\n22.\\tواو گژھہِ تُہٕندِس سارِنٕے پادٕرۍ کھٮ۪نہٕ، تہٕ تُہٕندِس عاشق گژھن قٲدِس مَنٛز، یێلہِ پَزِ تێلہِ گژھِو ژے پنہٕ نِس سارِنٕے بد کارانہٕ سٍتـ̡ شرمندہ تہٕ پریشان گٔژھِو۔\n23.\\tاے لبنانکۍ بسکین، یُس دیودارس منز پنُن گرہ بناوان چھُ، تیلہِ کوتاہ مہربان روزِ ژے ییلہ ژیہ دگ وۅتھان آسہِ، تۅہہ چھہ زنانہِ ہٕندِ دگ ہٕندۍ پٲٹھۍ! {بسکین: ہیب۔ بسکین}\n24. خداوند چُھ ونان زِ بہٕ چُھس زندٕ، یێلہِ یہوداہ کِس بادشاہ یہوویقیم سُند نیچو کونیاہ آسہِ میانہِ دچھنہِ اتھس پیٹھ نشانہٕ، توتہِ کٔرٕ بہٕ ژے تتہِ تُلِتھ۔\n25. تہٕ بہٕ دِیہ ژے تِمن ہٕندِس اتھس مَنٛز یِم تُہٕندِس زُو ژھاران چھِ، تہٕ تِمن ہٕندِس اتھس مَنٛز یِمن ہٕندِس بُتھِس کھوژان چُھ، حتیٰ کہ بابل کِس بادشاہ نبوکدریزار سٕندِس اتھس منز، تہٕ چالدانن ہٕندِس اتھس منز۔\n26. تہٕ بہٕ کٔرٕ ژے تہٕ تہنز موج یُس ژےٚ زیٚنہٕ آسہٕ آمٕژ، کُنہِ بییِس ملکس مَنٛز کٔڈِتھ یتہِ نہٕ ژے زامٕژ ٲس۔ تہٕ تتہِ گژھِو تُہۍ مرُن۔\n27.\\tمگر تتھ زمینس کُن یُس تم واپس گژھُن یژھان چھِ، تتہِ گژھن نہٕ تِم واپس۔ {خواہش: ہیب۔ تِمن ہُند ذہن تُلُن}\n28.\\t{کیا یہِ شخٕص کونیاہ چھُہ اکھ حقیر پھُٹمُت بُت؟ {کیا سُہ} چُھ اکھ برتن یتھ منز {چُھ} نہٕ کانہہ لذت چُھ؟ کیازِ چھہِ تم کڈنہ آمت، سہ تہ تسند اولاد، تہ تتھ زمینس منز تراونہ یوان یُس نہ تم زانان چھہِ۔\n29. اے زمین، زمین، زمین، بوزو خداوند سُند کلام۔\n30.\\tخداوند چُھ یِتھٕ پٲٹھۍ فرماوان زِ یێمہِ شخٕص لیٚکھِو یُس بےٚ اولاد آسہِ، یُس نہٕ پننِس دۅہس مَنٛز روزِ نہٕ ترقی، تکیازِ تٔمۍ سٕندِس نسلُک کانہہ تہِ نفر روزِ نہٕ داؤد سٕندِس تختس پیٹھ بِہتھ تہٕ یہوداہَس مَنٛز حکومت کرِ۔","1. یِمن پادرین ہُند افسوس چھُ یِم میانہِ مرگہٕ ہٕندِس دامَس تباہ کٔرِتھ تہٕ پھٔہلٲوِتھ چھِ! خداوند چُھ فرماوان۔\n2. تێمہِ کِنۍ چُھ یِتھٕ پٲٹھۍ اسرٲیلُک خداوند خدایہِ میانین لُکن کھٮ۪ن دِنہٕ والٮ۪ن پادرین خلاف وَنان۔ ژے چھُکھ میٲنۍ کھورِ ژٔٹِتھ ژٔلِتھ ژٔلِتھ تہٕ تِمن نِش چھُکھ نہٕ یِمن نِش وُچھمُت، یێلہِ بہٕ چُھس ژے سٍتـ̡ پننہِ کامہِ ہٕنزِ بُرٲیی ہُند بُرٕ دِنہٕ آمُت، خداوند چُھ فرماوان۔\n3. تہٕ بہٕ کَرٕ پنٕنـ̡ کھورِ ہٕندِس باقٕے سارِنٕے مُلکو منزٕ جمع یێلہِ بہٕ تِمن ہٕندِس دُبارس مَنٛز اَنـ̡ تہٕ اَنـ̡ تِمن ہٕندِس دُبارس مَنٛز۔ تہٕ تِم گژھن پھلدار تہٕ بڑان۔\n4. تہٕ بہٕ کَرٕ تِمن پیٹھ چرواہ قٲیم یِم تِمن کھٮ۪وان دِیہِ، تہٕ تِم گژھن نہٕ مزید کھوژان، تہٕ نہ گژھن تِمن ہٕنز کٔمی، خداوند چُھ فرماوان۔\n5. خداوند چُھ ونان زِ یِم دۅہ یِوان زِ بہٕ کَرٕ داؤدس خٲطرٕ اکھ نیک شاخ تُلنہٕ، تہٕ اکھ بادشاہ کرِ بادشاہت تہٕ ترقی، تہٕ زمینس مَنٛز کرِ فیصلہٕ تہٕ انصاف انجام دِنہٕ۔\n6. تٔمۍ سٕندِس دۅہس مَنٛز ییہِ یہوداہ نجات دِنہٕ، تہٕ اسرٲیلِس روزِ رٲبطہٕ۔ تہٕ یێمہِ سُند ناو چُھہ یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ سُہ ییہِ وننہٕ یُن، خداوند سُند راستبازی۔ {خداوند...: ہیب۔ Jehovahtsidkenu}\n7. تێمہِ وِزِ یِم دۅہ یِن، خداوند چُھ ونان زِ تِم گژھن نہٕ وُنہٕ وَنُن، خداوند چُھ زندٕ، یٔمۍ اسرٲیلٕکۍ اولاد مصر کِس سرزمینہٕ منزٕ پٲدٕ کٔرۍ۔\n8. مگر خداوند چُھ زندٕ، یُس پرورش کٔرِتھ تہٕ یُس شُمالہٕ مُلکہٕ منزٕ تہٕ سارِنٕے ملکَو سٍتـ̡ یێلہِ مے تِم ژٔلِتھ دِژمٕژ ٲس۔ تہٕ تِم روزن پننِس سرزمینس منز۔\n9. پیغمبرن ہٕندِ سٍتـ̡ چُھہ میون دِل پھُٹمُت۔ میٲنۍ سٲری أڈجہِ چھِ لرزان۔ بہٕ چُھس أکِس شرابس ہٕندۍ پٲٹھۍ، تہٕ أکِس شرابس ہٕندۍ پٲٹھۍ، یٔمِس شرابَس پیٹھ غلبہٕ چُھ، خداوند سٕندِ سٍتـ̡ تہٕ تٔمۍ سٕندِ پاکیزگی ہٕندِ کلامَن سٍتـ̡ ۔\n10.\\tکیازِ زمین چھے زناکارو سٍتۍ بٔرِتھ۔ تکیازِ قسمہ کھاونہٕ سٍتـ̡ چُھہ زمینُک ماتم سپدان؛ بیابانن ہٕندۍ خۄشگوار مقام چھِ خشک گٔمٕتۍ، تہٕ تِہٕنٛز وتھ چھِ بُر، تہٕ تِہُند زور چھُنہٕ صحیح۔ {قسم: یا، لعنت} {کورس: یا، تشدد}\n11.\\tتکیازِ رسول تہٕ پادری دۅشوے چھہِ ناپاک ۔ آ، میہ چھہ میٲنس گرس منز تہنز بدکاری لبنہٕ آمژ، خداوند چُھ فرماوان۔\n12. تێمہِ مۅکھہ گژھہِ تِمن ہٕنزِ وتھ یِمن ہٕندِ خٲطرٕ رِکٕرِتھ تہٕ یِمن ہٕندِس یِنہٕ وٲلِس ؤریس سٍتـ̡ تہِ یِمن سٍتـ̡ بُرٕ واتناوُن، خداوند چُھ فرماوان۔\n13.\\tتہٕ میہ وچھ سامریہ کین پیغمبرن منز حماقت۔ تِمو کٔر بعلس مَنٛز پیشن گوئی، تہٕ میانہِ لُکہٕ اسرٲیلٕچ غلطی کٔرٕنۍ۔ {حماقت: یا، اکھ مضحکہ خیز چیز: ہیب۔ ناپسندیدہ}\n14.\\tمیہ وچھ یروشلم کین پیغمبرن منز تہِ اکھ خوفناک چیز: تم چھہِ زنا کران تہ اپزس منز پکان۔ تم چھہِ بدکارن ہندس اتھس تہِ مضبوط کران زِ کانہہ تہِ گژھہِ نہ پننہِ بدکاری نشہِ واپس۔ {an...: یا، گندگی}\n15. تێمہِ کِنۍ چُھ لشکرن ہُند رب پیغمبرن مُتلق ونان؛ وُچھِتھ بہٕ دِیہٕ تِمن کۅکرِ سٍتـ̡ تہٕ دِیہٕ تِمن گالُک آب چیوان، تکیازِ یروشلم کین پیغمبرن سٍتـ̡ چُھہ سارِنٕے زمینس مَنٛز ناپاک سپدان۔ {فحش: یا، منافقت}\n16. یِتھٕ پٲٹھـ̡ چُھ لشکرن ہُند رب فرماوان، پیغمبرن ہٕندِس کلامَس مَنٛز مہٕ بوزُن یُس تۅہہِ نِش پیشن گویی کران چُھ، تِم چِھ تۅہہِ بیکار بناوان: تِم چِھ پننہِ دِلُک وژن بولان، {تہٕ} نہٕ خداوند سٕندِ مُنہٕ سٍتـ̡ ۔\n17.\\tتِم چھِ وُنہِ تہِ تِمن وَننہٕ آمٕتۍ یِم مےٚ حقارت کران چھِ، خداوند چُھ وَنُن زِ تُہہِ گژھہِ امن حٲصِل کرنہٕ۔ تہٕ تِم چھِ پریتھ أکِس شخصس ونان یُس پننہِ دِل کِس تصورس پٔکِتھ پکان چُھ، تۅہہِ گژھہِ نہٕ کانہہ بُرٲے واتہِ۔ {تخیل: یا، ضد}\n18.\\tیُس چُھ خداوند سٕندِس مشورس مَنٛز کھڑا گومُت، تہٕ تٔمۍ سُند کلام بوزمُت تہٕ بوزمُت؟ کٔمۍ چُھ پنن کلام نشان زد کورمُت، تہٕ بوزمُت {یہ}؟ {مشورہ: یا، راز}\n19.\\tوُچھِو خداوند سُند اکھ وُپھ وُپھ تہِ وُپھ دِنہٕ آمُت، یُس بدکار سٕندِس کلس پیٹھ پَسُن۔\n20. خداوند سُند غصہٕ گژھہِ نہٕ واپس یُس نہٕ توٚت تام زِ سُہ پھٲلِتھ تہٕ توٚت تام نہٕ سُہ پَنٕنِس دِلُک خیال انجام دِیہِ: پٔتِمِس دۅہس مَنٛز گژھِو تُہۍ اتھ پیٹھ پورٕ پٲٹھۍ۔\n21.\\tمیہ چھہ نہ یم پیغمبر سوزمٕتۍ، توتہِ چھہِ تِمو ژٔلۍمٕتۍ، میہ چھے نہٕ تمن سٍتـ̡ کتھ کٔرمٕژ، توتہِ کٔر تِمو پیشن گوئی۔\n22.\\tمگر اگر تِم میانہِ مشورس منز کھڑا آسن تہٕ میانین لوکن میٲنۍ کلام بوزناوان آسہِ، تیلہِ گژھن تِم پننہِ بد وتہِ نِش تہٕ پننہِ بد عملہِ نِش پھیرٕنۍ۔\n23. خداوند چُھس ونان زِ بہٕ چُھس اتھس منز خدا، تہٕ دوٗر چُھہ نہٕ خدا؟\n24.\\tکانہہ ہیکہِ خفیہ مقامن منز ژوٗرِ روزِتھ یُس نہ میہ وُچھِتھ آسہِ؟ خداوند چُھ فرماوان۔ بہٕ چھُس نہٕ آسمانس تہٕ زمینس بٔرِتھ؟ خداوند چُھ فرماوان۔\n25.\\tمیہ بوزمُت زِ پیغمبرن ہُند ونُن چُھہ زِ پیشن گویی چھے میانہِ ناوٕ سٍتـ̡ ونان، میہ چُھہ خواب وُچھمُت۔\n26. پیغمبرن ہٕندِس دِلس مَنٛز کُس کالس روزِ یِم پیشن گویی کران چھِ؟ آ، {تِم} چھِ پننہِ دِلٕچ دھوکہٕ دِنٕکۍ پیغمبر۔\n27.\\tیُس میانہِ لُکن ہُند ناو پننیو خوابن سٍتۍ مٔشِد کرُن یُس تِم پرٮ۪تھ أکِس انسانس پننِس ہمساین ونان چھِ، تِکیازِ تِمن ہٕندِس مٲلِس چھُ میون ناو بعل مٔشِد گومُت۔\n28.\\tیُس نبی خواب آسہِ، سُہ گژھہِ خواب۔ تہٕ یُس میون کلام آسہِ، سُہ گژھہِ میون کلام وفاداری سان بولُن۔ کٕنکہٕ خٲطرٕ کیا چُھ؟ خداوند چُھ فرماوان۔ {یتھ اکھ خواب: ہیب۔ کُس چھُ وغیرہ}\n29.\\t{کیا چھُنہ} میون کلام نارس ہیو ہیو؟ خداوند چُھ فرماوان؛ تہٕ ہتھوڑٕکۍ پٲٹھۍ{یُس} کٔنہِ ٹُکرٕ ٹُکرٕ پھُٹراوان؟\n30.\\tتێلہِ چُھس بہٕ پیغمبرن خلاف چُھس، یُس پریتھ کانہہ ہمسایہ نِش میون کلام ژوٗرِ نِوان چُھ۔\n31. وچھو بہٕ چُھس پیغمبرن خلاف چُھ، خداوند چُھ ونان یُس تِہنز زبان استعمال کران چُھ، تہٕ ونان چُھ، سُہ چُھ وَنان۔ {یہ...: یا، تِمن ہٕنزِ زبانہِ ہموار کٔرِتھ}\n32.\\tوُچھِو بہٕ چُھس تِمن خلاف یُس اپُز خوابن ہٕنز پیشن گویی کران چُھ، خداوند چُھ ونان تہٕ تِمن وَنُن تہٕ میانین لوکن ہٕندِس اپزس سٍتـ̡ تہٕ تِمن ہٕنزِ ہلکی سٍتـ̡ گمراہ کران چُھہ ۔ توتہِ چُھس نہٕ مے تِم سوزمٕتۍ، تہٕ نہ دِیُتمُت حُکُم، لہذا یِمن ہُند کانہہ تہِ فٲیدٕ واتناوُن، خداوند چُھ فرماوان۔\n33.\\tتہٕ یێلہِ یێلہِ یہِ لُکھ یا پیغمبر یا پادٕر، تۅہہِ پرژھہِ زِ خداوند سُند بار کیا چُھہ؟ تیلہِ وَنُن تِمن کُس بوج؟ خداوند چُھ ونان زِ بہٕ کَرٕ ژےٚ تہِ ترک۔\n34.\\tتہٕ پیغمبر، پادٕرۍ تہٕ عوامس متعلق، یُس ونان، خداوند سُند بوجھ، بہٕ کرٕ أمس شخصس تہٕ تٔمۍ سٕندِس گرس سزا۔ {سزا: ہیب۔ وزِٹ کٔرِو}\n35. یِتھٕ پٲٹھۍ وَنُن پرٮ۪تھ أکِس پننِس ہمساین تہٕ پرٮ۪تھ أکِس پننِس بٲیِس سٍتۍ، خداوند کیا دِیُت جواب؟ تہٕ، خداوند کیا چُھ کتھ کٔرمٕژ؟\n36.\\tتہٕ خداوند سُند بار تہٕ کٔرِو نہٕ زیادٕ کُنہِ تہِ ذِکر، تکیازِ پرٮ۪تھ أکِس انسان سُند کلام آسہِ تٔمۍ سُند بوجھ۔ تکیازِ توے چُھہ زندٕ خدایہ سٕندِس کلامَس مسخ کٔرِمُت، یُس سانہِ خدایہ سُند رب سُند کلام چھُ۔\n37. یِتھٕ پٲٹھـ̡ چُھہ رسولس وَنُن، خداوند کیا چُھہ تُہُند جواب دِژمُت؟ تہٕ، خداوند کیا چُھ کتھ کٔرمٕژ؟\n38.\\tمگر یێلہِ چُھہ تُہۍ ونان چُھہ، خداوند سُند بوجھ۔ تێمہِ کِنۍ چُھ خداوند یِتھٕ پٲٹھۍ وَنان۔ کیازِ تُہۍ چُھہ یہِ لفظ ونان خداوند سُند بوجھ، تہٕ مے چُھس ژے سوزمُت، تہٕ وَنُن چُھہ نہٕ خداوند سُند بوجھ۔\n39. تێمہِ کِنۍ، بہٕ تہٕ بہٕ تہِ ژے تہٕ ژے تہٕ سُہ شہر یُس میہ ژے تہٕ تہندین بابن دِژمُت چُھ، {تہٕ ژے کٔرِتھ کٔرِتھ} پننہِ حٲضِری نِش کٔرِتھ:\n40. تہٕ بہٕ اَنہٕ ژےٚ خٲطرٕ اکھ ابدی ملامت تہٕ اکھ دٲیمی شرم، یُس نہٕ مشراونہٕ ییہِ۔","1.\\tخداوند ہٲو میہ تہٕ وُچھِتھ آیہ خداوند سٕندِس مندرس برونہہ کُن انجیر ہٕنز زٕ ٹوٗکرِ تھاونہٕ، تمہِ پتہٕ اوس بابلُک بادشاہ نبوکدرِززار یہوداہ کِس بادشاہ یہوواہ سُند نیچو یکونیاہ تہٕ یہوداہ کِس شہزادس یروشلیم پیٹھٕ چھانن تہٕ لوہارن سٍتـ̡ قٲد کٔرِتھ أنِمُت۔\n2.\\tاکھ ٹوٗکرِ {ٲس} واریاہ اصل انجیر {حتیٰ کہ} ہیو انجیر {یُس گۅڈہ پوٚکمت چھہِ} تہ بیاکھ ٹوٗکرِ {ٲس} سیٹھا شرارتی انجیر یُس نہ کھٮوان اوس، تم ٲسۍ سیٹھا خراب۔ {تِم...: ہیب۔ بدی خٲطرٕ}\n3. اَمہِ پتہٕ ووٚن خداوند مےٚ زِ یرمیاہ کیا چُھکھ وُچھان؟ تہٕ میہ ووٚن، انجیر؛ اصل انجیر، واریاہ اصل؛ تہٕ بُر، سٮ۪ٹھاہ بُر، یُس نہٕ کھٮ۪تھ ہیکو، تِم چھِ واریاہ بُرۍ۔\n4.\\tبییہِ آو میہ نِش خداوند سُند کلام وونُن،\n5. یِتھٕ پٲٹھـ̡ چُھ خداوند یُس اسرٲیلُک خدا چُھہ فرماوان۔ یِمن اصل انجیٖرن ہٕندۍ پٲٹھۍ، بہٕ تہٕ کرٕ تِمن ہُند اعتراف یِم یہوداہٕ سٕندِس قٲد کٔرِتھ نِنہٕ آمٕتۍ، یِم مے یَتھ جایہِ نِش کلدانن ہٕندِس سرزمینس مَنٛز سوزمٕتۍ چھِ۔ {تِم...: ہیب۔ قید}\n6.\\tکیازِ بہٕ کٔرٕ تِمن پیٹھ نظر، تہٕ بہٕ اَنہٕ تِم دُبارٕ یتھ زمینس پیٹھ: تہٕ بہٕ کرٕ تِم تعمیر تہٕ نہٕ تِمن ہٕندِس پٲٹھۍ۔ تہٕ بہٕ کٔرٕ تِم لاگُن، تہٕ تُلنہٕ نہٕ تِمن ہُند تُلُن۔\n7. تہٕ بہٕ دِیہ تِمن دِل زِ بہٕ چُھس خداوند تہٕ تِم گژھن میٲنۍ لوک، تہٕ بہٕ بنہٕ تِہُند خدا، کیازِ تِم گژھن پنٕنـ̡ پوٗرٕ دِلہٕ سٍتـ̡ میانہِ نِش واپس۔\n8. تہٕ یِتھٕ پٲٹھۍ بد انجیر یُس نہٕ کھٮ۪نہٕ یِوان چھُ، تِم چھِ سٮ۪ٹھاہ بدکار ۔ یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، یِتھے پٲٹھۍ دِیہٕ بہٕ یہوداہُک بادشاہ تہٕ تٔمۍ سٕندِس شہزادن تہٕ یروشلمٕچ باقیات یِم اتھ زمینس مَنٛز روزان چھِ، تہٕ یِم مصرٕچ سرزمینس مَنٛز روزان چھِ۔\n9.\\tتہٕ بہٕ واتناوٕ تِم سارِنٕے سلطنتن مَنٛز نِنہٕ خٲطرٕ، یِمن ہٕندِس دَرٕج سٍتـ̡ تہٕ اَکھ مَضموٗن تہٕ اکھ طعنہٕ تہٕ لعنت، یێلہِ تہٕ یێلہِ بہٕ یِمن کُن کٔرِتھ دِیہِ۔ {ہٹاونہٕ خٲطرٕ: Heb. ہٹاونہٕ خٲطرٕ، یا، پریشانی}\n10. تہٕ بہٕ سوزٕ تلوار، قحط تہٕ وبا تِمن منز، یوٚت تام تِم تِمن تہٕ تِہندین مٲلن دِژمٕژ زمینہٕ نِش ختم گژھن۔","1. یہوداہ کِس بادشاہ یوسیاہ سٕندِس نیچوِس ژوٗرمِس ؤریس مَنٛز یُس یہوداہ کِس بادشاہ نبوکدِصر سُند گۄڈنیُک ؤری اوس یرمیاہ ہس متعلق۔\n2. یُس یرمیاہ پیغمبرن یہوداہ کین سارنٕے لوکن تہٕ یروشلم کین سارنٕے بسکینن سٍتـ̡ وونُن چُھ،\n3. یہوداہ کِس بادشاہ آمون سٕندِس نیچوِس یوسیاہ سٕندِ تروٲہِمہِ ؤری پیٹھ، از تام یعنی تریہ تہٕ وُہمہِ ؤری، خداوند سُند کلام چُھہ میہ نِش آمُت، تہٕ مے چُھس ژے سٍتـ̡ کتھ کٔرمٕژ، سُلہٕ وُتھِتھ کتھ کٔرِتھ۔ مگر تۅہہ بوز نہٕ۔\n4. تہٕ خداوند چُھ توے نِش پَنٕنـ̡ سارِنٕے خادمَن پیغمبرن سٍتـ̡ سوزمُت، سُلہٕ وُتھِتھ تہٕ سوزُن۔ مگر ژے بوز نہٕ تہٕ نہ بوزنہٕ خٲطرٕ کٔرٕکھ پنٕنۍ کَن۔\n5.\\tتِمو ووٚن، وُنہِ کُنہِ أکِس بد وتہِ نِش تہٕ پننہِ کامہِ ہٕنزِ بد وتہِ نِش پھیُرِو، تہٕ تتھ زمینس مَنٛز روزُن یُس خداوند تہٕ تُہٕندِس مٲلِس دِژمُت چھُ۔\n6. تہٕ یِمن ہٕنزِ عبادت کرنہٕ خٲطرٕ تہٕ تِمن ہٕنزِ عبادت کرنہٕ خٲطرٕ گژھ نہٕ تہٕ بہٕ کٔرِو نہٕ پنٕنـ̡ اَتھن ہٕندِس کامہِ سٍتـ̡ ناراض کرنہٕ خٲطرٕ۔ تہٕ بہٕ کٔرٕ نہٕ ژےٚ کانٛہہ تہِ تکلیف دِوان۔\n7. توتہِ چُھہ نہٕ میہ بوزمُت، خداوند چُھ فرماوان۔ تہ ژیہ کٔرِکھ میہ پننین اتھن ہنزِ کامہِ سٍتۍ شرارت دِنہٕ۔\n8. تێمہِ کِنۍ چُھ لشکرن ہُند رب یِتھٕ پٲٹھۍ وَنان۔ کیازِ ژے چُھہ نہٕ میٲنۍ کتھ بوزمٕژ،\n9.\\tوُچھ، بہٕ سوزٕ تہٕ نِنہٕ شمالہٕ کِس سارِنٕے عیالس تہٕ نِنہٕ بابل ہُک بادشاہ، میون خادم، تہٕ یِمن ہٕندِس زمینس خٕلاف، تہٕ اَتھ کِس بسکینس خٕلاف تہٕ یِمن سارِنٕے قومن خٕلاف، تہٕ یِمن ہٕندِس سٍتـ̡ کرٕ تِمن ہٕندِس سٍتـ̡ تباہ تہٕ تِمن ہٕندِس حٲرتس تہٕ ہٕندِس سٍتـ̡ تہٕ یِمن ہٕندِس سٍتـ̡ تہٕ یِمن ہٕندِس سٍتـ̡ ہٕندِس سٍتـ̡ سٍتـ̡ تہٕ یِمن ہٕندِس سٍتـ̡ ہٕندِس سٍتـ̡ سٍت  تہٕ دٲیمی ویران۔\n10. امہِ علاوٕ نِہ بہٕ تِمن نِش خوشی ہٕنز آواز، تہٕ خوشی ہٕنز آواز، مہرازٕ سٕنز آواز، مہرازٕ سٕنز آواز، ملہِ ہٕنز آواز، تہٕ شمعہٕ سٕنز گاش۔ {بہٕ کرُن...: ہیب۔ بہٕ کرٕ تمن نش ختم}\n11.\\tتہ یہ سورے زمین گژھہِ ویران تہ حیران۔ تہٕ یِم قوم کٔرِن ستتھ ؤرین بابل کِس بادشاہس سٕنز خدمت۔\n12.\\tتہٕ یێلہِ ستتھ ؤری سپدِ، بہٕ دِیہٕ بابل کِس بادشاہس تہٕ تتھ قومس سزا، تہٕ کالدنین ہٕنزِ زمینہٕ سٍتـ̡ دِیہٕ دٲیرٕ خٲطرٕ۔ {سزا: ہیب۔ وزِٹ کٔرِو}\n13.\\tتہٕ بہٕ اَتھ زمینس پیٹھ پنٕنۍ سٲری کتھ یُس میہ اتھ خلاف بیان کورمُت چُھ، {حتیٰ کہ} یُس اتھ کتابہِ منز لیکھنہٕ آمُت چُھ، یُس یرمیاہ ہن سارنٕے قومن خلاف پیشن گویی کورمُت چھُ۔\n14.\\tواریاہ قومن تہٕ بٔڈ بادشاہن تہِ کرِ تِمن ہٕنزِ خدمت تہٕ بہٕ دِیہٕ تِمن ہٕندِ اعمال مطٲبق تہٕ تِہندِ کامہِ مُطٲبق بدلہٕ۔\n15. یِتھٕ پٲٹھۍ چُھ اسرٲیلُک خداوند میانہِ خٲطرٕ وَنان۔ امہِ قہر ہُند پیالہ رٔٹِتھ رٔٹِتھ تہٕ یِمن سارِنٕے قومن یِمن نِش بہٕ ژےٚ سوزان چھُس، یہ چیٚنہٕ خٲطرٕ۔\n16. تہٕ تِم گژھن چیٚن، تہٕ ہلاونہٕ یِن، تہٕ پاگل گژھن، یُس تلوار بہٕ تمن درمیان سوزان چھُ۔\n17. تێمہِ پَتہٕ نِیوو میہ خداوند سٕندِس اتھس نِش پیالہ تہٕ بنووُن سارِنٕے قومن چیٚنہٕ، یِمن نِش خداوند میہ سوزمُت اوس۔\n18.\\tیروشلم تہٕ یہوداہ کِس شہرس تہٕ تِمن ہٕندِس بادشاہن تہٕ تِمن ہٕندِس بادشاہس تہٕ یِمن ہٕندِس بادشاہس سٍتـ̡ یِمن ہٕندِس ویرٲنی ، حٲرت، تہٕ لعنتُک بَناوُن۔ یتھے پاٹھۍ {یہ چھہ} از دۅہ؛\n19. فرعون، مصرُک بادشاہ، تہٕ تٔمۍ سٕندِس خادم، تہٕ تٔمۍ سٕندِس شہزادس تہٕ تٔمۍ سٕندِس سارِنٕے لُکہٕ۔\n20.\\tتہٕ سارِنٕے رَلہٕ مِلہٕ لُکھ تہٕ عُزٕکۍ سارِنٕے بادشاہ تہٕ فلسطینی تہٕ اَشکلون تہٕ عزا، تہٕ عکرون تہٕ اَشدود سٕندِ باقٕے سٍتـ̡\n21. ادوم تہٕ موآب تہٕ عمون سٕندِ اولاد،\n22. تہٕ ٹائرس ہٕندِ سارِنٕے بادشاہ، تہٕ زیدونٕکۍ سارِنٕے بادشاہ، تہٕ جزیرٕکۍ بادشاہ یِم سمندرٕ اپارِ چھِ، {جزیرٕ: یا، سمندرٕ کِس بٔٹھِس کُن علاقہٕ}\n23.\\tدیدان، تہٕ تیما، تہٕ بوز، تہٕ سٲری {یِم} چھِ، {یہ...: ہیب۔ کونن منز ژٹنہٕ، یا مس کین کونن پیٹھ کٔرِتھ}\n24.\\tتہٕ عربٕکۍ سارِنٕے بادشاہ تہٕ رَلہٕ مِلہٕ لُکن ہٕندِ سارِنٕے بادشاہ یِم صحراہس مَنٛز روزان چھِ،\n25. تہٕ زِمری ہٕندِ سارِنٕے بادشاہ، تہٕ ایلام ہٕندِ سارِنٕے بادشاہ تہٕ مادٕکۍ سارِنٕے بادشاہ،\n26.\\tتہٕ شُمالٕکۍ سارِنٕے بادشاہ، دور تہٕ نزدیک، اَکھ أکِس سٍتۍ، تہٕ دُنیاہٕکۍ سارِنٕے بادشاہت، یِم زمینہٕ کِس بُتھِس پیٹھ چھِ، تہٕ شیشاچُک بادشاہ چُھ تِمن پَتہٕ چُھنہٕ۔\n27. تێمہِ کِنۍ چُھہ تِمن وَنُن، یِتھٕ پٲٹھـ̡ چُھہ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھہ وَنان۔ تم پیوو تہٕ شراب، تہٕ ژٔلِو، تہٕ پیوٚو، تہٕ وۄتھٕ نہٕ، تتھ تلوار سٍتۍ یُس بہٕ ژےٚ درمیان سوز۔\n28. تہٕ یێلہِ تِم پیالہ چنہٕ خٲطرٕ تۅہہِ ہٕندِس اتھس نِش نِش انکار کَرٕن، تێلہِ گژھہِ تِمن وَنُن، یِتھٕ پٲٹھۍ چُھہ لشکرن ہُند رب فرماوُن؛ ژیہ پزۍ پاٹھۍ چیوٚن۔\n29.\\tیِہ چُھس بہٕ یُس شہرس مَنٛز بُرٕ انُن شروع کران چھُ، یُس میانہِ ناوٕ سٍتـ̡ وننہٕ چُھ، تہٕ کیا ژے گژھہِ نہٕ سزا دِنہٕ؟ لشکرن ہُند رب چُھ ونان زِ بہٕ کرٕ زمینہٕ کین سارنٕے بسکینن پیٹھ تلوار منگناونہٕ۔ {کُس...: ہیب۔ یتھ پیٹھ میون ناو چُھ وننہٕ یوان}\n30. تێمہِ کِنۍ کٔرِو تِمن سارِنٕے کلامَن ہٕنز پیشن گویی تہٕ تِمن ونُن، خداوند کرِ تھزرٕ پیٹھٕ گرٛٮ۪ز، تہٕ پَنٕنـ̡ پۯاوٕنـ̡ پى۪ٹھ۔ سُہ کرِ پننہِ بستی پیٹھ زورٕ سان گرٛٮ۪ز۔ سُہ دِیہِ کرٛٮ۪کہٕ، یِتھٕ پٲٹھۍ یِم زمینہٕ کیٚن سارِنٕے بسکیٖنن خٕلاف پکان چھِ۔\n31.\\tاکھ شور گژھہِ زمینہِ ہندس اندس تام تہِ۔ کیازِ خداوند چُھ قومن سٍتـ̡ تنازعہٕ، سُہ کرِ سارنٕے مازس سٍتـ̡ التجا کرنہٕ۔ خداوند چُھ ونان زِ سُہ دِیہِ تِمن تلوارِ سٍتـ̡ بدکار چُھہ ۔\n32. یِتھٕ پٲٹھـ̡ چُھ لشکرن ہُند رب وَنُن زِ وُچھِو بُد بُد قومہٕ پٮ۪ٹھٕ قومہٕ پٲٹھۍ، تہٕ زمینہٕ کِس بٹھہٕ پیٹھٕ ییہِ اکھ بۆڈ وُپھ وُتھنہٕ۔\n33.\\tتہٕ خداوند سُند قتل گژھہِ تمہِ دۅہہ زمینہٕ کِس أکِس اندس پیٹھٕ زمینہِ ہٕندِس اندس تام، تِمن گژھِ نہٕ ماتم کرنہٕ، نہ جمع کرنہٕ یِن، تہٕ نہ یِن دفن کرنہٕ۔ تِم گژھن زمینس پیٹھ گُبر دِنہٕ۔\n34. اے چرواہ تہٕ کٔرِو کرٛٮ۪و۔ تہٕ رٔلِو پان رٔلِتھ رٔلِتھ رٔٹِتھ تہٕ تُہٕندِ ذبحٕکۍ دۅہ گٔیہِ مُکمل گٔمٕتۍ۔ تہٕ تُہۍ پٔزِو أکِس خۄشگوار برتن ہٕندۍ پٲٹھۍ۔ {دۅہہ...: ہیب۔ تُہند دۅہ ذبح کرنہٕ خٲطرٕ} {اکھ خوشگوار...: ہیب۔ خواہشُک اکھ برتن}\n35.\\tتہٕ پٔرِس آسہِ نہٕ ژلنٕچ کانہہ وتھ تہٕ نہ آسہِ ژلنہٕ خٲطرٕ۔ {چرواہے ...: ہیب۔ ژٔلِتھ وغیرہ}\n36.\\tپٔرِن ہٕنزِ فریاد ہٕنز آواز، تہٕ رٔژھہِ ہٕندِس مٲلِس سٕندِ کرٛٮ۪کہٕ ہٕنز آواز، {بوزنہٕ یِن}: کیازِ خداوند چُھ تِہُند چراگاہ برباد کوٚرمُت۔\n37. تہٕ خداوند سٕندِ شدید غصہٕ سٍتـ̡ چُھہ امن بستہٕ ژٹنہٕ یوان۔\n38.\\tتٔمۍ چُھ پَنُن پوشہٕ شیر سٕندِ پٲٹھۍ، تِکیازِ تِہٕنز زمین چھے ظالم سٕنزِ شدتہٕ کِنۍ تہٕ تٔمۍ سٕندِس شدید غصہٕ سٍتـ̡ ویران گٔمٕژ۔ {ویران : ہیب۔ اکھ ویرانی}","1. یہوداہ کِس بادشاہ یوسیاہ سٕندِس نیچوِس یہویاکیٖم سٕندِس دورس مَنٛز آو یہِ کلام خداوند سٕندِ طرفہٕ وَننہٕ،\n2. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ خداوند سٕندِس گرٕ کِس آنگنس مَنٛز کھڑا گژھِو، تہٕ یہوداہ کین سارنٕے شہرن سٍتـ̡ کتھ کرٕن، یِم خداوند سٕندِس گرس مَنٛز عبادت کرنہٕ خٲطرٕ یوان چھِ، تِم سٲری لفظ یِم بہٕ ژے تِمن سٍتـ̡ بولنُک حُکُم چُھس دِوان۔ اکھ لفظ تہِ کم کرُن:\n3.\\tاگر تِم بوزان تہٕ پرٮ۪تھ أکِس انسانس پننہِ بد وتہِ نِش پھیُرِن، یُس بہٕ تِمن ہٕنزِ بد کاری ہٕندِ وجہ سٍتـ̡ تِمن سٍتـ̡ کرُن یژھان چھُس۔\n4. تہٕ تُہۍ کٔرِو تِمن وَنُن، یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ یێلہِ نہٕ ژٕ میانہِ کتھ بوزِو، میانِس قانونس مُطٲبِق، یُس مے ژے برونہہ کُن تھوومُت چُھ،\n5.\\tمیانین بندھن ہٕنز کتھ بوزنہٕ خٲطرٕ، یِم میہ تۅہہِ نِش سوزمٕتۍ، دۅشوے سُلہٕ وۅتھان تہٕ سوزان چھِ، مگر تۅہہ چُھہ نہٕ بوزمُت۔\n6. تیلہٕ بناوٕ بہٕ یہِ گرٕ شِلوہٕکۍ پٲٹھۍ، تہٕ بَناوٕ یہِ شہر سارِنٕے زمینہٕ کیٚن قومن خٲطرٕ لعنت۔\n7.\\tتێلہِ بوز پادٕرۍ تہٕ پیغمبرو تہٕ سارِوٕے لوکو یێرمیاہ سٕندِس گرس مَنٛز یِم کلام بولان۔\n8. وۅنۍ سپد یہِ سپدُن، یێلہِ یرمیاہ ہن سارِنٕے لُکن سٍتـ̡ کتھ کرنُک حُکُم دِژمُت اوس تہٕ پادٕرۍ تہٕ پیغمبرن تہٕ سارِنٕے لُکن ہُند وَنُن تہٕ سارِنٕے لُکھ رٔٹِتھ تہٕ وَنُن زِ تُہہِ گژھہِ یٔقیٖنی طور مَرُن۔\n9. ژے کیازِ کٔر خداوند سٕندِ ناوٕ سٍتـ̡ پیشن گویی کٔرِتھ زِ یہِ گرٕ گژھہِ شیلوہس ہیوٗ تہٕ یہِ شہر گژھہِ کُنہِ بسکیٖن ورٲے ویران۔ تہٕ سٲری لُکھ گٔیہِ یرمیاہ سٕندِس گرس مَنٛز جمع ۔\n10.\\tییلہِ یہوداہ کٮ۪و شہزادو یِم کتھ بوز، تِم وٲتۍ بادشاہ سٕندِ گرٕ پیٹھٕ خداوند سٕندِس گرس تام، تہٕ بیوٹھ خداوند سٕندِس نٔوِس دروازس مَنٛز۔ {منز...: یا، دروازس پیٹھ}\n11.\\tاَمہِ پَتہٕ کٔر پادٕرۍ تہٕ پیغمبرن شہزادن تہٕ سارِنٕے لُکن سٍتـ̡ وَنُن زِ یہِ انسان چُھہ مرنس لایق۔ تکیازِ تمۍ چھیہ اتھ شہرس خلاف پیشن گویی کٔرمٕژ، یۅہے زن ژیہ پننیو کنو سیتۍ بوزمژ۔ {یہ انسان...: ہیب۔ موتُک فیصلہ چھُ أمِس شخصہٕ سٕندِ خٲطرٕ}\n12.\\tتێلہِ وۆن یرمیاہ سارنٕے شہزادن تہٕ سارنٕے لُکن سٍتـ̡ وونُن زِ خداوند چُھس مے یَتھ گرس تہٕ یتھ شہرس خلاف تِم سٲری کلام یِم تۅہہ بوزمٕژ چھِ۔\n13.\\tتێلہِ کٔرِو وۅنۍ پَنٕنـ̡ وَتھ تہٕ پَنٕنـ̡ کٔرِو پَنٕنـ̡ خدایہِ سٕنزِ آوازِ ہٕنز فرمانبردار۔ تہٕ خداوند کرِ أمِس تتھ بُرٲیی نِش توبہ یُس تٔمۍ تۅہہِ سٍتـ̡ دِژمُت چُھ۔\n14.\\tیوتام میہ چھُ، وچھ بہٕ چُھس تہندِس اتھس منز: میہ سٍتۍ کرُن یُتھ نیک باسان تہٕ ژے سٍتۍ مِلُن۔ {as...: Heb. تکیازِ یہ چھہ تہنزِ نظرن منز اصل تہ صحیح}\n15. مگر ژیہ پژھ پٲٹھۍ، اگر ژیہ میہ مارِو، تیلہِ گژھہِ پانس تہ یتھ شہرس تہ امہ کین بسکینن پیٹھ بے گناہ خون، تکیازِ پزۍ پاٹھۍ چھہ خداوند میہ ژے نِش سوزمُت یُس سٲری لفظ تہندین کنن منز بولنہٕ مۅکھہ۔\n16. اَمہِ پَتہٕ ووٚن شہزادو تہٕ سارِنٕے لُکن پادٕرین تہٕ پیغمبرن سٍتـ̡ ۔ یہِ شخٕص چُھنہٕ مرنس لایق: تِکیازِ تٔمۍ چُھ سانہِ خدایہ سٕندِ ناوٕ سٍتـ̡ اسہِ سٍتـ̡ کتھ کٔرمٕژ۔\n17.\\tاَمہِ پَتہٕ ووٚتھ زمینہٕ کین بُزرگ تہٕ سارِنٕے لُکن ہٕندِس مجلسس سٍتـ̡ وونُن\n18. میکاہ موراستی کٔر یہوداہ کِس بادشاہ حزقیاہ سٕندِس زمانس مَنٛز پیشن گویی تہٕ یہوداہ کین سارنٕے لُکن سٍتـ̡ وونُن زِ یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب فرماوُن۔ صیون یِیہِ کھہٕ ہٕندۍ پٲٹھۍ، تہٕ یروشلم گژھہِ ڈھیر تہٕ گرُک پہاڑ گژھہِ جنگلٕچ تھدِ جایہ۔\n19. کیا یہوداہُک بادشاہ حزقیاہ تہٕ سارِنٕے یہوداہَن دِژ سُہ مارُن؟ کیا سُہ اوس نہٕ خداوند سُند خوف تہٕ خداوند سٕنز منگ کٔرٕن، تہٕ خداوند کٔر تٔمِس بُرٲیی نِش توبہ یُس تٔمۍ تِمن خلاف اعلان کورمُت اوس۔ یتھہ پاٹھۍ ہیکون اسۍ پننین روحن خلاف بٔڈ بد کاری حٲصل کٔرتھ۔ {رب تہٕ: ہیب۔ رب سُند بُتھ وغیرہ}\n20. تہٕ اَکھ شخٕص تہِ اوس یٔمۍ خداوند سٕندِ ناوٕ سٍتـ̡ پیشن گویی کٔرمٕژ یُس کرجاتجیریم کِس شمعیاہ سُند نیچو اوس، یٔمۍ یرمیاہ سٕندِ سارِنٕے کلامَو مُطٲبِق یَتھ شہرس تہٕ یَتھ زمینس خلاف پیشن گویی کٔر:\n21.\\tییلہ یہویاکیمن بادشاہ پننین سارِنٕے طاقتور نفرن تہٕ سارِنٕے شہزادن سٍتـ̡ تٔمۍ سٕنز کتھ بوٗز، بادشاہن کٔر أمِس مارنٕچ کوٗشش، مگر یێلہِ یۆریجاہَن یہِ بوٗز، سُہ گوٚو کھوژُن، تہٕ ژوٚل تہٕ ژوٚل مصرس منز۔\n22.\\tتہٕ یہویاکیمن سوٗزۍ مرد مصرس مَنٛز، یعنی} اَختبور سُند نیچو ایلناتھن، تہٕ أمِس سٍتـ̡ سٍتـ̡ مرد مصرس مَنٛز۔\n23. تہٕ تِمو أنِتھ یُوریاہ مصرہٕ منزٕ تہٕ أنِن یہویاکیم بادشاہس نِش۔ ییٚمۍ سُہ تلوار سۭتۍ مٲرِتھ تہٕ أمۍ سٕنٛز لاش ترٛٲوٕن عام لوٗکن ہٕنٛزن قبرن منٛز۔ {عام...: ہیب۔ عوامک نیٚچو}\n24.\\tتوتہِ اوس شافان سٕندِس نیچوِس احیکم سُند اتھہٕ یرمیاہ ہس نِش، زِ تِم گژھن نہٕ أمِس لُکن ہٕندِس اتھس منز دِنہٕ یُس أمِس مارنہٕ خٲطرٕ دِنہٕ۔","1.\\tیہوداہ کِس بادشاہ یوسیاہ سٕندِس نیچوِس یہوویاقیم سٕندِس آغازس مَنٛز آو یہِ کلام یرمیاہ ہس خداوند سٕندِ طرفہٕ وونُن،\n2. یِتھٕ پٲٹھـ̡ چُھ خداوند میانہِ خٲطرٕ وَنان۔ ژے بٔنِتھ رٔٹِتھ تہٕ یِم تھٲوِو پننہِ گردنہِ پیٹھ، {وَنُن...: یا، خداوند چُھ وَننہٕ آمُت}\n3. تہٕ سوز تم ادوم کِس بادشاہس نِش، موآب کِس بادشاہس نِش، تہٕ عمونیت کِس بادشاہس نِش، تہٕ تیروس کِس بادشاہس تہٕ زِدون کِس بادشاہس نِش، یُس یروشلم یُس یہوداہ کِس بادشاہس سٍتـ̡ یِنہٕ وٲلِس رسولن ہٕندِ اتھہٕ سٍتـ̡ یُس یہوداہ کِس بادشاہس سٍتـ̡ یِوان چھُ۔\n4. تہٕ تِمن دِیُن حُکُم زِ تِم کٔرِن پننِس آقا سٍتـ̡ ونُن، یِتھٕ پٲٹھـ̡ چُھ لشکرن ہُند رب اسرٲیلُک خدا۔ یِتھٕ پٲٹھۍ کٔرِو تُہۍ پننٮ۪ن آقاؤں وَنُن۔ {ونُن...: یا، پننین آقاؤں متعلق، ونن}\n5. میہ بنوو زمین، انسان تہٕ جانور یُس زمینس پیٹھ چُھ، پننہ عظیم طاقتہٕ سٍتۍ تہٕ پننہ پھٔہلِتھ نرِ سٍتـ̡ تہٕ دِژمُت یُس میہ سٍتـ̡ باسان چُھ۔\n6. تہٕ وۅنۍ چُھہ مے یِم سٲری زمینہٕ بابل کِس بادشاہ نبوکدنضر سٕندِس اتھس مَنٛز دِژمٕژ، یُس میٲنِس خادم اوس۔ تہٕ مٲدانٕکۍ درندٕ تہِ دِژمٕتۍ أمِس خدمت کرنہٕ خٲطرٕ۔\n7. تہٕ سارِوٕے قومہٕ روزن أمِس تہٕ تٔمۍ سٕندِس نیچوِس تہٕ تٔمۍ سٕندِس نیچوِس سٕندِس نیچوِس سٕنز خدمت، یوتام نہٕ تٔمۍ سٕندِس زمینُک وق یِنہٕ۔\n8. تہٕ یہِ سپدِ یُس قوم تہٕ بادشاہت یُس نہٕ بابل کِس بادشاہ نبوکدنضر سٕنز خدمت کرِ، تہٕ یُس نہٕ تِہٕنزِ گردن بابل کِس بادشاہ سٕندِس جوتس تل تراوِ، تتھ قومس دِیہٕ بہٕ تلوار سٍتـ̡ تہٕ قحط سٍتـ̡ تہٕ وباہن سٍتـ̡ سزا۔  یوٚت تام نہ میہ تمۍ سندِ اتھہ سیتۍ کھیوٚن۔\n9. تێمہِ کِنۍ گژھ نہٕ پننین پیغمبرن ہٕنز بوزو، نہ پننین دیواہن ہٕندِس سٍتۍ، نہ پننین جادوگرن ہٕنز تہٕ نہ پننین جادوگرن ہٕنز یِم تۅہہِ سٍتـ̡ کتھ کران چھِ، یِم نہٕ تۅہہِ سٍتـ̡ کتھ کران چھِ، تُہۍ گژھِ نہٕ بابل کِس بادشاہس سٕنز خدمت کٔرِتھ: {خوابن والۍ: ہیب۔ خواب}\n10.\\tتِکیازِ تِم چھِ تۅہہِ سٍتـ̡ اپُز پیشن گویی کران، یُس تۅہہِ پننہِ زمینہٕ نِش دور کڈنہٕ مۅکھہٕ چُھہ تۅہہِ سٍتـ� تہٕ یہ زِ بہٕ کٔرِتھ ژےٚ ژےٚ ژٔلِتھ ژٔلِتھ تہٕ ژٕ گٔژھِو مارٕ۔\n11. مگر یِم قوُم یِم پَنٕنہِ گردن بابل کِس بادشاہ سٕندِس جوتس تل أنِتھ تہٕ أمِس خدمت کران چھِ، تِمن دِیہٕ بہٕ تِمن پننِس سرزمینس مَنٛز رُکاونہٕ یِن، خداوند چُھ فرماوان۔ تہٕ تِم روزن اتھ منز روزن۔\n12.\\tمیہ کٔر یِمن سارِنٕے کلامَن مطٲبق یہوداہ کِس بادشاہ سٕندِس گردن تَل تہٕ تٔمِس تہٕ تٔمۍ سٕندِس لوکن ہٕنز خدمت کٔرِتھ زِندٕ۔\n13. تہٕ تُہۍ تہٕ تُہٕندِس لُکہٕ سٍتـ̡ کیازِ مَرِو، تلوار سٍتـ̡ ، قحط سٍتـ̡ تہٕ وباہن سٍتـ̡ ، یِتھ کٔنۍ خداوند چُھہ تتھ قومس خلاف کتھ کٔرمٕژ یُس نہٕ بابل کِس بادشاہس سٍتـ̡ خدمت کرِ۔\n14. تێمہِ کِنۍ گژھ نہٕ تِمن پیغمبرن ہٕندِس کلامَس بوزُن یِم تۅہہِ سٍتـ̡ کتھ کران چھِ، یِم نہٕ بابل کِس بادشاہس سٕنز خدمت کٔرِتھ، تِکیازِ تِم چھِ تۅہہِ سٍتـ̡ اپُز پیشن گویی کران۔\n15. خداوند چُھ ونان زِ مے چُھ نہٕ تِم سوزمٕتۍ، توتہِ چھِ تِم میانہِ ناوٕ سٍتـ̡ اپُز پیشن گویی کران۔ یُتھ بہٕ ژےٚ ژٔلِتھ ژٔلِتھ تہٕ تہٕ تۅہہِ تہٕ پیغمبرن ہٕنز پیشن گویی کرٕنۍ۔ {اکھ اپُز: ہیب۔ اپزس منز، یا اپزس منز}\n16.\\tتہِ ووت میہ پادٕرین تہٕ یِمن سارِنٕے لُکن سٍتـ̡ وونُن، یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ پننین پیغمبرن ہٕنز کتھ بوز نہٕ یِم تۅہہِ نِش پیشن گویی کران چھِ، وُچھِو، خداوند سٕندِ گرٕکۍ بانہٕ یِن جلدٕے بابل پیٹھٕ دُبارٕ اننہٕ، کیازِ تِم چھِ تۅہہِ سٍتـ̡ اپُز پیشن گویی کران۔\n17. تِمن ہٕنز کتھ گژھ نہٕ بوزٕنۍ۔ بابل کِس بادشاہس خدمت کرُن، تہٕ زندٕ روزُن: یہ شہر کیازِ گژھہِ تباہ کرنہٕ؟\n18. مگر اگر تِم پیغمبر آسن، تہٕ یێلہِ خداوند سُند کلام تِمن سٍتـ̡ آسہِ، تێلہِ گژھن تِم لشکرن ہٕندِس خداوند سٕندِس گرس سٍتـ̡ شفاعت کرٕن، یێلہِ یِم بانہٕ خداوند سٕندِس گرس مَنٛز تہٕ یہوداہ کِس بادشاہ سٕندِس گرس مَنٛز تہٕ یروشلمس مَنٛز باقٕے روزان چھِ، تِم گژھن نہٕ بابل کُن گژھن۔\n19. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب ستون تہٕ سمندرس متعلق، تہٕ بنیادن متعلق، تہٕ اتھ شہرس منز باقین جہازن ہٕندِس باقیاتس متعلق،\n20. یُس نہٕ بابل کِس بادشاہ نبوکدنضرن نِیومُت، یێلہِ تٔمۍ یہوداہ کِس بادشاہ یہوویاقیم سُند نیچو یکونیاہ، یروشلم پیٹھٕ بابل تہٕ یہوداہ تہٕ یروشلم کین سارنٕے رئیسَن نِش نِنہٕ۔\n21. یِتھٕ پٲٹھـ̡ چُھہ لشکرن ہُند خدا، یُس خداوند سٕندِس گرس مَنٛز تہٕ یہوداہ تہٕ یروشلم کِس بادشاہ سٕندِس گرس مُتعلِق چُھہ ونان ۔\n22.\\tتِم یِن بابل نِنہٕ یِن، تہٕ تِم روزن تِمن ہٕندِس دۅہہس تام یُس بہٕ تِمن نِش گژھُن، خداوند چُھ فرماوان۔ تیلہ کٔرٕ بہٕ تِم پرورش تہٕ یِم یَتھ جایہِ واپس دِنہٕ۔","1.\\tتہٕ سپُد امی ؤریس منز، یہوداہ کِس بادشاہ صیدقیاہ سٕندِس دورِ کِس آغازس منز، ژوٗرمہِ ؤریس مَنٛز، {تہٕ} پٲنژمہِ ریتس منز، {یہ} حنانیاہ عزر سُند نیچو، یُس جبیونُک {اوس} اوس خداوند سٕندِس گرس مَنٛز، پادٕرین تہٕ سارنٕے لُکن ہٕنزِ موجودگی مَنٛز،  ونُن،\n2. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھ، وَنُن چُھ، مے چُھ بابل کِس بادشاہ سُند جوُر پھُٹروومُت۔\n3. پوٗرٕ دۄن ؤرِین اندر اَننہٕ بہٕ خداوند سٕندِ گرٕکۍ سٲری بانہٕ یِم بابل کِس بادشاہ نبوکدنضرن اَمہ جایہِ نِش نِتھ نِتھ بابل نِن: {زٕ...: ہیب۔ زٕ ؤری دۅہ}\n4. تہٕ بہٕ اَنِہ یہوداہ کِس بادشاہ یہوداہ سُند نیچو یکونیاہ یُس یہوداہ کِس سارِنٕے قٲدِس سٍتـ̡ یُس بابل کِس بادشاہس سٍتـ̡ پھُٹراوُن، خداوند چُھ ونان زِ بہٕ پھُٹراوٕ بابل کِس بادشاہ سُند جو۔ {قیدی: ہیب۔ قید}\n5. تێمہِ پَتہٕ وۆن پیغمبر یرمیاہ پیغمبر حنانیاہ سٕندِس پادٕرین ہٕنزِ موجودگی مَنٛز، تہٕ یِم سارِنٕے لُکن ہٕنزِ موجودگی مَنٛز یِم خداوند سٕندِس گرس مَنٛز کھڑا ٲسۍ،\n6.\\tیێمہِ سٍتـ̡ حضرت یرمیاہ سٕندِس رسولس سٍتـ̡ وۆنـ̡ آمین: خداوند کٔرِو تُہٕندِس کلامَس مُطٲبِق، یێمہِ سٍتـ̡ ژے پیشن گویی کٔرمٕژ چِھ، یێمہِ سٍتـ̡ خداوند سٕندِس گرٕکۍ بانہٕ تہٕ یُس سارِوٕے یُس قٲد کرنہٕ آمُت چُھ، یێمہِ جایہِ اَنـ̡ یێلہِ بێیہِ بێیہِ۔\n7. توتہِ بوزو یہ لفظ یُس بہٕ چُھس تہندین کنن منز تہٕ سارنٕے لوکن ہٕندِس کنن منز بولان چُھس۔\n8.\\tیِمو پیغمبرو یِمو میانہِ برونہہ تہٕ تۅہہِ برونہہ پرانہِ زمانہٕ آسہِ، تِمو کٔر واریاہن ملکن تہٕ بٔڈٮ۪ن سلطنتن خٕلاف، جنگہٕ تہٕ بدی ہٕنزِ تہٕ وباہن ہٕنزِ پیشن گویی ۔\n9.\\tیُس پیغمبر امنٕچ پیشن گویی کران چُھ، یێلہِ پیغمبر سُند کلام سپدِ، تێلہِ گژھہِ پیغمبرن معلوم سپدُن، زِ خداوند چُھ پٔزۍ پٲٹھـ̡ سُہ سوزمُت۔\n10.\\tتێلہِ کٔر حنانیاہ پیغمبرن یرمیاہ سٕنزِ گردنہِ منزٕ جوُر تہٕ ژٔٹِتھ ژٔٹِتھ۔\n11.\\tتہٕ حنانیاہ کٔر سارِنٕے لُکن ہٕندِس حضورس مَنٛز وَنُن زِ خداوند چُھ یِتھٕ پٲٹھۍ فرماومُت۔ توتہِ پھُٹراوٕ بہٕ بابل کِس بادشاہ نبوکدنضر سُند جوُر سارنٕے قومن ہٕنزِ گردنہٕ منزٕ پورٕ دۄن ؤرین ہٕندِس وقتس منز۔ تہٕ یرمیاہ پیغمبر گۆو پننہِ وتہِ۔\n12. تێمہِ پَتہٕ آو خداوند سُند کلام یرمیاہ {پیغمبر} نِش ، تمہ پتہٕ ہنانیاہ پیغمبرن یرمیاہ سٕنزِ گردنہِ پیٹھٕ جوُر پھُٹرٲوِتھ وونُن،\n13.\\tگژھ تہٕ حنانیاہ وَنُن، یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ ژے پھُٹرٲوۍ لٔکرِ ہُند جوُر؛ مگر تُہۍ بناو تِمن خٲطرٕ ششتٕرٕکۍ جوت۔\n14. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھ وَنان۔ مے چُھ یِمن سارِنٕے قومن ہٕندِس گردنہِ پیٹھ ششتٕرُک جوُر تھوومُت، یُتھ تِم بابل کِس بادشاہ نبوکدنضر سٕنز خدمت کٔرِتھ۔ تہٕ تِم کرِ أمِس خدمت: تہٕ مے دِژ أمِس میدانٕکۍ جانور تہِ۔\n15.\\tتێلہِ وۆن نبی یرمیاہ پیغمبرن حنانیاہ پیغمبرس سٍتـ̡ بوزو، حنانیاہ خداوند چُھ نہٕ ژے سوزمُت۔ مگر توے چھکھ یِمن لوکن اپزس پیٹھ پژھ کرنُک موقعہٕ دِوان۔\n16. تێمہِ کِنۍ چُھ خداوند یِتھٕ پٲٹھۍ فرماوان۔ وچھ بہٕ ژے ژے زمینہٕ پیٹھٕ ژھنُن: ییٚمہِ ؤرۍ یہِ ژے مرُن، کیازِ ژے چُھکھ خداوند سٕندِس خلاف بغاوت ہیچھناوٕنۍ۔ {بغاوت: ہیب۔ بغاوت}\n17.\\tتہ حنانیاہ رسول رسول سپد امی وریہِ سٔتِم ریتس مَنٛز مران۔","1. وۅنۍ چِھہ یِم چِٹھہِ ہٕندۍ لفظ یُس یرمیاہ پیغمبرن یروشلم پیٹھٕ بزرگن ہٕندِس باقیاتس تام سوزمُت اوس، یِم قٲد کٔرِتھ نِنہٕ آمٕتۍ، تہٕ پادٕرین تہٕ پیغمبرن تہٕ تِمن سارِنٕے لُکن خٲطرٕ یِم نبوکدنضرن یروشلم پیٹھٕ بابل نِتھ نِمٕتۍ۔\n2. (اَمہِ پَتہٕ یِکونیاہ بادشاہ، ملکہ، تہٕ خواجہ سرا ، یہوداہ تہٕ یروشلمٕکۍ شہزادٕ تہٕ چھان تہٕ لوہار گٔیہِ یروشلم پیٹھٕ روانہٕ۔) {خواجہ سرا: یا، چیمبرلین}\n3. شافان سُند نیچو ایلاسہ تہٕ حلقیاہ سُند نیچو جماریاہ سٕندِ اتھہٕ سٍتۍ، (یُس یہوداہ کِس بادشاہ صدقیاہ بابل کِس بادشاہ نبوکدنضرس نِش بابل سوزمُت) وونُن،\n4. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند خدا، اسرٲیلُک خدا، تِمن سارِنٕے قٲدِین سٍتـ̡ یِمن یِمن یروشلم پیٹھٕ بابل نِنہٕ آمُت چُھ، یێلہِ چُھہ یِمن سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یِمن ہٕندِس سٍتـ̡ یێلہِ یِمن ہٕند\n5.\\tمکانہ بنٲوِو تہٕ روزُن {تمن منز}۔ تہٕ باغ لگٲوِو تہٕ تِمن ہُند پھل کھیوٚن۔\n6. زنانہٕ رٔٹِو، تہٕ نیچو تہٕ کورِ پٲدٕ کٔرِو۔ تہٕ پَنٕنٮ۪ن نیٚچوٮ۪ن ہٕندِ خٲطرٕ رٔٹِو خانٛدارِن، تہٕ پَنٕنۍ کورِ دِیِو خانٛدارَن یُتھ تِم زیٚنہٕ نیٚچوِ تہٕ کورِ زیٚنہٕ۔ تاکہ تتہِ گژھہِ ہُریر، تہٕ کم گژھِو نہٕ۔\n7. تہٕ شہرٕچ امن ژھارِو ییتہِ بہٕ ژےٚ قٲد کٔرِمٕژ چھِ، تہٕ امہِ خٲطرٕ کٔرِو خداوند سٕندِ خٲطرٕ دُعا، تکیازِ اَتھ سٍتـ̡ گژھہِ تۅہہِ امن حٲصِل۔\n8. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھہ وَنان۔ تُہٕندِس پیغمبرن تہٕ تُہٕندِس خدایہِ سٍتـ̡ گژھن نہٕ دھوکہٕ دِنہٕ، تہٕ نہ گژھن تُہٕندِس خوابن ہٕندِس سٍتـ̡ بوزنہٕ یِنـ̡ یِمن خوابن ہٕندِس خوابس سٍتـ̡ تہٕ یِمن خوابن ہٕندِس سٍتـ̡ تہٕ یِمن خوابن ہٕندِس خوابس سٍتـ̡\n9. تِم چِھ میانہِ ناوٕ سٍتـ̡ ژےٚ غلط پیشن گویی کران: مے چُھہ نہٕ تِم سوزمٕتۍ، خداوند چُھ ونان ۔ {غلط: ہیب۔ اپزس منز}\n10. یِتھٕ پٲٹھۍ چُھ خداوند ونان زِ بابل مَنٛز ستتھ ؤری سپدِتھ بہٕ ژے نِش گژھِ، تہٕ ژےٚ یَتھ جایہِ واپس یِنہٕ خٲطرٕ پنُن نیک کلام ادا کَرُن۔\n11. کیازِ بہٕ چُھس زانان زِ بہٕ چُھس تُہٕندِس خیالس سٍتـ̡ سونٛچان، یُس بہٕ چُھس ژے سٍتـ̡ سونٛچان چُھہ، یُس نہٕ بدی ہُند خیال چُھ، یُس ژے متوقع انجام دِنہٕ خٲطرٕ۔ {متوقع...: ہیب۔ اختتام تہٕ توقع}\n12. تیلہِ کٔرِو ژے میہ بُلاون، تہٕ گژھِو میہ سٍتـ̡ دُعا کرنہٕ، تہٕ بہٕ کٔرٕ ژے بوزنہٕ۔\n13.\\tتہٕ ژے ژھانڈِو میہ تہٕ ژھانڈِو، ییلہ تہٕ ژے پنہٕ نِس دِلہٕ سٍتـ̡ ژھانڈنہٕ ییہِ۔\n14. خداوند چُھ ونان تہٕ بہٕ گژھٕ ژےٚ نِش لبنہٕ یِوان، تہٕ بہٕ کٔرٕ ژےٚ سارِنٕے قومن نِش تہٕ تِمن سارِنٕے جاین پیٹھٕ یِمن تہٕ یێلہِ بہٕ ژےٚ ژےٚ ژٔلِمٕژ چھِ، خداوند چُھ فرماوان۔ تہٕ بہٕ اَننہٕ ژےٚ دُبارٕ تتھ جایہِ ییتہِ بہٕ ژےٚ قٲد کٔرِتھ نِنہٕ آمٕژ۔\n15.\\tکیازِ تۅہہ چُھہ ووٚنمُت، خداوند چُھ اسہِ بابل مَنٛز پیغمبرن ہٕندِ زندٕ کٔرۍمٕتۍ۔\n16. {زانِو} یِتھٕ پٲٹھۍ چُھ بادشاہ سُند رب یُس داؤد سٕندِس تختس پیٹھ بِہِتھ چُھ، تہٕ یِمن سارِنٕے لُکن ہُند یُس اتھ شہرس مَنٛز روزان چُھ، تہٕ تُہند بٲے یِم نہٕ تۅہہِ سٍتـ̡ قٲد کرنہٕ آمٕتۍ چھِ۔\n17. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب فرماوان۔ وچھ بہٕ سوز تمن پیٹھ تلوار، قحط تہٕ وباء، تہٕ بناوٕ تِمن بدکار انجیر ہٕندۍ پٲٹھۍ، یُس نہٕ کھٮ۪نہٕ یِتھ، تِم چھِ واریاہ بدکار۔\n18.\\tتہٕ بہٕ کرٕ تِمن تلوارِ سٍتـ̡ ستاونہٕ، قحط سٍتـ̡ تہٕ وبا سٍتـ̡ تہٕ یِمن سارِنٕے قومن مَنٛز دِنہٕ یِنہٕ خٲطرٕ، یێلہِ یێلہِ بہٕ تِمن سارِنٕے قومن مَنٛز بد دعا تہٕ حٲران تہٕ ملامت بٔنِتھ یِمن سارِنٕے قومن مَنٛز یێلہِ بہٕ یِم دِژمٕژ چھِ: { بد دعا بننہٕ خٲطرٕ:  ہیب۔ اکھ لعنت}\n19.\\tکیازِ تِمو چُھنہٕ میانہِ کلامٕچ کتھ بوزمٕژ، خداوند چُھ ونان یُس میہ پننین بندن ہٕندِ طرفہٕ تِمن نِش سوزمُت چھُ، سُلہٕ وُتھٕ وُتھٕ تہٕ سوزُن {تِم}۔ مگر تُہۍ بوزِو نہٕ، خداوند چُھ فرماوان۔\n20. تێمہِ کِنۍ بوزو خداوند سُند کلام، یُس میہ یروشلم پیٹھٕ بابل سوزمُت چُھ:\n21. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند خدا، اسرٲیلُک خدا، کولیاہ سُند نیچو اہاب تہٕ ماسیا سُند نیچو زدقیاہ سُند یُس میانہِ ناوٕ سٍتـ̡ ژے سٍتـ̡ اپُز نِش پیشن گویی کران چُھ، یُس میانہِ ناوٕ سٍتـ̡ ژے سٍتـ̡ اپُز نِش پیشن گویی کران چُھ، وچھ، بہٕ دِیہ تم بابل کِس بادشاہ نبوکدرِزر سٕندِس اتھس مَنٛز۔ تہٕ سُہ مارِ تِم تُہنزن نظرن برونہہ کُن۔\n22.\\tتہٕ یِمن مَنٛز ییہِ یہوداہ سٕندِس سارِنٕے قٲدِس سٍتـ̡ لعنت کرنہٕ یُس بابل مَنٛز چُھہ یُس {چُھ} بابل سٕندِس سٍتـ̡ دِنہٕ آمُت، یُس بابل کِس بادشاہن نارس مَنٛز زٲلِتھ دِنہٕ آمُت چھُ۔\n23. کیازِ تِمو چُھ اسرٲیلِس مَنٛز بدکاری کٔرمٕژ، تہٕ چُھکھ پننین ہمساین ہٕنزن زنانن سٍتـ̡ زنا کورمُت، تہٕ میانہِ ناوٕ سٍتـ̡ چُھکھ اپُز کتھ کٔرمٕژ، یُس نہٕ میہ تِمن حُکُم دِژمُت چُھ۔ میہ تہِ چھہ پتاہ تہ گواہ تہِ چھہ خدایہ فرماوان۔\n24. {یِتھٕ پٲٹھۍ} تہِ کرو ژے شمعیاہ نہیلمی سٍتـ̡ کتھ کٔرِتھ {Nehelamite: یا، خواب}\n25. یِتھٕ پٲٹھـ̡ چُھہ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھہ ونان زِ تێے چُھہ پننہِ ناوٕ سٍتـ̡ یِمن سارِنٕے لُکن یُس یروشلمس مَنٛز چُھہ، تہٕ پادٕرۍ سٕندِس نیچوِس زفانیاہ تہٕ سارنٕے پادٕرین سٍتـ̡ چِٹھہِ سوزمُت،\n26.\\tخداوند چُھہ ژے یہویادا سٕندِ بدلہٕ پادٕرۍ بنوومُت، یُتھ زِ تُہۍ گژھِو خداوند سٕندِس گرس مَنٛز افسر بٔنِتھ، یُتھ زن پرٮ۪تھ أکِس انسانس پاگل چُھ، تہٕ پانس پیغمبر بناوُن، تہٕ ژے گژھِو أمِس قٲد خانس مَنٛز تہٕ ذخیرن مَنٛز تراوُن۔\n27.\\tتێلہِ کیازِ کٔر نہٕ ژے انتھوتھ کِس یرمیاہ سٕنز ملطمتہٕ، یُس پانس تۅہہِ خٲطرٕ پیغمبر بناوان چُھ؟\n28. تِکیازِ تٔمۍ سوٗز اسہِ نِش بابل تہٕ وونُن زِ یہِ {قٲد} چُھ زیٖٹھہِ روزُن: یِمو مکانہٕ بنٲوِو، تہٕ تِمن مَنٛز روزُن۔ باغ لگٲوِو تہٕ تِمن ہُند پھل کھٮ۪وان چھُ۔\n29.\\tتہٕ زفنیاہ پادٕرۍ پٔر یہِ چِٹھۍ یرمیاہ پیغمبر سٕندِس کنن منز۔\n30. اَمہِ پَتہٕ آو خداوند سُند کلام یرمیاہ ہس نِش وَنُن،\n31.\\tیِمن سارِنٕے سٍتـ̡ سوزِو یِمن سارِنٕے سٍتـ̡ یێلہِ، یِتھٕ پٲٹھـ̡ چُھ خداوند شمعیاہ نیہلمی سٕندِس بارس مُتلق فرماوان۔ تکیازِ تٔمۍ شمعیہ چھے تۅہہِ نِش پیشن گویی کٔرمٕژ، تہٕ مے سوز نہٕ سُہ تہٕ تٔمۍ کٔر ژےٚ اپزس پیٹھ بھروسہٕ:\n32. تێمہِ کِنۍ چُھ خداوند یِتھٕ پٲٹھۍ وَنان۔ وُچھِو بہٕ شمعیاہ نیہلمی تہٕ تٔمۍ سٕندِس اولادس سزا، أمِس آسہِ نہٕ یِمن لُکن مَنٛز روزنہٕ خٲطرٕ کانہہ نفر۔ خداوند چُھ ونان زِ سُہ گژھہِ نہٕ سُہ نیکی وُچھِتھ یُس بہٕ پننین لوکن ہٕندِ خٲطرٕ کرِ۔ تکیازِ تٔمۍ چُھ خداوند سٕندِس خلاف بغاوت ہیچھناوٕنـ̡ ۔ {بغاوت: ہیب۔ بغاوت}","1. سُہ کلام یُس خداوند سٕندِ طرفہٕ یرمیاہ ہس تام آمُت چُھ، یُس ونان چُھ،\n2. یِتھٕ پٲٹھـ̡ چُھ اسرٲیلـ̡ ہُند خداوند خدا ونان زِ تِم سٲری لفظ لیکھِو یِم مے ژے أکِس کتابہِ مَنٛز کتھ کٔرمٕژ چھِ۔\n3. خداوند چُھ ونان زِ یِم دۅہ یِنہٕ وٲلِس دۅہہٕ یِنہٕ زِ بہٕ اَننہٕ پننین لوکن اسرٲیلِس تہٕ یہوداہ سُند قید دُبارٕ یُس بہٕ تِمن ہٕندِس مٲلِس دِژمُت چھُ، تہٕ تِمن ہٕندِس مٲلِس سٍتـ̡ دِنہٕ آمُت تہٕ تِمن ہُند قبضہٕ کرُن۔\n4.\\tتہٕ یِم لفظ یِم خداوند اسرٲیلِس مُتلق تہٕ یہوداہ کِس بارس مُتلق کٔرۍمٕتۍ۔\n5. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ اسہِ بوز تھرتھر، خوفٕچ آواز، نہ کہ امنٕچ آواز۔ {خوفہٕ...: یا، خوف چھُ، تہٕ امن نہٕ}\n6.\\tوۅنۍ پرژھہِ تہ وُچھِو زِ انسان چھا شُرِ سٍتـ̡ مصیبت کران؟ میہ کیازِ چھہ پریتھ مرد پننین کمرن پیٹھ اتھہ تھٲوتھ، زنانہِ ہندۍ پاٹھۍ مصیبت زدہ تہ سٲری بُتھ چھہِ زرد گٔژھان۔ {اکھ مرد: ہیب۔ اکھ مرد}\n7. افسوس! تکیازِ تمہِ دۅہہ {چُھ} عظیم، یُتھ زن کانہہ تہِ {چُھ} یعقوب سٕندِ مصیبت ہُند وق تہِ۔ مگر سُہ گژھہِ اَمہ نِش بچاونہٕ یُن۔\n8. یێلہِ سٍتـ̡ سپدِ تمہِ دۅہٕ، لشکرن ہُند رب چُھ ونان زِ بہٕ ژٔٹِھہ تٔمۍ سُند جولہٕ ژٔٹِتھ تہٕ ژٔٹِتھ ژٔٹِتھ تہٕ اَمہ سٍتـ̡ کٔرِن نہٕ أمِس سٍتـ̡ پانس سٍتـ̡ خدمت کرنہٕ۔\n9. مگر تِم گژھن خداوند پنُن خدا، تہٕ داؤد سٕنز بادشاہ سٕنز خدمت، یُس بہٕ تِمن نِش تُلنہٕ یُن۔\n10. تێمہِ کِنۍ گژھ نہٕ خوفہٕ، اے میانہِ بندہ یعقوب، خداوند چُھ فرماوان۔ اے اسرٲیل، تێلہِ گژھہِ نہ مایوس، تکیازِ بہٕ بچاوٕ ژے دوٗرِ پیٹھ، تہٕ تُہند اولادٕ تِہٕنزِ قید کِس سرزمینہٕ نِش بچاو۔ تہٕ یعقوب گژھہِ واپس، تہٕ آرام روزُن، تہٕ ژھۄپہٕ روزُن، تہٕ کانٛہہ تہِ گژھِ نہٕ أمِس خوفزدہ کرنہٕ۔\n11. خداوند چُھس ونان زِ بہٕ چُھس ژے سٍتـ̡ رژھراوان تہٕ یێلہِ بہٕ چُھس تۅہہِ ہٕندِس سارِنٕے قومن ہُند خاتمہ کٔرِتھ، توتہِ کرٕ نہٕ بہٕ ژے پورٕ پٲٹھـ̡ ختم کٔرِتھ، مگر بہٕ کرٕ ژے سٍتـ̡ تہٕ یێلہِ تہٕ بہٕ کٔرٕ نہٕ ژے س\n12. یِتھٕ پٲٹھۍ چُھ خداوند ونان زِ تُہند زخم {چُھ} لاعلاج، {تہٕ} چُھ تُہند زخم {چُھ} شدید۔\n13. {چُھہ} چُھنہٕ کانہہ تہِ تُہٕندِس کامہِ ہٕنز وَرٕ دِنہٕ خٲطرٕ، یُتھ تہٕ ژے چُھہ نہٕ کانہہ شفا بخش دواہ۔ {یہ...: ہیب۔ پابند کرنہٕ خٲطرٕ، یا، دباونہٕ خٲطرٕ}\n14. چانہِ سارِنٕے عاشق چھِ ژےٚ مٔشِد گٔمٕتۍ۔ تِم چھِنہٕ تۅہہ ژھاران۔ تکیازِ مے چُھس ژے أکِس دُشمن سٕندِس زخمس سٍتۍ، أکِس ظالم سٕندِ عذابس سٍتۍ، چانہِ بدکاری ہٕندِس بٔڈِس سٍتـ̡ زخم دِژمُت۔ {کیازِ} چُھہ تُہند گۅناہ ہُرراوُن۔\n15. ژٕ کیازِ چُھکھ پننہِ مصیبت خٲطرٕ فریاد کران؟ تُہند غم {چُھ} چُھہ چانہِ گناہ ہُند بٔڈِتھ ہُریومُت، مے کٔر ژے سٍتـ̡ یِم کامہِ کٔرِتھ۔\n16. تێمہِ کِنۍ یِم تۅہہِ کھٮ۪وان چھِ، سُہ گژھِ کھٮ۪نہٕ یُن۔ تہٕ تُہند سٲری مُخٲلِف، یِمو منزٕ پرٮ۪تھ اکھ گژھِ قٲد کرنہٕ۔ تہٕ یِم تۅہہ خراب کرِ، تم گژھن غنیمت، تہٕ یُس تہٕ یُس تہٕ سُہ شکار کرُن بہٕ دِیہٕ شکار۔\n17. کیازِ بہٕ کرٕ ژے صحت بحال تہٕ بہٕ کرٕ ژے چانہِ زخمو نِش شفا دِنہٕ، خداوند چُھ فرماوان۔ تکیازِ تِمو وَنُن چُھہ ژے آوٹ کاسٹ، {ونُن}، یہِ {چُھ} صییون، یُس نہٕ کانہہ تہِ انسان ژھاران چُھ۔\n18. خداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ وچھ بہٕ اَننہٕ یعقوب سٕندِس خیمَن ہُند دُبارٕ قٲد، تہٕ تٔمۍ سٕندِس روزن گاہَن پیٹھ رحم کرُن۔ تہٕ شہر ییہٕ پننس ڈھیرس پیٹھ تعمیر کرنہٕ، تہٕ محل گژھہٕ امہٕ طریقس پتہٕ روزٕ۔ {ہیپ: یا، لٹل ہل}\n19.\\tتہٕ یِمو منزٕ گژھہِ شُکرگزاری تہٕ خۅش گژھن والٮ۪ن ہٕنز آواز، تہٕ بہٕ کرٕ تِمن ہُند تعداد تہٕ تِم گژھن نہٕ کم۔ بہٕ تہِ کٔرٕ تِمن ہٕنز تعریف، تہٕ تِم گژھن نہٕ لۄکٕٹۍ۔\n20. تِہٕندِ شُرِ تہِ گژھن برونہمہِ ہٕندِس پٲٹھۍ، تہٕ تِہٕنزِ جماعت گژھہِ میانہِ برونہہ کُن قایم کرنہٕ، تہٕ بہٕ دِیہٕ تِمن سارِنٕے ظالمن سٍتـ̡ سزا۔\n21.\\tتہٕ تِہٕندِ رئیسَن گژھن پانَس سٍتـ̡ تہٕ تِہُند گورنر گژھہِ تِمن منزٕ نیرُن۔ تہٕ بہٕ کٔرِس أمِس نزدیک، تہٕ سُہ گژھہِ میہ نِش، کیازِ یہِ کُس چھُ یُس پنُن دِل میہ نِش واتناوُن؟ خداوند چُھ فرماوان۔\n22. تہٕ تُہۍ بٔنِو میٲنۍ لوک، تہٕ بہٕ بنہٕ تُہند خدا۔\n23.\\tوُچھو خداوند سُند وُپھ چُھہ غصہٕ سٍتـ̡ نیران، یُس بدکار سٕندِس کلس سٍتـ̡ دگ سٍتـ̡ پۯاوُن۔ {جٲری: ہیب۔ کَٹِنگ} {فال...: یا، باقی}\n24. خداوند سُند شدید غصہٕ گژھہِ نہٕ واپس یوتام نہٕ سُہ یہ کرِ، تہٕ یوتام نہٕ سُہ پنہٕ نِس دِلُک ارادٕ پورٕ کرِ: پٔتِمِس دۅہس مَنٛز گژھِو تُہۍ اتھ پیٹھ غور کرُن۔","1. اَمی ساتہٕ، خداوند چُھ فرماوان زِ بہٕ بنہٕ اسرٲیلِکۍ سارِنٕے خاندانن ہُند خدا، تہٕ تِم گژھن میٲنۍ لوک۔\n2. یِتھٕ پٲٹھـ̡ چُھ خداوند فرماوان، یِم لُکھ تلوار نِش باقٕے ٲسۍ، بیابانن مَنٛز فضل حٲصل کٔرِتھ۔ {حتیٰ کہ} اسرٲیل، ییلہ بہٕ تس آرام دِنہٕ خٲطرٕ گوٚو۔\n3. خداوند چُھ میہ برونہہ کُن ظٲہر گومُت، {ونُن}، آ، بہٕ چُھس ژے اَکہِ ابدی محبتہٕ سٍتـ̡ محبت کٔرمٕژ، تێمہِ مۄکھٕ چُھہ مے ژے محبتہٕ سٍتـ̡ پانس سٍتـ̡ پانس سٍتـ̡ رٔٹمُت۔ {of...: ہیب۔ دوٗرِ پیٹھ} {محبتہٕ سٍتۍ...: کیا مے کٔر ژے سٍتۍ محبتہٕ دِنہٕ}\n4. بہٕ کٔرٕ دُبارٕ ژے تعمیر تہٕ اے اسرائیلٕچ کنواری، تہٕ ژٕ گژھہٕ دوبارٕ پنٕنـ̡ پنہٕ نِس لباسو سٍتـ̡ سجاونہٕ، تہٕ یِمن ہٕندِس رقصس مَنٛز نیرُن یِم خۅش کران چھِ۔ {ٹیبریٹس: یا، ٹمبرلس}\n5.\\tتوتہِ کٔرِو سامریہ کِس پہاڑن پیٹھ انگور لاگُن، کُلۍ کٔرِن تہٕ عام چیزو سٍتـ̡ کھٮ۪ن۔ {کھیوٚن...: ہیب۔ تمن کٔرِو بے حرمتی}\n6. یێلہِ سُہ دۅہ گژھہِ یُس افرایم کِس پہاڑس پیٹھ پٔہلِتھ چوکیدار کٔرِن کُنہِ دۅہہٕ، وۅتھٕ وُتھ، تہٕ أسۍ گژھو صیہون کُن پننِس خداہس نِش۔\n7. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ یعقوب سٕندِ خٲطرٕ گیو خوشی سٍتـ̡ تہٕ قومن ہٕندِس سردارس مَنٛز کٔرِو کرٛٮ۪کہٕ: اے خداوند، پَنٕنـ̡ پَنٕنـ̡ أسرٲیلـ̡ ہٕندِس باقٕے سٍتـ̡ بچٲوِو۔\n8.\\tوُچھ، بہٕ أنِتھ تِم شُمٲلی مُلکہٕ پیٹھ، تہٕ یِمن سٍتـ̡ اَنـ̡ تہٕ لوٚنگـ̡ تہٕ یِمن سٍتـ̡ شُرِ سٍتـ̡ شُرِ ہٕندِس سٍتـ̡ تہٕ یِمن سٍتـ̡ یِمن سٍتـ̡ شُرِ سٍتـ̡ تہٕ یِمن سٍتـ̡ اَکہٕ وٹہٕ یِنہٕ وٲلِس س\n9. تِم یِن وَنُن ہٮ۪تھ تہٕ دُعا کٔرِتھ بہٕ تِمن ہٕنز رہنُمٲیی کٔرِتھ، بہٕ کَرٕ تِمن آبہٕ کِس دریاوَن کِس سٍتـ̡ سیدِ پٲٹھۍ، یێلہِ نہٕ تِم ٹھوکر کھسنہٕ یِن، تکیازِ بہٕ چُھس اسرٲیلُک مول تہٕ افرائیم چُھہ میون گۄڈنیُک زامُت۔ {دعا: یا، احسان}\n10.\\tاے قوبو، خداوند سُند کلام بوزو، تہٕ دوٗر جزیرن مَنٛز اعلان کرُن، تہٕ ونُن، یُس اسرٲیلُک پھٔہلِتھ چھُ، سُہ کرِ أمِس جمع تہٕ رژھرِ پٲٹھۍ، یُس پَنُن پٔرِتھ چُھہ پَنُن پٲٹھۍ۔\n11.\\tیِکیازِ خداوند چُھ یعقوب نجات دِژمُت، تہٕ دِتُن أمِس سٕندِ اتھہٕ نِش یُس أمِس کھوتہٕ زیادٕ طاقتور اوس۔\n12. تێمہِ مۅکھہ گژھن تِم یِن تہٕ صیون کِس تھزرس مَنٛز گٮ۪ون، تہٕ خداوند سٕنزِ نیکی خٲطرٕ، کٕنٕک، شرابٕ خٲطرٕ، تیٖلہٕ خٲطرٕ، تہٕ ریوڑن ہٕندِس بچن تہٕ کھورِ ہٕندِس بچن خٲطرٕ رٔلِتھ وسان تہٕ تِہُند روح آسہِ آبہٕ دار باغٕکۍ پٲٹھۍ۔ تہٕ تِم گژھن نہٕ مزید غم۔\n13. تیلہِ گژھہِ کنواری رقصس منز خۅش، جوان تہٕ بُزرگ دۅشوے یکوٹہٕ، تکیازِ بہٕ کرٕ تِہُند ماتم خوشی منز بدلاو، تہٕ تِمن تسلی دِوان تہٕ تِمن ہٕندِس غمس سٍتـ̡ خوش کرُن۔\n14. تہٕ بہٕ کَرٕ پادٕرین ہُند روح مُطمعہٕ سٍتـ̡ مُطمعیٖن، تہٕ میانہِ لوٗکھ گژھن میانہِ نیکی سٍتـ̡ مطمئن، خداوند چُھ فرماوان۔\n15. خداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ راماہس منز بوز اکھ آواز، ماتم تہٕ تلخ روُن۔ راحیلن اوس پننین شُرین خٲطرٕ روُن کران پننین شُرین ہٕندِ خٲطرٕ تسلی دِنس انکار، تکیازِ تِم ٲسۍ نہٕ نہٕ۔\n16. خداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ پنٕنۍ آواز رونہٕ نِش تہٕ أچھن رُکٲوِو اوٚش نِش، تکیازِ تۅہہِ کامہِ ہُند ثواب میلہِ، خداوند چُھ فرماوان۔ تہٕ تِم یِن دُشمن ہٕندِ سرزمینہٕ پیٹھٕ دُبارٕ یِنہٕ۔\n17. تہٕ چُھہ تۅہہِ سٕندِس اندس مَنٛز وۅمید زِ تُہند شُرِ یِن دُبارٕ پننِس سرحدس پیٹھ۔\n18.\\tمیہ چھہ پزۍ پاٹھۍ بوزمُت زِ افرائیم چھہ پانس ماتم کران {یتھہ پاٹھۍ}۔ ژے کٔر میہ سزا، تہٕ میہ آو سزا دِنہٕ، یُس نہٕ عادت اوس نہٕ دِنہٕ آمُت: ژے پھیُر، تہٕ بہٕ گژھہٕ پھیرنہٕ۔ تِکیازِ تُہۍ چھُکھ خداوند میانہِ خدا۔\n19.\\tیَتھ پَتہٕ گۆو بہٕ توبہٕ۔ تہٕ تمہ پتہ آو میہ ہدایت دِنہٕ، میہ لوٚگ پننِس رانس پیٹھ تھپھ: میہ ٲس شرمندگی، آ، پریشان تہِ، تکیازِ میہ ٲس پننہ جوانی ہٕنز ملامت برداش۔\n20. {کیا} افرائیم میون پیاری نیچو؟ {سُہ} چھا اکھ خۄشگوار شُر؟ تکیازِ ینہ پیٹھہ میہ تس خلاف کتھ کٔرمٕژ، میہ چھہ وُنہِ تہِ سُہ یاد پٲٹھۍ: لہذا چھہ میانہِ مۅکھہ تٔمۍ سٕندِ خٲطرٕ پریشان۔ خداوند چُھ ونان زِ بہٕ کٔرٕ یٔقیٖنی طور أمِس پٮ۪ٹھ رحمت۔ {are...: Heb. آواز}\n21.\\tپَنُن دِل تھاوُن شاہراہس کُن، یێمہِ وتہِ کُن پھیرُن، یێمہِ وتہِ کُن پھیرُن، اے اِسرٲیلٕچ کنواری، دُبارٕ پھیرُن یِمن شہرن کُن۔\n22. اے پتھ کُن کورِ ژیہ کوتاہ کال۔ تکیازِ خداوند چھہ زمینس منز اکھ نۆو چیز تخلیق کورمُت، زنانہ کرِ مردس سیتۍ وابستہ۔\n23. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھ فرماوان۔ وُنہِ تہِ کرِ تِم یہِ تقریر یہوداہ کِس سرزمینس تہٕ اَمہ کِس شہرن مَنٛز استعمال، یێلہِ بہٕ تِہُند قید دُبارٕ اَننہٕ۔ خداوند کرِ ژے برکت، اے عدل کِس بساون، {تہٕ} پاکیزگی ہُند پہاڑ۔\n24.\\tتہٕ یہوداہَس مَنٛز تہٕ تِمن ہٕندِس سارِنٕے شہرَن مَنٛز روزن تہٕ تِم گٔژھِتھ رٔلِتھ نیران۔\n25. تکیازِ مے چُھ تھکہٕ مٕتۍ روح پوٗرٕ کورمُت، تہٕ مے چُھس پرٮ۪تھ غمگسار روحس بھرمُت۔\n26.\\tاَمہ وِزِ وُچھمُت تہٕ وُچھمُت۔ تہٕ میون نندر ٲس میانہِ خٲطرٕ میٹھ۔\n27. خداوند چُھ فرماوان زِ یِم دۅہ یِوان زِ بہٕ کرٕ اسرائیلُک گرٕ تہٕ یہوداہ کِس گرس انسان سٕندِ بیول سٍتـ̡ تہٕ درندٕ سٕندِ بیول سٍتـ̡ وونہٕ۔\n28.\\tتہٕ یِتھ کٔنۍ میہ یِمن پیٹھ نظر تھوو، تُلنہٕ خٲطرٕ، تہٕ پھُٹنہٕ خٲطرٕ، تہٕ تباہ کرنہٕ خٲطرٕ، تہٕ تباہ کرنہٕ خٲطرٕ، تہٕ مصیبت دِنہٕ۔ یێلہِ چُھس بہٕ تِمن رٲچھ کٔرِتھ، تعمیر کرنہٕ خٲطرٕ، تہٕ لگاونہٕ خٲطرٕ، خداوند چُھ وَنان۔\n29.\\tتِمن دۅہن چُھ نہٕ تِم مزید وَنُن، مٲلۍ چُھ کھٔٹۍ انگور کھٮ۪ومُت، تہٕ شُرین ہٕندِ دندٕ چِھہ دِنہٕ آمٕتۍ۔\n30. مگر پریتھ کانہہ گژھہِ پننہِ بدکاری کِنۍ مرُن: یُس انسان کھٹۍ انگور کھٮ۪وان آسہِ، تٔمۍ سٕندِ دند گژھن کُنہِ\n31. خداوند چُھ ونان زِ یِم دۅہ یِوان زِ بہٕ کرٕ اسرٲیلِس گرس سٍتـ̡ تہٕ یہوداہ کِس گرس سٍتـ̡ نۆو عہد کرُن:\n32.\\tیُس معاہدٕ مُطٲبق یُس میہ تِہندِس مٲلِس سٍتـ̡ کرنہٕ آمُت اوس، ییمہِ دۅہہٕ مے تِمن مصرہٕ منزٕ نٮ۪بر نِنہٕ خٲطرٕ اتھہٕ تھپھ کٔرِتھ رٔٹمُت۔ یُس میون عہد پھُٹراوان چھُ، حالانکہ بہٕ اوسُس تِمن ہُند خانٛدار اوس، خداوند چُھ ونان: {حالانکہ...: یا کیا بہٕ پزٕ تمن خٲطرٕ خانٛدار تھاوُن؟}\n33.\\tمگر یہ گژھہِ سُہ عہد یُس بہٕ اسرٲیلِس گرس سٍتـ̡ کرِ۔ یِمن دۅہن پَتہٕ، خداوند چُھ ونان، بہٕ تھاوٕ پنُن قانون تِہندِس اندرونی حصس منز، تہٕ تہندِس دلس مَنٛز لیکھہٕ ۔ تہٕ تِہُند خدا، تہٕ تِم آسن میٲنۍ لوک۔\n34. تہٕ تِم کرٕ نہٕ پرٮ۪تھ أکِس شخصس پننِس ہمساین تہٕ پرٮ۪تھ أکِس شخصس تٔمۍ سٕندِس بٲیِس سٍتـ̡ ہیچھناوُن، تہٕ خداوند سُند وَنُن چُھ، تِکیازِ تِم سارِوٕے گژھن میہ زانن، یِمو منزٕ سارِوٕے کھۄتہٕ لۄکٹِس پیٹھٕ سارِوٕے کھۄتہٕ بٔڈِس تام، خداوند چُھ ونان زِ بہٕ کرٕ تِہٕندِس گناہ سٍتـ̡ معاف، تہٕ بہٕ کرٕ نہٕ تِہُند گۅناہ یاد۔\n35. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان، یُس آفتابس دۅہلہٕ گاشہٕ خٲطرٕ دِوان چُھ، {تہٕ} زونہِ تہٕ ستارن ہٕندِ حکمہٕ چُھہ رٲژ ہٕندِس گاشہٕ خٲطرٕ، یُس سمندرس تقسیم کران چُھ، یُس سمندرس تقسیم کران چُھ، یُس امہِ سٕنزِ لہرٕ وُچھان چُھ۔ میزبانن ہُند رب {چُھ} تٔمۍ سُند ناو:\n36. یێلہِ یێلہِ یِم احکام میانہِ برونہہ کُن ختم گژھن، خداوند چُھ ونان زِ {تیلہِ} گژھِ اسرٲیلُک نسل تہِ میانہِ برونہہ کُن اکھ قوم بننہٕ نِش ہمیشہٕ خٲطرٕ بند۔\n37. خداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ خداوند چُھ ونان زِ اگر ہیرِ کُن آسمانُک پیمائش ییہِ کرنہٕ، تہٕ زمینٕچ بُنیاد ژھانڈنہٕ ییہِ، بہٕ کٔرٕ تِمو سارِنٕے سارِنٕے سٍتـ̡ یُس تِمو کٔرمُت چُھ، بہٕ تہِ تراوٕ اسرٲیلُک سٲرِسٕے بیول یُس تِمو کٔرمُت چُھ، خداوند چُھ فرماوان۔\n38. خداوند چُھ ونان زِ شہر یِیہِ حنانیل کِس مینار پیٹھٕ کونہٕ کِس دروازس تام خداوند سٕندِ خٲطرٕ تعمیر کرنہٕ۔\n39.\\tتہٕ پیمائش لٲنہِ گژھہِ وُنہِ تہِ اتھ خلاف بالہٕ گریبس پیٹھ، تہٕ گوتھس تام گژھہِ اندۍ پکھۍ۔\n40. تہٕ لاشن ہٕنز سورے وادی، تہٕ سوٗر ہٕنز، تہٕ سارِنٕے کھہَن ہٕنز وادی تہٕ مشرقس کُن گُرِ دروازٕ کِس کونس تام، خداوند سٕندِ خٲطرٕ مقدس آسُن۔ یہِ گژھِ نہٕ تُلنہٕ یِنہٕ تہٕ نہ یِیہِ ہمیشہٕ خٲطرٕ دِنہٕ۔","1. سُہ لفظ یُس یہوداہ کِس بادشاہ صدقیاہ سٕندِس دٔہِمِس ؤریس مَنٛز خداوند سٕندِ طرفہٕ یُس نبوکدرِزرُک اردٲہِم ؤری اوس۔\n2. تکیازِ بابل کِس بادشاہ فوجن کوٚر یروشلمس محاصرٕ، تہٕ یرمیاہ پیغمبر آو جیل کِس آنگنس مَنٛز بند کرنہٕ، یُس یہوداہ کِس بادشاہ سٕندِس گرس مَنٛز اوس۔\n3.\\tیہوداہ کِس بادشاہ زدقیاہ اوس سُہ بند کٔرِتھ ونان، کیازِ چُھکھ ژے پیشن گویی کران تہٕ ونان، یِتھٕ پٲٹھۍ چُھہ خداوند فرماوان، یێلہِ بہٕ دِیہٕ یہِ شہر بابل کِس بادشاہس اتھس مَنٛز، تہٕ سُہ کرِ یہِ نِنہٕ۔\n4. تہٕ یہوداہُک بادشاہ صدقیاہ گژھِ نہٕ کلدانن ہٕندِ اتھہٕ نِش ژلنہٕ، بلکہ ییہِ یٔقیٖنی طور بابل کِس بادشاہ سٕندِس اتھس منز دِنہٕ، تہٕ أمِس سٍتـ̡ گژھِ ٲسِس سٍتـ̡ کتھ کرنہٕ، تہٕ تٔمۍ سٕنزِ أچھ گژھن تٔمۍ سٕنزِ أچھن وُچھان۔\n5. تہٕ سُہ کرِ صدیقیاہ بابل کُن نِنہٕ، تہٕ سُہ روزِ توٚت تام یوٚت تام بہٕ أمِس نِش گژھِ، خداوند چُھ ونان زِ یێلہِ تہٕ یێلہِ تہِ چُھہ چالدانن سٍتـ̡ جنگ کٔرِتھ، تۂ ہێکہِ نہٕ کامیاب سپدِتھ۔\n6. تہٕ یرمیاہ ووٚن، خداوند سُند کلام آو میہ نِش وونُن،\n7.\\tوُچھِو حنامیل، شالوم سُند نیچو، تُہُند پیٚتٕر یُس تۅہہِ نِش یِوان چھُ، یُس انتھوتھس مَنٛز چھُ، یُس تۅہہِ ہُند حق چھُ، یُس تۅہہِ ہُند حق چھُ۔\n8.\\tیِتھٕ ہنامیل میانہِ پیٚتٕر سُند نیچو آو میہ نِش قٲد خانس مَنٛز خداوند سٕندِ کلامَس مُطٲبق، تہٕ وونُن میہ زِ میون کھیت ہینہٕ، بہٕ چھُس ژے دُعا کران، یُس {چُھ} انتھوتھس مَنٛز، یُس {چُھ} بنیامین سٕندِس ملکس مَنٛز، یُس {چُھ} تُہُند حق چُھ، تہٕ چھُ تُہُند حق۔ پانس خٲطرٕ ہیٚیِو {یہ}۔ امہ پتہ ٲس میہ پتاہ زِ یہ {اوس} خداوند سُند کلام۔\n9.\\tتہٕ مے ہیوٚت پننِس پیٚتٕر سٕندِس نیچوِس حنامیل سُند کھیت یُس انتھوتھس منز اوس، تہٕ تٔمِس پونسہٕ تولُن، {حتیٰ کہ} سدہ شیکل رۄپہٕ۔ {سدہ ...: یا، ستھ شیکل تہٕ داہ رۄپہٕ}\n10.\\tتہٕ مے کٔر شہادت سبسکرائب کٔرِتھ، تہٕ مُہر کٔرِتھ گَواہ رٔٹِتھ تہٕ کٔرٕن پوٚنٛسہٕ وزن۔ {سبسکرائب...: ہیب۔ کتابہِ منز لیوکھمُت}\n11.\\tتێلہِ کٔر مے خٔریٖدٲری ہٕنز شہادت، {دۄشوے} یُس شریعت تہٕ رسم و رواجٕچ مُہر ٲس کرنہٕ آمٕژ، تہٕ یُس یُس یلہٕ اوس:\n12.\\tتہٕ مے دِژ خٔریٖدٲری ہٕنز گوٲہی ہنامیل میانِس پیترس سٕندِس نظرس منز، تہٕ تِمن گواہَن ہٕنزِ موجودگی منز یِمو خٔریٖدٲری ہٕنز کتاب سبسکرائب کٔرۍ، یِم سارِنٕے یہودی یِم قٲد خانس مَنٛز بِہتھ ٲسۍ۔\n13.\\tتہٕ میہ وونُن تِمن برونہہ کُن باروخس سٍتـ̡\n14. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھ فرماوان۔ یِم ثبوت، خریدٲری ہُند یہ ثبوت، دۅنوے یِم مُہر چھِ، تہٕ یہ شہادت یُس یلہٕ چھُ؛ تہٕ تِم تھووُن أکِس میژِس بانس منٛز، تاکہ تِم واریاہن دۄہن جٲری روزن۔\n15. یِتھٕ پٲٹھـ̡ چُھہ لشکرن ہُند خداوند یُس اسرٲیلُک خدا چُھہ وَنان۔ اتھ زمینس منز گژھن مکانہٕ تہٕ کھیت تہٕ انگور باغن پیٹھ دوبارٕ قبضہ کرنہٕ۔\n16.\\tییلہ میہ نیریاہ سٕندِس نیچوِس باروخس خٔریٖدٲری ہٕنز شہادت واتنوو، مے کٔر خداونس نِش دُعا ،\n17. اے خدا! وچھ ژے بنوو پننہِ عظیم طاقتہٕ سٍتۍ آسمان تہٕ زمین تہٕ نٔر پھٔہلٲوِتھ، {تہٕ} تہٕ ژے خٲطرٕ چُھنہٕ کانہہ تہِ مشکل: {تہِ...: یا ژے نِش پوشیدٕ}\n18. توے چُھہ ساسہٕ بٔدین سٍتـ̡ محبتہٕ دِوان، تہٕ تِمن ہٕندِس پَتہٕ یِنہٕ وٲلِس شُرین ہٕندِس سٍتـ̡ دِوان چُھہ بٔڈِس سٍتـ̡ دِوان تہٕ یێمہِ سُند ناو چُھہ بٔڈـ̡\n19. مشورس مَنٛز بٔڈ تہٕ کامہِ مَنٛز طاقتور تہٕ کامہِ مَنٛز طاقتور آسُن: تُہٕنزِ أچھ چِھہ انسانہٕ سٕندِس فرزندن ہٕندِس سارِنٕے وتہٕ سٍتـ̡ یلہٕ پٲٹھـ̡ دِنہٕ خٲطرٕ: {کٲم: عبرانی۔ کرُن}\n20. یٔمۍ از تام مصر کِس سرزمینس مَنٛز تہٕ اسرائیلس مَنٛز تہٕ باقین انسانن مَنٛز نشانہٕ تہٕ عجائب قایم کٔرۍمٕتۍ۔ تہٕ بنووُن ژے اکھ ناو، یُتھ زن از تہِ چھُ۔\n21. تہٕ کٔرٕن پنٕنۍ قوم اسرائیل مصر کِس سرزمینہٕ منزٕ نشانہٕ تہٕ عجائبات سٍتۍ، مضبوٗط اتھہٕ سٍتۍ، نٔر پھٔہلٲوِتھ تہٕ سٮ۪ٹھاہ دہشت سٍتـ̡ نیبر کٔرِتھ۔\n22.\\tتہٕ دِژُن تِمن یہِ زمین، یُس ژے تِمن مٲلِس دِنُک قَسم اوس کٔرمُت، یُس دۄد تہٕ ماچھ سٍتـ̡ وسان آسہِ۔\n23.\\tتہٕ تِم آیہِ اژِتھ تہٕ کوٚرُکھ اَتھ نِش قبضہٕ۔ مگر تِمو کٔر نہٕ تُہنزِ آوازِ ہٕنز فرمانبرداری، تہٕ نہ کٔرٕکھ چانہِ قانونس مَنٛز۔ تِمو چُھہ نہٕ تِمن سارِنٕے سارِنٕے سٍتـ̡ کٔرمُت یُس تۅہہ حُکُم دِیُتمُت چُھ، تێلہِ چُھہ تِمن سٍتـ̡ یہِ سورُے بُرٕ دِژمُت:\n24. وُچھِو پہاڑ، تِم چھِ شہرس منز یِوان نِنہٕ خٲطرٕ۔ تہٕ شہر چُھ چالڈین ہٕندِس اتھس منز دِنہٕ آمُت، یُس تلوار تہٕ قحطہٕ سٍتـ̡ تہٕ وباہن سٍتـ̡ اتھ خلاف لڑان چُھ، تہٕ یُس تہٕ ژے کتھ کٔرمٕژ چُھ، سُہ چُھ سپدان۔ تہٕ وچھ ژے وچھان {یہ}۔ {ماونٹس: یا، انجن آف شاٹ}\n25. تہٕ ژے چُھہ مے ووٚنمُت، اے خدایہ، ژے ہیوٚن کھیت پٲنسہٕ خٲطرٕ تہٕ گوٲہی نِن؛ تکیازِ شہر چُھ چالڈین ہٕندِس اتھس منز دِنہٕ آمُت۔ {for the: or, even the}\n26. اَمہِ پَتہٕ آو خداوند سُند کلام یرمیاہ ہس نِش وَنُن،\n27. وُچھِو، بہٕ چُھس خدا، سارِنٕے جسمُک خدا: کیا میانہِ خٲطرٕ چھا کانہہ مشکل؟\n28. تێمہِ کِنۍ چُھ خداوند یِتھٕ پٲٹھۍ فرماوان۔ وچھ، بہٕ دِیہ یہ شہر کلدانن ہٕندِس اتھس منز، تہٕ بابل کِس بادشاہ نبوکدرِزر سٕندِس اتھس منز، تہٕ سُہ کرِ یہِ نِن:\n29.\\tتہٕ یِم چالدان یِم اتھ شہرس خلاف لڑان چھِ، یِم یِمن شہرس نار دِن، تہٕ یِمن ہٕندٮ۪ن چھتن پیٹھ یِمو بعلس بخور دِژمٕژ چھِ، تہٕ باقین دیوتاہن خٲطرٕ چِھکھ شرابٕچ قربانی دِژمٕژ، یُس مےٚ شرارت دِنہٕ خٲطرٕ۔\n30. کیازِکہ بنی اسرائیل تہٕ یہوداہ کیو اولادو کٔر میہ برونہہ کُن پننہِ جوانی پیٹھے صرف بُرکاری کٔرمٕژ، کیازِ بنی اسرائیل چُھ میہ صرف پننیو اتھو سٍتـ̡ شرارت دِژمُت، خداوند چُھ فرماوان۔\n31. تکیازِ یہ شہر چُھ میانہِ خٲطرٕ میانہِ خٲطرٕ میٲنۍ شرارت تہٕ میانہِ غصہٕ ہُند اشتعال دِنہٕ آمُت ییمہ دۅہہ تمو یہ از تام تعمیر کوٚر۔ زِ میہ پزِ یہ پننہِ بُتھِ برونہہ کنہِ ہٹاون، {اکھ اشتعال...: ہیب۔ میانہِ شرارت خٲطرٕ}\n32. بنی اسرائیل تہٕ یہوداہ کین اولادن ہٕنزِ تمام بُرکاری کِنۍ، یُس تمو میہ شرارت دِنہٕ خٲطرٕ کورمُت چُھ، تِمو ، تِہندیو بادشاہن، تِہندیو شہزادن، تہندیو پادٕرۍ، تہٕ تِہندِ پیغمبرن تہٕ یہوداہ کین انسانو تہٕ یروشلم کین بسکینن ہٕندِس سٍتـ̡ ۔\n33.\\tتہٕ تِمو چُھہ میہ کُن پوٚت پھیرمُت، بُتھ نہٕ، یۆدوَے مے تِمن ہیچھناوُن، سُلہٕ وُتھٕ وُتھان تہٕ تِمن ہیچھناوُن، توتہِ چُھہ نہٕ تِمو ہیچھناوُن بوزمُت۔ {واپس: ہیب۔ گردن}\n34.\\tمگر تِمو کٔر گرس مَنٛز پنٕنۍ ناپاک کٔرِتھ، یُس میانہِ ناوٕ سٍتۍ وَننہٕ یوان چھُ، اَتھ ناپاک کرنہٕ خٲطرٕ۔\n35.\\tتہٕ تِمو بنٲو بعلٕچ تھدِ جایہ، یِم حنوم سٕندِس نیچوِس وادی مَنٛز چھِ، یُس پننین نیچوٮ۪ن تہٕ کورِ ہٕندِس نارس منزٕ مولیخس تام واتناوُن۔ یُس میہ تمن حکم دیُت نہٕ، تہٕ نہ آو میٲنس ذہنس منٛز زِ تم گژھن یہٕ مکروہ کرٕن، یہوداہک گناہ کرنُک سبب بنن۔\n36. تێمہِ کِنۍ چُھ یِتھٕ پٲٹھـ̡ یێلہِ یێمہِ شہرس مُتعلِق یێلہِ تُہۍ ونان چھِ، یێمہِ سٍتـ̡ یِیہِ تلوارٕ سٍتـ̡ تہٕ قحط سٍتـ̡ تہٕ وباہن سٍتـ̡ بابل کِس بادشاہ سٕندِس اتھس مَنٛز دِنہٕ۔\n37.\\tوُچھ، بہٕ کٔرٕ تِم سارِنٕے مُلکو منزٕ جمع کٔرِتھ، ییتہِ مے تِم پننہِ شرارتس منز، پننِس غصس سٍتـ̡ تہٕ سٮ۪ٹھاہ غصہٕ سٍتـ̡ ژٔلِتھ دِژمٕژ چھِ۔ تہٕ بہٕ اَننہٕ تِم دُبارٕ یَتھ جایہ، تہٕ بہٕ کَرٕ تِم محفوٗظ پٲٹھۍ:\n38. تہٕ تِم گژھن میٲنۍ لوک، تہٕ بہٕ بنہٕ تِہُند خدا:\n39. تہٕ بہٕ دِیہ تِمن اکھ دِل، تہٕ اکھ وتھ، یُتھ تِم ہمیشہٕ خٲطرٕ میہ تہٕ تِمن ہٕندِس بچن ہٕندِ بھلائی خٲطرٕ خوفزدہ روزن۔ سارِنٕے دۅہہ}\n40. تہٕ بہٕ کَرٕ تِمن سٍتـ̡ ابدی عہد زِ بہٕ کَرٕ نہٕ تِمن نِش پتھ کُن، تہٕ تِمن سٍتـ̡ نیکی کرنہٕ مۅکھہٕ۔ مگر بہٕ تھاوٕ پنُن خوف تہندِس دلس منز، زِ تِم گژھن نہٕ میہ نِش دور۔ {تمن منز: ہیب۔ تمن پتہٕ}\n41. آ، بہٕ کَرٕ تِمن پیٹھ خوش تہٕ بہٕ کَرٕ یِم پنٕنِس پوٗرٕ دِلہٕ تہٕ پوٗرٕ روحہٕ سٍتـ̡ یَتھ زمینس مَنٛز پٲٹھۍ۔ {یقینا: ہیب۔ حقیقتس منز، یا، استحکام}\n42. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ یِتھ کٔنۍ مے یِمن لوکن پیٹھ یہ سورے بٔڈ بُردی انمٕژ، تِتھے کٔنۍ کٔرٕ بہٕ تِمن پیٹھ سٲرۍسٕے خیر یُس میہ تمن وعدٕ کورمُت چھُ۔\n43.\\tتہٕ اتھ زمینس منز یِن کھیت ہینہٕ، یتھ متعلق تۅہہ ونان چھِو، {یہِ} چُھہ انسان تہٕ جانور ورٲے ویران۔ یہٕ چُھ چالڈین ہٕندِس اتھس منز دِنہٕ آمُت۔\n44.\\tانسان گژھن پٲنسہٕ خٲطرٕ کھیت ہینہٕ، تہٕ شہادت حٲصل کٔرِتھ، تہٕ مہر لگاونہٕ یِن، تہٕ بنیامین سٕندِس ملکس منز، یروشلم کِس اندۍ پکھۍ مقامن منز، یہوداہ کین شہرن منز، پہاڑن ہندین شہرن منز، وادی ہٕندِس شہرن منز، تہٕ جنوبٕکین شہرن مَنٛز، تہٕ بہٕ کرٕ تِمن ہٕندِس قید واپس یِن،  خداوند چُھ فرماوان۔","1.\\tبییہِ ووت خداوند سُند کلام یرمیاہ ہس نِش دوٚیمہِ لٹہِ ییلہ سُہ وُنہِ تہِ قٲد خانس منز بند اوس، وونُن زِ\n2. یِتھٕ پٲٹھـ̡ چُھ خداوند یُس یہِ بناون وول چُھ، خداوند یُس یہِ بنوومُت چُھ، یہِ قٲیِم کرنہٕ خٲطرٕ چُھ وَنان۔ خداوند {چُھ} تٔمۍ سُند ناو؛ {خداوند چُھ: یا، یہوواہ وغیرہ}\n3.\\tمیہ کٔرِو بلاو، تہٕ بہٕ کرٕ ژے جواب تہٕ بٔڈ تہٕ بٔڈ چیز ہٲوِتھ یِم نہٕ ژے پتاہ چھِ۔ {طاقتور: یا، پوشیدٕ}\n4. یِتھٕ پٲٹھـ̡ چُھ خداوند اسرٲیلُک خدا، یێمہِ شہرٕکین گھرن مُتعلِق تہٕ یہوداہ کِس بادشاہن ہٕندِس گھرس مُتعلِق یِم پہاڑو تہٕ تلوار سٍتـ̡ دِنہٕ آمٕتۍ چھِ۔\n5. تِم چِھ چالدانن سٍتـ̡ لڑنہٕ خٲطرٕ یِوان، مگر {یہٕ} چُھہ تِمن مردن ہٕنزِ لاشہٕ سٍتـ̡ بٔرِتھ بٔرِتھ، یِم مے پننِس شَرارتہٕ تہٕ غصس سٍتـ̡ مٲرِمٕتۍ، تہٕ یِمن سارِنٕے بدکارن ہٕندِ خٲطرٕ چُھہ مے یِمن ہٕندِس شہرس نِش بُتھ ژوٗرِ تھوومُت۔\n6. وچھ بہٕ اَتھ صحت تہٕ علاج، تہٕ بہٕ کٔرٕ تِمن شفا تہٕ تِمن ہٕندِ خٲطرٕ امن تہٕ حقیقتٕچ کثرت ظٲہر۔\n7. تہٕ بہٕ کٔرٕ یہوداہ سٕندِ قٲد تہٕ اسرٲیلِچ قید واپس تہٕ یِم بناوٕ گۅڈنچہ لٹہِ۔\n8. تہٕ بہٕ کَرٕ تِمن ہٕندِس سارِنٕے گناہ نِش پاک ییمہ سٍتـ̡ تِمو میانہِ خلاف گۅناہ کورمُت چُھ۔ تہٕ بہٕ کَرٕ تِہٕندِس سارِنٕے گناہ معاف، یِمو سٍتـ̡ تِمو گۅناہ کورمُت چُھ، تہٕ ییمہ سٍتـ̡ تِمو میانہِ خلاف زیادتی کٔرمٕژ چھِ۔\n9. تہٕ یہ آسہِ میانہِ خٲطرٕ سارِنٕے زمینہٕ کین قومن برونہہ کُن خوشی، تعریفن تہٕ عزتُک ناو، یُس بہٕ تِمن سٍتـ̡ سٲرِی نیکی بوزِ، تہٕ تِم گژھن سارِنٕے نیکی تہٕ سارِنٕے خۄشحٲلی خٲطرٕ کھوژان تہٕ تھرتھر یُس بہٕ اتھ حٲصل کران چُھ۔\n10.\\tخداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ یێمہِ جایہِ یێلہِ یێلہِ تہٕ یێلہِ بێیہِ یێلہِ تہٕ بےٚ درندٕ تہٕ یِمن ہٕندِس شہرس مَنٛز، یِم ویران چھِ، بغٲر انسانہٕ تہٕ بسکیٖن تہٕ درندٕ ورٲے، یِم ویران چھِ، یِم بےٚ انسانہٕ تہٕ بسکیٖن تہٕ درندٕ بغٲر چھِ،\n11. خوشی ہٕنز آواز، تہٕ خوشی ہٕنز آواز، مہرازٕ سٕنز آواز، تہٕ مہرِنہِ ہٕنز آواز، تِمن ہٕنز آواز یُس وَنُن چُھ، لشکرن ہٕندِس رب سٕنز تعریف: کیازِ خداوند چُھہ اصل۔ تٔمۍ سٕنزِ رحمتہٕ خٲطرٕ روزِ ہمیشہٕ خٲطرٕ: {تہٕ} یُس خداوند سٕندِس گرس مَنٛز تعریفٕچ قربانی دِیہِ۔ کیازِ بہٕ کرٕ زمینُک قید واپس کرنُک سبب، یِتھ کٔنۍ زن گۅڈنچہ لٹہِ، خداوند چُھ فرماوان۔\n12. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب فرماوان۔ اَتھ جایہِ یُس انسانہٕ ورٲے تہٕ درندٕ ورٲے ویران چھُ، تہٕ اَمہ کِس سارِنٕے شہرن مَنٛز، آسہِ چرواہَن ہُند مسکن یُس {تِہٕندِ} ریوڑ بٔنِتھ روزان چھُ۔\n13.\\tپہاڑن ہندین شہرن منز، وادی کین شہرن منز، تہٕ جنوبٕکۍ شہرن منز، تہٕ بنیامین سٕندِس سرزمینس منز، تہٕ یروشلم اندۍ پکھۍ جاین تہٕ یہوداہ کین شہرن مَنٛز، یُس یہوداہ کین شہرن مَنٛز، یُس یہِ ونان چُھ، خداوند چُھ فرماوان۔\n14. خداوند چُھ فرماوان زِ بہٕ کرٕ سُہ اصل کٲم یُس میہ اسرٲیلِس تہٕ یہوداہ کِس گرس سٍتـ̡ وعدٕ کورمُت چُھ۔\n15.\\tتِمن دۅہن تہٕ تمہِ وِزِ بہٕ کٔرٕ نیکی ہٕنز شاخ داؤدس تام بڑان۔ تہٕ سُہ کرِ زمینس مَنٛز فٲصلہٕ تہٕ نیکی انجام دِنہٕ۔\n16. یِمن دۅہن منز ییہِ یہوداہ نجات دِنہٕ، تہٕ یروشلم روزِ رٲبطہٕ سٍتـ̡ تہٕ یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ یێلہ {خداوند...: ہیب۔ Jehovahtsidkenu}\n17. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ داؤد گژھہِ نہٕ زانہہ تہِ یژھان زِ کانہہ انسان گژھہِ اسرٲیلِہ کِس تختس پیٹھ بِہُن۔ {ڈیوڈ...: ہیب۔ ڈیوڈس سٍتـ̡ گژھہِ نہٕ ژٹنہٕ یُن}\n18.\\tنہ گژھن پادٕرۍ یِم میانہِ برونہہ کُن کانہہ نفر زٲلِتھ نذرانہ پیش کرُن، تہٕ مازٕچ قربانی دِنہٕ خٲطرٕ تہٕ لگاتار قربانی دِنہٕ یِن۔\n19. تہٕ خداوند سُند کلام آو یرمیاہ ہس نِش وونُن،\n20. خداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ یێلہِ تہٕ یێلہِ تُہۍ میون دۅہُک عہد تہٕ راتُک میٲنۍ عہد پھُٹرٲوِتھ، تہٕ یِمن ہٕندِس موسمس مَنٛز گژھِ نہٕ دۄہ تہٕ رٲژ آسٕنۍ۔\n21. {پتہٕ} گژھِ میون عہد تہِ پھُٹراونہٕ یُن میٲنِس خادمس سٍتـ̡ زِ أمِس گژھہِ نہٕ پننِس تختس پیٹھ بادشاہی کرنہٕ خٲطرٕ کانہہ نیچو۔ تہٕ لاوِین سٍتـ̡ پادٕرۍ، میانین وزیرن سٍتـ̡ ۔\n22.\\tیِتھٕ پٲٹھـ̡ اسمانُک لشکر ہیکو نہٕ گنزراونہٕ یِتھ، سمندرٕچ سیکہِ ہُند پیمائش ہیوٚک نہٕ کٔرِتھ، تِتھے پٲٹھۍ کٔرٕ بہٕ پنُن خادم داؤد سُند بیول تہٕ یِم میانہِ خدمت کران چھِ۔\n23.\\tامہِ علاوہ آو خداوند سُند کلام یرمیاہ ہس نِش وونُن،\n24.\\tژیہ کیا چُھہ نہٕ غور کران زِ یِمن دۅن خاندانن یِم خداوند چُھہ ژٲرمٕتۍ، تِم تہِ کٔرۍمٕتۍ۔ اَتھ پٲٹھۍ چھُ تِمو میانٮ۪ن لوٗکن سۭتۍ حقارت کٔرمٕژ، زِ تِم گژھِ نہٕ تِمن برونہہ کُن اکھ قوم آسٕنۍ۔\n25.\\tخداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ یێلہِ میون عہد {آسہِ} دۅہ تہٕ راتس سٍتـ̡ {تہٕ اگر} مے چُھہ نہٕ آسمانن تہٕ زمینن ہٕندِ احکام مقرر کرمٕتۍ۔\n26. تیلہِ کٔرٕ بہٕ یعقوب سُند بُل، تہٕ داؤد پنُن خادم، یُتھ بہٕ نہٕ تٔمۍ سٕندِس اولادُک کانہہ تہِ حصہٕ ابراہیم، اسحاق تہٕ یعقوب سٕندِس اولادس پیٹھ حکمران بنہٕ، تکیازِ بہٕ کرٕ تِہُند قٲد واپس تہٕ تِمن پیٹھ کرٕ رحم۔","1. سُہ کلام یُس یرمیاہ ہس رب سٕندِ طرفہٕ آو ، یێلہِ بابلُک بادشاہ نبوکدنضر تہٕ تٔمۍ سٕندِس سارِنٕے لشکر تہٕ تٔمۍ سٕندِس سلطنت ہٕندِس سارِنٕے بادشاہتن تہٕ سارِنٕے لُکن یروشلمس تہٕ تٔمِس سارنٕے شہرن خٕلاف جنگ کٔرِتھ وونُن یێمہِ سٕندِس سٍتـ̡ ہٕندِس بادشاہس سٍتـ̡ ۔ تٔمۍ سٕنٛدِ اَتھُک غلبہٕ}\n2. یِتھٕ پٲٹھـ̡ چُھ خداوند اسرائیلُک خدا فرماوان۔ گژھ تہٕ یہوداہ کِس بادشاہس سٍتـ̡ کتھ کرٕن، تہٕ وَنُن خداوند چُھہ یِتھٕ پٲٹھۍ۔ وُچھ، بہٕ دِیہٕ یہِ شہر بابل کِس بادشاہس اتھس منٛز، تہٕ سُہ دِیہِ یہِ نارٕ سٍتـ̡ زالنہٕ:\n3.\\tتہٕ ژیہ ژٔلِتھ ژٔلِتھ تٔمۍ سٕندِس اتھہٕ نِش نِش نیرُن، مگر یِیہِ یٔمۍ سٕندِس اتھس مَنٛز دِنہٕ یُن۔ تہٕ تۅہہِ ہٕنزِ أچھ وُچھن بابل کِس بادشاہ سٕنزِ أچھ، تہٕ سُہ کرِ ژے سٍتـ̡ ٲسس سٍتـ̡ کتھ کرنہٕ، تہٕ ژے گژھہِ بابل کُن۔ {سُہ کرُن...: ہیب۔ تٔمۍ سُند اوس چُھس کتھ کٔرِتھ}\n4. توتہِ بوزو خداوند سُند کلام، اے صدقیہ یہوداہ کِس بادشاہ۔ یِتھٕ پٲٹھۍ چُھ تُہند رب ونان زِ ژے گژھ نہٕ تلوار سٍتـ̡ مٔرِتھ:\n5. {مگر} ژے مرُن امن سٍتـ̡ تہٕ پنہٕ نـ̡ پنہٕ نـ̡ بادشاہن ہٕندِس زالنہٕ سٍتـ̡ یِم تۅہہِ برونہہ ٲسۍ، تِتھے پٲٹھـ̡ زالنہٕ یِنہٕ سٍتـ̡ تۅہہِ خٲطرٕ {خوشبو} تہٕ تِم چھِ تۅہہِ ماتم کٔرِتھ، {ونان}، اے خدا! خداوند چُھ ونان زِ میہ چُھ لفظ تلفظ کورمُت۔\n6.\\tتێلہِ وۆن یرمیاہ پیغمبرن یروشلمس مَنٛز یہوداہ کِس بادشاہ زدقیاہ ہس سٍتـ̡ یِم سٲری لفظ وون،\n7.\\tییلہ بابل کِس بادشاہس لشکر یروشلمس خلاف تہٕ یہوداہ کین سارنٕے شہرن خلاف یُس باقٕے رودمُت، لاخیش تہٕ عزیقاہس خلاف لوٚڑ، تکیازِ یِم دفاع کرنہٕ آمٕتۍ شہر رودۍ یہوداہ کین شہرن منز۔\n8. {یہِ} چُھ سُہ لفظ یُس خداوند سٕندِ طرفہٕ یرمیاہ ہس نِش آو، اَمہِ پتہٕ اوس بادشاہ صیدقیاہ تِمن سارِنٕے لُکن سٍتـ̡ عہد کورمُت یِم یروشلمس مَنٛز ٲسۍ، تِمن ہٕنزِ آزٲدی ہُند اعلان کرنہٕ خٲطرٕ۔\n9.\\tزِ پریتھ انسان گژھہِ پننِس نوکرس تہٕ پرٮ۪تھ أکِس شخصس یُس عبرانی یا عبرانی آسہِ، آزاد گژھُن۔ زِ کٲنسہ تہِ گژھہِ نہ تمن ہنز خدمت کرُن، اکس یہودی سٕندِس بٲے سٕندِس سٍتـ̡ ۔\n10.\\tوۅنۍ ییلہ سارِنٕے شہزادو تہٕ سارِنٕے لوکو یِمو معاہدس منز دٲخل گٔمٕتۍ، بوز زِ پرٮ۪تھ کٲنسہ پزِ پنُن نوکر تہٕ پرٮ۪تھ أکِس نوکرس آزاد کرُن، یُتھ زن نہٕ کانہہ تہِ تِمن ہٕنز خدمت کرٕنۍ، تیلہِ کٔر تِمو اطاعت تہٕ یِمن دِنہٕ یِنہٕ۔\n11.\\tمگر امہ پتہ گٔیہ تِمو پھیرۍ تہٕ نوکروں تہٕ دٲیرۍ، یِم یِمو آزاد کٔرۍمٕتۍ، واپس تہٕ أنِکھ نوکروں تہٕ دٲیرن ہٕندِ خٲطرٕ تابع۔\n12. تێمہِ کِنۍ آو خداوند سُند کلام یرمیاہ ہس نِش خداوند سٕندِ طرفہٕ وونُن،\n13. یِتھٕ پٲٹھـ̡ چُھ خداوند اسرٲیلُک خدا فرماوان۔ میہ کوٚر تۅہہِ مٲلس سٍتـ̡ تمہِ دۅہہ عہد زِ بہٕ تِم مصر کہِ سرزمینہٕ منز، غلامن ہٕندِس گرٕ منزٕ نیبر کٔرِتھ وونُن،\n14. سَتن ؤرین ہٕندِس ٲخرس پیٹھ گژھ ژیہ پرٮ۪تھ أکِس شخصس سُند بٲے یُس تۅہہِ کٕننہٕ آمُت چُھ، یُس تۅہہِ کٕننہٕ آمُت چُھ۔ تہٕ ییلہ تۅہہ شیہ ؤری خدمت کرِ، تہٕ ژے تراوُن سُہ پانس نِش آزاد، مگر تہندیو مٲلو بوز نہٕ میانہِ کُن تہٕ نہ کٔرٕکھ کُن۔ {ہا ہا...: یا، ہیو پان کُن}\n15.\\tتہٕ تۅہہ ٲسکھ وۅنۍ پھیرمٕژ، تہٕ ٲسکھ میانہِ نظرِ منز صحیح کٲم کٔرمٕژ، پرٮ۪تھ أکِس انسانس پننِس ہمساین نِش آزٲدی ہُند اعلان کٔرِتھ۔ تہٕ ژے اوس میانہِ برونہہ کنہِ اَتھ گرس مَنٛز اکھ عہد کورمُت یُس میانہِ ناوٕ سٍتـ̡ ونان چھُ: {وۆن: ہیب۔ ٹو ڈے} {کُس...: ہیب۔ ییمہ پتہٕ میون ناو وننہٕ چُھ یوان}\n16.\\tمگر ژے کٔرِو میٲنۍ ناو ناپاک تہٕ پرٮ۪تھ أکِس شخصس پنُن خادم، تہٕ پرٮ۪تھ أکِس شخصس کٔرِکھ تٔمۍ سٕنزِ خادم، یُس تِمن ہٕنزِ مرضی مُطٲبق آزاد کورمُت اوس، واپس یِنہٕ خٲطرٕ، تہٕ أنِکھ تِم خادمَن تہٕ دٲیرین ہٕندِ خٲطرٕ پانس نِش بٔنِتھ۔\n17. تێمہِ کِنۍ چُھ خداوند یِتھٕ پٲٹھۍ وَنان۔ ژے چُھہ نہٕ میانہِ خٲطرٕ آزٲدی ہُند اعلان کرنہٕ خٲطرٕ، پرٮ۪تھ کانٛہہ پننِس بٲیِس تہٕ پرٮ۪تھ أکِس شخصس پننِس ہمساین ہٕندِس خٲطرٕ آزٲدی ہُند اعلان کٔرِتھ، خداوند چُھ ونان زِ بہٕ چُھس تہٕ تۅہہِ خٲطرٕ آزٲدی ہُند اعلان کران چھُس۔ تہٕ بہٕ بناوٕ ژے زمینہٕ کین سارنٕے سلطنتن مَنٛز نِنہٕ۔ {to be...: Heb. ہٹاونہٕ خٲطرٕ}\n18.\\tتہٕ بہٕ دِیہ تِم نفر یِمو میانہِ عہدٕچ خلاف ورزی کٔرۍ، یِمو نہٕ میانہِ برونہہ کُن عہد کٔرِتھ کٔرِمٕتۍ، یِمو بَچھرٕ ژٔٹِتھ تہٕ اَمہ کِس حِصس مَنٛز گٔیہِ،\n19.\\tیہوداہٕکۍ شہزاد، تہٕ یروشلمٕکۍ شہزادٕ، خواجہ سرا تہٕ پادٕرۍ، تہٕ زمینٕکۍ سٲری لوُکھ، یِم بچھرٕ کِس حِصس مَنٛز گٔژھان۔\n20. بہٕ دِیہ تِمن ہٕندِس دُشمن ہٕندِس اتھس منز، تہٕ تِمن ہٕندِس اتھس مَنٛز یِم تِمن ہٕنزِ جان ژھاران چھِ، تہٕ تِہٕنزِ لاشہٕ گژھن اسمانٕکۍ جاناوارن تہٕ زمینہٕ کین درندن ہٕندِس ماز خٲطرٕ۔\n21. تہٕ یہوداہُک بادشاہ سدقیاہ تہٕ تٔمۍ سٕندِس شہزادس دِیُس بہٕ تِہندِس دُشمنن ہٕندِس اتھس منز، تہٕ تِمن ہٕندِس دُشمن ہٕندِس اتھس مَنٛز، تہٕ بابل کِس بادشاہ سٕندِس لشکرس مَنٛز، یُس ژے نِش ہیوٚر گوٚمُت چھُ۔\n22.\\tوچھ، بہٕ کرٕ حُکُم، خداوند چُھس ونان تہٕ تِمن یَتھ شہرس منز واپس یِنُک حُکُم کَرُن۔ تہٕ تِم کرِ اتھ خلاف لڑان، تہٕ نِن تہٕ نارٕ سٍتـ̡ زالنہٕ، تہٕ بہٕ بناوٕ یہوداہ کِس شہرس بغٲر کُنہِ بسکیٖن سٍتـ̡ ویران۔","1. سُہ کلام یُس یہوداہ کِس بادشاہ یوسیا سٕندِس نیچوِس یہویاکیمس سٕندِس زمانس مَنٛز یُس یہوداہ کِس بادشاہ یہوسیاہ سٕندِس نیچوِس سٕندِس زمانس مَنٛز یُس یرمیاہ سٕندِ طرفہٕ آمُت چھُ،\n2.\\tیِمن ہٕندِس گرس مَنٛز گژھِو تہٕ تِمن سٍتـ̡ کتھ کرٕن، تہٕ تِمن أنِو خداوند سٕندِس گرس مَنٛز، أکِس خانس مَنٛز، تہٕ دِیُن تِمن شراب چنہٕ خٲطرٕ۔\n3. اَمہِ پَتہٕ رٔٹۍ یَرمیاہُک نیٚچُو، حبزینیاہ سُند نیٚچُو، تہٕ تٔمۍ سٕندِس سارِنٕے نیٚچوِس تہٕ تٔمۍ سٕندِس سارِنٕے نیٚچوِس تہٕ رِکابیَن ہُند سورُے گر۔\n4.\\tتہٕ بہٕ اوٚن تِم خداوند سٕندِس گرس منز، حنان سٕندِس نیچوِس ہٕندِس کمرس منز، یُس خدایہ سُند نیچو اوس، یُس شہزادن ہٕندِس کمرس مَنٛز اوس، یُس شالوم سُند نیچو ماسیہ سٕندِس کمرس پیٹھ، دروازُک رٲچھ کرن وول اوس: {دروازہ: حب۔ تھریشولڈ، یا، ویسل}\n5. تہٕ مے تھوو ریکیبٹس ہٕندِس گرٕ کِس نیچوَن برونہہ کُن شرابہٕ تہٕ پیالہ بٔرِتھ بانہٕ، تہٕ مے ووٚنمُت تِمن شراب۔\n6. مگر تِمو ووٚن زِ أسۍ چِھہ نہٕ شراب، تکیازِ سٲنِس مٲلہِ رِچاب سٕندِ نیچو جوناداب دِیُت اسہِ حُکُم زِ تُہۍ پَزِ نہٕ شراب، تہٕ نہ تہٕ تُہٕندِس نیٚچوِس ہمیشہٕ خٲطرٕ۔\n7.\\tژیہ کٔرِو مکانہٕ بَناوُن، نہ کُنہِ دۅہہٕ کُنہِ خیمَن مَنٛز روزُن۔ یُتھ زن تُہۍ واریاہن دۅہن تتھ زمینس منز روزِتھ ییتہِ تم اجنبی ٲسِو۔\n8. یِتھٕ پٲٹھۍ کٔر اسہِ سٲنِس مٲلہِ رِچاب سٕندِس نیچوِس جوناداب سٕنزِ آوازِ ہٕنز اطاعت یُس تٔمۍ اسہِ دِژمُت چھُ، سُہ چُھہ سارِنٕے دۅہس منز شراب چیٚنہٕ، سانہِ زنانہٕ، پننین نیچوین تہٕ سانین کورِن ہُند حکم دِنہٕ آمُت۔\n9. نہ چُھہ اسہِ روزنہٕ خٲطرٕ مکانہٕ بناوُن: نہ چُھہ اسہِ انگور، نہ کھیت تہٕ نہ بیٲلۍ:\n10.\\tمگر أسۍ رودۍ خیمن مَنٛز روزان، تہٕ کٔرٕکھ سٲرِسٕے مُطٲبِق یُس سٲنِس مٲلہِ جوناداب سُند حُکُم اوس دِژمُت۔\n11.\\tمگر سپد ییلہ بابلُک بادشاہ نبوکدرِززار زمینس مَنٛز ووت، اسہِ ووٚن، یِمو تہٕ اسہِ گژھو یروشلم کُن کلدانن ہٕندِ فوجہٕ کہِ خوفہٕ سٍتـ̡ تہٕ شامٕچ فوجہٕ کہِ خوفہٕ سٍتـ̡ یِتھٕ پٲٹھۍ أسـ̡ یروشلمس مَنٛز روزان۔\n12. پتہٕ آو خداوند سُند کلام یرمیاہ ہس نِش وَنُن،\n13. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھ فرماوان۔ گژھ تہٕ یہوداہ کین لوکن تہٕ یروشلم کین بسکینن وَنُن، کیا ژیہ میلہٕ نہٕ میانہِ کلامٕچ کتھ بوزنٕچ ہدایت؟ خداوند چُھ فرماوان۔\n14.\\tرِچاب سٕندِس نیچوِس جوناداب سٕندِ کلام، زِ تٔمۍ دِژ پننین نیچوین شراب نہٕ چیٚنُک حُکُم۔ تِکیازِ از تام چھِ نہٕ تِم کانٛہہ تہِ چیٚوان، مگر چھِ پننِس مٲلہِ سٕنٛدِس حُکمس تعمیل کران: باوجوٗد چھُ مےٚ ژےٚ کتھ کٔرمٕژ، سُلہٕ وُتھان تہٕ کتھ کٔرِتھ۔ مگر ژے بوز نہٕ میہ کُن۔\n15.\\tمیہ چھُ پنٕنـ̡ سارِنٕے خادمَن نِش سُلہٕ سُلہٕ وُتھٕ تہٕ سُلہٕ سُلہٕ سُہ سُہ وُچھِتھ سُہ وَنُن زِ یێلہِ کٔرِو پرٮ۪تھ أکِس بد وتہِ نِش واپس، تہٕ پَنٕنـ̡ کٔرِو پَنٕنـ̡ کٔرِو تِمن ہٕنزِ خدمتہٕ کرنہٕ خٲطرٕ بێیِو نہٕ باقین دیوتاہن پَتہٕ یِمن ہٕنزِ خدمتہٕ کرنہٕ خٲطرٕ، تہٕ تُہۍ روزِو تتھ زمینس مَنٛز یُس مے ژے تہٕ تُہٕندِس مٲلِس دِژمُت چھُ۔  مگر ژے کٔر نہ پنُن کُن ہیوٚت، تہٕ نہ بوزمُت۔\n16.\\tکیازِ ریچاب سٕندِس نیچوِس جوناداب سٕندِس نیچویو چُھ پننِس مٲلہِ سُند حُکُم پوٗرٕ کوٚرمُت، یُس تِمن حُکُم اوس دِتمُت۔ مگر یِمو لوٗکو چُھنہٕ مے بوزمُت:\n17. تێمہِ کِنۍ چُھ یِتھٕ پٲٹھـ̡ لشکرن ہُند خدا، یُس اسرٲیلُک خدا چُھہ ونان ۔ وُچھِو بہٕ یہوداہ تہٕ یروشلم کین سارنٕے بسکیٖنن پیٹھ سُہ سُہ بُراے یُس میہ تِمن خلاف اعلان کورمُت چُھ، کیازِ مے چُھ تِمن سٍتـ̡ کتھ کٔرمٕژ، مگر تِمو چُھنہٕ بوزمُت۔ تہٕ مے چُھس تِمن بُلاونہٕ آمُت، مگر تِمو دِژ نہٕ جواب۔\n18. تہٕ یرمیاہ ہن ووٚن رِکیبِس کِس گرس سٍتـ̡ یِتھٕ پٲٹھـ̡ چُھہ لشکرن ہُند خدا، یُس اسرٲیلُک خدا چُھہ ونان چُھ۔ تکیازِ ژے چھُکھ پننِس مٲلہِ جوناداب سٕندِس حُکمس تعمیل کورمُت، تہٕ تٔمۍ سٕندِس سارِنٕے حکمس مُطٲبِق کٔرِکھ تٔمۍ سٕندِس حُکمس مُطٲبِق۔\n19. تێمہِ کِنۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھ، یێلہِ چُھ یِتھٕ پٲٹھۍ فرماوان۔ ریچاب سُند نیچو جوناداب گژھہِ نہٕ یژھان زِ کانہہ انسان گژھہِ میہ برونہہ کنہِ ہمیشہٕ خٲطرٕ کھڑا روزُن۔ {جونادب...: ہیب۔ رِچاب سٕندِس نیچوِس جوناداب نِش گژھِ نہٕ کانہہ نفر ژٹنہٕ یُن، بیترِ}","1. تہٕ یہِ سپُد یہوداہ کِس بادشاہ یوسیاہ سٕندِس نیچوِس ژوٗرمِس ؤریس مَنٛز، یہِ لفظ آو یرمیاہ سٕندِ طرفہٕ یِتھ وَنُن،\n2.\\tژے نِو کِتابہِ ہُند اکھ رول، تہٕ اَتھ مَنٛز لیکھِو تِم سٲری لفظ یِم مے ژے اسرٲیلِس خٕلاف، یہوداہَس خٕلاف تہٕ سارنٕے قومن خٕلاف کتھ کٔرمٕژ چھِ، ییمہِ دۅہہٕ پیٹھٕ مے ژے سٍتـ̡ کتھ کٔرمٕژ چھِ، یُس میہ ژے سٍتـ̡ کتھ کٔرمٕژ چھِ، یێمہِ دۅہہٕ پیٹھٕ یُس میہ ژے سٍتـ̡ کتھ کٔرمٕژ چھِ، یێمہِ دۅہہٕ پیٹھٕ یُس میہ ژے سٍتـ̡ کتھ کٔرمٕ\n3. یہِ ہیکہِ ٲسِتھ زِ یہوداہُک گرٕ بوزِ سٲرِی بُرٲے یُس بہٕ تِمن سٍتـ̡ کرُن چُھس یژھان چھُ۔ تاکہ تِم کرِ پرٮ۪تھ أکِس انسانس تٔمۍ سٕنزِ بد وتہِ نِش واپس۔ تاکہ بہٕ ہیٛکہٕ تِہٕنٛز بدکٲری تہٕ تِہُند گناہ معاف۔\n4.\\tیێمہِ پَتہٕ وُن یرمیاہ سُند نیچو باروخ تہٕ باروخن لیکھِن یِم خداوند سٕندِ سٍتـ̡ تٔمِس سٍتـ̡ کتھ کٔرمٕژ ٲس، یِم أمِس سٍتـ̡ کتھ کٔرۍمٕتۍ۔\n5.\\tتہٕ یرمیاہ ہن دیُت باروخُک حُکُم، وونُن زِ بہٕ چُھس ژھۄپہٕ کٔرِتھ۔ بہٕ ہیٛکہٕ نہٕ خداوند سٕندِس گرس مَنٛز گژھِتھ:\n6. تێمہِ کِنۍ پٔرِو تہٕ پٔرِو رِلس مَنٛز، یُس ژے میانہِ مَنٛز لیوکھمُت چُھ، روزٕ کہِ دۅہہٕ خداوند سٕندِس گرس مَنٛز لُکن ہٕندِس کنن مَنٛز پٔرِو۔ تہٕ تہٕ پٔرِو تِم سارِنٕے یہوداہ سٕندِس کنن مَنٛز یُس تِہندیو شہرو منزٕ نیران چُھ۔\n7.\\tیہ ہیکہِ ٲسِتھ زِ تِم گژھن پنٕنۍ دُعا خداوند سٕندِ برونہہ کُن پیش تہٕ پرٮ۪تھ أکِس بد وتہِ نِش واپس: یُس غصہٕ تہٕ غصہٕ خداوند یِمن لُکن ہُند اعلان کورمُت چھُ۔ {تِم...: ہیب۔ تہنز دعا گژھہِ ناکام}\n8. تہٕ نیریاہ سٕندِ نیچو باروخ کٔر یِمن سارِنٕے مُطٲبق یُس یرمیاہ پیغمبرن أمس حکم دِژمُت اوس، کتابہِ مَنٛز پٔرِتھ خداوند سٕندِس گرس مَنٛز۔\n9. تہٕ یہِ سپُد یہوداہ کِس بادشاہ یوسیاہ سٕندِس نیچوِس یہوویاقیم سٕندِس پٲنژمِس ؤریس مَنٛز، نٔوِمِس رٮ۪تس مَنٛز، یِمو کٔر یِمو یروشلمس مَنٛز سارنٕے لُکن تہٕ یہوداہ کِس شہرو پیٹھٕ یِنہٕ وٲلِس سارِنٕے لُکن خٲطرٕ خداوند سٕندِ برونہہ کُن روزُک اعلان ۔\n10.\\tپٔرِو باروخ کتابہِ مَنٛز یرمیاہ سٕندِ کلام، یُس شافان سُند نیچو جماریاہ سٕندِس کمرس منز، اعلیٰ دربارس مَنٛز، خداوند سٕندِس گرٕ کِس نٔوِس دروازس مَنٛز، سارِنٕے لُکن ہٕندِس کنن مَنٛز۔ {اندراج: یا، دروازٕ}\n11.\\tییلہ شافان سٕندِ نیچو جماریاہ سٕندِ نیچو میکائیاہَن کِتابہٕ منزٕ خداوند سٕندِ تمام کلام بوزمٕتۍ،\n12.\\tتمہ پتہ ووت سُہ بادشاہ سٕندِس گرس منز، کاتب سٕندِس کمرس منز، تہٕ سارِنٕے شہزادٕ بِہتھ اَتہِ بِہِتھ، حتیٰ کہِ الیشامہ کاتب تہٕ شمعیاہ سُند نیچو دلیاہ تہٕ اچبور سُند نیچو ایلناتھن تہٕ شافان سُند نیچو جماریاہ تہٕ حنانیاہ سُند نیچو زدیقیاہ تہٕ سارِنٕے شہزادن ہٕندِس سٍتـ̡ بِہتھ ۔\n13. اَمہِ پتہٕ کٔر میکائیاہن تِمن سارِنٕے کَلام یِم تٔمۍ بوزمٕتۍ ٲسۍ، ییٚلہِ باروخن لُکن ہٕندِس کنن منز کتاب پٔرِتھ۔\n14.\\tلہذا سوٗز سارِوٕے شہزادو نیتھنیا سُند نیچو، شیلمیاہ سُند نیچو، کوشی سُند نیچو، باروخس نِش وونُن زِ سُہ رول رٔٹِو پننِس اتھس منز یُس ژے لُکن ہٕندِس کنن منز پٔرِتھ پٔرِتھ چھُ۔ چنانچہ نیریاہ سٕندِ نیچو باروخن رٔٹ رول پننِس اتھس منز، تہٕ آو تِمن نِش۔\n15.\\tتہٕ تِمو ووٚن أمِس بِہتھ تہٕ پٔرِو سانٮ۪ن کنن منز۔ چنانچہ باروخن پٔر تہندین کنن منز۔\n16.\\tوۅنۍ سپد ییلہ تِمو سٲری لفظ بوزۍ، تِم گٔیہِ اَکہِ أکِس تہٕ بییِس کھوژان، تہٕ وونُن باروخس زِ أسۍ وَننہٕ یِم سارِنٕے لفظ۔\n17.\\tتہٕ تِمو پرژھ باروچ، وَنُن زِ وَنُن زِ ژے کِتھہ کٔنۍ لیکھۍ یِم سٲری لفظ أمِس ٲسِس پیٹھ؟\n18.\\tاَمہ پتہٕ دِژ باروخن تِمن جواب، تٔمۍ کٔر یِم سٲری لفظ میانہِ خٲطرٕ پننہِ ٲسس سٍتۍ، تہٕ مے لیوکھ کتابہِ منز سیاہی سٍتـ̡ ۔\n19.\\tاَمہِ پتہٕ ووٚن شہزادو باروچ، ژے تہٕ یرمیاہ ژٔرِتھ ژٔرِو۔ تہٕ کٲنسہِ تہِ گژھہِ نہ خبر زِ تہۍ کتہِ چھِو۔\n20.\\tتہٕ تِم گٔیہِ بادشاہس نِش دربارس منز، مگر تِمو تھووُکھ اِلِشاما سٕندِس کمرس مَنٛز رول تہٕ وَنُن بادشاہ سٕندِس کنن منز سٲری لفظ۔\n21. چنانچہ بادشاہن سوُز یہودی رول اننہٕ خٲطرٕ، تہٕ تٔمۍ کٔر یہِ کاتب سٕندِ کمرہٕ منزٕ نٮ۪بر۔ تہٕ یہودی ین پٔر یہِ بادشاہ سٕندِس کنن منز، تہٕ بادشاہس سٍتۍ کھڑا سارِنٕے شہزادن ہٕندِس کنن منز۔\n22.\\tوُن بِہتھ بادشاہ بِہتھ نٔوِمہِ رٮ۪تس منز وندٕ خانس منز: تہٕ {أمِس برونہہ کُن دزان چُھس نار}۔\n23.\\tتہ سپد یہ سپد {یہ} ییلہ یہودی ین تریہ ژور پنہٕ پٔرۍ، تمٔۍ ژٔٹِتھ ژٔٹِتھ ژٔٹِتھ نارس منز یُس {اوس} نارس پیٹھ، یوٚت تام سورے رول نارس منز دزِتھ یُس {اوس} نارس پیٹھ۔\n24.\\tتوتہِ گٔیہِ نہٕ تِم کھوژمٕتۍ، تہٕ نہ کٔرِکھ بادشاہس تہٕ نہ تٔمۍ سٕندِس خادمَس یِم یِم سارِنٕے کَلام بوزۍ۔\n25. توتہِ اوس ایلناتھن تہٕ دلیاہ تہٕ جماریاہ بادشاہس کٔرِتھ شفاعت کٔرمٕژ زِ سُہ کرِ نہٕ رول زٲلِتھ، مگر سُہ بوزِ نہٕ تِمن ہٕندِ۔\n26. مگر بادشاہن دِیُت حُکُم زِ یِم کٔرِن باروخ کاتب تہٕ یرمیاہ پیغمبر نِنُک حُکُم۔ {ہملیخ: یا، بادشاہ سُند}\n27.\\tپتہٕ آو خداوند سُند کلام یرمیاہ ہس نِش، تمہ پتہٕ اوس بادشاہن رول زٲلمُت، تہٕ تِم لفظ یِم باروخن یرمیاہ سٕندِس ٲسِس پیٹھ لیوٚکھمٕتۍ،\n28.\\tبییہِ رٔٹِتھ رٔٹِتھ لیٚکھِو تِم سٲری لفظ یِم گۄڈنِکِس رولس مَنٛز ٲسۍ، یُس یہوداہُک بادشاہ یہودیاہن زٲلمُت چھُ۔\n29.\\tتہٕ یێلہِ چُھہ یہوداہ کِس بادشاہ یہوہیکیمس وَنُن، یِتھٕ پٲٹھـ̡ خداوند چُھ فرماوان۔ ژے چھُکھ یہِ رول زٲلِتھ ونان زِ ژے کیازِ چُھکھ اتھ منز لیکھمُت، بابل ہُند بادشاہ ییہ یٔژ یِتھ زمینس تباہ کٔرِتھ، تہٕ اَمہ سٍتـ̡ کرِ انسان تہٕ درندٕ رُکاونہٕ۔\n30. تێمہِ کِنۍ چُھ یہوداہُک بادشاہ یہوویاقیم ہُند رب وَنان۔ أمِس آسہِ نہٕ داؤد سٕندِس تختس پیٹھ بِہنہٕ خٲطرٕ کانٛہہ تہِ: تہٕ تٔمۍ سُند لاش یِیہِ دۅہلہِ گرمی مَنٛز تہٕ رٲژ یِیہِ تٔرِتھ دِنہٕ۔\n31. تہٕ بہٕ دِیہٕ أمِس تہٕ تٔمۍ سٕندِس اولادس تہٕ تٔمۍ سٕندٮ۪ن خدمتگارن تِہٕندِ بدکٲری ہُند سزا۔ تہٕ بہٕ اَننہٕ تِمن تہٕ یروشلم کین بسکینن تہٕ یہوداہ کِس انسانس پیٹھ، سُہ سُہ بُراے یُس میہ تِمن خلاف اعلان کورمُت چھُ۔ مگر تِمو بوز نہٕ۔ {سزا: حب۔ وزِٹ کٔرِو}\n32.\\tتێلہِ رٔٹِتھ نِریاہ سٕندِس نیچوِس کاتب باروخس دِنہٕ۔ یمۍ اتھ منز یرمیاہ سٕندِ زبانہِ سٍتـ̡ لیوکھمٕژ کتابہِ ہٕندۍ سٲری لفظ یُس یہوداہ کِس بادشاہ یہوداہُک بادشاہ نارس مَنٛز زٲلمُت اوس، تہٕ یِمن علاوٕ آیہ واریاہ ہِش لفظ شٲمل کرنہٕ۔ {یتھہ پاٹھۍ: ہیب۔ یتھ کٔنۍ تِم}","1. تہٕ یوسیاہ سُند نیچو بادشاہ صدقیاہ کٔر یہویاکیم سٕندِس نیچوِس کونیاہ سٕندِ بدلہٕ حکومت، یُس بابل کِس بادشاہ نبوکدرِزارن یہوداہ کِس سرزمینس مَنٛز بادشاہ بنوو۔\n2. مگر نہ تٔمۍ سٕندِس خادمَو تہٕ نہ زمینہٕ کِس لوکو بوز خداوند سٕندِ کلام، یُس تٔمۍ یرمیاہ پیغمبرن کٔرِمُت اوس۔ {by...: ہیب۔ رسول اللہ صلی اللہ علیہ وآلہ وسلم سٕندِ اتھہٕ سٍتۍ}\n3.\\tتہٕ سُہ بادشاہ سوٗز شلیمیاہ سُند نیچو یہوکال تہٕ پادٕرۍ ماسیاہ سُند نیچو زفانیاہ پیغمبر یرمیاہ نِش تہٕ وونُن زِ وۅنۍ کٔرِو سانہِ خٲطرٕ سٲنِس خداہس نِش دُعا۔\n4.\\tوُنہِ آو یرمیاہ اژان تہٕ لُکن منزٕ نٮ۪بر، تِکیازِ تِمو اوس نہٕ سُہ قٲد خانس مَنٛز ترٛٲومُت۔\n5. تمہ پتہ آو فرعون سُند فوج مصرہٕ منزٕ نیبر، تہٕ ییلہ یروشلمس محاصرٕ کرن والیو کلدانیو تِہنز خبر بوٗز، تِم دراو یروشلم پیٹھٕ۔\n6. اَمہِ پَتہٕ آو خداوند سُند کلام یِمیاہ پیغمبرس نِش وَننہٕ،\n7. یِتھٕ پٲٹھـ̡ چُھ خداوند اسرٲیلُک خدا فرماوان۔ یِتھٕ پٲٹھۍ کٔرِو ژٕ یہوداہ کِس بادشاہس وَنُن، یٔمۍ ژےٚ مےٚ نِش پرژھہٕ گٲر کرنہٕ خٲطرٕ سوزمُت چھُ۔ وچھ فرعون سُند لشکر یُس تۅہہِ مدتھ کرنہٕ خٲطرٕ برونہہ کُن آو، سُہ گژھہِ پننِس سرزمینس منز واپس مصر۔\n8. تہٕ چالڈین یِن دُبارٕ یِن، تہٕ اتھ شہرس خلاف لڑان، تہٕ اتھ پیٹھ قبضہٕ کرُن، تہٕ نارٕ سٍتـ̡ زالنہٕ۔\n9. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ پانس مہٕ دھوکہٕ دِتھ یہ ؤنِتھ زِ چالدانی گژھن یٔقیٖنی طور اسہِ نِش نیرن: تِکیازِ تِم گژھن نہٕ نیرن۔ {تم پانے: ہیب۔ تُہند روح}\n10.\\tیێلہِ ژے ژے پانس خلاف لڑن وٲلِس کلدانن ہُند سورُے لشکر مارمُت، تہٕ تِمن مَنٛز ٲسۍ زخمی نفر باقی، {توتہِ} گژھن تِم پرٮ۪تھ أکِس خیمہٕ سٍتـ̡ تھوٚد تہٕ یِمن شہرس نارٕ سٍتـ̡ زٲلِن۔ {زخمی: ہیب۔ تھرو تھرو تھرو}\n11.\\tتہٕ سپُد یہِ زِ ییلہ فرعون سٕندِ فوجہٕ کہِ خوفہٕ کِنۍ یروشلم پیٹھٕ کلدانن ہُند لشکر پھُٹاونہٕ آو، {پھُٹُن...: ہیب۔ کھسنہٕ خٲطرٕ بناونہٕ آمُت}\n12. یورمیاہ دراو یروشلم پیٹھٕ بنیامین سٕندِس سرزمینس مَنٛز گژھنہٕ خٲطرٕ، تتہِ نِش لُکن منز پان الگ کرنہٕ خٲطرٕ۔ {الگ کرُن...: یا، لوکن منز تتہِ نِش ژلُن}\n13.\\tتہٕ ییلہ سُہ بنیامین سٕندِس دروازس مَنٛز اوس، یُس وارڈُک اکھ کپتان اوس، یُس حنانیاہ سُند نیچو شیلمیاہ سُند نیچو اوس اِریجاہ۔ تہٕ تٔمۍ نیو یرمیاہ پیغمبر، یہِ وونُن زِ تہٕ ژے چُھکھ کلدانن نِش گٔژھان۔\n14.\\tاَمہِ پتہٕ ووٚن یرمیاہ {یہِ} چھُ اپُز۔ بہٕ چُھس نہٕ چالڈین نِش دور۔ مگر تٔمۍ بوز نہٕ أمِس کُن، تہٕ اِریجاہَن نیو یرمیاہ تہٕ أنِن سُہ شہزادن نِش۔ {غلط: ہیب۔ اپُز، یا، اپُز}\n15. اَمہِ مۄکھٕ گٔیہِ شہزادو یرمیاہ سٍتـ̡ شرارت، تہٕ دِتُکھ أمِس لَٹہٕ تہٕ تھووُکھ سُہ یوناتھن کاتب سٕندِس گَرَس مَنٛز قٲد خانہٕ، تِکیازِ تِمو اوس یہِ قٲد خانہٕ بنوومُت۔\n16.\\tییلہ یرمیاہ تہٕ کیبنَس مَنٛز دٲخل گومُت، تہٕ یرمیاہ اوس واریاہن دۅہن اَتہِ روٗدمُت۔ {کیبن: یا، سیلہٕ}\n17.\\tاَمہِ پَتہٕ سُہ نِش نِش نیرُن، تہٕ بادشاہن پُرٛژھ أمِس پَنٕنِس گَرَس مَنٛز ژوٗرِ پٲٹھۍ، تہٕ وونُن، کیا چُھہ خداوند سٕندِ طرفہٕ کانہہ کَتھ ؟ تہٕ یرمیاہ ہن ووٚن، تِکیازِ تٔمۍ ووٚن زِ تُہۍ یِیہِ بابل کِس بادشاہ سٕندِس اتھس مَنٛز دِنہٕ۔\n18.\\tیرمیاہ ہن ووٚن بادشاہ صدقیاہ ہس زِ میہ کیا چُھہ ژے سٍتـ̡ یا تہندین خدمتگارن سٍتـ̡ یا یِمن لوکن سٍتـ̡ کیا چُھہ میہ قٲد کورمُت؟\n19.\\tکتہِ چھہِ تۅہہِ پیغمبرن یِمو تۅہہِ نِش پیشن گویی کٔرمٕژ چھِ، بابل ہُند بادشاہ گژھِ نہٕ تۅہہِ خلاف تہٕ نہ یتھ زمینس خلاف۔\n20. تێلہِ بوزو وۅنۍ بہٕ ژے دُعا کٔرِتھ، اے میانہِ آقا بادشاہ: میون دُعا گژھہِ ژے برونہہ کُن قبول۔ زِ ژے کٔرِو نہٕ مےٚ یوناتھن کاتب سٕندِس گرس منز واپس، نتہٕ بہٕ مرٕ تتہِ۔ {let...: Heb. میٲنۍ دُعا گٔژھ پٮ۪وان}\n21. پتہٕ دِیُت بادشاہ صدقیاہ ہُند حُکُم زِ تِم گژھن یرمیاہ قٲد خانس مَنٛز دِنہٕ، تہٕ تِم گژھن أمِس روزانہٕ بیکرَن ہٕنزِ سڑکہِ منزٕ اکھ روٹی دِنہٕ، یوتام نہٕ شہرُک سورُے روٹی ختم سپدِ۔ یِتھٕ پٲٹھۍ روٗد یرمیاہ جیل کِس دربارس منٛز۔","1. اَمہِ پَتہٕ بوٗز مَطان سُند نیچو شیفطیا تہٕ پاشُور سُند نیچو تہٕ شیلمیاہ سُند نیچو جوکل تہٕ ملکیا سُند نیچو پاشور بوز تِم لفظ یِم یرمیاہ سارِنٕے لُکن سٍتـ̡ کٔرۍمٕتۍ،\n2. یِتھٕ پٲٹھـ̡ چُھ خداوند ونان زِ یُس اتھ شہرس مَنٛز روزِ، سُہ گژھہِ تلوار سٍتـ̡ تہٕ وباہٕ سٍتـ̡ مَرُن، مگر یُس چالدانن نِش نیرِ، سُہ گژھہِ زندٕ۔ تکیازِ تس آسہِ شکارس خٲطرٕ پنٕنۍ جان تہٕ زندٕ۔\n3. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان زِ یہِ شہر یِیہِ یقینا بابل کِس بادشاہ سٕندِس لشکرس اتھس مَنٛز دِنہٕ، یُس اتھ نِنہٕ ییہِ۔\n4. تَمہِ کِنۍ ووٚن شہزادو بادشاہس زِ أسۍ چھِ ژےٚ التجا کران، یہِ نفر گژھِ مارنہٕ یُن، تِکیازِ یِتھ پٲٹھۍ چُھ سُہ یِمن شہرس مَنٛز روزن وٲلِس جنگی نفرن ہٕندِ اتھہٕ کمزور کران، تہٕ سارنٕے لُکن ہٕندِس اتھہٕ سٍتـ̡ یِمن سٍتـ̡ یِتھٕ کتھ کٔرِتھ، کیازِ یہِ شخٕص چُھنہٕ یِمن ہٕندِس لُکن ہٕنز فلاح و بہبودٕ ژھاران۔  مگر تکلیف دِنہٕ۔ {ویلفیئر: ہیب۔ امن}\n5.\\tاَمہِ پَتہٕ ووٚن زِ سُہ چُھہ تُہٕندِس اتھس مَنٛز، کیازِ بادشاہ {چُھ} چُھہ نہٕ تۅہہِ خلاف کانہہ تہِ کٔرِتھ۔\n6.\\tتِمو رٔٹِتھ رٔٹِتھ دِژُکھ یِرمیاہ سٕندِس نیچوِس ہملیاہ سٕندِس تہٕ یُس قٲد خانس مَنٛز اوس، تہٕ یِمو ترٛٲوِکھ یرمیاہ رَزِ سٍتـ̡ ۔ تہٕ تہٕ کوٹھس منز اوس نہٕ آب مگر مَلہٕ، یِتھے پٲٹھۍ ژوٚٹ یرمیاہ گٔیہِ دلدَس مَنٛز۔ {ہملیخ: یا، بادشاہ سُند}\n7.\\tوۅنۍ ییلہ ایبیڈمیلک ایتھوپیا یُس بادشاہ سٕندِس گرس منز اوس، بوز زِ یِمو چُھ یرمیاہ تہِ کوٹھس مَنٛز ترٛٲومُت۔ بادشاہ اوس تمہ پتہٕ بینجمن سٕندِس دروازس پیٹھ بِہتھ۔\n8.\\tابیڈمیلک دراو بادشاہ سٕندِ گرٕ منزہ نیبر، تہٕ وونُن بادشاہس سٍتـ̡ کتھ کرنہٕ،\n9.\\tمیانہِ آقا بادشاہ، یِمو نفرو چھُ یرمیاہ پیغمبرس سٍتـ̡ یُس تہٕ یِمو تہٕ یِمو کوٹھس مَنٛز دِنہٕ آمُت چھُ، یُس تِمو تہٕ دِژمُت چھُ۔ تہٕ سُہ چُھ تتھ جایہِ فاقہٕ کِنۍ مرُن ہیوٗ یُس سُہ چُھ: کیازِ شہرس منز چُھنہٕ وۅنۍ کانہہ روٹی آسان۔ {سہ چھہ یتھہ پاٹھۍ...: ہیب۔ سہ گژھہِ مرُن}\n10. پتہٕ دِیُت بادشاہن ایبیڈمیلک حُکُم تہٕ وونُن زِ اَتہِ نِیو پانس سٍتـ̡ ترٕہ نفر تہٕ یرمیاہ پیغمبر تُلُن تہٕ تُلُن مرنہٕ برونہہ، تہٕ تُلُن یرمیاہ پیغمبر۔ {توے سٍتۍ: ہیب۔ تۅہہِ اتھس منز}\n11.\\tیێمہِ سٍتـ̡ نِیوُن ابیدمیلک نفر پانس سٍتـ̡ تہٕ ژاو خزانہٕ تل بادشاہ سٕندِس گرس منز، تہٕ تتہِ نِن پرانہِ کاسٹ کٔرِتھ تہٕ پرانہِ گٔژِھتھ لٔگِتھ تہٕ ترٲوٕن رَزِ سٍتـ̡ یرمیاہ کِس کوٹھس منز۔\n12.\\tتہٕ ایبڈمیلک ووٚن یرمیاہ ہس زِ وۅنۍ تھٲوِو یِم پرانہِ کٔرِتھ تہٕ گٔژِھتھ لٔگِتھ رَزِ تَل ۔ تہٕ یرمیاہ کٔر یہِ ۔\n13.\\tیێمہِ کٔر یِمو یرمیاہ رَزِ سٍتـ̡ تہٕ نِیوُن سُہ تہٕ یٔرمیاہ روٗد قٲد خانہٕ کِس دربارس مَنٛز۔\n14. پتہٕ سُہ سُہ بادشاہ سُوُز، تہٕ نِیوُن یرمیاہ پیغمبر پانس نِش تریمہِ دَرِ مَنٛز یُس خداوند سٕندِس گرس مَنٛز چُھ، تہٕ بادشاہن ووٚن یرمیاہ ہس زِ بہٕ کرٕ ژے اکھ کتھ پرژھہٕ۔ میہ نِش تھاو نہ کانہہ تہِ۔ {تریم : یا، پرنسپل}\n15.\\tیێلہِ ووٚن یرمیاہ یێلہِ ژے سٍتـ̡ یہ اعلان کرُن، کیا ژٕ کٔرِکھ نہٕ میہ مٲرِتھ؟ تہٕ اگر بہٕ ژےٚ مشورٕ دِیہ، کیا ژٕ کٔرٕ نہٕ میانہِ کتھ بوزنہٕ؟\n16. یێلہِ چُھہ زِدقیاہ بادشاہ ژوٗرِ پٲٹھـ̡ یرمیاہ ہس سٍتـ̡ قسم، یێلہِ چُھہ خداوند زندٕ چُھ، یێمہِ سٍتـ̡ اسہِ یہِ روح بنوو، بہٕ دِیہ نہٕ ژے تِمن نفرن ہٕندِس اتھس مَنٛز یِم تُہٕندِس زُو ژھارناوان چھِ۔\n17.\\tیێلہِ وۆن یرمیاہ سٍتـ̡ یێلہِ سٍتـ̡ یێلہِ سٍتـ̡ خداوند سُند خدا، یُس اسرٲیلُک خدا چُھ، یێلہِ چُھہ فرماوُن۔ یێلہِ ژٕ یٔقیٖنی پٲٹھـ̡ بابل کِس بادشاہس نِش نیرِو، تیلہِ گژھہِ تُہند روح زندٕ، تہٕ یہِ شہر گژھہِ نہٕ نارٕ سٍتـ̡ زالنہٕ۔ تہٕ تُہۍ روزِو زندٕ، تہٕ پنُن گر:\n18.\\tمگر اگر نہٕ ژیہ بابل کِس بادشاہس نِش نیرِو، تیلہِ یِیہِ یہِ شہر چالدانن ہٕندِس اتھس منز دِنہٕ، تہٕ تِم زٲلِن یہِ نارٕ سٍتـ̡ تہٕ ژٔلِتھ ژٔلِتھ تہٕ ژٔلِتھ تہٕ ژٔلِتھ تہٕ ژٔلِ\n19.\\tتہٕ زدیقیاہ بادشاہن ووٚن یرمیاہ ہس زِ بہٕ چُھس یہودین سٍتـ̡ کھوژان یِم کلدانس نِش پۯاونہٕ آمٕتۍ، نتہٕ تِم گژھن میہ پننِس اتھس مَنٛز دِنہٕ، تہٕ تِم چھِ میہ ٹھٹھہٕ کران۔\n20. مگر یرمیاہ ہن ووٚن زِ تِم کرِ نہٕ تۅہہِ دِنہٕ۔ اطاعت کٔرِو، بہٕ چُھس ژے خدایہِ سٕنز آواز، یُس بہٕ ژے سٍتـ̡ کتھ کران چُھس، یێلہِ چُھہ تۅہہِ سٍتـ̡ خیر تہٕ تُہند روح روزِ زندٕ۔\n21. مگر یێلہِ ژے نیرنس انکار کٔرِو، یہِ چُھ سُہ لفظ یُس خداوند میہ ہٲومُت چُھ:\n22. تہٕ وُچھِو، یِم سارِنٕے زنانہٕ یِم یہوداہ کِس بادشاہ سٕندِس گرس مَنٛز باقٕے روزان چھِ، یِم یِن بابل کِس بادشاہس نِش اننہٕ، تہٕ تِم زنانہٕ ونن زِ تۅہہِ ہٕندِس یارو چُھکھ ژےٚ رٔٹِتھ تہٕ چُھکھ تۅہہِ پیٹھ فتح حٲصل کٔرمٕژ، تہٕ تۅہہِ ہٕندِس کھۅر گٔیہِ دلدَس مَنٛز، تہٕ تِم چھِ واپس پھیرنہٕ آمٕتۍ۔ {تہند دوس: ہیب۔ تیری امن ہٕندۍ مرد}\n23. یێلہِ کٔرِن تِم تُہٕنزِ سارِنٕے زنانہٕ تہٕ شُرِ کَلدانَن نِش نِن، تہٕ تُہۍ ژٔلِو نہٕ تِہٕندِ اتھہٕ نِش نِش، بٔلکہِ یِیہِ بابل کِس بادشاہ سٕندِ اتھہٕ سٍتـ̡ نِنہٕ۔ {تۅہہ کرو کیز...: ہیب۔ ژے دزُن وغیرہ}\n24. اَمہِ پتہٕ ووٚن زِدقیاہ یرمیاہ سٍتـ̡ یِمن کلامَن ہٕنز خبر تہٕ تُہہِ گژھِ نہٕ مَرُن۔\n25.\\tمگر اگر شہزادن یہ بوزان زِ میہ چھیہ ژےٚ سٍتۍ کتھ کٔرمٕژ، تہٕ تِم یِن تہٕ تۅہہِ نِش یِن تہٕ وَنُن زِ ژے بادشاہس کیا چُھکھ ووٚنمُت، اسہِ نِش گژھ نہٕ ژےٚ ژےٚ مارنہٕ۔ بادشاہن کیا ووٚن ژےٚ:\n26. تیلہٕ کٔرِو تِمن وَنُن، مے کٔر بادشاہس برونہہ کُن پنٕنۍ دُعا پیش، زِ سُہ کرِ نہٕ بہٕ جوناتھن سٕندِس گرس واپس، تتہِ مرنہٕ خٲطرٕ۔\n27.\\tپتہٕ آیہِ سارِنٕے شہزادٕ یرمیاہ نِش تہٕ پرژھکھ أمِس تہٕ تٔمۍ ووٚن تِمن سارِنٕے لفظو مُطٲبِق یِم بادشاہن حُکُم دِژمٕتۍ۔ چنانچہ تمو تروو أمس سۭتۍ کتھ کرنہٕ۔ تکیازِ یہ معاملہ آو نہٕ سمجھنہٕ۔ {تِم...: ہیب۔ تِم ٲسۍ أمِس نِش ژھۄپہٕ}\n28. یێمہِ دۅہہٕ یێلہِ یروشلم آو نِنہٕ یێلہِ سُہ اوس جیلہٕ کِس دربارس مَنٛز روزان، تہٕ سُہ اوس یێلہِ یروشلیم نِنہٕ آمُت۔","1. یہوداہ کِس بادشاہ زدقیاہ سٕندِس نٔوِمِس ؤریس مَنٛز، دٔہمہِ رٮ۪تس مَنٛز، آو بابلُک بادشاہ نبوکدرِزر تہٕ تٔمۍ سُند سورُے لشکر یروشلمس خلاف تہٕ تِمو کوٚر اتھ محاصرٕ۔\n2. {تہ} صدیقیاہ کِس کٔہمہِ ؤریس منز، ژوٗرمہِ ریتس منز، ریتہٕ کِس نٔوِمِس دۅہس مَنٛز، آو شہر پھُٹراونہٕ۔\n3.\\tتہٕ بابل کِس بادشاہ سٕندِ سٲری شہزادٕ آیہِ اژنہٕ، تہٕ بیوٹھ منزمِس دروازس منز، نیرگلشیرزر، سمگارنیبو، سرسیخم، ربساریس، نرگلشارزر، ربماگ، بابل کِس بادشاہ سٕندِس شہزادن ہٕندِس سارِنٕے باقیاتس سٍتۍ۔\n4.\\tتہٕ سپُد یہِ سپُد، یێلہِ یہوداہ کِس بادشاہ زدقیاہ ہن تِم تہٕ سارِنٕے جنگی نفر وُچھ، تِم ژٔلِتھ ژٔلِتھ رٲژ شہرٕ نیبر، بادشاہ سٕندِ باغہٕ کِس وتہِ کِنۍ، دۄن دیوارن درمیان دروازٕ کِنۍ، تہٕ سُہ دراو میدانہٕ کِس وتہِ نِش۔\n5.\\tمگر کلدان سُند لشکر لوٚگ تِمن پَتہٕ تہٕ یریحو کِس مٲدانس مَنٛز کوٚرُن سُہ سُہ بابل کِس بادشاہ نبوکدنضرس نِش حَماتھ کِس سرزمینس مَنٛز ربلہ کِس نِش۔ {دِیُت...: ہیب۔ تمس سٍتۍ کٔر فیصلہٕ}\n6.\\tبابل کِس بادشاہن مٲرِتھ ربلاہس مَنٛز زدیقیاہ سٕندِ نیچوۍ تہٕ مٲرِتھ تہٕ بابل کِس بادشاہن تہِ مٲرِتھ یہوداہ کِس سارِنٕے رئیس۔\n7. امہِ علاوٕ کٔرِن تٔمۍ صدقیاہ سٕنزِ أچھ تہٕ زنجیر لٲگِتھ بٔنِتھ بابل نِنہٕ مۅکھہٕ۔ {with...: Heb. زٕ بریسن زنجیرٕ سۭتۍ، یا، زنجیر}\n8. تہٕ چالدینو زٲلۍ بادشاہ سُند گرٕ تہٕ لُکن ہٕندِس مکانس نارٕ سٍتۍ، تہٕ یروشلمٕچ دیوار پھُٹرٲوِتھ ۔\n9.\\tپتہٕ نِبوزارادنن نِیوُن رٲچھ کَرن والٮ۪ن ہٕندِس باقٕے لُکن ہُند باقٕے باقٕے لُکن ہُند باقٕے باقٕے لُکن سٍتـ̡ بابل کُن قٲد کرنہٕ۔ {کپتان...: یا، چیف مارشل: ہیب۔ چیف آف جلاد، یا، ذبح}\n10.\\tمگر نبوزاردانن تروو یہوداہ کِس سرزمینس مَنٛز غریبن ہٕندِس غریبس منز، یُس نہٕ کانہہ تہِ اوس، تہٕ دِتُن تِمن اکی ساتہٕ انگور تہٕ کھہٕ۔ {کپتان...: یا، چیف مارشل: ہیب۔ چیف آف دی جلاد، یا، ذبح} {at the...: Heb. تمہ دۅہہ}\n11.\\tوُن بابل کِس بادشاہ نبوکدرِزرن دِژ یرمیاہ سٕندِس بارس مُتلِق رٲچھ کَرن وٲلِس کپتان، نبوزارادنس نِش وونُن، {to: Heb. {کپتان...: یا، چیف مارشل: ہیب۔ چیف آف جلاد، یا، ذبح}\n12. أمِس رٔٹِتھ تہٕ أمِس کُن رٔٹِتھ تہٕ أمِس کٔرِو نہٕ کانٛہہ تہِ نقصان ۔ مگر أمِس کٔرِو تِتھۍ پٲٹھۍ یُتھ سُہ ژےٚ وَنُن۔ {وچھو...: ہیب۔ أمِس کُن کٔرِو نظر تھاوُن}\n13.\\tیێلہِ سوٗزُن گارڈُک کپتان، تہٕ نیبوشاسبان، ربسارِس تہٕ نیرگلشیرزر، ربماگ تہٕ بابل کِس سارِنٕے بادشاہ سوٗز۔ {کپتان...: یا، چیف مارشل: ہیب۔ چیف آف جلاد، یا، ذبح}\n14.\\tتِمو تہِ سوٗزِتھ تہٕ نِیُکھ یرمیاہ قٲد خانہٕ منزٕ نیبر، تہٕ کوٚرُکھ سُہ شافان سُند نیچو اہیکم سُند نیچو گیڈالیاہَس حوالہٕ، یُتھ سُہ گَرٕ نِنہٕ یُن، یِتھٕ پٲٹھۍ روٗد سُہ لُکن مَنٛز روزان۔\n15.\\tیێلہِ ووت خداوند سُند کلام یرمیاہ ہس نِش، ییلہ سُہ قٲد خانس مَنٛز بند اوس، وونُن،\n16.\\tگژھ تہٕ ایبیڈمیلکس سٍتـ̡ کتھ کرٕنـ̡ تہٕ وَنُن چُھہ یِتھٕ پٲٹھـ̡ لشکرن ہُند خدا، یُس اسرٲیلُک خدا چُھہ ونان ۔ وچھ بہٕ اَتھ شہرس پیٹھ پنٕنۍ کتھ بدی خٲطرٕ اَننہٕ، نہ کہ خیر خٲطرٕ۔ تہٕ تِم گژھن تۅہہِ برونہہ کُن {پورٕ}۔\n17. مگر بہٕ کٔرٕ تۅہہ تمہِ دۅہہٕ نجات دِنہٕ، خداوند چُھ فرماوان: تہٕ ژٕ گژھ نہٕ تمن لوکن ہٕندِس اتھس منز دِنہٕ یِمن سٍتـ̡ ژٕ کھوژان چُھ۔\n18.\\tیِکیازِ بہٕ کَرٕ ژے یٔقیٖنی طور نجات تہٕ تہٕ ژٕ گژھِ نہٕ تلوار سٍتـ̡ پَنُن شِکار، تِکیازِ ژے چُھہ میہ پیٹھ بھروسہٕ کورمُت، خداوند چُھ فرماوان۔","1.\\tیُس کلام یُس خداوند سٕندِ طرفہٕ یرمیاہ ہس آو ، تمہ پتہٕ یُس رٲچھ کرن وٲلِس کپتانن نیبزارادنن اوس تس رامہ نشہِ تراوُن، ییلہ تٔمۍ یروشلم تہٕ یہوداہ کِس یرغمال نِنہٕ آمٕتۍ سارِنٕے سارِنٕے سارِنٕے سٍتـ̡ زنجیرن منز بٔنِتھ نِنہٕ آمُت اوس، یِم بابل کُن قٲد کٔرِتھ نِنہٕ آمٕتۍ۔ {زنجیر: یا، مینیکلس}\n2.\\tتہٕ رٲچھ کرن والہِ کپتانن روٚٹ یرمیاہ تہٕ وونُن أمِس زِ خداوند چُھہ تُہند خدایہ یَتھ جایہِ بُرٲیی ہُند اعلان کورمُت۔\n3. وۅنۍ چُھہ خداوند اوٚنمُت، تہٕ یێلہِ چُھہ تٔمۍ سٕندِس کُنہِ سٍتـ̡ تہٕ چُھہ نہٕ تٔمۍ سٕنزِ آوازِ ہٕنز فرمانبرداری کٔرمٕژ، تێمہِ کِنۍ چُھہ یہِ چیز توے سٍتـ̡ آمُت۔\n4. تہٕ وُن، وُچھ، بہٕ ژے از دۅہہ زنجیرو نِش یلہٕ تراوان یِم تۅہہِ اتھس پیٹھ ٲسۍ۔ اگر ژے میانہِ سٍتـ̡ بابل یِنـ̡ چُھہ تۅہہِ سٍتـ̡ یِنـ̡ تہٕ یێلہِ چُھہ تێلہِ یِن تہٕ بہٕ کٔرٕ ژے رژھ رژھ نظر، مگر اگر ژے میانہِ سٍتـ̡ بابل یِنُک بُرٕ باسان چُھ، تێلہِ گژھہِ تتہِ گژھُن۔ {ٲسۍ...: یا، چھہِ تۅہہِ اتھس پیٹھ} {بہٕ کرُن...: ہیب۔ بہٕ کٔرٕ ژے پیٹھ پنٕنۍ نظر}\n5.\\tییلہ سُہ وُنہِ تام واپس اوس نہٕ آمُت، {تٔمۍ ووٚن}، یُس شافان سُند نیچو احیکم سُند نیچو گیڈالیاہ تہِ واپس گژھُن، یُس بابل کِس بادشاہن یہوداہ کین شہرن پیٹھ حکمران بنوومُت چُھ، تہٕ أمِس سٍتـ̡ روزُن لُکن مَنٛز۔ چنانچہ رٲچھ دِنہٕ والہِ کپتانن دِژ أمِس خوراک تہٕ انعام، تہٕ دِژُن أمِس یلہٕ۔\n6. پتہٕ گۆو یرمیاہ احیکم سُند نیچو گدلیاہ نِش مزپاہ کُن۔ تہٕ روٗد أمِس سٍتـ̡ تِمن لُکن مَنٛز روزان یِم زمینس مَنٛز باقٕے ٲسۍ۔\n7. وۅنۍ ییلہ یمن فوجن ہٕندِس سارِنٕے کپتانو یِم کھاہن منز ٲسۍ، تِمو تہٕ تِہندیو نفرو بوز زِ بابل کِس بادشاہن اوس گیڈالیاہ احیکم سُند نیچو زمینس منز گورنر بنوومُت، تہٕ أمِس سٍتـ̡ اوسُکھ مرد، زنانہٕ، بچہٕ تہٕ زمینہٕ کین غریبن ہٕندِس سٍتـ̡ یِم نہٕ بابل کُن نِنہٕ آمٕتۍ ٲسۍ۔\n8.\\tپتہٕ آیہِ تِم گدلیاہ نِش مزپاہ، حتیٰ کہ نیتھیاہ سُند نیچو اسماعیل، تہٕ یوحنان تہٕ یوناتھن کریہ سٕندِ نیچو، تہٕ تنہومتھ سُند نیچو سریاہ تہٕ یِمن ہٕندِس نیچو یِمن ہٕندِس نیچو تہٕ یِمن ہٕندِس مردس سٍتـ̡ تہٕ یِمن ہٕندِس نفرس سٍتـ̡ یێلہِ سٍتـ̡ نیچو تہٕ یِمن ہٕندِس نیچو۔\n9.\\tتہٕ شافان سٕندِس نیچو احکیم سٕندِس نیچو گیڈالیاہ کٔر تِمن تہٕ تِہندین نفرن سٍتـ̡ حلف تہٕ وونُن زِ کلدانن ہٕنز خدمت کرنہٕ نشہِ گژھ نہٕ خوفہٕ۔ زمینس مَنٛز روزو تہٕ بابل کِس بادشاہس سٕنز خدمت کرٕن، تہٕ یہ گژھہِ تۅہہِ سٍتـ̡ رژھرٕ۔\n10.\\tبہٕ روزٕ مِزپاہَس مَنٛز کلدانن ہٕنز خدمت کرنہٕ خٲطرٕ، یُس اسہِ نِش یِنہٕ یِن، مگر تۅہہ کٔرِو شراب، ریتہٕ کالہٕ کِس مٮ۪وٕ تہٕ تیٖل جمع کٔرِتھ تہٕ پننین شہرن مَنٛز روزُن یِم تۅہہ قبضہٕ کٔرۍمٕتۍ۔ {خدمت کرنہٕ خٲطرٕ: ہیب۔ برونہہ کُن کھڑا گژھُن}\n11. یِتھے پٲٹھـ̡ ییلہ تمام یہودی یِم موآبس مَنٛز ٲسۍ، تہٕ عمونین منز، تہٕ ادومس مَنٛز، تہٕ سارنٕے ملکن مَنٛز، بوز زِ بابل کِس بادشاہن چُھ یہوداہُک اکھ باقیات ترٲومُت، تہٕ تٔمۍ اوس تِمن پیٹھ شافان سُند نیچو احیکم سُند نیچو گیڈالیاہ تھوومُت۔\n12.\\tسٲری یہودی تہِ گٔیہِ سارِوٕے جایہِ نِش واپس، یێلہِ تِم کڈنہٕ آمٕتۍ، تہٕ آیہِ یہوداہ کِس سرزمینس منز، گیدلیاہ کُن، مزپاہ کُن تہٕ کٔرِکھ شراب تہٕ ریتہٕ کالہٕ کِس میوٕ سٍتـ̡ سٮ۪ٹھاہ سٮ۪ٹھاہ جمع کٔرِتھ۔\n13.\\tامہِ علاوٕ آو کریہ سُند نیچو جوہانان تہٕ فوجٕکۍ سٲری سردار یِم کھہَن مَنٛز ٲسۍ، گٔیہِ گدالیا کِس مِزپاہَس کُن۔\n14.\\tتہٕ ووٚننس زِ ژیہ چھا پتاہ زِ عمونیتٮ۪ن ہٕندِس بادشاہ بعلس چُھ نِتھنیاہُک نیچو اسماعیل تہٕ ژےٚ مارنہٕ خٲطرٕ سوزمُت؟ مگر احکیم سُند نیچو گدلیاہ کور نہٕ تمن پیٹھ یقین کرنہٕ۔ {مارنہٕ خٲطرٕ...: حب۔ تۅہہِ ہٕندِس روحس منز مارنہٕ خٲطرٕ؟}\n15.\\tاَمہِ پَتہٕ کٔر یُس کارعیاہ سٕندِس نیچوِس یُس ژوٗرِ پٲٹھـ̡ مِزپاہَس مَنٛز گَدلیاہ سٍتـ̡ ژوٗرِ پٲٹھـ̡ کتھ کٔرِتھ وونُن زِ بہٕ تراوُن تہٕ بہٕ کٔرٕ نیتھنیا سُند نیچو اسماعیل، تہٕ کٲنسہ تہِ گژھہِ نہٕ خبر زِ سُہ کیازِ مارُن تہٕ تۅہہِ نِش جمع کرنہٕ آمٕتۍ سٲری یہودی گژھن منتشر کرنہٕ یِن، تہٕ یہوداہَس مَنٛز بَچِھہ باقٕے گَژھن مارٕنـ̡ ۔\n16.\\tمگر احیکم سٕندِس نیچوِس گیدلیاہ ووٚن کریہ سٕندِس نیچوِس یوہنانس زِ ژے گژھ نہٕ یہِ کتھ کٔرِتھ، تکیازِ ژے چھُکھ اسماعیل سٕندِس بارس منز اپُز کتھ کران۔","1. وۅنۍ سپُد سٔتِم ریتس مَنٛز، {یہ} نیتھنیاہُک نیچو اسماعیل، الیشامہ سُند نیچو، تہٕ بادشاہ سٕندِ شہزادہٕ تہٕ أمِس سٍتـ̡ دَہ نفر تہِ وٲتِتھ آۓ احیکم سُند نیچو گدالیاہ نِش۔ تہٕ تتہِ کھیوٚو تِمو مزپہس منز اِکہٕ وٹہٕ روٹی کھٮ۪وان۔\n2. تمہ پتہ ووٚتھ نیتھانیا سُند نیچو اسماعیل، تہٕ أمس سٍتـ̡ موجود داہ نفر، تہٕ دِتُن شافان سٕندِس نیچو احیکم سٕندِس نیچوِس گیدلیاہ تلوار سٍتـ̡ مارُن، یُس بابل کِس بادشاہن زمینس پیٹھ حکمران بنوومُت اوس۔\n3.\\tاسماعیلَن مٲرِتھ سارِنٕے یہودی یِم أمِس سٍتـ̡ ٲسۍ، یێلہِ تہٕ یێلہِ تہٕ تتہِ لبنہٕ یِنہٕ وٲلِس کلدانی تہٕ جنگی نفر تہِ۔\n4. تہٕ یہ سپُد دوٚیمہِ دۅہہ ییلہ تٔمۍ گدلیہ مارنہٕ آو، تہٕ کٲنسہ تہِ اوس نہٕ خبر،\n5.\\tزِ شیکیم، شیلوہ تہٕ سامریہٕ پیٹھٕ آیہ ژۅشہ نفر، یِمو داڑھ کاسنہٕ کٔرِتھ، تہٕ پلو پھٔٹِتھ تہٕ پان ژٹِتھ تہٕ اتھس منز نذرانہ تہٕ بخور ہیتھ کٔرِکھ خداوند سٕندِس گرس مَنٛز اننہٕ۔\n6.\\tتہٕ نیتھانیاہُک نیچو اسماعیل دراو مزپاہ پیٹھٕ تِمن سٍتـ̡ وَننہٕ خٲطرٕ، تہٕ ووت تِمن سٍتـ̡ یِمن سٍتـ̡ یێلہِ أمِس سٍتـ̡ یِمن سٍتـ̡ یێلہِ سٍتـ̡ یِمن سٍتـ̡ یێلہِ سٍتـ̡ یِمن سٍتـ̡ یِمن سٍتـ̡ سٍتـ {وُن...: ہیب۔ گَژھنہٕ تہٕ روُن}\n7. تہٕ یێلہِ یێلہِ تِم شہرس مَنٛز وٲتِتھ تہٕ یِم نیتھنیاہ سٕندِس نیچو اسماعیلَن مٲرِتھ تہٕ دِژن تِم تہٕ یِم أمِس سٍتـ̡ ٲسۍ۔\n8.\\tمگر یمن منز آیہ داہ نفر لبنہٕ یِمو اسماعیلَس وَنُن زِ اسہِ مٔرِو نہٕ اسہِ مَرُن، تِکیازِ اسہِ نِش چھِ کھہَس مَنٛز خزانہٕ، کٕنٕکُن، جو، تیٖل تہٕ ماچھہِ ہُند خزانہٕ۔ چنانچہ تٔمۍ کٔر نہٕ تِمن بٲے مَنٛز مٲرِتھ تہٕ مارُن نہٕ۔\n9.\\tوُنہِ سُہ کھۄڈ یَتھ مَنٛز اسماعیلَن تِمن نفرن ہٕنزِ سارِنٕے لاشہٕ ترٲومٕژ، یِم تٔمۍ گدلیاہ سٕندِ وجہہ سٍتـ̡ مارنہٕ آمٕتۍ ٲسۍ، سُہ اوس یُس آسا بادشاہن اسرٲیلِکِس بادشاہ بعشہٕ سٕندِ خوفہٕ سٍتـ̡ بنوومُت اوس۔ {کیازِ...: یا، گدلیہ نزدیک: ہیب۔ اَتھٕ سٍتۍ، یا گَدلیہ سٕندِ طرفہٕ\n10.\\tاَمہِ پتہٕ نِیُن اسماعیلَن یِم لُکن ہٕندِس سارِنٕے باقیات یِم مزپاہَس مَنٛز ٲسۍ، حتیٰ کہ بادشاہ سٕنزِ کورِ تہٕ تِم سٲری لُکھ یِم مِزپاہَس مَنٛز باقٕے ٲسۍ، یِم نِبوزارادنن رٲچھ کَرن وٲلِس کپتانن احیکم سٕندِس نیچوِس گیدلیاہ سٕندِس نِش دِژمٕژ ٲس۔\n11.\\tمگر ییلہ قاریہ سُند نیچو یوحنانن تہٕ أمِس سٍتـ̡ موجود فوجن ہٕندِس سارِنٕے کپتانو بوز یُس نیتھیاہ سٕندِس نیچو اسماعیل سٕندِ کٔرمٕژ ٲس ،\n12.\\tتێلہِ رٔٹۍ تِمو سارِنٕے نفر تہٕ گٔیہِ نیتھایاہ سٕندِس نیچوِس اسماعیلَس سٍتـ̡ لڑنہٕ خٲطرٕ، تہٕ لٔبِکھ سُہ گِبیونَس مَنٛز بٔڈِس آبس نِش۔\n13.\\tوۅنۍ سپد یہِ سپدُن، {یہ} ییلہ سارِوٕے لُکھ یِمو اسماعیلَس سٍتـ̡ یُس یوحنانس سٍتـ̡ کریہ سُند نیچو تہٕ تِمن فوجن ہٕندِس سارِنٕے کپتانن وُچھمُت یِم أمِس سٍتـ̡ ٲسۍ، تیلہِ گٔیہِ تِم خۅش۔\n14.\\tیِم سٲری لُکھ یِم اسماعیلَن مِزپاہ نِش قٲد کٔرِتھ نِمٕتۍ، تِم گٔیہِ واپس تہٕ گٔیہِ کریہ سٕندِس نیچوِس جوہانانس نِش۔\n15.\\tمگر نثانیاہ سُند نیچو اسماعیل ژوٚل ٲٹھن نفرن سٍتـ̡ یوحنانس نِش تہٕ گۆو عمونین نِش۔\n16.\\tاَمہِ پتہٕ نِیوُن کریہ سُند نیچو جوحنان تہٕ تِمن فوجن ہٕندِ سارِنٕے کپتان یِم أمِس سٍتـ̡ ٲسِتھ، تِمن ہٕندِس سارِنٕے باقٕے لُکن ہٕندِس باقٕے سٍتـ̡ یِم تٔمۍ نیتھانیا سٕندِس نیچوِس اسماعیلِس نِش بازیافت کٔرۍمٕتۍ، یێمہِ پتہٕ اوس تٔمۍ احیقام سُند نیچو گیڈالیاہ تہٕ جنگجو مرد تہٕ زنانہٕ تہٕ شُرِ مٲرِتھ مٲرِتھ۔  تہٕ خواجہ سرا ، یِم تٔمۍ گِبیونَس پٮ۪ٹھ دُبارٕ أنِمٕتۍ ٲسۍ:\n17. تہٕ تِم دراو تہٕ بٔسِتھ کِمہام کِس بستی مَنٛز یُس بیت اللحمس نِش چھُ، مصرس مَنٛز اژنہٕ خٲطرٕ،\n18.\\tچالدان سٕندِ مۅکھہٕ: تِکیازِ تِم ٲسۍ تِمن سٍتـ̡ کھوژان، تِکیازِ نیتھیاہ سٕندِ نیچو اسماعیلَن اوس احیکامُک نیچو گیدلیاہ مٲرِمُت، یُس بابل کِس بادشاہن زمینس مَنٛز گورنر بنوو۔","1. تمہ پتہ آیہ فوجکۍ سٲری سردار تہ کریہ سُند نیچو یوحنان تہٕ ہوشیہ سُند نیچو یزانیہ تہٕ سارِنٕے لُکھ لۅکہٕ پیٹھٕ بٔڈِس تام وٲتِتھ نزدیک۔\n2. تہٕ وۆنُن یرمیاہ پیغمبرس سٍتـ̡ ، أسـ̡ چُھہ ژے دُعا کرنہٕ آمُت، تہٕ یێمہِ سارِنٕے باقٕے خٲطرٕ گژھہِ خداوند خدایہِ سٕندِس خداہس سٍتـ̡ دُعا کرنہٕ۔ (تکیازِ اسہِ چھہِ کینہہ {مگر}، یتھہ پاٹھۍ چانۍ اچھ اسہِ وچھان:) {چلو...: یا، سون دُعا گژھہِ ژے برونہہ کُن}\n3. یێلہِ خداوند تُہند خدا ہٲوِن اسہِ سُہ وَتھ یتھ مَنٛز أسـ̡ پَکُن پٔکِتھ، تہٕ سُہ کُن یُس أسـ̡ کٔرِتھ ہیکو۔\n4.\\tیێلہِ وۆن یرمیاہ پیغمبرن تِمن وۆن، مے چُھہ بوزمُت {تُہ}۔ وُچھ، بہٕ کَرٕ تُہٕندِس کلامَس مُطٲبِق خداوند پنُن خدایہِ سٕنز دُعا۔ تہٕ یہِ سپدِ، {یہ} یُس تہِ خداوند تۅہہِ جواب دِیہِ، بہٕ کرٕ ژےٚ سُہ اعلان کرنہٕ۔ بہٕ تھاوٕ نہٕ ژےٚ نِش کیٚنٛہہ تہِ۔\n5. اَمہِ پَتہٕ ووٚن یِمو یرمیاہ سٍتـ̡ خداوند اسہِ درمِیان پٔزۍ تہٕ وفادار گواہ روزُن، یێلہِ أسـ̡ سارِنٕے چیزَن مُطٲبِق تہٕ یێلہِ نہٕ تُہُند خدا تُہُند خدا اسہِ نِش سوزِ۔\n6. چاہے یہ اصل آسہِ، یا بد آسہِ، أسۍ کرو پننِس خدایہ سٕنزِ آوازِ ہٕنز فرمانبرداری، یٔمِس نِش أسۍ تۅہہ سوزان چھِ۔ یێلہِ أسۍ پننِس خدایہ سٕنزِ آوازِ ہٕنز فرمانبرداری کٔرِو، تێلہِ گژھہِ اسہِ سٍتـ̡ ٹھیٖک روزُن۔\n7. تہٕ دَہَو دۅہہٕ پَتہٕ سپُد یہِ زِ خداوند سُند کلام آو یرمیاہ ہس تام۔\n8.\\tاَمہِ پتہٕ وُنُن یُس کریہ سُند نیچو تہٕ سارِنٕے فوجٕکۍ کپتان یِم أمِس سٍتـ̡ ٲسۍ، تہٕ سارِنٕے لُکھ یِم أمِس سٍتـ̡ ٲسۍ، تہٕ سارِنٕے لُکھ یِم أمِس سٍتـ̡ ٲسۍ،\n9. تہٕ وۆنُن تِمَن یِتھٕ پٲٹھۍ چُھہ خداوند یُس اسرٲیلُک خدا، یٔمِس نِش ژے مے پنٕنۍ دُعا پیش کرنہٕ خٲطرٕ سوزمُت چھُ۔\n10. یێلہِ تہِ یێلہِ تہِ یَتھ زمینس مَنٛز روزِو، تیلہِ کٔرٕ بہٕ ژے تعمیر کٔرِتھ، تہٕ بہٕ کٔرٕ ژے کٔرِتھ، تہٕ ژے ژٔٹِتھ تہٕ ژےٚ ژٔٹِتھ تہٕ بہٕ کٔرٕ ژے تُلِتھ تہٕ تُہٕندِس بُرٲیی سٍتـ̡ توبہ کٔرِتھ یُس مےٚ ژےٚ سٍتـ̡ کٔرمُت چُھ۔\n11. بابل کِس بادشاہس سٍتـ̡ گژھ نہٕ کھوژُن، یٔمِس سٍتـ̡ تُہۍ کھوژان چھِو۔ خداوند چُھ ونان زِ بہٕ چُھس ژے سٍتـ̡ بچاونہٕ خٲطرٕ تہٕ تٔمۍ سٕندِس اتھہٕ نِش نجات دِنہٕ خٲطرٕ تہٕ بہٕ چُھس ژے سٍتـ̡ سٍتـ̡ خوفزدہ سپدُن۔\n12. تہٕ بہٕ کَرٕ ژےٚ رحمت، یُتھ سُہ کرِ تۅہہِ پیٹھ رحم تہٕ کرِ ژےٚ پنٕنِس سرزمینس منز واپس۔\n13. مگر یێلہِ تُہۍ یہِ ؤنِو زِ أسـ̡ نہٕ یَتھ زمینس مَنٛز روزِو، تہٕ نہ کرو خداوند پنٕنـ̡ خدایہِ سٕنزِ آوازِ ہٕنز فرمانبرداری،\n14. ونُن، نہٕ؛ مگر أسۍ گژھو مصر کِس سرزمینس منز، ییتہِ نہ اسہِ کانہہ جنگ وُچھن، نہ بُزرگ ہٕنز آواز، نہ روٹی ہٕنز بھوک۔ تہٕ تتہِ روزو أسۍ:\n15. تێمہِ کِنۍ بوزو خداوند سُند کلام، اے یہوداہ ہٕندِس باقیاتس سٍتـ̡ ۔ یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھ وَنان۔ یێلہِ پَنُن بُتھ مصرس مَنٛز اژنہٕ خٲطرٕ تہٕ اَتہِ روزنہٕ خٲطرٕ گٔژھِو۔\n16. تیلہ گژھہِ یہِ سپدِ، سُہ تلوار یُس تۅہہِ کھوژان اوس، سُہ گژھہِ تتہِ مصرٕکِس سرزمینس مَنٛز تہٕ یُس قحط یُس تۅہہِ کھوژان اوس، سُہ گژھہِ تۅہہِ پتہٕ مصرس مَنٛز۔ تہٕ تتہِ گژھِو تُہۍ مرُن۔ {پَتہٕ پَتہٕ...: ہیب۔ ژیہ ژٔٹِتھ ژ\n17.\\tیِتھے پٲٹھۍ گژھہِ سارِنٕے نفرن سٍتـ̡ یِم مصرس مَنٛز روزنہٕ خٲطرٕ بُتھ تھاوان چھِ۔ تِم گژھن تلوار سٍتۍ، قحطہٕ سٍتۍ، تہٕ وباہٕ سٍتۍ مرُن: تہٕ یِمو منزٕ روزِ نہٕ کانہہ تہِ بُرٕ نِش تہٕ بچِتھ یُس بہٕ تِمن پیٹھ دِیہِ۔ {تو...: ہیب۔ یتھے پاٹھۍ گژھن سٲری مرد آسن}\n18. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب اسرٲیلُک خدا فرماوان۔ یێلہِ میون شَرارتہٕ تہٕ غصہٕ چُھ یروشلم کین بسکینن پیٹھ تراونہٕ آمُت۔ یێلہِ تہٕ یێلہِ تہٕ ژے مصرس مَنٛز اژِو، تہٕ تۅہہ گژھہِ اکھ عذاب، تہٕ حٲرت، تہٕ لعنت، تہٕ ملامت بنہٕ۔ تہٕ ژیہ وُچھِو نہٕ یہِ جاے پتہٕ۔\n19.\\tخداوند چُھ تۅہہِ مُتعلِق وونمُت، اے یہوداہ ہٕندِس باقیَس مُتعلِق چُھہ وَننہٕ آمُت۔ ژیہ گژھ نہٕ مصرس منز: پٔزۍ پٲٹھـ̡ زان زِ مے چُھہ از دۅہہ نصیحت کورمُت۔ {نصیحت...: ہیب۔ تۅہہِ خلاف گوٲہی دِژ}\n20. یێلہِ تہٕ یێلہِ تہٕ ژے میہ خداوند پننِس خداہس نِش سوزمُت، یہِ ؤنِتھ زِ اسہِ خٲطرٕ کٔرِو سٲنِس خداہس نِش دُعا دُعا۔ تہٕ یێلہِ سارِنٕے مُطٲبِق یُس خداوند سُند خدا وَنُن، تێلہِ کٔرِو اسہِ اعلان تہٕ أسۍ کرو یہِ۔ {ژیہ کٔر بے قرار...: یا، ژیہ چھکھ پننین روحن خلاف دھوکہ دہی استعمال کٔرمٕژ}\n21.\\tتہٕ {وُن} مے چُھس اَمہ دۅہہٕ ژےٚ اعلان کوٚرمُت۔ مگر ژے چُھہ نہٕ خداوند پنُن خدایہ سٕنزِ آوازِ ہٕنز اطاعت کٔرمٕژ، تہٕ نہ چُھہ کُنہِ تہِ چیزٕچ اطاعت کٔرمٕژ یُس تٔمۍ مے ژےٚ خٲطرٕ سوزمُت چُھ۔\n22. لہذا گژھہِ پزۍ پاٹھۍ معلوم زِ تلوار سٍتۍ، قحط سٍتۍ، تہٕ وباہن سٍتۍ، تتھ جایہ یُس تہِ گژھُن یژھان چھِو۔ {گژھُن...: یا، سفرس پیٹھ گژھُن}","1. تہٕ سپُد یہِ سپدُن، {یہِ} یێلہِ یرمیاہ سارِنٕے لُکن سٍتـ̡ خداوند تِہندِ خدایہ سٕندِ سارِنٕے کلامٕچ کتھ کرٕنـ̡ بند کٔرِتھ، یێمہِ خٲطرٕ خداوند تِہندِ خدایہِ سُند سُہ تِمن نِش سوزمُت اوس، {حتیٰ کہ} یِم سٲری لفظ تہِ،\n2. اَمہِ پَتہٕ وَنُن عزریاہ سُند نیچو، تہٕ کریہ سُند نیچو جوحنان تہٕ سارِنٕے مغرور نفرن وَنُن یرمیاہ سٍتـ̡ چُھہ اپُز کتھ کران: خداوند سٲنـ̡ خدایہِ چُھہ نہٕ ژے یہِ وننہٕ خٲطرٕ سوزمُت زِ مِصرس مَنٛز گژھ نہٕ اتہِ روزنہٕ خٲطرٕ۔\n3. مگر نیریاہ سُند نیچو باروخ چُھ ژے اسہِ خلاف بِہناونہٕ آمُت، یُتھ زن اسہِ کلدِین ہٕندِس اتھس منز تراوُن، یُتھ تِم اسہِ مارنہٕ یِن، تہٕ اسہِ قٲد کٔرِتھ بابل نِن۔\n4.\\tیێلہِ کٔر یہوداہ سٕندِس سرزمینس مَنٛز روزنہٕ خٲطرٕ یُس نہٕ یوحنان سُند نیچو تہٕ فوجٕکۍ سارِوٕے کپتان، تہٕ سارِنٕے لُکھ کٔر نہٕ خداوند سٕنزِ آوازِ ہٕنز فرمانبرداری۔\n5.\\tمگر کریہ سُند نیچو جوہانن تہٕ فوجٕکۍ سارِوٕے کپتان، نِیوو یہوداہ سٕندِ سارِنٕے باقٕے باقیات، یُس سارِوٕے قومن نِش واپس آمُت اوس، یُس یہوداہ کِس سرزمینس مَنٛز روزنہٕ خٲطرٕ واپس آمُت اوس۔\n6. {حتی} مرد تہٕ زنانہٕ تہٕ بچہٕ تہٕ بادشاہ سٕنز کورِ تہٕ پرٮ۪تھ کانہہ شخص یُس نبوزاردان محافظن ہُند کپتان اوس گڈالیاہ سٍتـ̡ یُس شافان سُند نیچو احیکم سُند نیچو تہٕ یرمیاہ پیغمبر تہٕ نیریاہ سُند نیچو باروخ سٍتـ̡ ترٲومُت۔\n7.\\tتہ آیہ تِم مصرٕکِس سرزمینس مَنٛز، تِکیازِ تِمو کٔر نہٕ خداوند سٕنزِ آوازِ ہٕنز فرمانبرداری، یِتھٕ پٲٹھۍ وٲتۍ تِم تہِ تہِ تاہپانہس کُن۔\n8. اَمہِ پتہٕ ووت خداوند سُند کلام یرمیاہ ہس تہٕ تہٕ وونُن،\n9.\\tبٔڈۍ کٔنہِ رٔٹِو پننِس اتھس منز، تہٕ یُس یہوداہ کین انسانن ہٕندِس نظرِ منز فرعون سٕندِس مکانس منز اژنہٕ وِزِ چھُ۔\n10. تہٕ تِمن وَنُن زِ یِتھٕ پٲٹھۍ چُھ لشکرن ہُند خدا، اسرٲیلُک خدا۔ وچھ بہٕ سوز تہٕ نِنہٕ بابلُک بادشاہ نیبوکدرِزر، یُس میون خادم اوس، تہٕ تٔمۍ سُند تخت تھاوٕ یِمن کنن پیٹھ یِم مے ژوٗرِ تھوومٕتۍ چھِ۔ تہٕ سُہ پھٔہلٲوِ پنُن شٲہی محلہٕ تِمن پیٹھ۔\n11. تہٕ ییلہ سُہ یِیہ، سُہ کرِ مصر کِس سرزمینس پیٹھ مارُن، {تہٕ یُس موت} خٲطرٕ دِیہِ۔ تہٕ یِتھٕے {یِتھٕ پٲٹھۍ چھِ} قید کرنہٕ خٲطرٕ؛ تہٕ یِتھٕ پٲٹھۍ چھِ تلوار خٲطرٕ تلوار۔\n12. تہٕ بہٕ دِیہٕ مصرٕکین دیوتاہن ہٕندِس گَرَن مَنٛز نار زالنہٕ۔ تہٕ سُہ کرِ تِم زٲلِتھ تہٕ نِنہٕ یِمن قٲد۔ تہٕ سُہ کرِ مصرٕچ سرزمینہٕ سٍتـ̡ سٍتـ̡ پَنُن پٲٹھـ̡ پَنُن پٲٹھـ̡ پٲٹھـ̡ پَنُن پٲٹھـ̡ تہٕ سُہ نیرِ تتہِ منزٕ امن سٍتـ̡ نیرُن۔\n13.\\tسُہ پھُٹراوِ بیت شمش سٕنزِ شکلہٕ تہِ، یعنی مصر کِس سرزمینس مَنٛز۔ تہٕ مصری دیوتاہن ہٕندِ گرٕ دزِ سُہ نارٕ سٍتـ̡ دزنہٕ۔ {تصویر: ہیب۔ مجسمہٕ، یا، کھڑا تصویر} {بیت شیمیش: یا، آفتابُک گھر}","1.\\tیُس لفظ یرمیاہ ہس سٍتـ̡ مصر کِس سرزمینس مَنٛز روزن وٲلِس سارِنٕے یہودین مُتلق آو ، یِم مگڈولَس مَنٛز روزان چھِ، تہٕ نوفس مَنٛز تہٕ پاتھروس کِس ملکس مَنٛز روزان چھِ، یُس وَنُن چُھ،\n2. یِتھٕ پٲٹھـ̡ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھہ فرماوان۔ یُس میہ یروشلمس تہٕ یہوداہ کین سارنٕے شہرن پیٹھ وُچھمُت چھُ، سُہ سورُے بُراے وُچھمُت۔ تہٕ وچھ از کل چھ تم ویران تہٕ اتھ منٛز چُھ نہٕ کانٛہہ تہٕ انسان روزان،\n3. تِمن ہٕنزِ بدکٲری کِنۍ یُس تِمو مےٚ شرارت دِنہٕ خٲطرٕ انجام دِژمُت چھُ، یتھ مَنٛز تِم گٔیہِ بخور زالنہٕ خٲطرٕ، {تہٕ} باقین دیوتاہن ہٕنز خدمت کرنہٕ خٲطرٕ، یِمن نہٕ تِم زانان ٲسۍ۔\n4.\\tبہٕ سوٗزۍ میہ پنٕنۍ سارِنٕے خادم، پیغمبرن سُلہٕ وُتھِتھ تہٕ سوزُکھ یہِ مُشکِل کتھ یُس بہٕ نفرت کران چھُ۔\n5.\\tمگر تِمو بوز نہٕ تہٕ کٔرٕکھ نہٕ پنٕنۍ بدکاری نِش پھیرنہٕ خٲطرٕ، بییِس دیوتاہن ہٕندِ خٲطرٕ کُنہِ بخور زالنہٕ خٲطرٕ۔\n6. اَمہِ مۄکھٕ گۆو میون قہر تہٕ میٲنۍ غصہٕ تہٕ یہوداہ کِس شہرن تہٕ یروشلم کین سڑکن مَنٛز دزنہٕ۔ تہٕ تِم چھِ از کِس پٲٹھۍویران۔\n7. تێمہِ کِنۍ چُھ یِتھٕ پٲٹھـ̡ خداوند یُس لشکرن ہُند خدا، اسرٲیلُک خدا چُھہ وَنان۔ تێلہِ کٔرِو تُہۍ پننِس روحس سٍتـ̡ بٔڈ بُردی کٔرِتھ، یُس یہوداہ نِش مرد تہٕ زنانہٕ، شُرِ تہٕ دۄدٕ دِنہٕ خٲطرٕ ژٔٹِتھ ژٔٹِتھ تہٕ ژے روزُن نہٕ کانہہ تہِ روزُن۔ {نیبر...: ہیب۔ یہوداہ کِس وسطس منز}\n8. یێمہِ سٍتـ̡ چُھہ میہ پننیو اتھو سٍتـ̡ شرارت دِنہٕ خٲطرٕ اِشارٕ دِوان، یێلہِ تہٕ یێلہِ ژٔٹِتھ تہٕ سارِنٕے قومن مَنٛز بٔنِتھ بٔنِتھ تہٕ بٔنِتھ بٔنِو۔\n9. کیا تۅہہ چھوا پننین مٲلن ہٕنز بدکاری تہٕ یہوداہ کین بادشاہن ہٕنز بدکاری، تہٕ تِہنزن زنانن ہٕنز بدکاری تہٕ پننہِ زنانہِ ہٕنز بدکاری تہٕ پننہِ زنانہِ ہٕنز بدکاری مٔشِد گٔمٕژ، یُس تِمو یہوداہ کِس سرزمینس تہٕ یروشلم کین سڑکن مَنٛز کٔرمٕژ چھِ۔ {بدکاری...: ہیب۔ بدکاری، یا، سزا، وغیرہ}\n10. تِم چِھنہٕ از تام عاجز گٔمٕتۍ، نہ چُھہ تِمو کھوژان، تہٕ نہ چُھہ میانِس قانونس مَنٛز پکان یُس بہٕ ژے تہٕ تہندٮ۪ن مٲلن برونہہ کُن تھاونہٕ آمُت۔ {عاجز: ہیب۔ contrite}\n11. تێمہِ کِنۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھہ وَنان۔ وُچھ، بہٕ کَرٕ ژےٚ بُتھ تہٕ یہوداہ ژٹنہٕ خٲطرٕ تہٕ ژٹنہٕ خٲطرٕ۔\n12. تہٕ بہٕ نِہ یہوداہ سٕندِس باقیاتس سٍتـ̡ یِمو مصر کِس سرزمینس مَنٛز روزنہٕ مۅکھہٕ بُتھِس بُتھِس سٍتـ̡ رٔٹِتھ چُھہ، تہٕ تِم سارِنٕے گژھن کھٮ۪نہٕ یِن، {تہٕ} مصر کِس سرزمینس مَنٛز پۯاوٕنـ̡ ۔ تِم گژھن تلوار سٍتـ̡ تہٕ قحط سٍتـ̡ مَرٕن: تِم مرن سارِوٕے کھۄتہٕ کم پیٹھٕ بٔڈِس تام، تلوار سٍتـ̡ تہٕ قحط سٍتـ̡ تہٕ تِم گژھن اکھ عذاب، {تہٕ} حیرت، تہٕ لعنت، تہٕ ملامت کرنہٕ۔\n13. تِکیازِ بہٕ کَرٕ تِمن یِمن مصرٕچ سرزمینس مَنٛز روزان چھِ، یِتھ کٔنۍ مے یروشلمس تلوار سٍتۍ، قحط تہٕ وبا سٍتـ̡ سزا دِژمٕژ چھِ:\n14.\\tیُتھ یہوداہ کِس باقیاتس منز، یُس مصر کِس سرزمینس مَنٛز روزنہٕ خٲطرٕ گٔژھمُت چُھ، ہێکہِ نہٕ ژلِتھ تہٕ روزِ، یُس یہوداہ کِس سرزمینس مَنٛز واپس یِن، یێمہِ سٍتـ̡ یێلہِ تِمن ہٕندِس سرزمینس مَنٛز واپس۔ {ہیو...: ہیب۔ تِہُند روح تُلُن}\n15.\\tتێلہِ سارِنٕے مردَن یِمن پتاہ ٲس زِ تِہٕنزِ زنانہٕ آسہٕ باقین دیوتاہن خٲطرٕ بخور زٲلمٕژ، تہٕ سارِنٕے زنانہٕ یِم اَتھ سٍتـ̡ کھڑا آسہٕ، حتیٰ کہ سارِنٕے لُکھ یِم مصرٕکِس سرزمینس مَنٛز، پاتھروس مَنٛز روزان ٲسۍ، دِژ یرمیاہ ہس جواب،\n16. یُس کلام ژے خداوند سٕندِ ناوٕ سٍتـ̡ اسہِ سٍتـ̡ بولمُت چُھ، أسـ̡ چُھہ نہٕ تُہٕندِ کُن بوزان۔\n17.\\tمگر أسۍ کٔرِو یُس تہِ پننہِ ٲسہِ منزٕ نیرِ، اسمانٕچ ملکہِ خٲطرٕ بخور زالنہٕ خٲطرٕ، تہٕ أمِس چُھہ شرابٕچ نذرانہ تراوُن، یِتھ کٔنۍ أسۍ تہٕ پننین مٲلن، پننین بادشاہن، تہٕ پننین شہزادن یہوداہ کین شہرن تہٕ یروشلم کین سڑکن مَنٛز، یِتھ کٔنۍ أسۍ تہٕ پننین مٲلن، پننین بادشاہن تہٕ پننین شہزادن یہوداہ کین شہرن مَنٛز تہٕ یروشلم کین سڑکن مَنٛز کٔرۍمٕتۍ، تکیازِ اسہِ آسہٕ واریاہ زیادٕ خوراک،  تہٕ ٲسٕکھ ٹھیٖک ٹھیٖک، تہٕ وُچھُن نہٕ کانٛہہ بُرٕ۔ {ملکہ...: یا، آسمانُک فریم} {وِکچوئلز: ہیب۔ بریڈ }\n18.\\tمگر یێلہِ أسۍ آسمانٕچ ملکہِ ہٕندِس اگربتی زالنہٕ خٲطرٕ تہٕ أمِس شرابٕچ نذرانہ تراونہٕ خٲطرٕ تروو، أسۍ چھِ سارِنٕے چیزن ہٕنز خواہش کٔرمٕژ، تہٕ تلوار تہٕ قحطہٕ سٍتـ̡ کھٮ۪نہٕ آمٕتۍ۔\n19. تہٕ ییلہ أسۍ آسمانٕچ ملکہِ خٲطرٕ بخور زٲلِتھ تہٕ أمِس شرابٕچ نذرانہ تراوٕن، کیا أسۍ أمِس پوٗزا کرنہٕ خٲطرٕ کیک بنٲوِتھ، تہٕ پننین نفرن ورٲے، أمِس خٲطرٕ شراب نذرانہ تراوُن؟ {مرد: یا، خانٛدار؟}\n20.\\tیێلہِ ووٚن یرمیاہ سارنٕے لُکن ، مردن تہٕ زنانن تہٕ تِمن سارِنٕے لُکن یِمو أمِس جواب دِژمُت اوس ،\n21.\\tیُس بخور یُس تہٕ یُس نہٕ تٔمۍ سٕندِس ذہنس مَنٛز دِنہٕ آمُت؟\n22. یێلہِ خداوند ہێکہِ نہٕ تُہنزِ بُرٲیی ہٕندِ سٍتـ̡ تہٕ یِمن مُکُلمن ہٕندِس سٍتـ̡ تہٕ یِمن کُنہِ سٍتـ̡ ہێکہ تَمہِ کِنۍ چھُ تُہٕنٛز سرزمین ویران، تہٕ حٲرت، تہٕ لعنت، یُس از کُنہِ روزَن وٲلِس بغٲر چھُ۔\n23. کیازِ چُھہ تہٕ یێلہِ چُھہ خداوند سٕنزِ آوازِ ہٕنز فرمانبرداری کٔرمٕژ، تہٕ چُھہ نہٕ خداوند سٕنزِ آوازِ ہٕنز فرمانبرداری کٔرمٕژ، تہٕ چُھہ نہٕ تٔمۍ سٕندِس شریعتس مںز، نہ تٔمۍ سٕندِس قونونس منز، تہٕ تٔمۍ سٕنزِ گوٲہی مَنٛز۔ تَمہِ کِنۍ چُھ یہِ بُرٕ تۄہہِ سٍتـ̡ سپدمُت، یِتھٕ پٲٹھـ̡ از تہِ سپدِ۔\n24. یرمیاہ ہن ووٚن سارنٕے لُکن تہٕ سارنٕے زنانن سٍتـ̡ خداوند سُند کلام بوزو، سارِنٕے یہوداہ سُند کلام یُس مصر کِس سرزمینس مَنٛز چُھہ:\n25. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھہ ونان چُھ، تۅہہ تہٕ تہنزِ زنانہِ چھے دۅشوے پننہِ ٲسس سٍتۍ کتھ کٔرمٕژ، تہٕ پننہِ اتھہٕ سٍتۍ پورٕ کورمُت، أسۍ کرو یقینا پنُن عہد پورٕ یُس اسہِ عہد کورمُت چُھ، اسمانٕچ ملکہِ خٲطرٕ بخور زالن، تہٕ تٔمِس کٔرِو شرابٕچ نذرانہ تراون، تہٕ یٔقیٖنی طور کٔرِو پَنُن عہد پورٕ۔\n26. تێمہِ کِنۍ بوزو خداوند سُند کلام، یُس مصرٕچ سرزمینس مَنٛز روزان چھُ۔ وُچھمُت، میہ چُھ پننِس عظیم ناوٕ سٍتـ̡ حلف کورمُت، خداوند چُھ ونان زِ میٲنۍ ناو ییہِ نہٕ یہوداہ کِس سارِنٕے سرزمینس مَنٛز یہوداہ کِس کٲنٛسہِ تہِ شخصہٕ سٕندِس ٲسِس مَنٛز ناو تھاونہٕ، یہِ وَنُن زِ خداوند چُھ زندٕ۔\n27.\\tوُچھِو بہٕ یِمن ہٕندِس بُرِس سٍتـ̡ رٲچھ کٔرِتھ، تہٕ یہوداہ ہٕندِس سارِنٕے لُکہٕ یُس مصر کِس سرزمینس مَنٛز چُھہ، تِم گژھن تلوار تہٕ قحط سٍتـ̡ ختم گژھن، یوتام نہٕ تِمن ہُند خاتمہٕ سپدِ۔\n28.\\tتوتہِ یُس تلوار نِشہ بچان چُھ، سُہ گژھہِ مصر کہِ سرزمینہٕ منزٕ یہوداہ کِس سرزمینس مَنٛز واپس، تہٕ یہوداہٕکۍ سارِنٕے باقٕے یُس مصرٕکِس سرزمینس مَنٛز روزنہٕ خٲطرٕ گٔژھمٕتۍ، تِمن گژھہِ معلوم زِ کُس سُند کلام آسہِ، میٲنۍ یا تِہُند۔ {میٲنۍ ...: ہیب۔ میہ نِش، یا تمن نِش}\n29. تہٕ یہِ آسہِ تۅہہِ خٲطرٕ اکھ نشانہٕ، خداوند چُھ فرماوان زِ بہٕ کرٕ ژےٚ یَتھ جایہِ سزا، یُتھ ژے زانہٕ زِ میٲنۍ کلام گژھن یٔقیٖنی طور بدی ہٕندِس خلاف کھڑا روزُن:\n30. خداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ وچھ بہٕ دِیہ مصرُک بادشاہ فرعون ہوفرا پننین دُشمنن ہٕندِس اتھس منز، تہٕ تِمن ہٕندِس اتھس منز یِم تٔمۍ سٕنز جان ژھاران چھِ۔ یێلہِ میہ دِژ یہوداہُک بادشاہ صدقیاہ بابل کِس بادشاہ نبوکدرِززار سٕندِس اتھس منز، یُس تٔمۍ سُند دُشمن اوس، تہٕ تٔمۍ کٔر تٔمۍ سٕنز جان ژھارنہٕ۔","1. سُہ لفظ یُس یرمیاہ پیغمبرن نیریاہ سٕندِس نیچوِس باروخس سٍتـ̡ کتھ کٔرمٕژ، یێمہِ سٍتـ̡ یێمہِ یہوداہ کِس بادشاہ یوسیاہ سٕندِس نیچوِس ژوٗرمِس ؤریس مَنٛز یِم لفظ یرمیاہ سٕندِس واتس پیٹھ أکِس کتابہِ مَنٛز لیکھمُت اوس، یہوداہ کِس بادشاہ جوسیاہ سٕندِس نیچوِس سٕندِس ژوٗرمِس ؤریس مَنٛز، یہوداہ کِس بادشاہ جوسیاہ سٕندِس نیچوِس سٍتـ̡ وونُن،\n2. یِتھٕ پٲٹھـ̡ چُھہ خداوند اسرٲیلُک خدا، اے باروخ تہٕ تُہہِ سٍتـ̡ وَنان۔\n3.\\tژے ووٚنمُت، ہا ہا میہ وۆن! تکیازِ خداوند چُھ میٲنس غمس منز غم ہُریومُت۔ میہ گوو پننہِ آہ وُچھتھ بے ہوش، تہ میہ چھہ نہ کانہہ آرام میلان۔\n4. یِتھٕ پٲٹھـ̡ چُھہ تٔمِس وَنُن، خداوند چُھ یِتھٕ پٲٹھـ̡ وَنان۔ وُچھ، {یہ} یُس میہ بنوومُت چُھ، تہٕ یُس میہ ووتمُت چُھ، سُہ تہٕ یُس میہ ووتمُت چُھس بہٕ تُلِتھ، یہ سورے زمینہٕ تہِ۔\n5. تہٕ کیا ژٕ چُھکھ پانس خٲطرٕ بٔڈ چیز ژھاران؟ خداوند چُھ ونان زِ بہٕ کرٕ سارِنٕے جسمس پیٹھ بُرٕ اننہٕ، مگر بہٕ دِیہٕ تُہند زُو ژے پریتھ جایہِ شِکارٕ خٲطرٕ دِنہٕ۔","1. خداوند سُند کلام یُس یرمیاہ پیغمبرس نِش غیر قومن خلاف آو۔\n2. مصرس خٕلاف، مصر کِس بادشاہ فرعونیکو سٕندِس لشکرس خٕلاف، یُس کارکیمشس مَنٛز دریائے فرات کِس نِش اوس، یُس بابل کِس بادشاہ نبوکدرِزرن یہوداہ کِس بادشاہ یوسیاہ سٕندِس نیچوِس ژوٗرِمِس ؤریس مَنٛز لوٚگمُت۔\n3. بکلر تہٕ ڈھالُک حُکُم کٔرِو تہٕ جنگس نزدیک گژھُن۔\n4. گُرٮ۪ن ہُنٛد استعمال کٔرِو؛ تہٕ ووٚتھ، اے گُرۍ سوار، تہٕ کھڑا گژھو {پنٕنۍ} ہیلمٹ ہٮ۪تھ۔ نیزٕ لٔگِتھ تہٕ لٔگِتھ لٔگِتھ لٔگِتھ۔\n5. میہ کیازِ وچھ تم مایوس {تہٕ} واپس پھیرۍ؟ تہٕ تِہٕندِس طاقتور چھِ مارنہٕ آمٕتۍ، تہٕ ژٔلِتھ ژٔلِتھ، تہٕ پتھ کُن چھُنہٕ وُچھان: {کیازِ} چھُ خوفہٕ اندۍ پٔکھۍ دِنہٕ آمُت، خداوند چُھ فرماوان۔ {مارنہٕ آمُت...: ہیب۔ ٹکڑن منز پھُٹمُت} {ژل...: ہیب۔ پروازٕ ژوٚل}\n6. تیز رفتار ژلُن نہٕ تہٕ نہ ژلُن طاقتور انسان۔ تِم گژھن ٹھوکر کھسان تہٕ دریائے فرات کِس شمالس کُن وسن۔\n7.\\tیہ {یُس} کُس چھہ سٔہلاب سٍتـ̡ وۅتھان یێمہِ سُند آب دریاوَن ہٕندِس پٲٹھـ̡ منتقل سپدان چُھ؟\n8. مصر چُھ سٔلابن ہٕندۍ پٲٹھۍکھسان، تہٕ {تٔمِس} آب چُھ دریاوَن ہٕندۍ پٲٹھۍ۔ تہٕ سُہ چُھس ونان زِ بہٕ گژھہٕ تھوٚد، {تہٕ} کرٕ زمینہٕ ؤلِتھ۔ بہٕ کٔرٕ شہر تہٕ اَتھ کِس روزن وٲلِس تباہ ۔\n9.\\tیۅہے گُرۍ، یۅہے گُرۍ۔ تہٕ غصہٕ، اے رتھ؛ تہٕ طاقتور نفر گژھن نیبر۔ ایتھوپیا تہٕ لیبیا ہٕکۍ باشندٕ، یِم ڈھال سنبھالان چھِ؛ تہٕ لیڈین، یم ہینڈل {تہٕ} کمانس موڑان چِھ۔ {ایتھوپیا: ہیب۔ کُش} {لیبیا: ہیب۔ پُٹ}\n10.\\tیِہ چُھ خداوند خدایہ سُند دۅہ، یُس انتقامُک دۅہ، یُس سُہ پننین دشمنن ہُند انتقام نِنہٕ ییہِ، تہٕ تلوار گژھہِ کھٮ۪نہٕ، تہٕ یہِ گژھہِ تسٕندِس خونہٕ سٍتـ̡ شراب، تکیازِ خداوند خدایہ سُند دٔرِ شُمٲلی مُلکس مَنٛز دریائے فرات کِس نِش قربانی دِنہٕ۔\n11.\\tجلعادس مَنٛز گژھ تہٕ اے کنوارِی، مصرٕچ کورِ بام، بیکار گژھ واریاہ دواہ استعمال۔ {تکیازِ} ژیہ گژھہِ نہ ٹھیک سپدِتھ۔ {توے کرُن...: ہیب۔ تۅہہِ گژھہِ نہ کانہہ علاج}\n12. قومن چُھ تُہٕنزِ شرمندگی ہٕنز خبر بوزمٕژ، تہٕ تُہٕنزِ فریاد چھے زمینہٕ بٔرِتھ بٔرِتھ، تکیازِ طاقتور انسان چُھ طاقتورن خلاف ٹھوکر کھٲلِتھ تہٕ تِم گٔیہِ دۅشوے اِکہٕ وٹہٕ۔\n13.\\tسُہ کلام یُس خداوند یرمیاہ پیغمبرس سٍتـ̡ وونمت چُھ، کِتھہ پٲٹھـ̡ گژھہِ بابلُک بادشاہ نبوکدرِززار یُس مصر کِس سرزمینس پیٹھ مارُن۔\n14.\\tمصرس مَنٛز اعلان کرُن، تہٕ مگڈولس منز شایع کرُن، تہٕ نوفس تہٕ تہپانس منز شایع کرُن: وَنُن زِ یُس رٔٹِتھ روزُن تہٕ تیار کرُن۔ تکیازِ تلوار گژھہِ ژیہ اندۍ پکھۍ کھیوان۔\n15.\\tچانۍ بہادر کیازِ چھہِ ژٔلۍمٕتۍ؟ تِم ٲسۍ نہٕ کھڑا گٔژھمٕتۍ، تِکیازِ خداوند اوس تِم کڈان۔\n16.\\tتٔمۍ کٔر واریاہ پیوٚو، آ، اَکھ پیوٚو أکِس پیٹھ، تہٕ تِمو ووٚن، وۅتھٕ وُتھ، تہٕ أسۍ گژھو پننین لوکن کُن، تہٕ پننہِ پیدائشہٕ کِس سرزمینس کُن، ظالمانہ تلوار پیٹھ۔ {بنیومُت...: ہیب۔ فالر کٔر ضرب دِنہٕ}\n17.\\tتِمو کٔر اَتہِ وُن، فرعون یُس مصرُک بادشاہ چُھہ اَکھ شور۔ تٔمۍ کوٚر مقرر کرنہٕ آمُت وقت۔\n18.\\tبادشاہ چھہ ونان یمۍ سُند ناو {چُھ} لشکرن ہُند رب چُھ، یٔمۍ سُند ناو چُھہ لشکرن ہُند رب تہٕ سمندرٕ کِس بٔٹھِس پٲٹھۍ، سُہ یِتھ کٔنۍ یِیہِ سُہ یِنہٕ۔\n19.\\tاے مصرس منز روزن واجنہِ کورِ، قٲد کرنہٕ خٲطرٕ کرو پان تیار، تکیازِ نوف گژھہِ کُنہِ بسکینس ورٲے ویران تہٕ ویران۔ {فرنش...: ہیب۔ ژے بناو قیدکۍ آلات}\n20. مصر {چُھ} سٮ۪ٹھاہ منصفانہ گاو ، {مگر} چھُ تباہی سپدان۔ یہٕ چُھ شمالہٕ پیٹھہٕ نیران۔\n21.\\tتٔمۍ سٕندِس کرایہ دار مرد تہِ چھِ أمِس منزٕ موٚٹۍ بیلن ہٕندۍ پٲٹھۍ۔ تکیازِ تِم تہِ آیہ واپس پھیرنہٕ، {تہٕ} چھِ اِکہٕ وٹہٕ ژلنہٕ آمٕتۍ: تِم ٲسۍ نہٕ کھڑا گٔمٕتۍ، تکیازِ تِمن ہٕنزِ آفتُک دۅہ اوس تِمن پیٹھ آمُت، {تہٕ} یِمن ہٕندِ ملاقاتُک وق۔ {موٹ...: ہیب۔ سٹالٕکۍ بیل }\n22. اَمہ سٕنز آواز گژھہِ ناگ ہٕندۍ پٲٹھۍ۔ تِکیازِ تِم گژھن أکِس لشکرس سٍتۍ پیش قدمی کٔرِتھ، تہٕ لٔکرِ ہٕندۍ پٲٹھۍ کلہٕ ہٮ۪تھ أمِس خٕلاف۔\n23. خداوند چُھ ونان زِ تِم ژٹِن تٔمۍ سُند جنگل ژٹُن، حالانکہ یہِ ہیکہِ نہٕ تلاشی دِتھ۔ تکیازِ یم چھہِ ٹڈۍ کھۅتہ زیادہ تہ {چھہِ} بے شمار۔\n24. مصرٕچ کورِ گژھِ پریشان کرنہٕ۔ سۅ ییہ شمالہٕ کین لوکن ہٕندِس اتھس منز دِنہٕ۔\n25. لشکرن ہُند خدا، اسرٲیلُک خدا، چُھ ونان؛ وچھ بہٕ دِیہ نو، فرعون تہٕ مصرس تہٕ تِہندین دیوتاہن تہٕ بادشاہن سٍتـ̡ سزا۔ حتیٰ کہ فرعون، تہٕ {سارِنٕے} تِم یِم أمِس پیٹھ بھروسہٕ کران چھِ: {کثیر: یا، پرورش کَرُن: ہیب۔ Amon}\n26. تہٕ بہٕ دِیہ تِم تِمن ہٕندِس اتھس مَنٛز یِم پنٕنۍ جان ژھاران چھِ، تہٕ بابل کِس بادشاہ نبوکدرِزر سٕندِس اتھس منز، تہٕ تٔمۍ سٕندِس خادمَن ہٕندِس اتھس مَنٛز۔\n27. مگر اے میانہِ بندہ یعقوب، تہٕ اے اسرٲیل، تہٕ گژھ نہٕ خوفزدہ گژھُن، تکیازِ بہٕ کرٕ ژے دوٗرِ نِش تہٕ تُہند اولادٕ تِہٕندِ قید نِش بچاو۔ تہٕ یعقوب گژھہِ واپس، تہٕ آرام تہٕ آرام سان روزُن، تہٕ کانہہ تہِ گژھہِ نہٕ تس خوفزدہ کرنہٕ۔\n28.\\tاے یعقوب میانہِ بندہ، خداوند چُھ ونان زِ بہٕ چُھس ژے سٍتـ̡ سٍتـ̡ خوفزدہ گژھُن، یێلہِ چُھس بہٕ چُھس ژے سٍتـ̡ ۔ تِکیازِ بہٕ کَرٕ تِمن سارِنٕے قومن ہُند پوٗرٕ خاتمہٕ ییتہِ بہٕ ژےٚ ژٔلِمٕژ چھِ، مگر بہٕ کَرٕ نہٕ ژےٚ پوٗرٕ پٲٹھۍ، مگر بہٕ کَرٕ ژےٚ پوٗرٕ پٲٹھۍ۔ توتہِ تراوٕ نہٕ بہٕ ژےٚ پوٗرٕ پٲٹھۍ سزا ورٲے ۔ {نہ تراوُن...: یا، ژیہ نہ ژیہ مکمل طور ژٹ}","1. خداوند سُند کلام یُس یرمیاہ پیغمبرس فلسطینن خلاف آو تہ امہ برونہہ زِ فرعون غزہ ہس پیٹھ حملہ کرُن۔ {غزہ: ہیب۔ عزا}\n2. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ وچھ آب چُھ شمالہٕ کِنۍ وۅتھان تہٕ یُس سٔہلاب آسہِ، تہٕ زمینہٕ تہٕ اَتھ منز موجود سارِنٕے چیزن ہٕندِس سٍتـ̡ وسان چُھہ؛ شہر، تہٕ تِم یِم اَتھ منز روزان چھِ: تیلہٕ گژھن مرد کرٛٮ۪کہٕ، تہٕ زمینٕکۍ سٲری روزن وٲلۍ۔ {یہ سورُے...: ہیب۔ امچ مکمل آسن}\n3.\\tتٔمۍ سٕندِس مضبوٗط گُرٮ۪ن ہٕندِس کھورِ ہٕندِس شورس پیٹھ، تٔمۍ سٕندٮ۪ن رتھن ہٕندِس گڑبڑس پیٹھ، تہٕ تٔمۍ سٕندِس چکرَن ہٕندِس گڑبڑس پیٹھ، مٲلۍ چھِنہٕ اَتھن ہٕنزِ کمزوری ہٕندِس کُن پتھ کُن نظر۔\n4. یُس دۅہہ یُس سارنٕے فلسطینی خراب کرنہٕ خٲطرٕ یُس یُس سارِنٕے فلسطینی بُلاونہٕ خٲطرٕ یُس تہٕ یُس باقی روزُن چُھہ تیروس تہٕ زیدون نِش ژٹنہٕ یِوان، تکیازِ خداوند کرِ فلسطینی بُلوٹ یُس کۅفتور کِس ملکُک باقیمانہٕ آسہِ۔ {ملک: ہیب۔ جزیرٕ}\n5.\\tغزہ ہس منز چھہ گنج آمت۔ اشکلون چُھ تِہٕنزِ وادی ہٕندِس باقیاتس سٍتـ̡ ژٹنہٕ آمُت: ژے کوتاہ کالس ژٔٹِتھ؟\n6. اے خداوند سٕنز تلوار، ژٕ کوتاہ کال روزِ ژھۄپہٕ؟ پنُن پان تھوٚوُن پننِس کھالس منز، آرام کرُن تہٕ خاموش روزُن۔ {پُٹ...: ہیب۔ پان جمع کٔرِو}\n7.\\tیہ کتھہ پاٹھۍ ہیکہِ ژھۅپہ کٔرِتھ، یہ وچھتھ زِ خداوند چھہ اتھ اشکلون تہ سمندر بٹھس خلاف الزام دژمُت۔ تتہِ چھہ سہ مقرر کورمت۔ {کتھہ پاٹھۍ...: ہیب۔ ژیہ کتھہ پاٹھۍ ہیکو کٔرتھ}","1. موآبس خلاف چُھ یِتھٕ پٲٹھـ̡ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھہ ونان ۔ نیبو ہُند افسوس! تکیازِ یہ چھہ خراب گومُت: کریاتھیم چھہ پریشان {تہٕ} نِنہٕ آمُت: مِسگاب چھُ پریشان تہٕ مایوس۔ {مِسگاب: یا، تھدِ جاے}\n2.\\tموآب سٕنز تعریفٕ گژھہِ نہٕ کرنہٕ: ہیشبونس منز چھُ تمو اتھ خلاف بُرٲیی ہٕنز منصوبہ بندی کٔرمٕژ۔ آ تہ اسۍ کرو یہ اکھ قوم بننہ نشہِ ژٹان۔ تہٕ ژے گژھ ژٹنہٕ یِن، اے پاگل۔ تلوار کرِ ژےٚ پتہٕ۔ {ژٹُن...: یا، ژھۄپہٕ کٔرِو} {تعاقب...: ہیب۔ پَتہٕ گٔژھِو}\n3.\\tہرونیم سٍتـ̡ چُھہ کُنہِ سٍتـ̡ وُپھ کٔرِتھ تہٕ بٔڈ تباہی۔\n4. موآب آو تباہ کرنہٕ۔ تٔمۍ سٕنٛدٮ۪و لۄکٹٮ۪و شُرۍ چھِ کرٛٮ۪کھ بوزنہٕ آمٕژ۔\n5.\\tتکیازِ لوہِتھ کِس کھسنہٕ سٍتـ̡ چُھہ لگاتار روُن ہُران۔ تکیازِ ہورونیم کِس وسنس منز چُھ دشمنن تباہی ہٕنز کرٛٮ۪کھ بوزمٕژ۔ {مسلسل...: ہیب۔ روُن وُن}\n6. ژٔلِو، پنٕنۍ زُو بچٲوِو، تہٕ بیابانن ہٕندِس پٲٹھۍ۔ {دی ہیتھ: یا، اکھ ننگہٕ کُل}\n7. کیازِ ژے چُھہ پننین کامین تہٕ پننین خزانن پیٹھ بھروسہٕ کورمُت، تہٕ کیموش گژھہِ پننین پادٕرین تہٕ شہزادن سٍتـ̡ یکوٹہ قٲد کرنہٕ۔\n8. تہٕ خراب کرن وول گژھہِ پرٮ۪تھ شہرس پیٹھ یِنہٕ، تہٕ کانہہ تہِ شہر ژلہِ نہٕ: وادی تہِ گژھہِ تباہ تہٕ میدانی گژھہِ برباد کرنہٕ، یِتھ کٔنۍ خداوند چُھ کتھ کٔرمٕژ۔\n9. موآبس دِیُن پَکھہٕ، یُتھ سُہ ژلِتھ ژلِتھ ژٔلِتھ تہٕ یِمن ہٕندِس شہر گژھن ویران تہٕ یِمن منز روزنہٕ خٲطرٕ آسہِ نہٕ۔\n10. یُس خداوند سٕنز کٲم دھوکہ دِتھ کرِ، تہٕ یُس تلوار خونہٕ نِش واپس تھاوان چُھ، سُہ چُھ لعنت۔ {دھوکہ دِتھ: یا، لاپرواہی سان}\n11. موآب چُھ جوانی پیٹھے آرام گومُت، تہٕ سُہ چُھ نہٕ پنہٕ نِس لٔگِس پیٹھ آباد گومُت، تہٕ چُھنہٕ سُہ بانہٕ پتہٕ بٔنِتھ خٲلی گومُت، تہٕ نہ چُھ سُہ قٲد گومُت، تێمہِ مۄکھٕ چُھ تٔمِس مَنٛز تٔمِس ذوق تہٕ تٔمۍ سٕنز خوشبو چُھنہٕ بدلان۔ {باقی: ہیب۔ کھڑا}\n12. تێمہِ وِزِ وُچھِو یِم دۅہ یِن، خداوند چُھ ونان زِ بہٕ سوزٕ أمِس نِش آوارٕ یِن، یُس أمِس پھیُرِ پھُراونہٕ یِن، تہٕ تٔمۍ سٕندِ بانہٕ خٲلی کرِ، تہٕ تِہٕنزِ بوتلہٕ پھُٹراوٕنۍ۔\n13.\\tتہٕ موآب گژھہِ کیموشس سٍتـ̡ شرمندٕ، یِتھ کٔنۍ زَن اسرٲیلُک گرٕ اوس بیتھل سٍتـ̡ تہندِس اعتقادس سٍتـ̡ شرمندہ گومُت۔\n14.\\tتۅہہ کتھہ پاٹھۍ چھہ ونان زِ اسۍ چھہِ جنگہ خاطرہ طاقتور تہ مضبوط نفر؟\n15. موآب چُھ خراب گومُت، تہٕ چُھ تٔمۍ سٕندِس شہرو منزٕ ہیوٚت، تہٕ تٔمۍ سٕندِ منتخب جوان گٔیہِ ذبح کُن بۄن، بادشاہ چُھ ونان یٔمۍ سُند ناو چُھ لشکرن ہُند رب ۔ {امس...: ہیب۔ انتخاب}\n16.\\tموآب سُند آفت چھُ یِنہٕ وٲلِس نزدیک، تہٕ تٔمۍ سُند مصیبت چھُ جلدٕے وُچھان۔\n17.\\tیُس أمِس اندۍ پکھۍ چھُو، تٔمِس سٍتـ̡ ماتم کٔرِو۔ تہٕ تم سٲری یُس تٔمۍ سُند ناو زانان چُھ، وَنُن زِ مضبوٗط لاٹھہٕ کِتھہ کٔنۍ پھُٹمُت، {تہٕ} خوبصورت لاٹھ!\n18.\\tژے کورِ یۅسہٕ دِبنس منز روزان چھےٚ، پننہِ جلال منزٕ بۄن تہٕ بِہِتھ پیاسہٕ سٍتـ̡ ۔ تکیازِ موآبُک خراب کرن وول گژھہِ توے پیٹھ، {تہٕ} سُہ کرِ تُہند مضبوط گڑھ تباہ کرنہٕ۔\n19.\\tاے آروئر کِس بسکین، وتہِ کھٔرِتھ تہٕ جاسوس۔ أمِس پرژھہٕ سُہ ژلُن، تہٕ یُس ژلان چُھ، {تہٕ} وَنُن، کیا چُھ گومُت؟ {بسکین: ہیب۔ بسکین}\n20. موآب چُھ پریشان گومُت۔ تکیازِ یہ چھہ پھُٹمُت: کۅکرِ تہٕ کۅکر؛ آرنونس منز ونو یہ زِ موآب چھہ خراب گومُت،\n21.\\tتہٕ چُھہ میدانس پیٹھ فیصلہ سپدان۔ ہولونس پیٹھ، تہٕ جاہزاہس پیٹھ، تہٕ میفاتھس پیٹھ،\n22. تہٕ دیبون پیٹھ، تہٕ نیبو پیٹھ، تہٕ بیت دیبلتھیمس پیٹھ،\n23. تہٕ کریاتھیمس پیٹھ، تہٕ بیت گملس پیٹھ، تہٕ بیت میونیس پیٹھ،\n24.\\tتہٕ کیریوت پیٹھ، بوزرہ پیٹھ، تہٕ موآب کِس سرزمینہٕ کِس سارنٕے شہرن پیٹھ، دور یا نزدیک۔\n25. موآب سُند سینگ چُھ ژٹنہٕ آمُت، تہٕ تٔمۍ سٕنز نٔر چُھ پھُٹمٕژ، خداوند چُھ فرماوان۔\n26.\\tأمِس کٔرِو شرابہٕ، تکیازِ تٔمۍ کٔر خداوند سٕندِس خٕلافس سٍتـ̡ پانس سٍتـ̡ بٔرِتھ تہٕ سُہ تہِ گژھہِ طنز کرنہٕ۔\n27.\\tکیازِ اسرٲیلِس اوس نہٕ تۅہہِ سٍتـ̡ طنز کٔرِتھ؟ کیا سُہ اوسا چورن منٛز لبنہٕ آمُت؟ تکیازِ ییلہ ژیہ أمس متعلق کتھ کٔر، ژیہ ژٔلِتھ ژٔلِتھ۔ {skippedst...: یا، Movedst thyself}\n28.\\tاے یُس موآبس منز روزان چھُ، شہر ترٲوِتھ کٔنہِ کٔنہِ منز روزُن، تہٕ کۅتر ہٕندۍ پٲٹھۍ{یُس} گٔژھِتھ چھُ۔\n29.\\tاسہِ بوز موآب سُند غرور، تٔمۍ سُند غرور تہٕ تکبر تہٕ تٔمۍ سٕندِس دِلُک غرور۔\n30. خداوند چُھ ونان زِ بہٕ چُھس تٔمۍ سُند قہر زانان۔ مگر {یہٕ آسہٕ} نہٕ {be} تہٕ؛ تٔمۍ سُند اپُز گژھِ نہٕ تیوٗت اثر۔ {تہند اپُز...: یا، یمن پیٹھ سُہ روزان چُھ (Heb. تہند بار) چُھ نہٕ صحیح}\n31. تێمہِ کِنۍ کٔرٕ بہٕ موآب خٲطرٕ کرٛٮ۪کہٕ دِنہٕ، تہٕ بہٕ کَرٕ سارِنٕے موآبَس خٲطرٕ فریاد دِنہٕ۔ {میون دِل} کرِ کرہیرس کین مردن ہُند ماتم ۔\n32.\\tاے سِبمہِ ہٕندِس وُپھ سٍتـ̡ چُھس ژے روُن: چانہِ کُلۍ گٔیہِ سمندرس منز، تِم وٲتِتھ چھِ سمندرس تام وٲتِتھ، یێلہِ تہٕ تۅہہِ ہٕندِس سمندرس سٍتـ̡ ووت تہٕ تۅہہِ ہٕندِس سمندرس پیٹھ۔\n33.\\tتہٕ خوشی تہٕ خوشی چھِ وافر میدانہٕ تہٕ موآب کِس سرزمینہٕ پیٹھٕ نِنہٕ یوان۔ تہٕ مے کٔر شراب پریسَو منزٕ شراب: کانٛہہ تہِ گژھِ نہٕ کرٛٮ۪کہٕ دِنہٕ سٍتۍ۔ {تِہُند} کرٛٮ۪کہٕ دِنہٕ چُھ نہٕ کُنہِ کرٛٮ۪کہٕ دِنہٕ آمُت۔\n34.\\tہیشبون سٕنزِ فریاد پیٹھٕ الیعلہ تام {تہٕ حتیٰ کہ} جہازس تام، تِمو کٔر پننہ آواز، زوار {حتی} پیٹھہٕ حورونیم تام، {یِتھ} تریہ ؤری وٲنسہِ ہُند گاو تہِ، تکیازِ نمرمُک آب تہِ گژھہِ ویران۔ {ویران : ہیب۔ ویرانی}\n35. امہِ علاوہ کرٕ بہٕ موآبس منز بند کرُن، خداوند چُھ ونان یُس تھدٮ۪ن مقامن پیٹھ پیش کران چُھ، تہٕ یُس پننین دیوتاہن خٲطرٕ بخور زالان چُھ۔\n36.\\tتێلہِ چُھہ میون دِل موآب سٕندِ خٲطرٕ پایپٕکۍ پٲٹھۍ، تہٕ میون دِل کرہیرس کین مردن ہٕندِ خٲطرٕ پایپٕکۍ پٲٹھۍ، تکیازِ یُس دولت أمِس حٲصل سپدِ، سُہ چُھ ختم گٔمُت۔\n37.\\tپرٮ۪تھ کلہٕ آسہِ ٹَکٕرِتھ تہٕ پرٮ۪تھ کُنہِ داڑھ آسہِ: سارِنٕے اَتھَن پیٹھ تہٕ کُنہِ {کلپڈ: ہیب۔ کم گومُت}\n38.\\tموآب کین سارنٕے گرن تہٕ تِمن ہٕنزن سڑکن پیٹھ گژھہِ عام طور ماتم کرنہٕ، کیازِ میہ چُھ موآب أکِس برنہٕ ہٕندۍ پٲٹھۍپھُٹرٲومُت یتھ منز نہٕ کانہہ خوشی آسہِ، خداوند چُھ فرماوان۔\n39.\\tتِم کٔرِن کۅکر، {ونن}، یہ کِتھہ پٲٹھۍپھُٹ! موآب کِتھہ کٔنۍ چھُ شرم کٔرِتھ پتھ کُن پھیُرُن! یتھے پاٹھۍ گژھہِ موآب تس متعلق سارِنٕے خٲطرٕ طنز تہٕ مایوسی۔ {واپس: ہیب۔ گردن}\n40. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ وچھ سُہ وُڑان عقاب سٕندۍ پٲٹھۍ، تہٕ موآبس پیٹھ پنٕنۍ پکھہٕ پھٔہلٲوِ۔\n41.\\tکیروتھ آو نِنہٕ، تہٕ مضبوطہٕ گٔیہِ حٲران تہٕ تمہِ دۅہہ آسہِ موآبس مَنٛز طاقتور مردن ہُند دِل أکِس زنانہِ ہٕندِس دِلٕکۍ پٲٹھۍ۔ {کیریوتھ: یا، شہر}\n42.\\tتہٕ موآب گژھہِ اکھ قوم آسنہٕ سٍتـ̡ تباہ کرنہٕ، کیازِ تٔمۍ چُھ خداوند سٕندِس خلاف پانس بٔرِتھ۔\n43.\\tخوف، تہٕ کھۅپھ تہٕ جال، اے موآب کِس بسکین، خداوند چُھ فرماوان۔\n44.\\tیُس خوفہٕ نِش ژلِتھ آسہِ سُہ گژھہِ کھۅنہِ مَنٛز پیوٚو۔ تہٕ یُس کھۅنہٕ منزہ نیرِ، سُہ گژھہِ جالس منز نِنہٕ، تکیازِ بہٕ اَتھ پیٹھ اننہٕ، موآبس پیٹھ، یُس تِہٕندِ زیارت ہُند ؤری تہِ، خداوند چُھ فرماوان۔\n45.\\tیِم ژٔلِتھ ژٔلِتھ گٔیہِ ہشبون سٕندِس ژھایہِ تل کھڑا، مگر ہیشبون منزٕ نیرِ نار تہٕ سِہون کِس درمِس منزٕ اکھ نار نیرِ، تہٕ موآب کِس کونس تہٕ ہنگامہ خیز لوکن ہٕندِس کلہٕ سُند تاج کھٮ۪یہِ۔ {ہنگامہٕ...: ہیب۔ شورٕکۍ بچہٕ}\n46.\\tاے موآب، ہا ہا! کیموشٕکۍ لوٗکھ چھِ ختم گٔمٕتۍ: تِکیازِ تُہند نیچو چھِ قٲد کرنہٕ آمٕتۍ، تہٕ تُہٕنٛزِ کورِ چھِ قٲد کرنہٕ آمٕژ۔ {قید، تہٕ: ہیب۔ قیدَس مَنٛز، وغیرہ}\n47. توتہِ اَنہٕ بہٕ پٔتِمِس دۅہس مَنٛز موآبُک قید دُبارٕ اَننہٕ، خداوند چُھ فرماوان۔ وُنیُک تام چُھ موآب سُند فیصلہٕ۔","1. عمونیتس متعلق، خداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ اسرٲیلِس چھا نہٕ نیچوۍ؟ أمِس چھا نہٕ کانٛہہ وٲرِث؟ تِہُند بادشاہ کیازِ چُھ گاد سُند وٲرث، تہٕ تٔمۍ سٕندِ لُکھ چھِ تٔمۍ سٕندِس شہرن منز روزان؟ {متعلقہ: یا، خلاف} {تہند بادشاہ: یا، میلکوم}\n2. تێمہِ کِنۍ، وُچھِو یِم دۅہ یِن، خداوند چُھ ونان زِ بہٕ کرٕ عمونین ہٕندِس رباہس مَنٛز جنگُک الارم بوزنہٕ۔ تہٕ یہِ گژھہِ ویران ڈھیر، تہٕ تٔمۍ سٕنزِ کورِ یِن نارٕ سٍتـ̡ زالنہٕ، تیلہِ گژھہِ اسرٲیلِس تِمن ہُند وٲرِث یِم أمۍ سٕندِ وٲرِث ٲسۍ، خداوند چُھ فرماوان۔\n3.\\tاے ہیشبون، اے ہشبون، کیازِ اے چھُ خراب گومُت: رَب سٕنزِ کورِ، رَب سٕنزِ کورِ، ژے کٔرِو بُرِ کُلِس سٍتـ̡ رٔلِتھ۔ ماتم کٔرِتھ، تہٕ لٔگِس کٔرِتھ یور کُن ژلان۔ تِکیازِ تِہُند بادشاہ گژھِ قٲد کرنہٕ، تہٕ تٔمۍ سٕندِ پادٕرۍ تہٕ تٔمۍ سٕندِ شہزادٕ یکوٹہٕ۔ {تہند بادشاہ: یا، میلکوم}\n4.\\tژے کیازِ چھے وادی منز، پننہِ وسوٕنۍ وادی منز، اے پتھ کھسنہٕ واجنہِ کورِ۔ یُس پننِس خزانس پیٹھ بھروسہٕ اوس، {ونان}، کُس واتہِ میانہِ نِش؟ {تۅہہِ...: یا، چانۍ وادی چھیہ وسان ژلان}\n5. یێلہِ چُھس بہٕ ژے سٍتـ̡ خوف پٲدٕ کٔرِتھ، یێلہِ سٍتـ̡ سارِنٕے سٍتـ̡ یێلہِ سٍتـ̡ چُھہ یێلہِ سٍتـ̡ خدایہِ سٍتـ̡ دِنہٕ آمُت۔ تہٕ یِیہِ پرٮ۪تھ أکِس نفرس کٔڑِتھ کڑنہٕ۔ تہٕ یُس بھٹکُن آسہِ نہٕ کانہہ تہِ جمع کٔرِتھ۔\n6. تہٕ اَمہِ پتہٕ اَنہٕ بہٕ اَمون سٕندٮ۪ن شُرین ہُند قٲد دُبارٕ، خداوند چُھ فرماوان۔\n7.\\tادوم سٍتـ̡ چُھہ یِتھٕ پٲٹھـ̡ لشکرن ہُند رب فرماوُن؛ {کیا} تیمانس منز چھا نہ ونہِ کانہہ دانش؟ وکیل چھا ہوشیار نِش ختم؟ کیا تہنز عقل چھا ختم؟\n8. ژٔلِو، واپس پھیرِو، سٔنِس سٍتـ̡ روزُن، اے دیدانٕکۍ بسکین۔ تکیازِ بہٕ اَنہٕ تس پیٹھ عیسو سٕنز آفت، تمہ وقتہٕ یُس بہٕ أمس نِش گژھہِ۔ {turn...: یا، تم چھہِ واپس پھیرنہ آمت}\n9.\\tاگر گرپیگیتھرس نِش یِن تۅہہِ نِش یِنہٕ تِم {کیٚنٛہہ} انگور تراوُن؟ اگر راتس ژور آسہِ، تِم چھِ توٚت تام تباہ کٔرِتھ یوٚت تام تِمن کٲفی آسہِ۔ {tiltil...: Heb. تہنز کافی}\n10.\\tمگر مے چُھس عیساو نِش بٔنِتھ تہٕ تٔمۍ سٕندِس بٲے تہٕ ہمسایہ تہٕ سُہ چُھہ نہٕ ژوٗرِ روزِتھ۔\n11. پَنٕنـ̡ بٔرِتھ بَچِھہٕ بێیہِ شُرۍ، بہٕ رژھرٕ تِمن زِندٕ۔ تہٕ چانۍ بیواہ گژھن میہ پیٹھ بھروسہٕ۔\n12. یِتھٕ پٲٹھۍ چُھ خداوند فرماوان۔ وُچھِو، یِمن ہُند فیصلہٕ پیالہ چُھنہٕ یِمن ہُند فٲصلہٕ اوس یِمن ہُند پیالہ چُھنہٕ یِمن ہُند فٲصلہٕ چُھ، تِمو چُھ یقینا شراب۔ تہٕ {art} کیا تۅہہ {یُس} گژھہِ پوٗرٕ پٲٹھۍ سزا دِنہٕ؟ ژیہ گژھہِ نہ سزا ورٲے مگر ژیہ گژھہِ یقینا اتھ منز پییہِ۔\n13. کیازِ میہ چُھ پانَے قسم، خداوند چُھ ونان زِ بوزرہ گژھہِ ویرانی، ملامت تہٕ لعنت۔ تہٕ تِمن ہٕندۍ سٲری شہر گژھن دائمی فضلہٕ۔\n14. مے چُھ خداوند سٕندِ طرفہٕ اکھ افواہ بوزمٕژ، تہٕ اکھ سفیر آو کافرن نِش سوزنہٕ، {ونُن}، تم جمع کرو تہٕ أمس خلاف یِن تہٕ جنگس تام ووتھُن۔\n15.\\tکیازِ، بہٕ بناوٕ ژے کافرن منز لوکُٹ، {تہٕ} انسانس مَنٛز حقارت کرنہٕ۔\n16. چانہِ ہولناکی چُھہ ژے دھوکھہٕ دِژمُت، تہٕ چُھہ تُہٕندِس دِلُک غرور، اے ژے یُس کنہِ کُنہِ کُنہِ دراڑس مَنٛز روزان چُھ، یُس بالہٕ ہُند تھزر چُھ، یودوَے ژے پنُن گرٕ عقاب ہیوٗ تھود بناوُن، بہٕ اَتہِ نِش بۄن کَرُن، خداوند چُھ فرماوان۔\n17.\\tاَتھ سٍتـ̡ تہِ گژھہِ اَمہ سٍتـ̡ یێلہِ بێیہِ تہٕ یێلہِ سٍتـ̡ سٍتـ̡ یێلہِ سٍتـ̡ وُپھ دِنہٕ یِنہٕ وٲلِس سٍتـ̡ گژھہِ حٲران تہٕ یێمہِ سٍتـ̡ سارِنٕے و\n18.\\tیِتھے پٲٹھـ̡ سدوم تہٕ عمورہ تہٕ ہمسایہ {شہر} ہٕندِس تختس مَنٛز، خداوند چُھ ونان زِ کانہہ تہِ انسان روزِ نہٕ اَتھ مَنٛز روزُن۔\n19.\\tوچھ سُہ گژھہِ اردن کِس ورمہٕ سٍتـ̡ شیرٕکۍ پٲٹھۍ، مگر بہٕ کرٕ اچانک أمِس نِش ژلناوُن: تہٕ کُس چُھہ {انسان} یُس بہٕ أمِس پیٹھ مقرر کٔرِتھ؟ میہ ہیو کُس {چُھ}؟ تہٕ کُس کرِ میہ وقت؟ تہٕ سُہ چرواہ کُس چُھ یُس میانہِ برونہہ کنہِ کھڑا آسہِ؟ {مے مقرر کٔرِو...: یا کٔرِو مے فٲصلس منز؟}\n20. تێمہِ کِنۍ بوزو خداوند سُند مشورٕ، یُس تٔمۍ ایڈومس خلاف رٔٹمُت چُھ۔ تہٕ تٔمۍ سُند مقصد یُس تٔمۍ تیمان کین بسکینن خلاف مقصود چُھ: یقینا کم از کم ریوڑ کرِ تِمن نٮ۪بر کڈنہٕ: یقینا سُہ کرِ تِمن سٍتۍ تِمن ہٕندِس بستی ویران۔\n21.\\tزمین چھیہ تِہندِ گرِ ہٕندِس شورس سٍتـ̡ ہلاونہٕ یوان، اَمہ کِس شورس سٍتـ̡ بوزنہٕ آمُت۔ {بحر احمر: ہیب۔ ویڈی سمندر}\n22.\\tوُچھِو سُہ وُڈِتھ وُڈِتھ بُزراہس پیٹھ پَنٕنہِ پَکھہٕ پھٔہلٲوِتھ، تہٕ اَمہِ دۅہہٕ گژھہِ ادوم کِس طاقتور مردَن ہُند دِل أکِس زنانہِ ہٕندِس دِلٕکۍ پٲٹھۍ۔\n23. دمشقس متعلق۔ حمتھ چھہ پریشان تہ ارپاد: تکیازِ تمو چھیہ بد خبر بوزمژ: تم چھہِ بے ہوش۔ سمندرس پیٹھ چھہ غم۔ یہ ہیکہِ نہ ژھۅپہ ٲستھ۔ {بے ہوش: ہیب۔ پگھلُن} {پیٹھ...: یا، یِتھ کٔنۍ سمندرس پیٹھ}\n24.\\tدمشقس چھہ کمزور سپدان، {تہِ} ژلنہ خاطرہ پھیران تہ خوفہ چھہ تس رٔٹتھ ژلان۔\n25. تعریفُک شہر کِتھہ کٔنۍ چُھنہٕ میانہِ خوشی ہُند شہر!\n26. تێمہِ کِنۍ گژھن تٔمۍ سٕندِس سٍتـ̡ جوان تٔمۍ سٕنزِ سڑکہِ مَنٛز پٔسِن، تہٕ اَمہ دۅہہٕ گژھن سارِنٕے جنگی مرد ژٹنہٕ، لشکرن ہُند رب چُھ فرماوان۔\n27. تہٕ بہٕ دَمشقٕچ دیوارس مَنٛز نار زالٕ تہٕ سُہ کرِ بن ہداد کِس محلس زال۔\n28.\\tکیدار سٍتـ̡ تہٕ حزور سٕندِس بادشاہس متعلق، یُس بابلُک بادشاہ نبوکدرِزر مارِ دِیہِ، یِتھٕ پٲٹھـ̡ چُھ خداوند فرماوان۔ وۅتھٕ وُتھ، کیدارس تام گژھ تہٕ مشرقٕکۍ نفر کرو بِلو۔\n29.\\tتِہٕندِ خیمہ تہٕ پَنٕنہِ پَنٕنہِ پَنٕنـ̡ پردٕ، تہٕ پَنٕنـ̡ پۯاونہٕ یِنـ̡ تہٕ تِم چِھ تِمن کُن فریاد دِوان، پریتھ طرفہٕ خوف {چُھ}۔\n30.\\tژٔلِو، ژٔلِو، دوٗر کٔرِو، سٔنِس سٍتـ̡ روزُن، اے حزورٕکۍ بسکین، خداوند چُھ فرماوان۔ تکیازِ بابلُک بادشاہ نبوکدرِزرن چُھ تۅہہِ خلاف مشورٕ کورمُت، تہٕ چُھس تۅہہِ خلاف اکھ مقصد تصور کورمُت۔ {گٔژھِو...: ہیب۔ سیٹھا پھِلُن}\n31.\\tوُتھ، وُچھِو تُہٕندِس مالدار قومس تام، یُس بے پرواہ روزان چُھ، خداوند چُھ ونان یُس نہٕ دروازٕ تہٕ نہ سلاخہٕ، {یُس} کُنی روزان چُھ۔ {دولت: یا، یہ چھہ آرام سان}\n32.\\tتہٕ تِہٕندِ اوُنٹھ آسہِ غنیمت تہٕ تِہٕندِ چارواین ہُند بٔڑِس بٔڑِس غُنیمتَس مَنٛز تہٕ بہٕ پھِرِتھ سارِنٕے ہواہن مَنٛز یِم سارِنٕے کُنَن مَنٛز چھِ۔ تہٕ بہٕ اَنہٕ تِہٕنزِ آفت سارِوٕے طرفہٕ اَننہٕ، خداوند چُھ فرماوان۔ {منز...: ہیب۔ کونن منز ژٹِتھ، یا یمن ہندۍ مس کُن کٔرِتھ چھہِ}\n33.\\tتہٕ حزور آسہِ ڈریگن ہٕندِ خٲطرٕ روزن گاہ، {تہٕ} ہمیشہٕ خٲطرٕ ویران روزُن، اَتھ منز روزِ نہٕ کانہہ انسان روزُن، تہٕ نہ روزِ کانہہ تہِ انسان سُند نیچو۔\n34.\\tخداوند سُند کلام یُس یرمیاہ پیغمبرس نِش یہوداہ کِس بادشاہ صیدقیاہ سٕندِس دورس مَنٛز ایلامس خلاف آو تہٕ وونُن:\n35. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب فرماوان۔ وچھ بہٕ پھٹراوٕ تہندِ طاقتُک سردار ایلام سُند کمان۔\n36.\\tتہٕ ایلامس پیٹھ اَننہٕ بہٕ ژۅن ژۅن ژۅن واو سٍتـ̡ تہٕ یِمن سارِنٕے ہواہن کُن پھٔہلِتھ ۔ تہٕ کانہہ قوم گژھہِ نہٕ ییتہِ ایلامٕکۍ بے دخل گژھن یِن۔\n37.\\tکیازِ بہٕ کرٕ ایلام تِہندِ دُشمنن برونہہ کُن تہٕ تِمن برونہہ کُن یُس تِمن ہُند جان ژھاران چُھ، تہٕ بہٕ کرٕ تِمن پیٹھ بُرٲے تہٕ یِمن سٍتـ̡ پنُن شدید غصہٕ تہِ، خداوند چُھ فرماوان۔ تہٕ بہٕ سوزٕ تلوار تِمن پتہٕ، یوٚت تام بہٕ تِم کھٮ۪نہٕ یِوان:\n38. تہٕ بہٕ بِہٕ پنُن تخت ایلامس مَنٛز بِہاونہٕ، تہٕ تتہِ کٔرٕ بادشاہ تہٕ شہزادن تباہ کرنہٕ، خداوند چُھ فرماوان۔\n39.\\tمگر یہ سپدِ ٲخری دۅہن منز، {یہِ} بہٕ اَنہٕ بییہِ ایلام سُند قید اَننہٕ، خداوند چُھ فرماوان۔","1. سُہ کلام یُس خداوند بابلس خلاف {تہٕ} یرمیاہ پیغمبرن کٔر کلدان زمینس خلاف کتھ کرنہٕ۔ {by...: ہیب۔ یرمیاہ سٕندِ اتھہٕ سٕتۍ}\n2. قومن مَنٛز اعلان کٔرِو، تہٕ شایع کٔرِو تہٕ اکھ معیار قٲیِم کٔرِو۔ شایع کٔرِتھ، {تہٕ} چھُ نہٕ ژوٗر کٔرِتھ: وَنُن، بابل چھُ رٹنہٕ آمُت، بیل چھُ الجھن، میروڈچ چھُ ٹُکرٕ ٹُکرٕ کٔرِتھ پھُٹمُت۔ تٔمۍ سٕنٛدۍ بُت چھِ الجھان، تٔمۍ سٕنٛزٕ شکلہٕ چھِ ٹُکرٕ ٹُکرٕ کٔرِتھ۔ {سیٹ اپ: ہیب۔ تُلُن کٔرِو}\n3.\\tتکیازِ شمالہٕ منزٕ چُھ أمِس خلاف اکھ قوم پٲدٕ سپدان، یُس تٔمۍ سٕنز زمین ویران کرِ، تہٕ اَتھ مَنٛز روزِ نہٕ کانٛہہ تہِ: تِم گژھن ہٹاونہٕ، تِم نیرِ، انسان تہٕ جانور دۄشوٕے۔\n4. یِمن دۅہن تہٕ تَمہِ وقتس مَنٛز، خداوند چُھ ونان زِ بنی اسرٲیل، تِم تہٕ یہوداہ ہٕکۍ بچہٕ یِکہٕ وَٹہٕ گژھن تہٕ روُن: تِم گژھن تہٕ خداوند سٕندِس خداہس سٍتـ̡ ژھانڈنہٕ۔\n5.\\tتِم گژھن صییون کُن وتھ پرژھن، {ونن}، آؤ، تہٕ أسۍ کرو خداوند سٕندِس سٍتـ̡ دٲیمی عہد {یُس} یُس نہٕ مشراونہٕ یُن۔\n6.\\tمیانہِ لُکہٕ گٔیہِ رٲوِمٕژ، تِہٕندِیو گٔیہِ تِم گَمراہ گٔمٕتۍ، تِمو چھِ تِم پَنٕنہِ آرام گاہ مٔشِد گٔمٕتۍ۔ {آرام کرنٕچ جاے: ہیب۔ لیٹنہٕ خٲطرٕ جاے}\n7.\\tیِمو سارِوٕے لٔبِتھ چُھہ تِم کھٮ۪نہٕ آمُت، تہٕ تِہٕندِیو مُخٲلِفن ووٚن زِ أسـ̡ چُھہ نہٕ گُناہ کٔرِتھ، کیازِ تِمو چُھ خداوند سٕندِس سٍتـ̡ گۅناہ کورمُت، یێلہِ تہٕ تِمن ہٕندِس مٲلِس سٕنزِ وۅمیدٕ سٍتـ̡ چُھہ خدایہِ سٕندِس سٍتـ̡ گۅناہ کورمُ\n8.\\tبابل منزہ نیرِو تہٕ کالدِین ہٕندِس سرزمینہٕ منزٕ نیرِو، تہٕ بٔنِتھ گژھِو ژھاوٕنـ̡ ہٕندِس پٲٹھۍ۔\n9. تکیازِ بہٕ کٔرٕ شمٲلی ملکہٕ پیٹھٕ بٔڈ قومن ہٕنز اکھ مجلس بابل ہس خلاف کھڑا تہٕ تِم کرٕ پانس خلاف صف بندی کرنہٕ۔ اتہِ پیٹھہ ییہ سۅ نِنہٕ: تِہٕندِ تیر گژھن أکِس طاقتور ماہر انسان سٕندۍ پٲٹھۍ۔ کانٛہہ تہِ گژھِ نہٕ بیکار واپس۔ {ماہر...: یا، تباہ کَرُن}\n10. تہٕ کلدیہ گژھہِ غنیمت: یُس أمس خراب کرِ، سُہ گژھہِ مطمئن، خداوند چُھ فرماوان۔\n11.\\tکیازِ تۅہہ ٲسکھ خۅش گٔمٕژ، اے میٲنۍ وراثتٕکۍ تباہ کرَن والۍ، تکیازِ تم چھِو گاسہٕ ہٕندِس پٲٹھۍموٚٹۍ گٔمٕتۍ، تہٕ بیلن ہٕندۍ پٲٹھۍ گٔژھمٕتۍ۔ {چربی: ہیب۔ بٔڈ، یا، کارپولنٹ} {بیلو...: یا، گُرِ ہٕندِس طورس پیٹھ}\n12.\\tچانہِ ماجہ گژھہِ پریشان گژھن۔ سُہ یُس تۅہہِ نٮ۪بر کٔرِتھ آسہِ شرمندٕ: وُچھِو، قومن ہٕندِس سارِوٕے کھۄتہٕ زیٛادٕ رُکاوٹ آسہِ بیابان، اکھ خشک زمین تہٕ اکھ صحرا۔\n13.\\tخداوند سٕندِ قہر سٍتـ̡ گژھہِ نہٕ آباد سپدُن، مگر یێلہِ گژھہِ یہِ پوٗرٕ پٲٹھـ̡ ویران گژھُن: یُس تہٕ یُس بابل کُن نیرِ، سُہ گژھہِ حٲران تہٕ تٔمِس سٍتـ̡ سارِنٕے آفتن ہٕندِس سٍتـ̡ ہُند شکار۔\n14.\\tپان ترٲوِو بابلس اندۍ پکھۍ صفہٕ: یُس کمان نِوان چھُ، تٔمِس کُن گولہٕ چلاوُن، تیر تراوُن نہٕ، کیازِ تٔمۍ چُھ خداوند سٕندِس خلاف گۅناہ کورمُت۔\n15.\\tأمِس اندۍ پکھۍ کٔرِو کرٛٮ۪کہٕ: تٔمۍ سٕنز بُنیاد گٔیہِ پٔسۍ، دیوارٕ گٔیہِ پٔرِتھ، تٔمۍ سٕندِ دیوارٕ گٔیہِ ؤسِتھ، تکیازِ یہِ چُھہ خداوند سُند انتقام: أمِس سٍتـ̡ کرُن انتقام۔ یتھہ پاٹھۍ تمۍ کرمژ چھیہ، تس کرُن۔\n16.\\tیُس بابل نِش ووپدُن وول تہٕ یُس فصلہٕ وِزِ دٲرِ رَٹان چُھ، ظٲلم تلوار کہِ خوفہٕ سٍتـ̡ ژٔٹِن تِم پرٮ۪تھ أکِس پننِس لوکَس کُن، تہٕ ژٔلِن پرٮ۪تھ أکِس پننہِ سرزمینس کُن۔ {دٲری؛ یا، دٲری}\n17. اسرٲیلؠ چھُ اَکھ بکھرِتھ کَرُن؛ شیرو ژٔلِتھ گۅڈٕ اَشورٕکۍ بادشاہن کھٮ۪نہٕ آمُت۔ تہٕ ٲخٕر کٔر بابلُک بادشاہ نیبوکدرِزارن پنٕنۍ أڈجہِ پھُٹرٲومٕژ۔\n18. تێمہِ کِنۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھہ وَنان۔ وچھ بہٕ دِیہ بابل کِس بادشاہس تہٕ تٔمۍ سٕندِس سرزمینس سزا، یِتھ کٔنۍ مے اسریاہٕکِس بادشاہس سزا دِژمٕژ۔\n19.\\tتہٕ بہٕ اَنِہ اِسرٲیلِس دُبارٕ تٔمۍ سٕندِس بَساہس مَنٛز، تہٕ سُہ کرِ کارمل تہٕ بشانَس کھٮ۪وان تہٕ تٔمۍ سُند روح گژھہِ کوہ افرائیم تہٕ جلعادس پیٹھ۔\n20. یِمن دۅہن تہٕ تَمہِ وقتس مَنٛز، خداوند چُھ فرماوان زِ اسرٲیلٕچ بدکاری ییہِ ژھارنہٕ، تہٕ {یێلہِ} آسہِ نہٕ۔ تہٕ یہوداہ سٕندِ گۅنہہ، تہٕ یِم گژھن نہٕ لبنہٕ: کیازِ بہٕ کٔرٕ تِمن معافی یِمن بہٕ رژھراوان چھُس۔\n21.\\tمیراتھیم کِس سرزمینس خٕلاف، تہٕ پیکوڈ کین بسکینن خٕلاف، تہٕ یِمن پَتہٕ کٔرِو برباد تہٕ پوٗرٕ پٲٹھۍ، خداوند چُھ فرماوان، تہٕ یُس میہ ژے حکم دِژمُت چُھ، تِمن سٍتـ̡ کٔرِو تِمن سٍتـ̡ کٔرِو۔ {میراتھیم: یا، باغین ہُند} {پیکوڈ: یا، وزِٹیشن}\n22.\\tزمینس منز چھہ جنگچ آواز تہ زبردست تباہی۔\n23.\\tسارِنٕے زمینہِ ہُند ہتھوڑا کِتھہ پٲٹھـ̡ ژٔٹِتھ پھُٹمُت! بابل کِتھہ پاٹھۍ چھہ قومن منز ویران بنیومُت!\n24.\\tمیہ چُھہ ژے خٲطرٕ اکھ جال بنوومُت، تہٕ ژے تہِ چُھکھ نِنہٕ آمُت، اے بابل، تہٕ ژے ٲس نہٕ خبر: تہٕ ژے چُھکھ لبنہٕ آمُت، تہٕ رٔٹنہٕ آمُت، کیازِ ژے چُھکھ خداوند سٕندِس خلاف کوشش کٔرمٕژ۔\n25. خداوند چُھ پَنُن ہتھیار کھولمُت، تہٕ چُھکھ پنٕنـ̡ شرارتٕکہِ ہتھیار کٔرِتھ، یێلہِ چُھہ چُھہ کلدانن ہٕندِس سرزمینس مَنٛز لشکرن ہٕندِس خدایہِ سٕنز کٲم۔\n26.\\tأمِس خٕلاف یِنہٕ سارِوٕے کھۄتہٕ زیادٕ سرحدٕ پیٹھ، تٔمۍ سٕندِس ذخیرٕ خانہٕ کھولُن: أمِس ترٛٲوِن ڈھیرس منز، تہٕ کرُن أمِس پوٗرٕ پٲٹھۍ تباہ کرنہٕ: أمِس گژھہِ نہٕ کانہہ تہِ باقٕے روزُن۔ {پیٹھ...: ہیب۔ ٲخرس پیٹھ} {کاسٹ ...: یا، ٹریڈ أمس}\n27.\\tتٔمۍ سٕندِس سارِنٕے بیل مارُن۔ تِم گژھن ذبح کُن: افسوس! تِہُند دۅہ چُھ آمُت، یِمن ہُند یِنُک وق۔\n28.\\tتِمن ہٕنز آواز یُس بابل کِس سرزمینہٕ منزٕ ژلان تہٕ ژلان چُھ، تِمن ہٕنز آواز یُس صیونس مَنٛز خداوند سُند انتقام، تٔمۍ سٕندِس مندرُک انتقامُک اعلان کرنہٕ مۅکھہٕ۔\n29.\\tبابل کِس خلاف کٔرِو تیر اندازن اِکہٕ وٹہٕ: یُس کمان نِوان چھُ، تِمو کٔرِو اَتھ اندۍ پٔکھۍ ڈیرٕ۔ اَمہ نِش گژھِ نہٕ کانہہ تہِ ژلُن: أمِس کامہِ مُطٲبق دِیُن معاوضہٕ؛ تٔمۍ سٕندِس سارِنٕے سٍتـ̡ کٔرِو أمِس سٍتـ̡ ناز کرنہٕ، کیازِ سُہ چُھ خداوند سٕندِس سٍتـ̡ نکُن ناز کٔرمُت، یێلہِ چُھہ اِسرٲیلِس مُقدسَس سٍ\n30. تێمہِ کِنۍ گژھن تٔمۍ سٕندِ جوان سڑکن مَنٛز پیوٚن، تہٕ تٔمۍ سٕندِس سارِنٕے جنگی نفر یِن تمہِ دۅہہٕ ژٹنہٕ، خداوند چُھ فرماوان۔\n31. وچھ بہٕ چُھس ژے خلاف، {اے ژے} سارِوٕے کھۄتہٕ زیادٕ ناز کٔرِتھ، خداوند لشکرن ہُند خدایہ چُھ ونان: تُہند دۅہ آو سُہ وق {یُس} بہٕ ژے نِش گژھُن۔ {زیادٕ...: ہیب۔ فخر}\n32. تہٕ سارِوٕے کھۄتہٕ زیادٕ مغرور گژھہِ ٹھوکر کھٔسِتھ تہٕ کانہہ تہِ تُلِتھ تہٕ بہٕ دِیہٕ تٔمۍ سٕندِس شہرس مَنٛز نار تہٕ سُہ گژھہِ تس اندۍ پکھۍ کھٮ۪نہٕ۔ {the...: ہیب۔ فخر}\n33. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب فرماوان۔ بنی اسرائیل تہٕ یہوداہ کِس اولادس آیہ اِکہٕ وٹہٕ ستاونہٕ: تہٕ یِمو سارِوٕے یِم قٲد کٔرۍ، تِمو رٔٹِتھ رٔٹِتھ ۔ تِمو کوٚر تِم تراونہٕ نِش انکار۔\n34. تِہُند نجات دِنہٕ وول {چُھ} مضبوط۔ لشکرن ہُند رب چُھ تٔمۍ سُند ناو: سُہ کرِ تِہٕندِس مقصدس سٍتـ̡ وُچھن، یُتھ سُہ زمینس آرام دِیہ، تہٕ بابل کین بسکینن پریشان کرِ۔\n35.\\tخداوند چُھ ونان زِ کلدینس پیٹھ تہٕ بابل کین بسکینن پیٹھ، تہٕ تٔمۍ سٕندٮ۪ن شہزادن تہٕ تٔمۍ سٕندِس دانشمندن پیٹھ۔\n36.\\tاکھ تلوار چھیہ اپزس پیٹھ۔ تہٕ تِم دِنہٕ یِن: اکھ تلوار {چُھ} پننِس طاقتور نفرن پیٹھ۔ تہٕ تِم گژھن مایوس۔ {اپُز: یا، چیف روزان: ہیب۔ بارز}\n37.\\tتلوار چُھہ تِہندین گُرٮ۪ن پیٹھ، تہٕ تِمن ہٕندِس رتھَن پیٹھ، تہٕ سارِنٕے رَلہٕ مِلہٕ لُکن پیٹھ یِم أمِس درمِیان چھِ۔ تہٕ تِم گژھن زنانہٕ ہٕندۍ پٲٹھۍ: تلوار {چھ} تٔمۍ سٕندِس خزانس پیٹھ؛ تہٕ تِم یِن لُٹنہٕ۔\n38. اَمہ سٕندِس آبس پیٹھ خشک سالی۔ تہٕ تِم گژھن خشک کرنہٕ: کیازِ یہِ چھُ {چھ} تِمن ہٕندِس بُتن ہُند سرزمین، تہٕ تِم چھِ تِمن ہٕندِس بُتن پیٹھ پاگل۔\n39.\\tتێلہِ گژھن صحراہٕکۍ جنگلی جانور جزیرن ہٕندٮ۪ن جنگلی درندن سٍتـ̡ روزان تہٕ راتہٕ مۄغل روزن اَتھ مَنٛز روزُن: تہٕ یێلہِ روزِ نہٕ ہمیشہٕ روزُن۔ نہ گژھہِ یہ نسل در پیر روزُن۔\n40. یێلہِ خداین سدوم تہٕ عمورہ تہٕ تِمن ہٕندِس ہمسایہ سٍتـ̡ خدایہ چُھ فرماوان۔ {یِتھٕ پٲٹھۍ} روزِ نہٕ کانٛہہ تہِ انسان اَتھ مَنٛز روزُن۔\n41.\\tوُچھِو شُمالہٕ سٍتـ̡ یِنہٕ اَکھ قوم تہٕ اَکھ بٔڈ قوم تہٕ واریاہ بادشاہ یِن زمینہٕ کِس بٹھہٕ پیٹھٕ وۅتھنہٕ۔\n42.\\tتِم رٔٹِتھ کمان تہٕ نیزہٕ: تِم چھِ ظالم، تہٕ رحم کٔرِن نہٕ: تِہٕنز آواز گٔژھِ سمندرٕکۍ پٲٹھۍ، تہٕ تِم گُرٮ۪ن پیٹھ سوار گٔژھِن، اے بابل ہٕنزِ کورِ ہٕندِس جنگس مَنٛز أکِس نفرٕکۍ پٲٹھۍ۔\n43.\\tبابل کِس بادشاہن بوز تِمن ہٕنز خبر تہٕ تٔمۍ سٕندِ اتھہٕ گٔیہِ کمزور: دَگ رٔٹِتھ گٔیہِ أمِس رٔٹِتھ، تہٕ تٔمِس گٔیہِ زنانہِ ہٕندِس مصیبت سٍتـ̡ دَگ دِنہٕ۔\n44.\\tوُچھِو سُہ سٕہہ سٕندِ پٲٹھۍ، یُس اردن ہٕندِس ورمہٕ پیٹھٕ طاقتورن ہٕندِس مکانس تام وُتھ، مگر بہٕ کرٕ تِم اچانک أمِس نِش ژلنہٕ: تہٕ کُس چُھہ ژارنہٕ آمُت، یُس بہٕ أمِس پیٹھ مقرر کٔرِتھ؟ میہ ہیو کُس {چُھ}؟ تہٕ کُس کرِ میہ وقت؟ تہٕ سُہ چرواہ کُس چُھ یُس میانہِ برونہہ کنہِ کھڑا آسہِ؟ {میہ مقرر کرُن...: یا، میہ کٔرِو درخواست کرنہٕ خٲطرٕ؟}\n45. تێمہِ کِنۍ بوزو خداوند سُند مشورٕ، یُس تٔمۍ بابل ہس خلاف رٔٹمُت چُھ۔ تہٕ تٔمۍ سُند مقصد چُھ، یُس تٔمۍ چُھ چالڈین ہٕندِس سرزمینس خلاف مقصود کورمُت: یقیناً کم از کم ریوڑ کرِ تِمن نِش نٮ۪بر، یقینا سُہ کرِ تِمن سٍتـ̡ تِمن سٍتـ̡ بستی ویران۔\n46.\\tبابل رٹنہٕ کِس شورس سٍتـ̡ چُھ زمین ہلاونہٕ یوان، تہٕ قومن مَنٛز چُھ فریاد بوزنہٕ یوان۔","1. خداوند چُھ یِتھٕ پٲٹھۍ فرماوان۔ وچھ بہٕ بابل سٕندِس خلاف تہٕ تِمن خلاف یُس میہ خلاف کھڑا روزان چُھ، اکھ تباہ کن واو۔ {درمیان: ہیب۔ دِل}\n2.\\tتہٕ سوزِ بابل کِس پنکھس منز، یُس أمِس پنکھہٕ دِن، تہٕ تٔمۍ سٕنز زمین خٲلی کرِ، تکیازِ مصیبت ہٕندِس دۅہس منز گژھن تِم أمِس اندۍ پکھۍ خٕلاف۔\n3. یُس {یُس} جھکُن چُھ، تیر انداز کرُن پنُن کمان، تہٕ {أمِس} خٕلاف یُس پنُن پان تُلِتھ تُلِتھ چُھ، تہٕ تٔمۍ سٕندِس جوانس تراوُن نہٕ۔ تٔمۍ سٕندِس سارِنٕے لشکرس کٔرِو پوٗرٕ پٲٹھۍ تباہ۔\n4. یِتھٕ پٲٹھـ̡ گٔیہِ مقتول چالڈین ہٕندِس سرزمینس مَنٛز، تہٕ یِم یِم تٔمۍ سٕنزِ سڑکن مَنٛز دِنہٕ یِن۔\n5. اسرٲیلس خٲطرٕ چُھہ نہٕ {تراونہٕ}آمُت، تہٕ یہوداہ چُھ نہٕ پننِس خدایہِ سُند یُس لشکرن ہٕندِس خداہس سٍتـ̡ چُھہ تراونہٕ آمُت۔ حالانٛکہِ تِہٕنٛز سرزمین ٲس اسرٲیلِس مُقدس سٕندِس خٕلاف گۅنہٕ سٍتـ̡ بٔرِتھ بٔرِتھ۔\n6. بابل منزٕ ژٔلِتھ ژٔلِو تہٕ پرٮ۪تھ أکِس انسانس سُند روح بچاوُن: تٔمۍ سٕنزِ بدکٲری سٍتـ̡ گژھ نہٕ ژٹنہٕ۔ تکیازِ یہ {چُھ} خداوند سٕندِ انتقامُک وق۔ سُہ دِیہِ أمِس بدلہٕ۔\n7. بابل اوس خداوند سٕندِس اتھس مَنٛز اکھ سۄنہٕ پیالہ ، یٔمۍ سارِنٕے زمینہٕ شرابس منز بنیوو: قومن چُھ تٔمۍ سٕندِ شرابُک شراب۔ تَمہِ کِنۍ چھِ قوُم پاگل۔\n8. بابل آو اچانک پیوٚو تہٕ تباہ سپُد: أمِس خٲطرٕ کرٛٮ۪کھ کٔرِتھ۔ تٔمۍ سٕنٛدِ دَگ خٲطرٕ رٔٹِو بام، اگر تہِ آسہِ سۄ گژھِ ٹھیٖک۔\n9.\\tأسـ̡ ہا بابل شفا دِتھ، مگر سُہ چُھہ نہٕ شفا گومُت: أمِس ترٲوِو تہٕ أسـ̡ پرٮ۪تھ أکِس پننِس ملکس مَنٛز گژھُن، تکیازِ تٔمۍ سُند فیصلہ چُھ آسمانس تام واتناوان تہٕ آسمانس تام تہِ تُلِتھ چُھ۔\n10. خداوند چُھ سانہِ نیکی برونہہ کُن دِژمٕژ: یِو تہٕ أسۍ زیونس مَنٛز خداوند سٕنزِ کامہِ ہُند اعلان کرُن۔\n11. تیر روشن کٔرِو؛ ڈھالہٕ جمع کٔرِو: خداوند چُھ میدس ہٕندِس بادشاہن ہُند روح تُلِمُت: تٔمۍ سٕندِ چال {چُھ} بابل ہس خٕلاف، یہِ تباہ کرنہٕ خٲطرٕ؛ کیازِ یہِ چُھ خداوند سُند انتقام، تٔمۍ سٕندِس مندرُک انتقام۔ {روشن: ہیب۔ خالص}\n12.\\tبابل کین دیوارن پیٹھ بٔنِتھ تھٲوِو پہرہ مضبوط، چوکیدار تھووُن، حملہٕ تیار کرُن، کیازِ خداوند چھُ سُہ بنوومُت تہٕ کورمُت یُس تٔمۍ بابل کین بسکینن خلاف کتھ کٔر۔ {ایمبش: ہیب۔ لایرز ان ویٹ}\n13. اے یُس واریاہ آبس پیٹھ روزان چھُ، یُس خزانہٕ سٍتـ̡ بٔرِتھ چُھ، تُہند انجام چُھ آمُت، تہٕ چُھہ پننہِ لالچُک پیمانہٕ۔\n14.\\tلشکرن ہٕندِس رب سٍتـ̡ چُھہ پانس سٍتـ̡ قَسم کورمُت، {ونُن}، یێلہِ بہٕ کٔرٕ ژے نفرو سٍتـ̡ بٔرِتھ، یِتھٕ پٲٹھـ̡ کٔرِتھ چُھہ ژے بٔرِتھ بٔرِتھ۔ تہٕ تِم تُلِن تۅہہِ خٕلاف کرٛٮ۪کہٕ۔ {پانے: ہیب۔ تٔمۍ سٕندِس روحس سٍتۍ} {تُلِتھ: ہیب۔ اَٹُر}\n15.\\tتٔمۍ کٔر پننہِ طاقتہٕ سٍتـ̡ زمینہٕ بنوومُت، تٔمۍ کٔر پننہِ عقلہٕ سٍتـ̡ دُنیا قایم تہٕ پننہِ عقلہٕ سٍتـ̡ آسمانس پھٔہلٲومُت۔\n16.\\tییلہ سُہ پننہِ آواز کڈان چُھ، {تتہِ} چُھہ آسمانس مَنٛز واریاہ آب۔ تہٕ سُہ چُھ زمینہٕ کِس اندس پیٹھ بخارات کھسان: سُہ چُھ روٗد سٍتـ̡ بجلی بناوان، تہٕ پنہٕ نِس خزانہٕ منزٕ واو کڈان۔ {کثیر: یا، شور}\n17.\\tپریتھ انسان چھہ پننہِ علمہ سٍتۍ وحشیانہ آسان۔ پرتھ کانہہ بانی چھہ تٔمۍ سٕنزِ پگھلِتھ تصویر {چھُ} اپُز، تہٕ {تمن منز چھہ نہٕ کانہہ شاہ۔ {چھُ وحشی...: یا، زاننہٕ کھوتہٕ زیادٕ وحشی}\n18.\\tتِم چھِ باطل، غلطین ہٕنز کٲم: یِمن ہٕندِس یِنہٕ وِزِ گژھن تِم فنا گٔژھان۔\n19.\\tیعقوب سُند حصہ چُھہ نہٕ تِمن ہٕندۍ پٲٹھۍ۔ تکیازِ سُہ چُھ سارِنٕے چیزن ہُند گۄڈنیُک: تہٕ {اسرٲیل} چُھ تٔمۍ سٕندِس وراثتُک لور: لشکرن ہُند رب {چُھ} تٔمۍ سُند ناو۔\n20. ژے چُھکھ میٲنۍ جنگی کلہٕ تہٕ جنگُک ہتھیار: تہٕ ژے سٍتۍ کرٕ بہٕ قومن ٹُکرٕ ٹُکرٕ پھٹراوُن، تہٕ ژے سٍتـ̡ کرٕ بہٕ سلطنتہٕ تباہ کرنہٕ۔ {ژے سٍتۍ: یا، ژے منز، یا، ژے سٍتۍ}\n21. تہٕ ژے سٍتۍ پھُٹراوٕ گُر تہٕ تٔمۍ سٕندِس سوارِ ٹُکرٕ ٹُکر۔ تہٕ ژے سٍتۍ پھُٹراوٕ بہٕ رَتھ تہٕ تٔمۍ سٕندِس سوارِ ٹُکرٕ ٹُکرٕ کٔرِتھ۔\n22. بہٕ ژے سٍتـ̡ تہٕ ژے سٍتـ̡ ژٔٹِتھ پھٔٹِتھ مرد تہٕ زنانہٕ۔ تہٕ ژے سٍتۍ پھُٹراوٕ بہٕ بُزرگ تہٕ جوان ٹُکرٕ ٹُکرۍ۔ تہٕ ژے سٍتۍ کرٕ بہٕ جوان تہٕ دٲر ٹُکرٕ ٹُکرٕ کرٕنۍ۔\n23.\\tبہٕ ژے تہٕ تٔمۍ سٕندِس ریوڑس سٍتـ̡ ژٔٹِتھ پھٔٹِتھ ۔ تہٕ ژے سٍتۍ پھُٹراوٕ بہٕ کٔرِتھ زٔمیٖندار تہٕ تٔمۍ سٕندِس بیلن ہُند جو۔ تہٕ ژے سٍتۍ پھٹراوٕ بہٕ کپتان تہٕ حکمران۔\n24. تہٕ بہٕ کَرٕ بابل تہٕ کلدیہ کین سارنٕے بسکیٖنن تِہٕنزِ سٲرِی بُرٲیی یُس تُہٕندِس نظرِ منز صہیونس مَنٛز کٔرمٕژ چھُ، خداوند چُھ فرماوان۔\n25. وچھ بہٕ چُھس ژے خلاف، اے تباہ کرن وول پہاڑ، خداوند چُھس ونان یُس سارِنٕے زمینس تباہ کران چُھ، تہٕ بہٕ کرٕ ژے پیٹھ پنُن اتھہٕ، تہٕ ژے کٔنہِ پٔنِس پٔتِس پیٹھ وُسِتھ تہٕ بناوٕ ژے اکھ دزمُت پہاڑ۔\n26.\\tتہٕ تِم نِن نہٕ تۅہہِ نِش کُنہِ کُنہِ تہٕ نہ کُنہِ مگر خداوند چُھ ونان زِ تُہۍ گژھِو ہمیشہٕ خٲطرٕ ویران روزُن۔ {ویران ...: ہیب۔ ابدی ویرانی}\n27. زمینس مَنٛز کٔرِو اکھ معیار قٲیم، قومن مَنٛز وُپھ وُن، قومن ہٕندِس خٕلاف تیار کٔرِو، ارارات، مِنی تہٕ اشچناز ہٕنزِ سلطنتن ہٕندِس خٕلاف بُلٲوِو۔ أمِس خٕلاف کٔرِو اکھ کپتان مقرر۔ گُرٮ۪ن ہٕندِس کھرِ کھرِ ہٕندِس کُنہِ\n28.\\tأمِس خٕلاف کٔرِو مَدَن ہٕندِس بادشاہَن سٍتـ̡ تہٕ تٔمِس سٍتـ̡ سارِنٕے حُکُمران تہٕ تٔمِس سٍتـ̡ تٔمِس سٍتـ̡ قومن ہٕندِس سٍتـ̡ تیار۔\n29.\\tتہٕ زمین گژھہِ تھرتھر تہٕ غم: خداوند سُند پرٮ۪تھ کانہہ مقصد گژھہِ بابل سٕندِس خلاف انجام دِنہٕ یُن، یُس بابل ہٕندِس سرزمینس کُنہِ بسکیٖنہٕ ورٲے ویران بناوُن۔\n30.\\tبابل کین طاقتور نفرو چھہ لڑایہِ نِش ترک کورمُت، تِم چھہِ پننین قبضن منز رودمٕتۍ: تِہُند طاقت گۆو ناکام۔ تِم بنییہِ زنانہٕ: تِمو چھِ تٔمۍ سٕندِس مکانہٕ گاہٕ زٲلِمٕتۍ۔ تٔمۍ سٕنٛدِ سلاخہٕ چھِ پھُٹمٕتۍ۔\n31. اَکھ چُھہ بییِس سٍتـ̡ سمکھنہٕ خٲطرٕ تہٕ اَکھ قاصد بییِس سٍتـ̡ سمکھنہٕ خٲطرٕ، بابل کِس بادشاہس ہاونہٕ خٲطرٕ زِ تٔمۍ سُند شہر چُھ {اَکہِ} اندس پیٹھ قبضہٕ کرنہٕ آمُت،\n32.\\tتہٕ یہ زِ وتہٕ آیہ بند کرنہٕ، تہٕ یِم سرٕ نار سٍتۍ زٲلِتھ چھِ، تہٕ جنگی نفر چھِ خوفزد۔\n33. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب یُس اسرٲیلُک خدا چُھ وَنان۔ بابل سٕنز کوٗر چِھہ کُنہِ کھورِ ہٕندِس پٲٹھۍ، {یہِ} چُھہ أمِس تھرِنُک وقٕت: توتہِ چُھہ کینہہ کال، تہٕ تٔمۍ سٕندِ فصلُک وق واتہِ۔ {یہِ چھُ...: یا، تمہِ وقتہٕ ییٚلہِ سُہ أمِس تھپھ دِوان چھُ}\n34. بابلُک بادشاہ نبوکدرزارن چُھ مے کھٮ۪ومُت، تٔمۍ چُھس مے مُشکِل کورمُت، تٔمۍ بنوو مے اکھ خٲلی بانہٕ، تٔمۍ چُھس مے ڈریگن ہٕندۍ پٲٹھۍ، تٔمۍ چُھس پنُن یٔڈ میانیو نازکو سٍتـ̡ بٔرِتھ، تٔمۍ کٔر مے کٔڈِتھ۔\n35.\\tیُس میہ تہٕ میٲنِس مازس سٍتـ̡ بابل سٍتـ̡ سپدُن، سٍتـ̡ چُھہ صییونُک روزن وول وَنُن؛ تہٕ چالدیہ کین بسکینن پیٹھ میون خون، یروشلم وَنُن۔ {تشدد...: ہیب۔ میون تشدد} {ماز: یا، باقی} {بسکین: ہیب۔ بسکین}\n36. تێمہِ کِنۍ چُھ خداوند یِتھٕ پٲٹھۍ فرماوُن؛ وچھ، بہٕ کرٕ چانہِ کامہِ ہٕنز درخواست تہٕ تۅہہِ ہُند انتقام۔ تہٕ بہٕ کرٕ أمۍ سُند سمندرٕ خشک تہٕ تٔمۍ سٕندِس چشمہٕ خشک کٔرِتھ۔\n37.\\tتہٕ بابل بنہِ ڈھیر، ڈریگن ہٕندِ خٲطرٕ روزنٕچ جاے، اکھ حٲران تہٕ اکھ ہُر، بغٲر کُنہِ بسکین۔\n38.\\tتِم چھِ شیرن ہٕندۍ پٲٹھۍاَکہٕ وٹہٕ گرٛٮ۪زان: تِم کٔرِن شیرن ہٕندِ بچہٕ ہٕندۍ پٲٹھۍ۔ {کرٛٮ۪کہٕ: یا کٔرِو پانَس ہلاونہٕ}\n39.\\tتِہٕندِس گرمی مَنٛز بہٕ بناوٕ تِہُند ضیافت تہٕ بہٕ بناوٕ تِمن شرابہٕ، یُتھ تِم خۅش گژھن تہٕ ہمیشہٕ نندر تہٕ بیدار گژھن نہٕ۔\n40. بہٕ اَننہٕ تِم کۅکرِ ہٕندۍ پٲٹھۍ، یِتھٕ پٲٹھۍ ژھاوٕرِ سٍتـ̡ کٔرِتھ کٔرِتھ۔\n41. شیشچ کِتھ کٔنۍ چُھ نِنہٕ یوان! تہٕ سارِنٕے زمینہِ ہٕندِس تعریفس کِتھہ کٔنۍ چھُ حیران! بابل کِتھہ پاٹھۍ چھہ قومن منز حیران سپدان!\n42.\\tسمندرُک ووت بابل پیٹھ: سُہ چُھ اَمہ کِس لہرَن ہٕندِس بٔڈِس سٍتـ̡ ؤلِتھ ۔\n43. تٔمۍ سٕندِ شہر چِھ ویران ، خشک زمین تہٕ بیابان ، اکھ زمین یتھ منز نہٕ کانہہ انسان روزان چُھ، تہٕ نہ چُھ انسان سُند نیچو اَتھ کُن نیران۔\n44. تہٕ بہٕ دِیہٕ بیلس بابل ہس منز سزا، تہٕ بہٕ کٔرٕ تٔمۍ سٕندِ ٲسہِ سٍتـ̡ سُہ یُس تٔمِس نِش نِنہٕ آمُت چُھ، تہٕ قومہٕ گژھن نہٕ تس نِش یکوٹہٕ پٲٹھۍ، آ، بابل ہٕچ دیوار پیٚیہِ۔\n45. میانہِ لوکو، تم نیرو أمس منز، تہٕ پرتھ کٲنسہِ انسان سٕندِس روحس خداوند سٕندِ شدید غضب نِش بچاو۔\n46.\\tتہٕ یێلہِ گژھہِ تُہُند دِل بێہوش تہٕ تۅہہِ گژھہِ تمہِ افواہ سٍتـ̡ خوفہٕ یُس زمینس مَنٛز بوزنہٕ ییہِ۔ اکھ افواہ ییہ دۅشوے ؤری، تہٕ تمہ پتہ ییہ {بییِس ؤریس منز} اکھ افواہ تہٕ زمینس منز تشدد، حکمرانس خلاف حکمران۔ {مۅکھہ: یا، گژھہِ نہٕ}\n47. تێمہِ وِزِ یِم دۅہ یِوان زِ بہٕ کَرٕ بابل کِس کھٔنِتھ بُنِس مجسمس پیٹھ فیصلہٕ: تہٕ تٔمۍ سٕنز سورٕے زمین گٔژھِ الجھاونہٕ، تہٕ تٔمۍ سُند سٲری مارنہٕ یِن أمِس منز۔ {ڈو...: ہیب۔ وزِٹ کٔرِو}\n48. تیلہِ کرِ آسمانس تہٕ زمینہٕ تہٕ اتھ منز موجود سورُے چیز، بابل خٲطرٕ گٮ۪وُن، کیازِ بد کار گژھن شمالہٕ پیٹھٕ أمِس نِش یِن، خداوند چُھ فرماوان۔\n49.\\tیِتھے پٲٹھـ̡ بابل سٍتـ̡ اسرٲیلُک مارُن پۯاوُن، تِتھے پٲٹھـ̡ پۯاوُن سارِنٕے زمینہٕ سٍتـ̡ مارنہٕ آمُت۔ {یِتھ...: یا، دۅشوے بابل گژھہِ پیُن، اے اسرٲیلِس سٍتـ̡ تہٕ بابل سٍتـ̡ وغیرہ} {زمین: یا، ملک}\n50. یُس تلوار نِش بچِتھ چُھ، ژٔلِو نہٕ رُکُن: دوٗر خداوند یاد تھاوُن، تہٕ یروشلم ییہ پننِس ذہنس مَنٛز۔\n51.\\tأسـ̡ چُھہ پریشان گومُت، کیازِ أسـ̡ چُھہ ملامت بوزمُت: شرم چُھہ سانہِ بُتھِس سٍتـ̡ وُپھ کٔرِتھ: کیازِ اجنبی چھِ خداوند سٕندِس گرٕ کِس مقدس مقامس مَنٛز یوان۔\n52. اَمہِ مۄکھہٕ چُھ، یِم دۅہ یِن، خداوند چُھ ونان زِ بہٕ کَرٕ تٔمۍ سٕنزِ کھٔنِتھ بُتن ہُند فیصلہٕ، تہٕ تٔمۍ سٕندِس سارِنٕے سرزمینس مَنٛز گژھہِ زخمیَن ہٕندِس سٍتـ̡ گُزار۔\n53.\\tیودوَے بابل گژھہِ آسمانس تام کھسُن، تہٕ یێلہِ سُہ پَنُن طاقتُک تھزرٕ قایم کرُن، {توتہِ} گژھن میانہِ نِش أمِس نِش خرابکار یِن، خداوند چُھ فرماوان۔\n54.\\tبابل پیٹھہ کُنہِ\n55. کیازِکہ خداوند چُھ بابل برباد کورمُت، تہٕ أمِس نِش چُھ عظیم آواز تباہ کٔرمٕژ۔ ییلہ تمۍ سنزِ لہرِ بٔڈۍ آبکۍ پاٹھۍ گڑبڑ کران چھہِ، تہنز آوازِ ہند شور چھہ نیران:\n56.\\tکیازِ یێمہِ سٍتـ̡ چُھہ أمِس سٍتـ̡ بابل سٍتـ̡ تہٕ تٔمۍ سٕندِس طاقتور نفرن ہٕندِس سٍتـ̡ چُھہ یِمن ہٕندِس کمانس سٍتـ̡ پھُٹراونہٕ آمُت، تِکیازِ خداوند خدایہِ سُند بدلہٕ چُھہ یٔقیٖنی پٲٹھـ̡ دِنہٕ آمُت۔\n57. تہٕ بہٕ بناوٕ تٔمۍ سٕندِس شہزادن، تہٕ تٔمۍ سٕندِس حکمرٲنی تہٕ تٔمۍ سٕندِس طاقتور نفرن شرابہٕ، تہٕ تِم گژھن ہمیشہٕ نندر تہٕ بیدار گژھن نہٕ، بادشاہ چُھ ونان یٔمۍ سُند ناو {چُھ} لشکرن ہُند رب چُھ۔\n58. یِتھٕ پٲٹھۍ چُھ لشکرن ہُند رب فرماوان۔ بابلٕچ وسیع دیوار گژھن پوٗرٕ پٲٹھۍپھُٹراونہٕ، تہٕ تٔمۍ سٕندِ تھدِ دروازٕ یِن نارٕ سٍتـ̡ زالنہٕ۔ تہٕ لوٗکھ گژھن بیکار محنتہٕ، تہٕ لُکھ نارس منٛز، تہٕ تِم چھِ تھکان گَژھان۔ {وسیع ...: یا، وسیع بیبلونٕچ دیوار} {پھُٹمُت: یا، ننگہٕ بناونہٕ}\n59.\\tسُہ لفظ یُس یرمیاہ پیغمبرن عیسیٰ سٕندِس نیچوِس نیریاہ سٕندِس نیچوِس سریاہ سٍتـ̡ حُکُم دِیُتمُت، یێلہِ سُہ یہوداہ کِس بادشاہس سٍتـ̡ پننہِ بادشاہ سٍتـ̡ ژوٗرمہِ ؤریس مَنٛز بابل گٔیہِ۔ تہٕ {یہ} سریہ اوس اکھ خاموش شہزادہ۔ {سۭتۍ: یا، طرفہٕ} {خاموش...: یا، مینوچا ہُک شہزادہ، یا، چیف چیمبرلین}\n60.\\tیێوَن یێلہِ یرمیاہ ہن أکِس کتابہِ مَنٛز سارِنٕے بُرٲیی یُس بابل سٍتـ̡ یُس یُس بابل سٍتـ̡ لیکھنہٕ یُن چُھ، {حتیٰ کہ} یِم سٲری لفظ یِم بابلس خلاف لیکھنہٕ آمٕتۍ چھِ۔\n61. تہٕ یرمیاہ ہن ووٚن سرایاہس زِ ییلہ تہٕ ژے بابل یِن، تہٕ وُچھِو تہٕ یِم سٲری لفظ پٔرِو۔\n62. تیلہٕ چُھہ ژے وَنُن، اے خداوند، ژے چُھہ یَتھ جایہِ ژٹنہٕ خٲطرٕ کتھ کٔرمٕژ، زِ اَتھ مَنٛز روزِ نہٕ کانہہ تہِ انسان، نہ جانور، مگر یہِ روزِ ہمیشہٕ خٲطرٕ ویران۔ {ویران : ہیب۔ ویرانی}\n63.\\tتہ ییلہ ژیہ یہ کتاب پرُن ختم کرِ، تہ اتھ سٍتـ̡ اکھ کٔن لٲگِتھ تہٕ فرات کِس وسطس مَنٛز تراوُن:\n64.\\tتہٕ ژے وَنُن زِ یِتھٕ پٲٹھـ̡ گژھہِ بابل ڈوبِتھ، تہٕ یُس بُرٕ سٍتـ̡ بہٕ أمِس سٍتـ̡ دِنہٕ یِیہ، تہٕ تِم گژھن تھکان ۔ وُنیُک تام چھِ یرمیاہ سٕندۍ کلام۔","1. صدیقیاہ اوس اَکھ وُہُر وُہُر ییلہ تٔمۍ بادشاہت شروع کٔر، تہٕ تٔمۍ کٔر یروشلمس مَنٛز کاہ وُہُر حکومت۔ تہٕ تٔمۍ سٕنزِ ماجہ ہُند ناو اوس ہموتل، یۄس لبناہٕچ یرمیاہ سٕنز کوٗر ٲس۔ {شروع...: ہیب۔ راج کٔر}\n2. تہٕ یُس خداوند سٕندِس نظرِ منز بد کار اوس، یُس یہویاکیمن اوس کوٚرمُت۔\n3.\\tکیازِ خداوند سٕندِ غصہٕ سٍتـ̡ سپد یروشلمس تہٕ یہوداہ ہس مَنٛز یێمہِ سٍتـ̡ یێلہِ تِم پننہِ حٲضِری نِش کٔرِتھ کٔرِتھ زِ صدیقیاہ کٔر بابل کِس بادشاہس سٍتـ̡ بغاوت ۔\n4. تہٕ یہٕ سپُد تٔمۍ سٕندِس دورِ حکومتہٕ کِس نٔوِمِس ؤریس منز، دٔہمہِ ریتس منز، دٔہمہِ دۅہہ، یُس بابل ہُند بادشاہ نیبوکدرِزر آو تہٕ تٔمۍ سُند سورُے لشکر آو یروشلمس خلاف تہٕ اتھ خلاف کوٚرُن قلعہٕ۔\n5. یِتھٕ کٔنۍ آو بادشاہ صدقیاہ سٕندِس کٔہمہِ ؤریس تام شہرس محاصرٕ کرنہٕ۔\n6. تہٕ ژوٗرمہِ ریتس مَنٛز، نٔوِمہِ دۅہہٕ اوس شہرس مَنٛز قحط ووٚتھ، یُتھ زن زمینہٕ کین لوکن ہٕندِ خٲطرٕ روٹی آسہٕ نہٕ۔\n7. پَتہٕ آو شہر پھُٹنہٕ، تہٕ جنگٕکۍ سٲری نفر ژٔلِتھ ژٔلِتھ رٲژ دۄن دیوارن درمیان دروازٕ کِنۍ شہرٕ نیبر، یُس بادشاہ سٕندِس باغس نِش اوس۔ (وۅنۍ ٲسۍ کلڈین اندۍ پکھۍ شہرس اندۍ پکھ:) تہٕ تم گٔیہ میدانی وتہِ کِنۍ۔\n8.\\tمگر کلدانن ہٕندِ لشکر لوٚگ بادشاہس پَتہٕ تہٕ یریحو کِس مٲدانس مَنٛز کوٚرُن زدیقیاہ پَتہٕ۔ تہٕ تٔمۍ سُنٛد سورُے فوج گوٚو أمِس نِش منتشر ۔\n9.\\tتَمہِ پَتہٕ نِیُکھ بادشاہ تہٕ نِیہِ بابل کِس بادشاہس نِش حَماتھ کِس سرزمینس مَنٛز ربلہ۔ ییتہِ تٔمۍ أمِس پیٹھ فٲصلہٕ دِیُت۔\n10.\\tتہٕ بابل کِس بادشاہن مٲرِتھ زِدقیاہ سٕندِ نیچو تہِ مٲرِتھ ربلاہس مَنٛز۔\n11. تمہ پتہ کٔر تمۍ صدقیاہ سٕنزِ أچھ کٔرِتھ۔ تہٕ بابل کِس بادشاہن بٔنِتھ زنجیرن منز بند، تہٕ نِن سُہ بابل تہٕ تھووُن مرنہٕ کس دۅہس تام قٲد خانس منٛز۔ {آوٹ کٔرتھ: ہیب۔ اندھ} {زنجیر: یا، زنجیر} {جیل: ہیب۔ وارڈن ہُنٛد ہاؤس}\n12.\\tوۅنۍ آو پوٗنٛژمہِ ریتس منز، ریتہٕ کِس دٔہمہِ دۅہس منز، یُس بابل کِس بادشاہ نبوکدرِزر سُند کُنوُہِم ؤری اوس، یُس بابل کِس بادشاہس سٍتـ̡ خدمت کران اوس، یروشلمس مَنٛز، {کپتان...: یا، چیف مارشل: حب۔ چیف آف دی جلاد، یا، ذبح} {سروڈ: ہیب۔ برونہہ کُن کھڑا}\n13.\\tتہٕ زٲلِن خداوند سُند گرٕ تہٕ بادشاہ سُند گر۔ تہٕ یروشلمٕکۍ سٲری گرٕ تہٕ بٔڈۍ {انسان} ہٕندۍ سارِنٕے گرٕ زٲلِتھ نارٕ سٍتـ̡ زٲلِتھ:\n14.\\tتہٕ چالدینن ہٕندِ سارِنٕے لشکر، یُس رٲچھ کِس کپتانس سٍتـ̡ ٲس، یُس یروشلمٕچ سارِنٕے دیوارٕ پھُٹرٲوِتھ ۔\n15.\\tپتہٕ نِیوُن محافظن ہٕندِس کپتانس منز غریبن ہٕندِس غریبس تہٕ شہرس منز روزن والٮ۪ن ہٕندِس باقیاتس تہٕ یِم گٔیہِ بابل کِس بادشاہس تہٕ باقٕے لُکن ہٕندِس نِش یِمن ہٕندِس باقٕے لُکن ہٕندِس نِش تہٕ باقٕے لُکن ہٕندِس لُکن ہٕندِس قٕسمس سٍتـ̡ نِنہٕ۔\n16.\\tمگر گارڈن کپتان نیبوزاردان تروو زمینہٕ کین غریبن ہٕندِ خٲطرٕ تہٕ زمینہٕ والٮ۪ن ہٕندِ خٲطرٕ۔\n17.\\tتہِ پیتلٕکۍ ستون یُس خداوند سٕندِس گرس مَنٛز اوس، تہٕ بٔنِس سٍتـ̡ تہٕ بٔرِس سمندرٕ یُس خداوند سٕندِس گرس مَنٛز اوس، تہٕ یِمن ہٕندِس سارِنٕے پیتل نِتھ بابل کُن۔\n18.\\tکۅکرِ تہِ، بیلچہ تہٕ نِش تہٕ پیالہ تہٕ چمچ، تہٕ سارِنٕے پیتلٕکۍ بانہٕ یِمن سٍتـ̡ تِم خدمت کران ٲسۍ۔ {بیلچہ: یا، آش ہٹاونک آلات} {پیالہٕ: یا، بیسن}\n19. تہٕ بیسن، تہٕ آتش دان، تہٕ پیالہٕ، تہٕ کۅکر، تہٕ شمعدان، تہٕ چمچ، تہٕ پیالہٕ۔ {یہ} یُس {اوس} سۄنہٕ {منز} سۄنہٕ سُند، تہٕ {یہ} یُس {اوس} رۄپہٕ {منز} رۄپہٕ سُند، نِیوُن گارڈُک کپتان۔ {فائر پینس: یا، سنسر}\n20.\\tزٕ تھم، اکھ سمندر، تہٕ باہ برسن بیل یِم بنیادن تل ٲسۍ، یُس بادشاہ سلیمانن رب سٕندِس گرس مَنٛز بنوومُت اوس، یِمن سارِنٕے بانن ہُند پیتل اوس نہٕ وزن۔ {پیتل: ہیب۔ تہند پیتل}\n21. تہٕ {ستونن متعلق}، اکس ستونک تھزر {اوس} ارداہ کیوبٹ۔ تہٕ بہن کیوبٹن ہُند اکھ فِلٹ اوس اتھ گھیرٕ کٔرتھ۔ تہ امچ موٚٹ {ٲس} ژور اونگجہِ: {یہ اوس} کھوکھر۔ {فلٹ: ہیب۔ تھریڈ}\n22. تہٕ اتھ پیٹھ اوس پیتلُک اکھ چپیٹر {اوس}۔ تہٕ أکِس چیپٹرُک تھزر اوس پانژھ کیوبِٹ، یتھ اندۍ پکھۍ چپیٹرن پیٹھ جال تہٕ انار ٲسۍ، سٲری پیتلۍ۔ دۆیم ستون تہِ تہ دٲن تہِ ٲسۍ یمن ہندۍ پاٹھۍ۔\n23.\\tتہٕ اَکہِ طرفہٕ ٲسۍ نَمتھ تہٕ شےٚ دٲن۔ {تہٕ}نیٹ ورکس پیٹھ موجود تمام انار {أس} ہتھ اندۍ اند۔\n24.\\tتہٕ رٲچھ کرن وٲلِس کپتانن رٔٹۍ سریاہ سردار پادٕر، تہٕ زیفانیاہ دۆیم پادٕرۍ تہٕ دروازٕکۍ تریہ رٲچھ کرن وٲلۍ: {دروازہ: عبری۔ تھریشولڈ}\n25.\\tتٔمۍ کٔر شہرٕ منزٕ اکھ خواجہ سرا تہِ، یٔمِس جنگی نفرن ہُند ذمہٕ دار اوس۔ تہٕ یِمو منزٕ ستھ نفر یِم بادشاہ سٕندِس شخصس نکھٕ ٲسۍ، یِم شہرس منز لبنہٕ آمٕتۍ ٲسۍ۔ تہٕ میزبان سُند اہم کاتب، یُس زمینٕکۍ لوٗکھ جمع کٔرۍ۔ تہٕ زمینٕکۍ لوٗکَن ہٕنٛدۍ ترےٚ نفر ، یِم شہرس منٛزباگ لبنہٕ آیہ۔ {أس نزدیک...: ہیب۔ بادشاہ سُند بُتھ وُچھمُت} {پرنسپل...: یا، میزبان سُند کاتب}\n26. چنانچہ نبوزارادنن نِیہِ رٲچھ کٔرِتھ تہٕ أنِن بابل کِس بادشاہس نِش ربلہ۔\n27.\\tتہٕ بابل کِس بادشاہن دِژ تِمن ہُند مار، تہٕ دِتُن تِم حَماث کِس سرزمینس مَنٛز ربلہ مَنٛز مارنہٕ۔ یِتھ پٲٹھـ̡ آو یہوداہ پننہِ سرزمینہٕ منزٕ نِنہٕ یِنہٕ۔\n28.\\tیِم چھِ تِم لُکھ یِم نبوکدرزارن قٲد کٔرِتھ: سٔتِمِس ؤریس مَنٛز ترے ساس یہودی تہٕ تریہ وُہ:\n29.\\tنبوکدرِزر سٕندِس اردٲہمہِ ؤریس مَنٛز نِیہِ یِمو یروشلم پیٹھٕ ٲٹھ ہتھ تہٕ زٕ نفر قٲد کٔرِتھ: {شخص: عبرانی۔ روح}\n30.\\tنبوکدرِزر سٕندِس تریمہِ تہٕ وُہمہِ ؤریس مَنٛز نِیوو گارڈُک کپتان یہودی ستھ ہتھ تہٕ پانژتٲجی نفر: سٲری نفر ٲسۍ ژور ساس تہٕ شیہ ہتھ۔\n31.\\tتہٕ یہِ سپُد یہوداہ کِس بادشاہ یہوویاچن سٕندِ قٲد گژھنہٕ کِس سَتِمِس تہٕ ترہمہِ ؤریس مَنٛز، بٔہمہِ ریتس مَنٛز، ریتہٕ کِس پانٛژمہِ تہٕ وُہمہِ دۅہہٕ مَنٛز، {یہ} بابل کِس بادشاہ ایویلمیروداخن تُل یہوداہ کِس بادشاہ یہوداہ سُند کلہٕ تہٕ أنُن قٲد خانہٕ منزٕ نیبر۔\n32.\\tتہٕ کٔرٕن أمِس سٍتـ̡ مہربانی سان کتھ کرنہٕ، تہٕ تھووُن پنُن تخت تِمن بادشاہن ہٕندِس تختس پیٹھ، یُس أمِس سٍتـ̡ بابل سٍتـ̡ اوس، {مہربانی...: حب۔ أمِس سۭتۍ اصل چیز}\n33.\\tتہٕ بدلٲوِن قٲدٕکۍ پَلَو: تہٕ سُہ اوس سارِنٕے دۅہہٕ أمِس برونہہ کُن روٹی کھیوان۔\n34.\\tتہٕ تٔمۍ سٕندِس غذاہس مۅکھہٕ اوس تس بابل کِس بادشاہس سٍتـ̡ مُسلسل غذا دِنہٕ یوان، پریتھ دۅہہ اوس تٔمۍ سٕندِس مرنہٕ دۅہس تام، تٔمۍ سٕنزِ زندگی ہٕندِس سارِنٕے دۅہس تام۔ {پرٮ۪تھ کُن...: ہیب۔ تمۍ سندِ دۅہک معاملہ}"];
